    /** Per-tick GPU upload budget while the Tutorial world streams in. */
    static constexpr std::size_t tutorial_upload_budget{24U};
    /**
     * Lazy entity model budget for the first playable frames.
     *
     * Entity state is authoritative immediately; only its presentation may
     * trail by a few frames. This prevents pickup-heavy maps from decoding and
     * uploading every crate/deployable KV6 in one frame.
     */
    static constexpr std::size_t entity_mesh_upload_budget{3U};

    /** Stable client-only id for one packet-97/98 UGC marker. */
    [[nodiscard]] static std::uint64_t
    ugc_presentation_entity_id(const network::InitialUgcItem& item) noexcept {
        const auto x = static_cast<std::uint64_t>(static_cast<std::uint16_t>(item.position[0U]));
        const auto y = static_cast<std::uint64_t>(static_cast<std::uint16_t>(item.position[1U]));
        const auto z = static_cast<std::uint64_t>(static_cast<std::uint16_t>(item.position[2U]));
        return 0x5547430000000000ULL | (static_cast<std::uint64_t>(item.item_id & 0x1FU) << 32U) |
               ((x & 0x1FFU) << 17U) | ((y & 0x1FFU) << 8U) | (z & 0xFFU);
    }

    /**
     * Materialize the retained UGC collection through the ordinary entity
     * renderer. Packet 98 has no CreateEntity edge, so keeping only its rows
     * made every successfully placed marker invisible to the editor host.
     */
    void sync_ugc_item_presentations() {
        if (tutorial_session == nullptr) {
            return;
        }
        std::set<std::uint64_t> expected;
        for (const auto& item : server_ugc_items) {
            if (item.item_id > 18U || item.position[0U] < 0 || item.position[1U] < 0 ||
                item.position[2U] < 0 || item.position[0U] >= 512 || item.position[1U] >= 512 ||
                item.position[2U] >= 256) {
                continue;
            }
            const auto id = ugc_presentation_entity_id(item);
            expected.insert(id);
            if (std::ranges::find(tutorial_session->entities(), id, &world::LocalEntity::id) !=
                tutorial_session->entities().end()) {
                continue;
            }
            world::LocalEntity entity;
            entity.id = id;
            entity.type = 29U;
            entity.position = {static_cast<double>(item.position[0U]),
                               static_cast<double>(item.position[1U]),
                               static_cast<double>(item.position[2U])};
            entity.team = world::ugc_entity_team(item.item_id);
            entity.face = 4U;
            entity.ugc_item_id = item.item_id;
            if (!tutorial_session->apply_server_entity(entity)) {
                settings_warning = "UGC marker rejected by the bounded entity renderer";
                break;
            }
        }

        std::vector<std::uint64_t> stale;
        for (const auto& entity : tutorial_session->entities()) {
            if (entity.type == 29U && (entity.id & 0xFFFFFF0000000000ULL) ==
                                          0x5547430000000000ULL &&
                !expected.contains(entity.id)) {
                stale.push_back(entity.id);
            }
        }
        for (const auto id : stale) {
            static_cast<void>(tutorial_session->destroy_server_entity(id));
        }
    }

    void initialize_social_client() {
        social_leave_after_create = false;
        social_open_match_generation.reset();
        social_open_match_lobby_id.clear();
        pending_social_lobby_navigation.reset();
        social_canceled_join.reset();
        social_chat_lobby_id.clear();
        social_chat_event_ids.clear();
        social_chat_event_order.clear();
        auto service = identity_service;
        social_client = std::make_unique<network::RevivalSocialClient>(
            [service](const network::RevivalSocialRequest& request, std::stop_token stop) {
                return service->social_request(request, stop);
            });
    }

    Impl(platform::WindowPort& source_window, NativeFrontendConfig source_config)
        : window{source_window}, config{std::move(source_config)},
          localization{config.localization_path},
          ui_layout_store{config.ui_layout_path},
          ui_layout_editor{ui_layout_store},
          identity_service{std::make_shared<network::RevivalIdentityService>()},
          native_steam{std::make_unique<platform::NativeSteamClient>(
              platform::default_native_steam_config(config.executable_directory))} {
        initialize_social_client();
        resolved_player_account_id = config.player_account_id;
        terrain_effects.set_particle_sink(&particles);
    }

    [[nodiscard]] std::string localized_text(std::string_view key) const {
        if (const auto translated = localization.lookup(key); translated.has_value()) {
            return std::string{*translated};
        }
        return english_text(key);
    }

    /** Load one non-prefab model through retail's startup model-quality tier. */
    [[nodiscard]] std::optional<world::Kv6Model>
    load_runtime_model(const std::filesystem::path& path, std::string* error) const {
        auto model = world::Kv6Model::load_file(path, error);
        if (model.has_value()) {
            *model = model->inverse_scaled(model_inverse_scale);
        }
        return model;
    }

    /** Cache the quality-scaled grave once; packet/effect paths remain I/O free. */
    void load_grave_effect_model() {
        const auto* grave = world::find_entity_definition(11U);
        if (grave == nullptr || grave->parts.empty()) {
            return;
        }
        std::string error;
        auto model = load_runtime_model(
            config.asset_root / "kv6" / std::string{grave->parts[0U].kv6}, &error);
        if (model.has_value()) {
            model->offset_pivots(grave->parts[0U].pivot_offset);
            terrain_effects.set_grave_model(*model);
            gameplay_debug_lab.set_grave_model(std::move(*model));
        }
    }

    void apply_identity(const network::RevivalAccount& account) {
        inventory_fixture=false;
        if (inventory_session) inventory_session->cancel();
        inventory_menu=InventoryMenuModel{};
        inventory_autoload=true;
        uploaded_sandbox_tool.reset(); loaded_tutorial_arm_class.reset();
        remote_class_model_cache.clear(); remote_weapon_model_cache.clear();
        remote_player_rigs.clear(); entity_model_cache.clear(); entity_part_slots.clear(); entity_part_appearances.clear();
        if (social_client == nullptr ||
            social_client->status(std::chrono::steady_clock::now()).closing) {
            initialize_social_client();
        }
        config.player_name = account.nickname;
        resolved_player_account_id = 0U;
        if (!account.offline && !account.legacy_id.empty()) {
            std::uint64_t parsed{};
            const auto first = account.legacy_id.data();
            const auto last = first + account.legacy_id.size();
            const auto conversion = std::from_chars(first, last, parsed);
            if (conversion.ec == std::errc{} && conversion.ptr == last) {
                resolved_player_account_id = parsed;
                config.player_account_id = parsed;
            }
        }
        friends_lobby_menu.set_identity(account.legacy_id);
        const auto social_available = !account.offline && identity_service->has_online_session();
        social_client->set_available(social_available);
        friends_lobby_menu.set_service_status(
            social_available,
            social_available ? std::string{} : "Social features require an online account.");
        authenticated_identity = true;
    }

    [[nodiscard]] static FriendsLobbySnapshot adapt_social_snapshot(
        const network::RevivalSocialSnapshot& source) {
        FriendsLobbySnapshot result;
        result.cursor = source.cursor;
        result.friends.reserve(source.friends.size());
        for (const auto& row : source.friends) {
            result.friends.push_back({row.legacy_id,
                                      row.nickname.empty() ? row.username : row.nickname,
                                      row.presence,
                                      row.friendship_status,
                                      row.direction,
                                      row.current_lobby_id,
                                      row.current_server_id});
        }
        result.invitations.reserve(source.invitations.size());
        for (const auto& row : source.invitations) {
            result.invitations.push_back(
                {row.id, row.lobby_id, row.lobby_name, row.inviter_name});
        }
        if (source.lobby.has_value()) {
            FriendsLobby lobby;
            lobby.id = source.lobby->id;
            lobby.owner_id = source.lobby->owner_id;
            lobby.name = source.lobby->name;
            lobby.state = source.lobby->state;
            lobby.server_id = source.lobby->server_id;
            lobby.maximum_members = source.lobby->maximum_members;
            lobby.members.reserve(source.lobby->members.size());
            for (const auto& row : source.lobby->members) {
                lobby.members.push_back({row.legacy_id, row.nickname, row.presence, row.in_game});
            }
            result.lobby = std::move(lobby);
        }
        return result;
    }

    [[nodiscard]] static std::optional<std::uint16_t> social_u16(
        const nlohmann::json& object,
        std::string_view key) {
        const auto found = object.find(key);
        if (found == object.end() || !found->is_number_integer()) return std::nullopt;
        const auto value = found->get<std::int64_t>();
        if (value < 0 || value > std::numeric_limits<std::uint16_t>::max()) {
            return std::nullopt;
        }
        return static_cast<std::uint16_t>(value);
    }

    /** Decode only known Match Lobby fields; the menu model normalizes them. */
    [[nodiscard]] static CreateMatchConfiguration social_configuration(
        const network::RevivalSocialLobby& lobby) {
        CreateMatchConfiguration result;
        result.privacy = lobby.privacy == "invite"
                             ? CreateMatchPrivacy::invite_only
                         : lobby.privacy == "friends"
                             ? CreateMatchPrivacy::friends_only
                             : CreateMatchPrivacy::open;
        result.max_players = static_cast<std::uint16_t>(
            std::clamp<std::size_t>(lobby.maximum_members, 2U, 24U));
        const auto& settings = lobby.settings;
        if (const auto value = social_u16(settings, "retail_playlist_id")) {
            result.retail_playlist_id = *value;
        }
        if (const auto value = social_u16(settings, "match_minutes")) {
            result.match_minutes = *value;
        }
        if (const auto value = social_u16(settings, "bot_count")) {
            result.bot_count = *value;
        }
        if (const auto value = social_u16(settings, "server_port")) {
            result.server_port = *value;
        }
        if (const auto found = settings.find("map_name");
            found != settings.end() && found->is_string()) {
            result.map_name = found->get<std::string>();
        }
        if (const auto found = settings.find("bot_difficulty");
            found != settings.end() && found->is_string()) {
            result.bot_difficulty = found->get<std::string>();
        }
        if (const auto found = settings.find("rule_overrides");
            found != settings.end() && found->is_object()) {
            for (const auto& [key, value] : found->items()) {
                if (value.is_string()) result.rule_overrides.emplace(key, value.get<std::string>());
            }
        }
        return result;
    }

    [[nodiscard]] static nlohmann::json social_settings(
        const CreateMatchConfiguration& configuration) {
        return nlohmann::json{{"retail_playlist_id", configuration.retail_playlist_id},
                              {"match_minutes", configuration.match_minutes},
                              {"bot_count", configuration.bot_count},
                              {"bot_difficulty", configuration.bot_difficulty},
                              {"server_port", configuration.server_port},
                              {"map_name", configuration.map_name},
                              {"rule_overrides", configuration.rule_overrides}};
    }

    [[nodiscard]] static std::string social_privacy(CreateMatchPrivacy privacy) {
        switch (privacy) {
        case CreateMatchPrivacy::invite_only: return "invite";
        case CreateMatchPrivacy::friends_only: return "friends";
        case CreateMatchPrivacy::open: return "open";
        }
        return "invite";
    }

    /** Support log line whenever the lobby's authority, phase or roster changes. */
    void trace_social_lobby(const network::RevivalSocialLobby& lobby) {
        std::string my_team{"-"};
        for (const auto& member : lobby.members) {
            if (member.legacy_id != friends_lobby_menu.local_account_id()) continue;
            const auto assigned = member.member_data.find("assigned_team");
            if (assigned != member.member_data.end() && assigned->is_number_integer()) {
                my_team = std::to_string(assigned->get<int>());
            }
        }
        const auto line = "id=" + lobby.id + " state=" + lobby.state + " rev=" + lobby.revision +
                          " owner=" + (lobby.owner_id == friends_lobby_menu.local_account_id()
                                           ? std::string{"me"} : lobby.owner_id) +
                          " members=" + std::to_string(lobby.members.size()) +
                          " my_team=" + my_team +
                          " server=" + (lobby.server_id.empty() ? std::string{"-"} : lobby.server_id);
        if (line == traced_lobby) return;
        traced_lobby = line;
        core::diagnostic("lobby", line);
    }

    /** Support log lines for screen changes and on-screen status text. */
    void trace_frontend_state() {
        const auto current = screen();
        if (!traced_screen.has_value() || *traced_screen != current) {
            traced_screen = current;
            std::string line{layout_screen_name(current)};
            if (current == FrontendScreen::class_selection) {
                line += " team=" + std::to_string(class_selection_menu.team()) +
                        " classes=" + std::to_string(class_selection_menu.classes().size()) +
                        " initial_join=" + (class_selection_initial_join ? "1" : "0") +
                        " forced_team=" + (forced_team.has_value()
                                               ? std::to_string(*forced_team) : std::string{"-"});
            }
            core::diagnostic("nav", line);
        }
        if (settings_warning != traced_warning) {
            traced_warning = settings_warning;
            if (!traced_warning.empty()) core::diagnostic("ui", traced_warning);
        }
    }

    void sync_social_match_lobby(const network::RevivalSocialSnapshot& source,
                                 bool apply_settings) {
        if (!source.lobby.has_value()) return;
        const auto& lobby = *source.lobby;
        trace_social_lobby(lobby);
        const bool authority_changed = social_match_lobby_id != lobby.id ||
                                       social_match_owner_id != lobby.owner_id;
        if (authority_changed) {
            social_desired_configuration.reset();
            social_sent_configuration.reset();
            social_settings_generation.reset();
            social_settings_waiting_for_sync = false;
            apply_settings = true;
        }
        social_match_lobby_id = lobby.id;
        social_match_owner_id = lobby.owner_id;
        std::vector<CreateMatchPlayer> players;
        players.reserve(lobby.members.size());
        std::uint64_t fallback_id{1U};
        for (const auto& member : lobby.members) {
            std::uint64_t account_id{};
            const auto first = member.legacy_id.data();
            const auto last = first + member.legacy_id.size();
            const auto converted = std::from_chars(first, last, account_id);
            if (converted.ec != std::errc{} || converted.ptr != last) account_id = fallback_id;
            ++fallback_id;
            const auto assigned = member.member_data.find("assigned_team");
            const auto team = assigned != member.member_data.end() && assigned->is_number_integer()
                                ? (*assigned == 2 ? 2 : *assigned == 3 ? 3 : 0) : 0;
            players.push_back(CreateMatchPlayer{account_id,
                                                member.nickname,
                                                team == 2 ? "TEAM1_COLOR" : team == 3 ? "TEAM2_COLOR" : "TEAM_NEUTRAL",
                                                member.legacy_id == lobby.owner_id,
                                                member.legacy_id ==
                                                    friends_lobby_menu.local_account_id(),
                                                member.in_game});
        }
        create_match_menu.set_players(std::move(players));
        create_match_menu.set_match_join_available(!lobby.server_id.empty() &&
            (lobby.state == "ready" || lobby.state == "in_game"),
            friends_lobby_menu.busy() || social_leave_generation ||
                social_join_active.load(std::memory_order_acquire));
        const auto owner = !friends_lobby_menu.local_account_id().empty() &&
                           lobby.owner_id == friends_lobby_menu.local_account_id();
        create_match_menu.set_host_authority(owner && lobby.state == "forming" &&
                                             !social_start_generation && !social_start_retry_configuration &&
                                             !social_leave_generation);
        create_match_menu.set_member_management_enabled(lobby.state == "forming");
        if (!lobby.name.empty()) static_cast<void>(create_match_menu.set_lobby_name(lobby.name));
        if (apply_settings) {
            create_match_menu.apply_authoritative_configuration(social_configuration(lobby));
        }
    }

    /** Fold new cursor events into the bounded Match Lobby chat panel. */
    void apply_social_lobby_events(const network::RevivalSocialSnapshot& source) {
        if (!source.lobby.has_value()) return;
        const auto& lobby = *source.lobby;
        if (social_chat_lobby_id != lobby.id) {
            social_chat_lobby_id = lobby.id;
            social_chat_event_ids.clear();
            social_chat_event_order.clear();
            create_match_menu.set_chat_lines({});
        }
        auto lines = create_match_menu.presentation().chat_lines;
        for (const auto& event : source.events) {
            if (event.type != "lobby.chat" || event.lobby_id != lobby.id) continue;
            if (event.id.empty() || social_chat_event_ids.contains(event.id)) continue;
            const auto message = event.payload.find("message");
            if (message == event.payload.end() || !message->is_string()) continue;
            social_chat_event_ids.insert(event.id);
            social_chat_event_order.push_back(event.id);
            while (social_chat_event_order.size() > 512U) {
                social_chat_event_ids.erase(social_chat_event_order.front());
                social_chat_event_order.pop_front();
            }
            auto author = event.actor_id;
            const auto member = std::ranges::find(lobby.members,
                                                  event.actor_id,
                                                  &network::RevivalSocialLobbyMember::legacy_id);
            if (member != lobby.members.end() && !member->nickname.empty()) {
                author = member->nickname;
            }
            if (author.empty()) author = "Player";
            lines.push_back(CreateMatchChatLine{std::move(author),
                                                message->get<std::string>()});
        }
        create_match_menu.set_chat_lines(std::move(lines));
    }

    [[nodiscard]] bool send_lobby_member_action(const CreateMatchMemberEffect& action) {
        if (social_client == nullptr) return false;
        const auto snapshot = social_client->snapshot();
        if (!snapshot.lobby || snapshot.lobby->state != "forming" ||
            snapshot.lobby->owner_id != friends_lobby_menu.local_account_id()) return false;
        const auto target = std::to_string(action.account_id);
        const auto member = std::ranges::find(snapshot.lobby->members, target,
            &network::RevivalSocialLobbyMember::legacy_id);
        if (member == snapshot.lobby->members.end() ||
            (action.kick && target == snapshot.lobby->owner_id)) return false;
        network::RevivalSocialRequest request;
        request.generation = background_social_generation();
        request.kind = network::RevivalSocialRequestKind::lobby_action;
        request.priority = true;
        request.lobby_id = snapshot.lobby->id;
        request.target = target;
        request.action = action.kick ? "kick" : "assign_team";
        request.payload = nlohmann::json{{"target", target}, {"team", action.team}};
        return social_client->enqueue(std::move(request));
    }

    [[nodiscard]] bool send_active_lobby_chat(std::string message) {
        if (social_client == nullptr || message.empty()) return false;
        const auto snapshot = social_client->snapshot();
        if (!snapshot.lobby.has_value()) return false;
        network::RevivalSocialRequest request;
        request.generation = background_social_generation();
        request.kind = network::RevivalSocialRequestKind::lobby_action;
        request.priority = true;
        request.lobby_id = snapshot.lobby->id;
        request.action = "chat";
        request.payload = nlohmann::json{{"message", std::move(message)}};
        return social_client->enqueue(std::move(request));
    }

    /**
     * Project the AoSPlay lobby into retail BaseSquadLobbyMenu's one true
     * roster. The Friends screen deliberately never renders a second roster.
     */
    void open_social_match_lobby(const network::RevivalSocialSnapshot& source) {
        if (!source.lobby.has_value()) return;
        pending_social_lobby_navigation = source.lobby->id;
        // Network replies may arrive halfway through the Friends slide. Keep
        // the destination pending until routing accepts it, rather than losing
        // the reply or disabling the still-visible menu.
        if (!navigation.shell().accepts_input()) return;
        const auto target = source.lobby->lobby_type == "ugc"
            ? FrontendScreen::ugc_editor_lobby : FrontendScreen::create_match;
        const auto current = screen();
        if (current != target) {
            const bool can_open = current == FrontendScreen::friends_lobby ||
                current == FrontendScreen::ugc_editor_browser || is_create_match_screen(current);
            if (!can_open) { pending_social_lobby_navigation.reset(); return; }
            if (!navigation.return_to(target) &&
                !navigation.replace(target, NavigationDirection::forward)) return;
        }
        pending_social_lobby_navigation.reset();
        settings_warning.clear();
        if (source.lobby->lobby_type == "ugc") {
            sync_ugc_social_lobby(source);
            friends_lobby_menu.leave();
            static_cast<void>(window.set_text_input_enabled(false));
            return;
        }
        sync_social_match_lobby(source, true);
        reset_create_match_page_transition();
        friends_lobby_menu.leave();
        static_cast<void>(window.set_text_input_enabled(false));
    }

    [[nodiscard]] std::uint64_t background_social_generation() noexcept {
        if (++next_background_social_generation == 0U) {
            next_background_social_generation = 1'000'000'000ULL;
        }
        return next_background_social_generation;
    }

    /** Queue authoritative Leave and navigate only after AoSPlay confirms it. */
    [[nodiscard]] bool leave_active_social_lobby() {
        if (social_client == nullptr || social_leave_generation.has_value()) return false;
        const auto snapshot = social_client->snapshot();
        if (!snapshot.lobby.has_value()) return false;
        network::RevivalSocialRequest request;
        request.generation = background_social_generation();
        request.kind = network::RevivalSocialRequestKind::lobby_action;
        request.priority = true;
        request.lobby_id = snapshot.lobby->id;
        request.action = "leave";
        const auto generation = request.generation;
        if (!social_client->enqueue(std::move(request))) return false;
        social_leave_generation = generation;
        if (social_join_worker.joinable()) social_join_worker.request_stop();
        if (const auto operation = friends_lobby_menu.operation(); operation &&
            operation->intent.kind == FriendsLobbyActionKind::join_game) {
            static_cast<void>(friends_lobby_menu.complete(operation->generation, true, {},
                                                         std::chrono::steady_clock::now()));
        }
        social_canceled_join = std::array{snapshot.lobby->id, snapshot.lobby->start_id,
                                          snapshot.lobby->server_id};
        pending_social_lobby_navigation.reset();
        create_match_menu.set_match_join_available(false);
        settings_warning = "Leaving the lobby...";
        return true;
    }

    [[nodiscard]] bool start_active_social_lobby(
        const CreateMatchConfiguration& configuration, bool retry = false) {
        if (social_client == nullptr || social_start_generation.has_value()) return false;
        if (!retry && social_start_retry_configuration) return false;
        const auto snapshot = social_client->snapshot();
        if (!snapshot.lobby.has_value() ||
            snapshot.lobby->owner_id != friends_lobby_menu.local_account_id() ||
            snapshot.lobby->state != "forming") {
            settings_warning = "Only the lobby owner can start this match";
            return false;
        }
        network::RevivalSocialRequest request;
        request.generation = background_social_generation();
        request.kind = network::RevivalSocialRequestKind::lobby_action;
        request.priority = true;
        request.lobby_id = snapshot.lobby->id;
        request.action = "start";
        if (!retry) {
            social_pending_start_id = network::new_revival_social_id();
            social_start_revision_retries = 0U;
            social_start_retry_configuration.reset();
        }
        if (social_settings_generation || social_desired_configuration || social_settings_waiting_for_sync) {
            social_pending_start_lobby_id = snapshot.lobby->id;
            social_start_retry_configuration = configuration;
            create_match_menu.set_host_authority(false);
            settings_warning = "Saving your latest settings before starting...";
            return true;
        }
        request.payload = nlohmann::json{{"settings", social_settings(configuration)},
            {"max_members", configuration.max_players}, {"privacy", social_privacy(configuration.privacy)}};
        if (snapshot.lobby->lobby_type != "ugc") social_pending_ugc_start.reset();
        if (snapshot.lobby->lobby_type == "ugc" && social_pending_ugc_start) {
            request.payload = nlohmann::json{{"settings", ugc_social_settings(*social_pending_ugc_start)},
                {"max_members", social_pending_ugc_start->maximum_players}};
            request.payload["privacy"] = ugc_social_privacy(social_pending_ugc_start->privacy);
        }
        request.payload["revision"] = snapshot.lobby->revision;
        request.payload["start_id"] = social_pending_start_id;
        const auto generation = request.generation;
        if (!social_client->enqueue(std::move(request))) return false;
        social_start_generation = generation;
        social_pending_start_lobby_id = snapshot.lobby->id;
        social_start_deadline = std::chrono::steady_clock::now() + std::chrono::seconds{30};
        social_pending_start_configuration = configuration;
        create_match_menu.set_host_authority(false);
        settings_warning = "Starting the lobby match...";
        return true;
    }

    void queue_social_settings(const CreateMatchConfiguration& configuration) {
        if (social_client == nullptr) return;
        const auto snapshot = social_client->snapshot();
        if (!snapshot.lobby.has_value() ||
            snapshot.lobby->owner_id != friends_lobby_menu.local_account_id() ||
            snapshot.lobby->state != "forming" || social_start_generation.has_value()) {
            return;
        }
        social_desired_configuration = configuration;
    }

    void pump_social_settings_update() {
        if (social_client == nullptr || social_settings_generation.has_value() ||
            social_settings_waiting_for_sync || !social_desired_configuration.has_value()) {
            return;
        }
        const auto snapshot = social_client->snapshot();
        if (!snapshot.lobby.has_value() || snapshot.lobby->revision.empty() ||
            snapshot.lobby->owner_id != friends_lobby_menu.local_account_id() ||
            snapshot.lobby->state != "forming" || social_start_generation.has_value()) {
            social_desired_configuration.reset();
            return;
        }
        const auto desired = *social_desired_configuration;
        network::RevivalSocialRequest request;
        request.generation = background_social_generation();
        request.kind = network::RevivalSocialRequestKind::lobby_action;
        request.priority = true;
        request.coalesce_key = "lobby-settings";
        request.lobby_id = snapshot.lobby->id;
        request.action = "update";
        request.payload = nlohmann::json{{"revision", snapshot.lobby->revision},
                                         {"privacy", social_privacy(desired.privacy)},
                                         {"max_members", desired.max_players},
                                         {"settings", social_settings(desired)}};
        const auto generation = request.generation;
        if (!social_client->enqueue(std::move(request))) return;
        social_settings_generation = generation;
        social_sent_configuration = desired;
        social_desired_configuration.reset();
    }

    [[nodiscard]] std::optional<std::pair<std::string, std::string>>
    invitation_target(std::string_view invitation_id) const {
        const auto found = std::ranges::find(friends_lobby_menu.snapshot().invitations,
                                             invitation_id,
                                             &FriendsLobbyInvitation::id);
        if (found == friends_lobby_menu.snapshot().invitations.end()) return std::nullopt;
        return std::pair{found->lobby_id, found->id};
    }

    void submit_social_intent(FriendsLobbyIntent intent) {
        const auto now = std::chrono::steady_clock::now();
        if (config.debug_ui && config.debug_ui->starts_with("friends") &&
            intent.kind != FriendsLobbyActionKind::back) {
            if (const auto operation = friends_lobby_menu.begin(intent, now)) {
                static_cast<void>(friends_lobby_menu.complete(operation->generation, false,
                    "Design preview only. Open Friends from the main menu to play online.", now));
            }
            return;
        }
        if (intent.kind == FriendsLobbyActionKind::open_lobby) {
            if (social_client != nullptr) open_social_match_lobby(social_client->snapshot());
            return;
        }
        if (intent.kind == FriendsLobbyActionKind::start_lobby && social_client != nullptr) {
            const auto snapshot = social_client->snapshot();
            if (snapshot.lobby && snapshot.lobby->lobby_type == "ugc") {
                open_social_match_lobby(snapshot);
                social_pending_ugc_start = ugc_editor_lobby.configuration();
                if (!start_active_social_lobby(CreateMatchConfiguration{})) social_pending_ugc_start.reset();
                return;
            }
            if (snapshot.lobby) {
                open_social_match_lobby(snapshot);
                if (!start_active_social_lobby(social_configuration(*snapshot.lobby)))
                    settings_warning = "Could not start the lobby. Please retry.";
                return;
            }
        }
        if (intent.kind == FriendsLobbyActionKind::back) {
            const auto snapshot = social_client != nullptr
                ? social_client->snapshot() : network::RevivalSocialSnapshot{};
            if (snapshot.lobby && !snapshot.lobby->server_id.empty())
                social_canceled_join = std::array{snapshot.lobby->id, snapshot.lobby->start_id,
                                                  snapshot.lobby->server_id};
            if (social_join_worker.joinable()) social_join_worker.request_stop();
            social_open_match_generation.reset();
            social_open_match_lobby_id.clear();
            pending_social_lobby_navigation.reset();
            friends_lobby_menu.leave();
            static_cast<void>(window.set_text_input_enabled(false));
            static_cast<void>(navigation.pop());
            play_back();
            return;
        }
        auto operation = friends_lobby_menu.begin(intent, now);
        if (!operation.has_value()) {
            if (intent.kind == FriendsLobbyActionKind::create_lobby && is_create_match_screen(screen()))
                settings_warning = "Online lobbies are unavailable. Use Local Match or reconnect and retry.";
            return;
        }

        if (intent.kind == FriendsLobbyActionKind::create_lobby ||
            intent.kind == FriendsLobbyActionKind::accept_lobby_invite ||
            intent.kind == FriendsLobbyActionKind::join_friend_lobby) {
            social_open_match_generation = operation->generation;
            social_open_match_lobby_id = intent.kind == FriendsLobbyActionKind::join_friend_lobby
                ? intent.target_id : std::string{};
            if (intent.kind == FriendsLobbyActionKind::accept_lobby_invite) {
                if (const auto target = invitation_target(intent.target_id))
                    social_open_match_lobby_id = target->first;
            }
            if (is_create_match_screen(screen())) {
                create_match_menu.set_host_authority(false);
                settings_warning = "Creating your online lobby...";
            }
        }

        if (intent.kind == FriendsLobbyActionKind::join_game) {
            if (social_leave_generation) {
                static_cast<void>(friends_lobby_menu.complete(operation->generation, false,
                    "Wait for Leave Lobby to finish before joining a match.", now));
                return;
            }
            social_canceled_join.reset();
            if (!begin_social_lobby_join(operation->generation, std::move(intent.target_id))) {
                static_cast<void>(friends_lobby_menu.complete(
                    operation->generation, false,
                    "The previous lobby connection is still cancelling. Please retry.", now));
            } else if (is_create_match_screen(screen())) {
                create_match_menu.set_match_join_available(true, true);
                settings_warning = "Finding the lobby server...";
            }
            return;
        }

        network::RevivalSocialRequest request;
        request.generation = operation->generation;
        request.priority = intent.kind == FriendsLobbyActionKind::create_lobby ||
                           intent.kind == FriendsLobbyActionKind::accept_lobby_invite ||
                           intent.kind == FriendsLobbyActionKind::join_friend_lobby ||
                           intent.kind == FriendsLobbyActionKind::invite_friend ||
                           intent.kind == FriendsLobbyActionKind::decline_lobby_invite ||
                           intent.kind == FriendsLobbyActionKind::send_friend_request ||
                           intent.kind == FriendsLobbyActionKind::accept_friend_request ||
                           intent.kind == FriendsLobbyActionKind::decline_friend_request ||
                           intent.kind == FriendsLobbyActionKind::remove_friend ||
                           intent.kind == FriendsLobbyActionKind::leave_lobby ||
                           intent.kind == FriendsLobbyActionKind::start_lobby;
        request.target = intent.target_id;
        switch (intent.kind) {
        case FriendsLobbyActionKind::search:
            request.kind = network::RevivalSocialRequestKind::find_friends;
            request.query = intent.text;
            request.coalesce_key = "friend-lookup";
            break;
        case FriendsLobbyActionKind::accept_friend_request:
        case FriendsLobbyActionKind::decline_friend_request:
        case FriendsLobbyActionKind::remove_friend:
        case FriendsLobbyActionKind::send_friend_request:
            request.kind = network::RevivalSocialRequestKind::friend_action;
            request.action = intent.kind == FriendsLobbyActionKind::send_friend_request
                                 ? "request"
                             : intent.kind == FriendsLobbyActionKind::accept_friend_request
                                 ? "accept"
                             : intent.kind == FriendsLobbyActionKind::decline_friend_request
                                 ? "decline"
                                 : "remove";
            break;
        case FriendsLobbyActionKind::join_friend_lobby:
            request.kind = network::RevivalSocialRequestKind::lobby_action;
            request.lobby_id = intent.target_id;
            request.action = "join";
            break;
        case FriendsLobbyActionKind::create_lobby:
            request.kind = network::RevivalSocialRequestKind::create_lobby;
            request.payload = nlohmann::json{
                {"name", config.player_name + "'s Lobby"},
                {"privacy", social_privacy(create_match_menu.configuration().privacy)},
                {"max_members", create_match_menu.configuration().max_players},
                {"settings", social_settings(create_match_menu.configuration())}};
            if (!intent.target_id.empty()) {
                // The collection endpoint creates the lobby and invitation in
                // one database transaction, avoiding a race with social sync.
                request.payload["invite_target"] = intent.target_id;
            }
            break;
        case FriendsLobbyActionKind::accept_lobby_invite: {
            const auto target = invitation_target(intent.target_id);
            if (!target.has_value()) {
                static_cast<void>(friends_lobby_menu.complete(
                    operation->generation, false, "That invitation has expired.", now));
                return;
            }
            request.kind = network::RevivalSocialRequestKind::lobby_action;
            request.lobby_id = target->first;
            request.action = "join";
            request.payload = nlohmann::json{{"invitation_id", target->second}};
            break;
        }
        case FriendsLobbyActionKind::decline_lobby_invite: {
            const auto target = invitation_target(intent.target_id);
            if (!target.has_value()) {
                static_cast<void>(friends_lobby_menu.complete(
                    operation->generation, false, "That invitation has expired.", now));
                return;
            }
            request.kind = network::RevivalSocialRequestKind::lobby_action;
            request.lobby_id = target->first;
            request.action = "decline_invite";
            request.payload = nlohmann::json{{"invitation_id", target->second}};
            break;
        }
        case FriendsLobbyActionKind::invite_friend:
            if (!friends_lobby_menu.snapshot().lobby.has_value()) {
                static_cast<void>(friends_lobby_menu.complete(
                    operation->generation, false, "Create a lobby before inviting friends.", now));
                return;
            }
            request.kind = network::RevivalSocialRequestKind::lobby_action;
            request.lobby_id = friends_lobby_menu.snapshot().lobby->id;
            request.action = "invite";
            break;
        case FriendsLobbyActionKind::leave_lobby:
        case FriendsLobbyActionKind::start_lobby:
            if (!friends_lobby_menu.snapshot().lobby.has_value()) {
                static_cast<void>(friends_lobby_menu.complete(
                    operation->generation, false, "The lobby is no longer available.", now));
                return;
            }
            request.kind = network::RevivalSocialRequestKind::lobby_action;
            request.lobby_id = friends_lobby_menu.snapshot().lobby->id;
            request.action = intent.kind == FriendsLobbyActionKind::leave_lobby ? "leave" : "start";
            break;
        case FriendsLobbyActionKind::retry:
        case FriendsLobbyActionKind::open_lobby:
        case FriendsLobbyActionKind::back:
        case FriendsLobbyActionKind::join_game:
            static_cast<void>(friends_lobby_menu.complete(
                operation->generation, false, "That action is not available.", now));
            return;
        }
        if (!social_client->enqueue(std::move(request))) {
            static_cast<void>(friends_lobby_menu.complete(
                operation->generation, false, "The social queue is busy. Please retry.", now));
            if (social_open_match_generation == operation->generation) {
                social_open_match_generation.reset();
            }
        }
    }

    /** Resolve one opaque social server ID without blocking the render loop. */
    [[nodiscard]] bool begin_social_lobby_join(std::uint64_t generation,
                                                std::string server_id) {
        if (social_join_worker.joinable()) {
            if (social_join_active.load(std::memory_order_acquire)) return false;
            social_join_worker.request_stop();
            social_join_worker.join();
        }
        {
            std::scoped_lock lock{social_join_mutex};
            social_join_outcome.reset();
        }
        const auto public_url = config.public_server_list_url;
        const auto snapshot = social_client != nullptr ? social_client->snapshot() : network::RevivalSocialSnapshot{};
        const bool follows_lobby = snapshot.lobby && snapshot.lobby->server_id == server_id;
        auto lobby_id = follows_lobby ? snapshot.lobby->id : std::string{};
        auto start_id = follows_lobby ? snapshot.lobby->start_id : std::string{};
        social_join_active.store(true, std::memory_order_release);
        social_join_worker = std::jthread{
            [this, generation, server_id = std::move(server_id), public_url,
             lobby_id = std::move(lobby_id), start_id = std::move(start_id)](
                std::stop_token stop) mutable {
                network::PublicDiscoveryConfig discovery_config;
                discovery_config.url = public_url;
                discovery_config.timeout = std::chrono::milliseconds{6'000};
                auto discovery = network::discover_public_servers(discovery_config, stop);
                if (stop.stop_requested()) {
                    social_join_active.store(false, std::memory_order_release);
                    return;
                }
                std::scoped_lock lock{social_join_mutex};
                social_join_outcome =
                    SocialJoinOutcome{generation, std::move(server_id), std::move(discovery),
                                      std::move(lobby_id), std::move(start_id)};
                social_join_active.store(false, std::memory_order_release);
            }};
        return true;
    }

    /**
     * Complete Join only after the master ID resolves to its current relay.
     * Generation validation makes late resolver results harmless.
     */
    void pump_social_lobby_join() {
        std::optional<SocialJoinOutcome> outcome;
        {
            std::scoped_lock lock{social_join_mutex};
            outcome = std::move(social_join_outcome);
            social_join_outcome.reset();
        }
        if (!outcome.has_value()) return;
        if (social_leave_generation) return;
        if (!outcome->lobby_id.empty()) {
            const auto snapshot = social_client != nullptr ? social_client->snapshot() : network::RevivalSocialSnapshot{};
            if (!snapshot.lobby || snapshot.lobby->id != outcome->lobby_id ||
                snapshot.lobby->start_id != outcome->start_id || snapshot.lobby->server_id != outcome->server_id) {
                static_cast<void>(friends_lobby_menu.complete(outcome->generation, false,
                    "The lobby changed before the server could be joined.", std::chrono::steady_clock::now()));
                return;
            }
        }
        const auto found = network::find_discovered_server(
            outcome->discovery.servers, outcome->server_id);
        if (!found.has_value()) {
            const auto reason = outcome->discovery.error.empty()
                                    ? "That lobby's server is no longer published."
                                    : "Could not resolve the lobby server: " +
                                          outcome->discovery.error;
            const auto accepted = friends_lobby_menu.complete(
                outcome->generation, false, reason, std::chrono::steady_clock::now());
            if (accepted && is_create_match_screen(screen())) settings_warning = reason;
            // Publication and public-list reads are eventually consistent.
            // Do not remember a failed lookup as joined: the authoritative
            // lobby poll must be allowed to retry the same server ID.
            if (social_last_joined_server_id == outcome->server_id) {
                social_last_joined_server_id.clear();
            }
            social_join_retry_at = std::chrono::steady_clock::now() +
                                   std::chrono::seconds{1};
            return;
        }
        const auto now = std::chrono::steady_clock::now();
        if (!friends_lobby_menu.complete(outcome->generation, true, {}, now)) return;
        social_last_joined_server_id = outcome->server_id;
        social_joined_lobby_id = outcome->lobby_id;
        social_joined_start_id = outcome->start_id;
        social_join_retry_at = {};
        begin_match_loading(ServerConnectRequest{found->game.identifier(),
                                                  found->game.host,
                                                  found->game.port,
                                                  found->map,
                                                  found->mode_code,
                                                  found->texture_skin,
                                                  found->classic,
                                                  found->master_identifier,
                                                  found->identity_ticket});
    }

    /** Move all potentially blocking host shutdown off the presentation thread. */
    void retire_local_host(LocalHostOutcome outcome) {
        if (!outcome.process && !outcome.tunnel && !outcome.relay) return;
        auto reservation = std::move(outcome.cleanup);
        reservation.defer(std::packaged_task<void()>{
            [service = identity_service, outcome = std::move(outcome)]() mutable {
                if (outcome.tunnel) outcome.tunnel->stop();
                if (outcome.process) outcome.process->stop();
                if (outcome.relay && service) {
                    static_cast<void>(service->close_relay_lobby(*outcome.relay));
                }
            }});
    }

    /**
     * Start Steam once per session.
     *
     * The client attaches at launch so Steam reports the game as running and
     * the friends list is reachable; a match that arrives first starts it
     * instead. Failure is ordinary: a player without Steam keeps the AoSPlay
     * relay.
     *
     * The launch attempt passes a zero relay timeout. Steam is reached in a
     * few hundred milliseconds, but its relay network needs seconds, and the
     * boot frames cannot wait for that; the pump thread keeps warming the
     * relays while the player is still in the menus.
     */
    [[nodiscard]] bool ensure_steam_runtime(
        std::chrono::seconds relay_timeout = std::chrono::seconds{20}) {
#if defined(AOS_HAS_STEAM_NETWORKING)
        if (steam_runtime.ready()) return true;
        if (steam_runtime_attempted) return false;
        steam_runtime_attempted = true;
        platform::SteamNetworkingRuntimeConfig steam_config;
        steam_config.search_directory = config.executable_directory;
        steam_config.relay_timeout = relay_timeout;
        std::string error;
        if (!steam_runtime.start(std::move(steam_config), error)) {
            core::diagnostic("steam", "unavailable, using the AoSPlay relay: " + error);
            return false;
        }
        return true;
#else
        static_cast<void>(relay_timeout);
        return false;
#endif
    }

    /**
     * Attach to Steam at launch so the player shows as in-game.
     *
     * A player may start Steam after the game, so a failed launch attempt
     * leaves the retry to the first match rather than standing for the session.
     */
    void attach_steam_for_presence() {
#if defined(AOS_HAS_STEAM_NETWORKING)
        if (!ensure_steam_runtime(std::chrono::seconds{0})) steam_runtime_attempted = false;
#endif
    }

    /** Accept friends over Valve's relays; returns the id they connect to. */
    [[nodiscard]] std::uint64_t start_steam_host(std::uint16_t local_server_port,
                                                 std::string server_identifier) {
#if defined(AOS_HAS_STEAM_NETWORKING)
        steam_host.stop();
        if (local_server_port == 0U || !ensure_steam_runtime()) return 0U;
        // The launch attach returns before the relays are up, so a match made
        // seconds later waits here rather than listening where Steam cannot
        // route friends to it yet.
        static_cast<void>(steam_runtime.wait_for_relays(std::chrono::seconds{15}));
        platform::SteamP2PHostConfig host_config;
        host_config.local_server_port = local_server_port;
        host_config.server_identifier = std::move(server_identifier);
        std::string error;
        if (!steam_host.start(steam_runtime, std::move(host_config), error)) {
            core::diagnostic("steam", "hosting over the relay network failed: " + error);
            return 0U;
        }
        return steam_runtime.steam_id();
#else
        static_cast<void>(local_server_port);
        static_cast<void>(server_identifier);
        return 0U;
#endif
    }

    /** Join a Steam host; returns the loopback port Protocol 168 connects to. */
    [[nodiscard]] std::uint16_t start_steam_client(std::uint64_t host_steam_id,
                                                   std::string& error) {
#if defined(AOS_HAS_STEAM_NETWORKING)
        steam_client.stop();
        if (!ensure_steam_runtime()) {
            error = "Steam is not running, so this match cannot be joined";
            return 0U;
        }
        // A connection opened before the relays are up is never routed, and
        // --connect runs immediately after the launch attach, which does not
        // wait for them.
        static_cast<void>(steam_runtime.wait_for_relays(std::chrono::seconds{15}));
        platform::SteamP2PClientConfig client_config;
        client_config.host_steam_id = host_steam_id;
        if (!steam_client.start(steam_runtime, std::move(client_config), error)) {
            core::diagnostic("steam", "joining " + std::to_string(host_steam_id) +
                                          " failed: " + error);
            return 0U;
        }
        // The hello names the AoSPlay server the match registered under. Joining
        // without a ticket for it had the whole map come across and then the
        // server reject the player as unverified.
        auto hello = steam_client.wait_for_host_hello(std::chrono::seconds{30});
        if (!hello.has_value()) {
            error = steam_client.last_error();
            if (error.empty()) error = "the Steam host did not answer";
            core::diagnostic("steam", "joining " + std::to_string(host_steam_id) +
                                          " failed: " + error);
            steam_client.stop();
            return 0U;
        }
        steam_join_server_id = std::move(*hello);
        core::diagnostic("steam", steam_join_server_id.empty()
                                      ? std::string{"the host needs no AoSPlay identity"}
                                      : "the host asks for a ticket for " + steam_join_server_id);
        return steam_client.local_port();
#else
        static_cast<void>(host_steam_id);
        error = "this build has no Steam transport";
        return 0U;
#endif
    }

    /**
     * A player-hosted match verifies a ticket it is offered but does not
     * demand one, so a joiner presents its AoSPlay identity when it has an
     * online session and otherwise joins as a plain player.
     */
    [[nodiscard]] bool steam_join_wants_ticket() const {
        return !steam_join_server_id.empty() && identity_service != nullptr &&
               identity_service->has_online_session();
    }

    void stop_steam_client() noexcept {
#if defined(AOS_HAS_STEAM_NETWORKING)
        steam_client.stop();
#endif
    }

    void stop_steam_host() noexcept {
#if defined(AOS_HAS_STEAM_NETWORKING)
        steam_host.stop();
#endif
        steam_host_id = 0U;
    }

    /** Stop and unpublish every resource owned by a client-hosted match. */
    void release_owned_local_match_host() {
        stop_steam_host();
        if (local_host_cancel != nullptr) local_host_cancel->request_stop();
        active_local_host_generation = 0U;
        owned_social_lobby_id.clear();
        owned_social_start_id.clear();
        social_publish_generation.reset();
        social_pending_owner_connect.reset();
        social_publish_attempts = 0U;
        LocalHostOutcome retired;
        retired.process = std::move(owned_local_server);
        retired.tunnel = std::move(owned_relay_tunnel);
        retired.relay = std::move(owned_relay_lobby);
        retired.cleanup = std::move(owned_host_cleanup);
        owned_relay_lobby.reset();
        retire_local_host(std::move(retired));
        hosted_results_retry_at = {};
    }

    /** Ask AoSPlay to return a failed lobby start to its editable state. */
    void queue_social_start_failed(std::string message) {
        if (social_client == nullptr) return;
        const auto snapshot = social_client->snapshot();
        const auto& lobby_id = owned_social_lobby_id.empty() ? social_pending_start_lobby_id : owned_social_lobby_id;
        const auto& attempt = owned_social_start_id.empty() ? social_pending_start_id : owned_social_start_id;
        if (!snapshot.lobby.has_value() ||
            lobby_id.empty() || attempt.empty() || snapshot.lobby->id != lobby_id ||
            snapshot.lobby->owner_id != friends_lobby_menu.local_account_id()) {
            return;
        }
        network::RevivalSocialRequest request;
        request.generation = background_social_generation();
        request.kind = network::RevivalSocialRequestKind::lobby_action;
        request.priority = true;
        request.lobby_id = snapshot.lobby->id;
        request.action = "start_failed";
        request.payload = nlohmann::json{{"message", std::move(message)}};
        request.payload["start_id"] = attempt;
        static_cast<void>(social_client->enqueue(std::move(request)));
    }

    /**
     * Publish the already-running relay into the social lobby.
     *
     * AoSPlay accepts this only after the authoritative server has completed
     * at least one authenticated heartbeat. A bounded retry therefore closes
     * the race between local A2S readiness and public master readiness.
     */
    [[nodiscard]] bool queue_social_publish() {
        if (social_client == nullptr || social_publish_generation.has_value() ||
            !owned_relay_lobby.has_value() ||
            !social_pending_owner_connect.has_value()) {
            return false;
        }
        const auto snapshot = social_client->snapshot();
        if (!snapshot.lobby.has_value() ||
            snapshot.lobby->owner_id != friends_lobby_menu.local_account_id()) {
            return false;
        }
        network::RevivalSocialRequest request;
        request.generation = background_social_generation();
        request.kind = network::RevivalSocialRequestKind::lobby_action;
        request.priority = true;
        request.lobby_id = snapshot.lobby->id;
        request.action = "publish";
        request.payload = nlohmann::json{
            {"relay_lobby_id", owned_relay_lobby->lobby_id},
            {"server_id", owned_relay_lobby->server_id}};
        if (!owned_social_start_id.empty()) request.payload["start_id"] = owned_social_start_id;
        const auto generation = request.generation;
        if (!social_client->enqueue(std::move(request))) return false;
        social_publish_generation = generation;
        ++social_publish_attempts;
        settings_warning = "Publishing the community match to the lobby...";
        return true;
    }

    void show_host_start_failure(std::string message) {
        match_loading.fail("SERVER_CONNECTION_FAILED");
        std::fprintf(stderr, "[hosting] %s\n", message.c_str());
        // Keep the map/rules editable and the concrete failure visible. A
        // relay outage must not strand the host on a generic failed loader.
        const auto newline = message.find_first_of("\r\n");
        settings_warning = message.substr(0U, std::min<std::size_t>(newline, 300U));
        static_cast<void>(navigation.leave_match_instant());
    }

    void fail_social_host_start(std::string message) {
        social_pending_ugc_start.reset();
        if (message.empty()) message = "The public match could not be published.";
        queue_social_start_failed(message);
        show_host_start_failure(std::move(message));
        release_owned_local_match_host();
    }

    /**
     * A disconnected HTTP response does not prove that a write failed.
     * PostgreSQL may have committed before the socket vanished.  These
     * outcomes stay pending until the next authoritative sync proves success
     * or the menu's bounded deadline expires.
     */
    [[nodiscard]] static bool social_write_may_have_committed(
        const network::RevivalSocialResult& result) noexcept {
        if (result ||
            (result.request.kind != network::RevivalSocialRequestKind::friend_action &&
             result.request.kind != network::RevivalSocialRequestKind::create_lobby &&
             result.request.kind != network::RevivalSocialRequestKind::lobby_action)) {
            return false;
        }
        if (result.http_status == 0L || result.http_status >= 500L) return true;
        if (result.request.kind == network::RevivalSocialRequestKind::create_lobby &&
            result.error_code == "active_lobby_exists") {
            return true;
        }
        if (result.request.kind == network::RevivalSocialRequestKind::friend_action &&
            result.error_code == "friend_request_missing") {
            return true;
        }
        return result.request.kind == network::RevivalSocialRequestKind::lobby_action &&
               result.request.action == "leave" &&
               result.error_code == "lobby_not_found";
    }

    void pump_social_publish_retry(std::chrono::steady_clock::time_point now) {
        if (!social_pending_owner_connect.has_value() ||
            social_publish_generation.has_value()) {
            return;
        }
        if (now >= social_publish_deadline) {
            fail_social_host_start(
                "The server started locally, but AoSPlay did not confirm its public relay in time.");
            return;
        }
        if (now >= social_publish_retry_at && !queue_social_publish()) {
            social_publish_retry_at = now + std::chrono::milliseconds{250};
        }
    }

    void pump_social() {
        if (config.debug_ui && config.debug_ui->starts_with("friends")) return;
        if (social_client == nullptr) return;
        const auto now = std::chrono::steady_clock::now();
        if (social_open_match_generation && ugc_create_deadline == std::chrono::steady_clock::time_point{}) {
            const auto operation = friends_lobby_menu.operation();
            if (!operation || operation->generation != *social_open_match_generation ||
                now >= operation->deadline) {
                social_open_match_generation.reset();
                social_open_match_lobby_id.clear();
                if (social_leave_after_create && is_create_match_screen(screen()))
                    static_cast<void>(navigation.pop());
            }
        }
        social_client->tick(now);
        for (auto result : social_client->drain(now)) {
            if (ugc_settings_generation == result.request.generation) {
                ugc_settings_generation.reset();
                ugc_settings_retry_at = now + std::chrono::seconds{2};
                if (!result) {
                    settings_warning = result.error;
                    // Keep the draft for transient errors; a rejected value
                    // must converge to the owner's authoritative settings.
                    if (!social_write_may_have_committed(result) &&
                        result.error_code != "lobby_revision_conflict") ugc_social_owner_id.clear();
                }
                continue;
            }
            if (ugc_discovery_generation == result.request.generation) {
                ugc_discovery_generation.reset();
                if (screen() == FrontendScreen::ugc_editor_browser) {
                    std::vector<UgcEditorLobbyRecord> rows;
                    if (result) for (const auto& lobby : result.snapshot.lobbies) {
                        if (lobby.lobby_type != "ugc") continue;
                        const auto friends = social_client->snapshot().friends;
                        if (ugc_editor_browser.source() == UgcEditorLobbySource::friends &&
                            !std::ranges::any_of(friends, [&](const auto& friend_row) {
                                return friend_row.legacy_id == lobby.owner_id;
                            }) && lobby.owner_id != friends_lobby_menu.local_account_id()) continue;
                        rows.push_back({lobby.id, lobby.name,
                            static_cast<std::uint16_t>(std::max(lobby.member_count, lobby.members.size())),
                            static_cast<std::uint16_t>(lobby.maximum_members), 0U, lobby.privacy == "open"});
                    }
                    static_cast<void>(ugc_editor_browser.complete_refresh(std::move(rows), static_cast<bool>(result)));
                }
                continue;
            }
            if (result) apply_social_lobby_events(result.snapshot);
            if (result.request.kind == network::RevivalSocialRequestKind::sync) {
                if (result && social_settings_waiting_for_sync) {
                    social_settings_waiting_for_sync = false;
                }
                continue;
            }
            if (social_leave_generation == result.request.generation) {
                if (result) {
                    social_leave_generation.reset();
                    release_owned_local_match_host();
                    social_desired_configuration.reset();
                    social_settings_generation.reset();
                    social_sent_configuration.reset();
                    social_settings_waiting_for_sync = false;
                    social_start_generation.reset();
                    social_pending_start_configuration.reset();
                    social_pending_ugc_start.reset();
                    ugc_social_lobby_id.clear();
                    ugc_settings_generation.reset();
                    create_match_menu.set_host_authority(true);
                    settings_warning.clear();
                    if (is_create_match_screen(screen())) {
                        static_cast<void>(navigation.pop());
                    }
                } else if (social_write_may_have_committed(result)) {
                    settings_warning = "Confirming that the lobby was left...";
                } else {
                    social_leave_generation.reset();
                    settings_warning = result.error.empty()
                                           ? "Leave Lobby failed. Please retry."
                                           : result.error;
                }
                continue;
            }
            if (social_settings_generation == result.request.generation) {
                social_settings_generation.reset();
                if (!result) {
                    if (!social_desired_configuration.has_value() &&
                        social_sent_configuration.has_value()) {
                        social_desired_configuration = social_sent_configuration;
                    }
                    settings_warning = result.error_code == "lobby_revision_conflict"
                                           ? "Lobby settings changed; synchronizing and retrying."
                                           : result.error;
                    social_settings_waiting_for_sync =
                        result.error_code == "lobby_revision_conflict";
                } else {
                    settings_warning.clear();
                    social_settings_waiting_for_sync = false;
                }
                social_sent_configuration.reset();
                continue;
            }
            if (social_start_generation == result.request.generation) {
                if (!result && result.error_code == "lobby_revision_conflict" &&
                    social_start_revision_retries < 3U && social_pending_start_configuration) {
                    ++social_start_revision_retries;
                    social_start_retry_configuration = social_pending_start_configuration;
                    social_pending_start_configuration.reset();
                    social_start_generation.reset();
                    social_settings_waiting_for_sync = true;
                    settings_warning = "Lobby settings changed; confirming the latest revision before starting...";
                } else if (!result && social_write_may_have_committed(result)) {
                    settings_warning = "Confirming that the lobby match started...";
                } else if (!result || !social_pending_start_configuration.has_value()) {
                    social_start_generation.reset();
                    settings_warning = result.error.empty()
                                           ? "The lobby could not start."
                                           : result.error;
                    social_pending_start_configuration.reset();
                    social_pending_ugc_start.reset();
                } else if (!result.snapshot.lobby ||
                           result.snapshot.lobby->id != social_pending_start_lobby_id ||
                           result.snapshot.lobby->owner_id != friends_lobby_menu.local_account_id() ||
                           result.snapshot.lobby->start_id != social_pending_start_id ||
                           (result.snapshot.lobby->state != "starting" && result.snapshot.lobby->state != "ready" &&
                            result.snapshot.lobby->state != "in_game")) {
                    social_start_generation.reset();
                    social_pending_start_configuration.reset();
                    social_pending_ugc_start.reset();
                    settings_warning = "The lobby changed before this match could start.";
                } else {
                    social_start_generation.reset();
                    const auto configuration = *social_pending_start_configuration;
                    social_pending_start_configuration.reset();
                    launch_social_session(configuration);
                }
                continue;
            }
            if (social_publish_generation == result.request.generation) {
                social_publish_generation.reset();
                if (result && social_pending_owner_connect.has_value()) {
                    auto request = std::move(*social_pending_owner_connect);
                    social_pending_owner_connect.reset();
                    social_publish_attempts = 0U;
                    settings_warning = "Community match published. Connecting...";
                    begin_match_loading(request);

                    // server_id is already authoritative after publish. This
                    // state only improves friends-list presence and is not a
                    // prerequisite for members to converge and connect.
                    network::RevivalSocialRequest in_game;
                    in_game.generation = background_social_generation();
                    in_game.kind = network::RevivalSocialRequestKind::lobby_action;
                    in_game.priority = true;
                    in_game.lobby_id = result.snapshot.lobby.has_value()
                                           ? result.snapshot.lobby->id
                                           : result.request.lobby_id;
                    in_game.action = "in_game";
                    if (!owned_social_start_id.empty()) in_game.payload["start_id"] = owned_social_start_id;
                    static_cast<void>(social_client->enqueue(std::move(in_game)));
                } else if (result.error_code == "relay_not_ready" &&
                           social_pending_owner_connect.has_value() &&
                           now < social_publish_deadline) {
                    const auto shift = std::min<std::uint32_t>(social_publish_attempts, 3U);
                    social_publish_retry_at =
                        now + std::chrono::milliseconds{250U << shift};
                    settings_warning =
                        "Waiting for the public server heartbeat before inviting the lobby...";
                } else if (social_write_may_have_committed(result) &&
                           social_pending_owner_connect.has_value() &&
                           now < social_publish_deadline) {
                    social_publish_retry_at = now + std::chrono::milliseconds{500};
                    settings_warning =
                        "Confirming the public community server with AoSPlay...";
                } else {
                    fail_social_host_start(result.error.empty()
                                               ? "The lobby rejected the public server."
                                               : result.error);
                }
                continue;
            }
            if (result.request.kind == network::RevivalSocialRequestKind::find_friends && result) {
                std::vector<FriendsLobbyFriend> matches;
                matches.reserve(result.found_players.size());
                for (const auto& row : result.found_players) {
                    matches.push_back({row.legacy_id,
                                       row.nickname.empty() ? row.username : row.nickname,
                                       row.presence,
                                       row.friendship_status,
                                       row.direction,
                                       row.current_lobby_id,
                                       row.current_server_id});
                }
                if (!friends_lobby_menu.apply_search_results(result.request.generation,
                        result.request.query, std::move(matches), now)) continue;
                if (result.found_players.empty()) {
                    static_cast<void>(friends_lobby_menu.complete(
                        result.request.generation, false, "No matching player profile was found.", now));
                    continue;
                }
                static_cast<void>(friends_lobby_menu.complete(
                    result.request.generation, true, {}, now));
                continue;
            }
            const auto reconcile_from_poll = social_write_may_have_committed(result);
            if (!reconcile_from_poll) {
                static_cast<void>(friends_lobby_menu.complete(
                    result.request.generation, static_cast<bool>(result), result.error, now));
            }
            if (social_open_match_generation.has_value() &&
                *social_open_match_generation == result.request.generation) {
                if (result && result.snapshot.lobby.has_value() &&
                    (social_open_match_lobby_id.empty() ||
                     result.snapshot.lobby->id == social_open_match_lobby_id)) {
                    if (!ugc_leave_after_create && !social_leave_after_create) open_social_match_lobby(result.snapshot);
                }
                if (!reconcile_from_poll) {
                    social_open_match_generation.reset();
                    ugc_create_deadline = {};
                    if (!result && social_leave_after_create && !result.snapshot.lobby) {
                        social_leave_after_create = false;
                        if (is_create_match_screen(screen())) static_cast<void>(navigation.pop());
                    }
                }
            }
        }
        friends_lobby_menu.apply_snapshot(
            adapt_social_snapshot(social_client->snapshot()), now);
        const auto authoritative = social_client->snapshot();
        create_match_menu.set_match_join_available(authoritative.lobby &&
            !authoritative.lobby->server_id.empty() &&
            (authoritative.lobby->state == "ready" || authoritative.lobby->state == "in_game"),
            friends_lobby_menu.busy() || social_leave_generation ||
                social_join_active.load(std::memory_order_acquire));
        if (social_leave_after_create && authoritative.lobby && !social_leave_generation &&
            leave_active_social_lobby()) {
            social_leave_after_create = false;
            social_open_match_generation.reset();
        }
        const bool pending_start_owned = authoritative.lobby &&
            authoritative.lobby->id == social_pending_start_lobby_id &&
            authoritative.lobby->owner_id == friends_lobby_menu.local_account_id();
        if (social_start_generation && !pending_start_owned) {
            social_start_generation.reset();
            social_pending_start_configuration.reset();
            social_pending_ugc_start.reset();
        }
        if (social_start_retry_configuration && !pending_start_owned)
            social_start_retry_configuration.reset();
        if (!owned_social_lobby_id.empty() &&
            (!authoritative.lobby || authoritative.lobby->id != owned_social_lobby_id ||
             authoritative.lobby->owner_id != friends_lobby_menu.local_account_id() ||
             authoritative.lobby->state == "forming" || authoritative.lobby->state == "closed" ||
             (!owned_social_start_id.empty() && authoritative.lobby->start_id != owned_social_start_id))) {
            release_owned_local_match_host();
            teardown_tutorial();
            static_cast<void>(navigation.leave_match_instant());
            settings_warning = "The lobby or hosted match changed. The previous server was stopped.";
        }
        if (!social_joined_lobby_id.empty() &&
            (!authoritative.lobby || authoritative.lobby->id != social_joined_lobby_id ||
             authoritative.lobby->start_id != social_joined_start_id ||
             authoritative.lobby->server_id != social_last_joined_server_id)) {
            social_joined_lobby_id.clear();
            social_joined_start_id.clear();
            social_last_joined_server_id.clear();
            teardown_tutorial();
            static_cast<void>(navigation.leave_match_instant());
            settings_warning = "The hosted match ended or the lobby changed. Returned to the lobby.";
        }
        if (!social_match_lobby_id.empty() && !authoritative.lobby) {
            social_match_lobby_id.clear();
            social_match_owner_id.clear();
            social_desired_configuration.reset();
            social_sent_configuration.reset();
            social_settings_generation.reset();
            social_settings_waiting_for_sync = false;
            create_match_menu.set_host_authority(false);
            create_match_menu.set_players({});
            while (is_create_match_screen(screen())) {
                if (!navigation.pop_instant()) break;
            }
            settings_warning = "The lobby has closed or you are no longer a member.";
        }
        if (ugc_leave_after_create && authoritative.lobby && authoritative.lobby->lobby_type == "ugc" &&
            !social_leave_generation && leave_active_social_lobby()) {
            ugc_leave_after_create = false;
            social_open_match_generation.reset();
        }
        if (!ugc_social_lobby_id.empty() && !authoritative.lobby) {
            ugc_social_lobby_id.clear();
            ugc_social_owner_id.clear();
            ugc_settings_generation.reset();
            social_pending_ugc_start.reset();
            ugc_editor_lobby.set_host_authority(false);
            if (screen() == FrontendScreen::ugc_editor_lobby) {
                settings_warning = "The editor lobby has closed or you are no longer a member.";
                static_cast<void>(navigation.pop());
            }
        }
        if (authoritative.lobby && authoritative.lobby->lobby_type == "ugc" &&
            screen() == FrontendScreen::ugc_editor_lobby) sync_ugc_social_lobby(authoritative);

        // Recover every state-changing transition from the authoritative poll
        // as well as from its direct HTTP response.  This is essential on
        // Wi-Fi/mobile networks where the database commit can outlive the
        // response socket, and it makes macOS and Windows converge identically.
        if (social_open_match_generation.has_value() &&
            authoritative.lobby.has_value() &&
            (social_open_match_lobby_id.empty() || authoritative.lobby->id == social_open_match_lobby_id)) {
            static_cast<void>(friends_lobby_menu.complete(
                *social_open_match_generation, true, {}, now));
            social_open_match_generation.reset();
            ugc_create_deadline = {};
            if (screen() == FrontendScreen::friends_lobby || screen() == FrontendScreen::ugc_editor_browser ||
                screen() == FrontendScreen::ugc_editor_lobby) {
                open_social_match_lobby(authoritative);
            }
        }
        if (social_leave_generation.has_value() && !authoritative.lobby.has_value()) {
            social_leave_generation.reset();
            release_owned_local_match_host();
            social_desired_configuration.reset();
            social_settings_generation.reset();
            social_sent_configuration.reset();
            social_settings_waiting_for_sync = false;
            social_start_generation.reset();
            social_pending_start_configuration.reset();
            social_pending_ugc_start.reset();
            ugc_settings_generation.reset();
            create_match_menu.set_host_authority(true);
            settings_warning.clear();
            if (is_create_match_screen(screen())) {
                static_cast<void>(navigation.pop());
            }
        }
        if (social_start_generation.has_value() &&
            social_pending_start_configuration.has_value() &&
            authoritative.lobby.has_value() &&
            pending_start_owned &&
            authoritative.lobby->start_id == social_pending_start_id &&
            authoritative.lobby->owner_id == friends_lobby_menu.local_account_id() &&
            (authoritative.lobby->state == "starting" ||
             authoritative.lobby->state == "ready" ||
             authoritative.lobby->state == "in_game")) {
            social_start_generation.reset();
            const auto configuration = *social_pending_start_configuration;
            social_pending_start_configuration.reset();
            launch_social_session(configuration);
        }
        if (!authoritative.lobby.has_value() ||
            authoritative.lobby->server_id.empty()) {
            // A failed/finished host start returns the same lobby to forming.
            // Forget its previous relay so a later allocation may legitimately
            // reuse the same public identifier and still trigger Join Game.
            social_last_joined_server_id.clear();
        }
        if (is_create_match_screen(screen()) && authoritative.lobby.has_value()) {
            const auto apply_settings = !social_settings_generation.has_value() &&
                                        !social_desired_configuration.has_value();
            sync_social_match_lobby(authoritative, apply_settings);
        }
        const auto status = social_client->status(now);
        friends_lobby_menu.set_service_status(status.available, status.last_error);
        friends_lobby_menu.tick(now);
        if (is_create_match_screen(screen()) && !authoritative.lobby && !friends_lobby_menu.busy()) {
            create_match_menu.set_host_authority(true);
            if (!friends_lobby_menu.error().empty()) settings_warning = friends_lobby_menu.error();
            if (social_open_match_generation && ugc_create_deadline == std::chrono::steady_clock::time_point{}) {
                social_open_match_generation.reset();
                if (social_leave_after_create) {
                    static_cast<void>(navigation.pop());
                }
            }
        }
        pump_social_settings_update();
        if (social_start_retry_configuration && !social_start_generation &&
            !social_settings_waiting_for_sync && !social_settings_generation) {
            const auto retry = *social_start_retry_configuration;
            social_start_retry_configuration.reset();
            static_cast<void>(start_active_social_lobby(retry, true));
        }
        if (social_start_generation && now >= social_start_deadline) {
            social_start_generation.reset();
            social_pending_start_configuration.reset();
            social_pending_ugc_start.reset();
            settings_warning = "AoSPlay could not confirm the match start. Retry after the lobby synchronizes.";
            queue_social_start_failed(settings_warning);
        }
        pump_ugc_social_settings(now);
        if (social_open_match_generation && ugc_create_deadline != std::chrono::steady_clock::time_point{} &&
            now >= ugc_create_deadline) {
            social_open_match_generation.reset();
            ugc_create_deadline = {};
            settings_warning = "AoSPlay could not confirm the editor lobby. Return to the browser and retry.";
            ugc_editor_lobby.set_host_authority(false);
            ugc_leave_after_create = true;
        }
        pump_social_publish_retry(now);
        if (pending_social_lobby_navigation) {
            if (authoritative.lobby && authoritative.lobby->id == *pending_social_lobby_navigation)
                open_social_match_lobby(authoritative);
            else pending_social_lobby_navigation.reset();
        }

        // Follow the host while viewing this lobby. Back cancels this particular
        // start; an explicit Join Game or a new start can try again. Background
        // polls must never pull someone out of another menu or match.
        const bool viewing_lobby = is_create_match_screen(screen()) ||
            screen() == FrontendScreen::ugc_editor_lobby;
        if (viewing_lobby && navigation.shell().accepts_input() && !social_leave_generation &&
            authoritative.lobby.has_value() &&
            (authoritative.lobby->state == "ready" || authoritative.lobby->state == "in_game") &&
            (!social_canceled_join || *social_canceled_join != std::array{
                authoritative.lobby->id, authoritative.lobby->start_id, authoritative.lobby->server_id}) &&
            authoritative.lobby->owner_id != friends_lobby_menu.local_account_id() &&
            !authoritative.lobby->server_id.empty() &&
            (authoritative.lobby->server_id != social_last_joined_server_id ||
             authoritative.lobby->start_id != social_joined_start_id ||
             authoritative.lobby->id != social_joined_lobby_id) &&
            now >= social_join_retry_at &&
            !social_join_active.load(std::memory_order_acquire)) {
            auto operation = friends_lobby_menu.begin(
                {FriendsLobbyActionKind::join_game,
                 authoritative.lobby->server_id,
                 {}},
                now);
            if (operation.has_value()) {
                // The resolver marks this ID joined only after it appears in
                // the authoritative public list. Recording it here made one
                // transient master-list miss permanently strand members in
                // the lobby while the owner was already playing.
                static_cast<void>(begin_social_lobby_join(
                    operation->generation, authoritative.lobby->server_id));
                if (is_create_match_screen(screen())) {
                    create_match_menu.set_match_join_available(true, true);
                    settings_warning = "Finding the lobby server...";
                }
            }
        }
    }

    void request_main_menu_after_identity() {
        enter_main_menu_pending = true;
        static_cast<void>(window.set_text_input_enabled(false));
    }

    void launch_identity_operation(IdentityOperation operation) {
        if (identity_operation != IdentityOperation::none || identity_menu.busy()) {
            return;
        }
        auto service = identity_service;
        auto username = std::string{identity_menu.username()};
        auto password = std::string{identity_menu.password()};
        switch (operation) {
        case IdentityOperation::refresh:
            identity_menu.set_busy(true, "Checking your AoSPlay session...");
            identity_worker =
                std::async(std::launch::async, [service] { return service->refresh(); });
            break;
        case IdentityOperation::login:
            identity_menu.set_busy(true, "Signing in...");
            identity_worker =
                std::async(std::launch::async,
                           [service,
                            username = std::move(username),
                            password = std::move(password)]() mutable {
                               return service->login(std::move(username), std::move(password));
                           });
            identity_menu.clear_password();
            break;
        case IdentityOperation::register_account:
            identity_menu.set_busy(true, "Creating your account...");
            identity_worker = std::async(std::launch::async,
                                         [service,
                                          username = std::move(username),
                                          password = std::move(password)]() mutable {
                                             return service->register_account(std::move(username),
                                                                              std::move(password));
                                         });
            identity_menu.clear_password();
            break;
        case IdentityOperation::guest:
            identity_menu.set_busy(true, "Preparing your signed guest...");
            identity_worker =
                std::async(std::launch::async, [service] { return service->guest_login(); });
            break;
        case IdentityOperation::logout:
            identity_menu.reset_form();
            identity_menu.set_busy(true, "Signing out...");
            identity_worker =
                std::async(std::launch::async, [service] { return service->logout(); });
            break;
        case IdentityOperation::none:
            return;
        }
        identity_operation = operation;
    }

    void begin_identity_bootstrap() {
        identity_menu.reset_form();
        identity_menu.set_steam_available(native_steam != nullptr && native_steam->ready());
        authenticated_identity = false;
        enter_main_menu_pending = false;
        if (const auto cached = identity_service->cached_account(); cached.has_value()) {
            if (identity_service->has_online_session()) {
                launch_identity_operation(IdentityOperation::refresh);
            } else if (cached->offline) {
                apply_identity(*cached);
                request_main_menu_after_identity();
            } else {
                static_cast<void>(window.set_text_input_enabled(true));
            }
        } else {
            static_cast<void>(window.set_text_input_enabled(true));
        }
    }

    void submit_identity(IdentityAction action) {
        switch (action) {
        case IdentityAction::login:
            launch_identity_operation(IdentityOperation::login);
            break;
        case IdentityAction::register_account:
            launch_identity_operation(IdentityOperation::register_account);
            break;
        case IdentityAction::steam:
            if (native_steam == nullptr || !native_steam->ready() ||
                native_steam->identity() == nullptr) {
                identity_menu.set_error(
                    native_steam == nullptr || native_steam->last_error().empty()
                        ? "Native Steam is unavailable. Import the retail game and start Steam."
                        : std::string{native_steam->last_error()});
                break;
            }
            {
                const auto& steam = *native_steam->identity();
                auto nickname = core::utf8_code_point_prefix(steam.persona_name, 15U);
                while (nickname.size() > 31U) {
                    const auto count = std::max<std::size_t>(1U, nickname.size() / 4U);
                    nickname = core::utf8_code_point_prefix(nickname, count - 1U);
                }
                if (nickname.empty()) nickname = "SteamPlayer";
                network::RevivalAccount account;
                account.public_id = "steam:" + std::to_string(steam.steam_id);
                account.legacy_id = std::to_string(steam.steam_id);
                account.nickname = std::move(nickname);
                account.account_type = "steam";
                account.identity_type = "steam";
                account.ranked_eligible = true;
                account.offline = false;
                apply_identity(account);
                identity_menu.reset_form();
                request_main_menu_after_identity();
            }
            break;
        case IdentityAction::guest:
            launch_identity_operation(IdentityOperation::guest);
            break;
        case IdentityAction::acknowledge_recovery:
            identity_menu.reset_form();
            request_main_menu_after_identity();
            break;
        }
    }

    void pump_hosted_results() {
        if (identity_service == nullptr || !authenticated_identity ||
            identity_operation != IdentityOperation::none || hosted_results_active.load() ||
            std::chrono::steady_clock::now() < hosted_results_retry_at) return;
        hosted_results_retry_at = std::chrono::steady_clock::now() + std::chrono::seconds{30};
        if (hosted_results_worker.joinable()) hosted_results_worker.join();
        hosted_results_active.store(true);
        hosted_results_worker = std::jthread([this, identity = identity_service](std::stop_token stop) {
            try { static_cast<void>(identity->flush_hosted_results(stop)); } catch (...) {}
            hosted_results_active.store(false);
        });
    }

    void pump_identity_operation() {
        if (identity_operation == IdentityOperation::none ||
            !identity_worker.valid() ||
            identity_worker.wait_for(std::chrono::milliseconds{0}) !=
                std::future_status::ready) {
            return;
        }
        const auto operation = identity_operation;
        identity_operation = IdentityOperation::none;
        network::RevivalAuthResult outcome;
        try {
            outcome = identity_worker.get();
        } catch (const std::exception& exception) {
            identity_menu.set_error(
                std::string{"Authentication failed safely: "} + exception.what());
            static_cast<void>(window.set_text_input_enabled(true));
            return;
        } catch (...) {
            identity_menu.set_error("Authentication failed safely.");
            static_cast<void>(window.set_text_input_enabled(true));
            return;
        }
        if (operation == IdentityOperation::logout) {
            authenticated_identity = false;
            inventory_autoload=false;
            if (inventory_session) inventory_session->cancel();
            inventory_menu=InventoryMenuModel{};
            social_client->shutdown(std::chrono::milliseconds{0});
            friends_lobby_menu.set_identity({});
            friends_lobby_menu.set_service_status(false,
                                                  "Sign in to use friends and lobbies.");
            config.player_name = "Player";
            config.player_account_id = 0U;
            resolved_player_account_id = 0U;
            identity_menu.reset_form();
            if (!outcome.error.empty())
                identity_menu.set_error(outcome.error);
            static_cast<void>(window.set_text_input_enabled(true));
            return;
        }
        if (!outcome) {
            identity_menu.set_error(outcome.error.empty() ? "Authentication failed."
                                                          : outcome.error);
            static_cast<void>(window.set_text_input_enabled(true));
            return;
        }
        apply_identity(*outcome.account);
        if (operation == IdentityOperation::register_account && !outcome.recovery_code.empty()) {
            identity_menu.show_recovery_code(std::move(outcome.recovery_code));
            static_cast<void>(window.set_text_input_enabled(false));
            return;
        }
        identity_menu.reset_form();
        request_main_menu_after_identity();
    }

    void pump_identity_navigation() {
        if (enter_main_menu_pending && authenticated_identity &&
            screen() == FrontendScreen::identity && !navigation.shell().transitioning()) {
            if (navigation.reset(FrontendScreen::select_menu, NavigationDirection::forward)) {
                enter_main_menu_pending = false;
                play_confirm();
                // Identity owns a quiet startup screen. Start the menu OST only
                // after login/register/guest succeeds, so first-run users can
                // set volume before music begins.
                if (audio_started && !audio->start_menu_music()) {
                    settings_warning =
                        "menu music could not start: " + std::string{audio->last_error()};
                }
            }
        }
        if (authenticated_identity && pending_startup_connection.has_value() &&
            screen() == FrontendScreen::select_menu && navigation.shell().accepts_input()) {
            auto request = std::move(*pending_startup_connection);
            pending_startup_connection.reset();
            begin_match_loading(request);
        }
    }

    /** Starts or refreshes the held-trigger loop for an automatic weapon. */
    void begin_fire_loop(std::uint8_t tool_id, audio::SoundPosition position) {
        if (fire_loop.voice != audio::invalid_loop_voice && fire_loop.tool_id != tool_id) {
            // Switching weapons mid-burst must close the previous loop with
            // its own tail, not leave it running under the new weapon.
            audio->stop_weapon_loop(fire_loop.voice,
                                    fire_loop.tool_id,
                                    audio::WeaponCue::fire_tail,
                                    position,
                                    audio::local_weapon_report_gain(),
                                    true);
            fire_loop = {};
        }
        if (fire_loop.voice == audio::invalid_loop_voice) {
            fire_loop.voice = audio->start_weapon_loop(
                tool_id, audio::WeaponCue::fire_loop, position,
                audio::local_weapon_report_gain(), true);
            if (fire_loop.voice == audio::invalid_loop_voice) {
                fire_loop = {};
                return;
            }
            fire_loop.tool_id = tool_id;
            fire_loop.cadence.open(world::fire_loop_quantum(
                tool_id, tutorial_session != nullptr && tutorial_session->machine_gun_deployed()));
            // Only on OPEN. The grid has to run from the moment the loop starts;
            // restarting it per round is precisely the idle timeout this
            // replaced, and would re-introduce the extra audible round.
        }
        fire_loop.cadence.refresh();
        audio->update_weapon_loop(fire_loop.voice, {}, 1.0F,
                                  audio::local_weapon_report_gain());
    }

    /**
     * Drops the local firing source immediately and without a tail.
     *
     * Death and weapon unset are hard lifecycle boundaries in retail. Waiting
     * for the ordinary release quantum here strands the source when simulation
     * no longer advances that previous-life trigger, producing an infinite
     * head-relative loop.
     */
    void cancel_fire_loop() {
        if (fire_loop.voice != audio::invalid_loop_voice && audio_started) {
            audio->stop_weapon_loop(fire_loop.voice);
        }
        fire_loop = {};
    }

    /**
     * Closes the loop on the first quantised boundary where the trigger is dead.
     *
     * Both the stop and its tail are deferred to that boundary, so the loop
     * always ends on a whole number of grains and the tail lands where the next
     * round would have.
     */
    void advance_fire_loop(double dt, bool trigger_live, audio::SoundPosition position) {
        if (fire_loop.voice == audio::invalid_loop_voice) {
            fire_loop.cadence.cancel();
            return;
        }
        if (fire_loop.cadence.advance(dt, trigger_live)) {
            audio->stop_weapon_loop(fire_loop.voice,
                                    fire_loop.tool_id,
                                    audio::WeaponCue::fire_tail,
                                    position,
                                    audio::local_weapon_report_gain(),
                                    true);
            fire_loop = {};
            return;
        }
        audio->update_weapon_loop(fire_loop.voice, {}, 1.0F,
                                  audio::local_weapon_report_gain());
    }

    [[nodiscard]] static audio::SoundPosition
    remote_sound_position(const network::RemotePlayerReplica& player) noexcept {
        return {static_cast<float>(player.position.x),
                static_cast<float>(player.position.y),
                static_cast<float>(player.position.z)};
    }

    /** Begin a clean tool-history slot at the authoritative life boundary. */
    void reset_combat_tool_memory(const network::RemotePlayerReplica& player) noexcept {
        if (player.player_id >= combat_tool_memory.size()) {
            return;
        }
        combat_tool_memory[player.player_id] =
            CombatToolMemory{player.generation, 0U, false};
    }

    /** Preserve only catalogued tools for the player's current generation. */
    void remember_combat_tool(const network::RemotePlayerReplica& player,
                              std::uint8_t tool_id) noexcept {
        if (player.player_id >= combat_tool_memory.size() ||
            world::find_weapon_definition(tool_id) == nullptr) {
            return;
        }
        combat_tool_memory[player.player_id] =
            CombatToolMemory{player.generation, tool_id, true};
    }

    /** Return no stale tool when a retail player id has been reused. */
    [[nodiscard]] std::optional<std::uint8_t>
    remembered_combat_tool(const network::RemotePlayerReplica* player) const noexcept {
        if (player == nullptr || player->player_id >= combat_tool_memory.size()) {
            return std::nullopt;
        }
        const auto& memory = combat_tool_memory[player->player_id];
        if (!memory.valid || memory.generation != player->generation) {
            return std::nullopt;
        }
        return memory.tool_id;
    }

    /** Apply retail Block Sucker warm-up/loop/tail ownership for one player. */
    void set_block_sucker_audio(BlockSuckerAudioState& audio_state,
                                std::uint8_t state,
                                audio::SoundPosition position,
                                bool head_relative) {
        state = std::min<std::uint8_t>(state, 2U);
        if (!audio_started) {
            audio_state.state = state;
            return;
        }
        if (audio_state.state == state) {
            if (audio_state.voice != audio::invalid_loop_voice) {
                audio->update_weapon_loop(audio_state.voice, position);
            }
            return;
        }
        const auto previous = audio_state.state;
        if (audio_state.voice != audio::invalid_loop_voice) {
            if (state == 0U && previous == 2U) {
                audio->stop_weapon_loop(audio_state.voice,
                                        63U,
                                        audio::WeaponCue::tool_loop_stop,
                                        position,
                                        1.0F,
                                        head_relative);
            } else {
                audio->stop_weapon_loop(audio_state.voice);
            }
            audio_state.voice = audio::invalid_loop_voice;
        }
        audio_state.state = state;
        if (state == 1U) {
            audio->play_weapon_cue(
                63U, audio::WeaponCue::tool_loop_start, 0U, position, 1.0F, head_relative);
        } else if (state == 2U) {
            audio_state.voice = audio->start_weapon_loop(
                63U, audio::WeaponCue::tool_loop, position, 1.0F, head_relative);
        }
    }

    void stop_all_block_sucker_audio() {
        if (local_block_sucker_audio.voice != audio::invalid_loop_voice && audio_started) {
            audio->stop_weapon_loop(local_block_sucker_audio.voice);
        }
        local_block_sucker_audio = {};
        for (auto& state : remote_block_sucker_audio) {
            if (state.voice != audio::invalid_loop_voice && audio_started) {
                audio->stop_weapon_loop(state.voice);
            }
            state = {};
        }
    }

    /** Start, move, switch, or close SnowBlowerWeapon's equipped engine loop. */
    void set_block_cannon_audio(BlockCannonAudioState& audio_state,
                                std::optional<std::uint8_t> selected_tool,
                                audio::SoundPosition position,
                                bool head_relative) {
        const bool selected = selected_tool == 29U || selected_tool == 48U;
        const auto desired_tool = selected ? *selected_tool : std::uint8_t{};
        if (!audio_started) {
            audio_state.tool_id = desired_tool;
            return;
        }
        if (audio_state.voice != audio::invalid_loop_voice && audio_state.tool_id != desired_tool) {
            audio->stop_weapon_loop(audio_state.voice);
            audio_state.voice = audio::invalid_loop_voice;
        }
        audio_state.tool_id = desired_tool;
        if (!selected) {
            return;
        }
        if (audio_state.voice == audio::invalid_loop_voice) {
            audio_state.voice = audio->start_weapon_loop(
                desired_tool, audio::WeaponCue::tool_loop, position, 1.0F, head_relative);
        } else {
            audio->update_weapon_loop(audio_state.voice, position);
        }
    }

    void stop_all_block_cannon_audio() {
        const auto stop = [this](BlockCannonAudioState& state) {
            if (state.voice != audio::invalid_loop_voice && audio_started) {
                audio->stop_weapon_loop(state.voice);
            }
            state = {};
        };
        stop(local_block_cannon_audio);
        for (auto& state : remote_block_cannon_audio) {
            stop(state);
        }
    }

    /** Advance retail's projectile-owned Drill flight/contact sound pair. */
    void advance_drill_audio() {
        const auto stop = [this](DrillAudioState& state) {
            if (audio_started && state.flight != audio::invalid_loop_voice) {
                audio->stop_weapon_loop(state.flight);
            }
            if (audio_started && state.contact != audio::invalid_loop_voice) {
                audio->stop_weapon_loop(state.contact);
            }
            state = {};
        };
        if (!audio_started || tutorial_session == nullptr) {
            for (auto& [key, state] : drill_audio) {
                static_cast<void>(key);
                stop(state);
            }
            drill_audio.clear();
            return;
        }

        for (auto& [key, state] : drill_audio) {
            static_cast<void>(key);
            state.seen = false;
        }
        const auto present = [this](std::pair<bool, std::uint64_t> key,
                                    const world::Vec3& position,
                                    bool contacting) {
            auto found = drill_audio.find(key);
            if (found == drill_audio.end()) {
                // A malformed server cannot turn a projectile burst into an
                // unbounded OpenAL allocation. Ordinary matches stay far below
                // this presentation-only ceiling.
                constexpr std::size_t drill_voice_budget{64U};
                if (drill_audio.size() >= drill_voice_budget) {
                    return;
                }
                found = drill_audio.emplace(key, DrillAudioState{}).first;
            }
            auto& state = found->second;
            state.seen = true;
            const audio::SoundPosition sound_position{
                static_cast<float>(position.x),
                static_cast<float>(position.y),
                static_cast<float>(position.z)};
            if (state.flight == audio::invalid_loop_voice) {
                state.flight = audio->start_named_voice_loop(
                    "drill_projectile", sound_position, 1.0F, false);
            } else {
                audio->update_weapon_loop(state.flight, sound_position);
            }
            if (contacting) {
                if (state.contact == audio::invalid_loop_voice) {
                    state.contact = audio->start_named_voice_loop(
                        "drill_loop", sound_position, 1.0F, false);
                } else {
                    audio->update_weapon_loop(state.contact, sound_position);
                }
            } else if (state.contact != audio::invalid_loop_voice) {
                audio->stop_weapon_loop(state.contact);
                state.contact = audio::invalid_loop_voice;
            }
        };

        for (const auto& projectile : tutorial_session->projectiles()) {
            if (projectile.behavior != world::TutorialProjectileBehavior::drill) {
                continue;
            }
            present({false, projectile.id},
                    projectile.position,
                    projectile.drilling_audio_remaining > 0.0);
        }
        for (const auto& entity : tutorial_session->entities()) {
            if (!entity.alive || entity.type != 23U) {
                continue;
            }
            present({true, entity.id},
                    entity.position,
                    entity.drilling_audio_remaining > 0.0);
        }

        for (auto iterator = drill_audio.begin(); iterator != drill_audio.end();) {
            if (iterator->second.seen) {
                ++iterator;
                continue;
            }
            stop(iterator->second);
            iterator = drill_audio.erase(iterator);
        }
    }

    void stop_all_drill_audio() {
        if (audio_started) {
            for (auto& [key, state] : drill_audio) {
                static_cast<void>(key);
                if (state.flight != audio::invalid_loop_voice) {
                    audio->stop_weapon_loop(state.flight);
                }
                if (state.contact != audio::invalid_loop_voice) {
                    audio->stop_weapon_loop(state.contact);
                }
            }
        }
        drill_audio.clear();
    }

    /** Stops one observer fire loop and optionally lands its retail tail. */
    void stop_remote_fire_loop(std::uint8_t player_id,
                               audio::SoundPosition position,
                               bool play_tail = true) {
        if (player_id >= remote_fire_loops.size())
            return;
        auto& state = remote_fire_loops[player_id];
        if (state.voice != audio::invalid_loop_voice && audio_started) {
            if (play_tail) {
                audio->stop_weapon_loop(
                    state.voice, state.tool_id, audio::WeaponCue::fire_tail, position,
                    audio::remote_weapon_report_gain(), false,
                    audio::SpatialSoundProfile::weapon_report);
            } else {
                audio->stop_weapon_loop(state.voice);
            }
        }
        state = {};
    }

    /** Tears down every positional weapon voice before a map/audio reset. */
    void stop_all_remote_fire_loops() {
        for (std::size_t id{}; id < remote_fire_loops.size(); ++id) {
            auto& state = remote_fire_loops[id];
            if (state.voice == audio::invalid_loop_voice)
                continue;
            audio::SoundPosition position{};
            if (const auto* player = tutorial_roster.player(static_cast<std::uint8_t>(id));
                player != nullptr) {
                position = remote_sound_position(*player);
            }
            stop_remote_fire_loop(static_cast<std::uint8_t>(id), position, false);
        }
    }

    /**
     * Publishes the current camera before decoding positional server sounds.
     *
     * Packet pumping happens before the fixed simulation step. Without this
     * early update, every PlaySound, remote shot and explosion was spatialized
     * against the previous map/frame's listener (the origin on first spawn).
     */
    void prime_audio_listener() {
        if (!audio_started || tutorial_session == nullptr)
            return;
        const auto eye = death_camera.active() ? [&]() {
            const auto pose = death_camera.pose();
            return std::array<double, 3U>{pose.eye.x, pose.eye.y, pose.eye.z};
        }()
                                               : tutorial_session->eye_position();
        const double yaw =
            death_camera.active() ? death_camera.pose().yaw_degrees : tutorial_session->yaw();
        const double pitch =
            death_camera.active() ? death_camera.pose().pitch_degrees : tutorial_session->pitch();
        const auto basis = render::world_camera_basis(yaw, pitch);
        const audio::SoundPosition listener{
            static_cast<float>(eye[0U]), static_cast<float>(eye[1U]), static_cast<float>(eye[2U])};
        audio->set_listener_pose(listener,
                                 {static_cast<float>(basis.forward[0U]),
                                  static_cast<float>(basis.forward[1U]),
                                  static_cast<float>(basis.forward[2U])},
                                 {static_cast<float>(basis.up[0U]),
                                  static_cast<float>(basis.up[1U]),
                                  static_cast<float>(basis.up[2U])});
        refresh_server_ambient_positions(listener);
    }

    /** Resolve one OpenAL source against the current authoritative VXL. */
    [[nodiscard]] float spatial_sound_gain(audio::SoundPosition listener,
                                           audio::SoundPosition source) const noexcept {
        if (tutorial_session == nullptr) {
            return 1.0F;
        }
        const float delta_x = source.x - listener.x;
        const float delta_y = source.y - listener.y;
        const float delta_z = source.z - listener.z;
        // Retail's in-world zone hard-culls at 50 blocks. Avoid traversing the
        // VXL for a source OpenAL will make inaudible anyway.
        constexpr float hearing_distance{50.0F};
        if (delta_x * delta_x + delta_y * delta_y + delta_z * delta_z >=
            hearing_distance * hearing_distance) {
            return 0.0F;
        }
        return world::raycast_acoustic_path(
                   tutorial_session->map(),
                   {listener.x, listener.y, listener.z},
                   {source.x, source.y, source.z})
            .transmission;
    }

    [[nodiscard]] static float spatial_sound_gain_callback(
        void* context,
        audio::SoundPosition listener,
        audio::SoundPosition source) noexcept {
        return context != nullptr
                   ? static_cast<Impl*>(context)->spatial_sound_gain(listener, source)
                   : 1.0F;
    }

    void remember_predicted_terrain_hit(std::uint8_t player_id,
                                        world::VoxelCell cell,
                                        std::int32_t shot_world_loop) {
        constexpr std::size_t maximum_hits{128U};
        if (predicted_terrain_hits.size() >= maximum_hits) {
            predicted_terrain_hits.erase(predicted_terrain_hits.begin());
        }
        predicted_terrain_hits.push_back({player_id, cell, shot_world_loop});
    }

    [[nodiscard]] bool consume_predicted_terrain_hit(std::uint8_t player_id,
                                                     world::VoxelCell cell) {
        constexpr std::int32_t maximum_age{30};
        std::erase_if(predicted_terrain_hits, [&](const PredictedTerrainHit& hit) {
            return latest_world_loop >= hit.shot_world_loop &&
                   latest_world_loop - hit.shot_world_loop > maximum_age;
        });
        const auto found = std::ranges::find_if(
            predicted_terrain_hits, [&](const PredictedTerrainHit& hit) {
                return hit.player_id == player_id && hit.cell.x == cell.x &&
                       hit.cell.y == cell.y && hit.cell.z == cell.z;
            });
        if (found == predicted_terrain_hits.end()) {
            return false;
        }
        predicted_terrain_hits.erase(found);
        return true;
    }

    /**
     * Re-run retail's observer-only scenery raycast for one packet-owned shot.
     * This emits contact presentation only; server terrain remains untouched.
     */
    void present_hitscan_contacts(std::uint8_t player_id,
                                  std::uint8_t tool_id,
                                  std::uint8_t seed,
                                  std::int32_t shot_world_loop,
                                  std::array<float, 3U> origin,
                                  std::array<float, 3U> orientation,
                                  bool zoomed) {
        if (tutorial_session == nullptr) {
            return;
        }
        for (const auto& impact : world::replicated_hitscan_impacts(
                 tutorial_session->map(), origin, orientation, tool_id, seed, zoomed)) {
            terrain_effects.spawn_impact(impact);
            remember_predicted_terrain_hit(player_id, impact.cell, shot_world_loop);
        }
    }

    /**
     * Presents one authoritative observer shot at the remote player's pose.
     *
     * Automatic weapons in retail often define no per-round sample at all;
     * their audible shot is a held fire_loop plus a fire_tail. Routing every
     * ShootFeedback through play_weapon_shoot therefore made SMGs, Tommy guns
     * and the automatic pistol completely silent to other clients.
     */
    [[nodiscard]] audio::SoundPosition
    remote_muzzle_position(const network::RemotePlayerReplica& shooter,
                           std::uint8_t tool_id) const {
        const auto fallback = remote_sound_position(shooter);
        const auto attachment = world::retail_third_person_muzzle_attachment(tool_id);
        const auto rig = remote_player_rigs.find(shooter.player_id);
        if (!attachment.has_value() || rig == remote_player_rigs.end() ||
            rig->second.tool_id != tool_id || rig->second.tool_part_count == 0U) {
            return fallback;
        }

        const auto& motion = rig->second.motion.sample();
        const float yaw = static_cast<float>(world::retail_character_root_yaw_degrees(
            {motion.orientation.x, motion.orientation.y, motion.orientation.z}));
        const double aim_pitch =
            std::asin(std::clamp(motion.orientation.z, -1.0, 1.0)) *
            180.0 / std::numbers::pi;
        const double elapsed =
            rig->second.last_primary_world_loop < 0
                ? 1.0e9
                : std::max(0.0,
                           static_cast<double>(latest_world_loop -
                                               rig->second.last_primary_world_loop) /
                               60.0);
        const auto pose = world::evaluate_retail_third_person_pose(
            tool_id, rig->second.tool_part_count, elapsed,
            rig->second.action_serial, aim_pitch);
        if (pose.tool_part_count == 0U) {
            return fallback;
        }

        const auto& part = pose.tool_parts[0U];
        auto held = mat_scale(static_cast<float>(pose.tool_model_scale));
        held = mat_mul(held,
                       mat_rotate_z(static_cast<float>(part.orientation_degrees.z)));
        held = mat_mul(held,
                       mat_rotate_y(static_cast<float>(part.orientation_degrees.y)));
        held = mat_mul(held,
                       mat_rotate_x(static_cast<float>(part.orientation_degrees.x)));
        held = mat_mul(held,
                       mat_translate(static_cast<float>(part.position.x),
                                     static_cast<float>(part.position.y),
                                     static_cast<float>(part.position.z)));
        held = mat_mul(held,
                       mat_rotate_x(static_cast<float>(pose.weapon_pitch_degrees)));
        const auto anchor = world::retail_display_vector(pose.tool_anchor);
        held = mat_mul(held,
                       mat_translate(static_cast<float>(anchor.x),
                                     static_cast<float>(anchor.y),
                                     static_cast<float>(anchor.z)));
        held = mat_mul(held, mat_rotate_x(-90.0F));
        auto root = mat_rotate_z(yaw);
        root = mat_mul(root,
                       mat_translate(static_cast<float>(motion.position.x),
                                     static_cast<float>(motion.position.y),
                                     static_cast<float>(motion.position.z)));
        held = mat_mul(held, root);

        auto local = world::retail_display_vector(attachment->offset);
        local.x *= attachment->scale;
        local.y *= attachment->scale;
        local.z *= attachment->scale;
        const auto world_position = mat_transform_point(
            held,
            {static_cast<float>(local.x),
             static_cast<float>(local.y),
             static_cast<float>(local.z)});
        return {world_position[0U], world_position[1U], world_position[2U]};
    }

    [[nodiscard]] std::string_view local_weapon_sound_cosmetic(std::uint8_t tool) const {
        const auto* item = local_equipped_cosmetic("weapon:"+std::to_string(tool)+":view");
        if (applied_settings.main.show_skins && !network_match && developer_tools_allowed() && config.tutorial_debug_cosmetic)
            item = find_inventory_cosmetic(*config.tutorial_debug_cosmetic);
        if (!item || std::ranges::none_of(item->parents, [tool](const auto& parent) { return parent.tool == tool; })) return {};
        return item->id;
    }

    void present_remote_shot(const network::ShootFeedbackPacket& feedback,
                             const network::RemotePlayerReplica& shooter) {
        const auto position = remote_sound_position(shooter);
        const auto muzzle = remote_muzzle_position(shooter, feedback.tool_id);
        const auto direction = std::array<float, 3U>{static_cast<float>(shooter.orientation.x),
                                                     static_cast<float>(shooter.orientation.y),
                                                     static_cast<float>(shooter.orientation.z)};
        world::emit_weapon_muzzle(particles,
                                  {muzzle.x, muzzle.y, muzzle.z},
                                  direction,
                                  static_cast<std::uint32_t>(feedback.seed) ^
                                      (static_cast<std::uint32_t>(feedback.shooter_id) << 16U) ^
                                      static_cast<std::uint32_t>(latest_world_loop));
        terrain_effects.spawn_weapon_flash({muzzle.x, muzzle.y, muzzle.z},
                                           feedback.tool_id);
        present_hitscan_contacts(
            feedback.shooter_id,
            feedback.tool_id,
            feedback.seed,
            feedback.shot_on_world_update,
            {static_cast<float>(shooter.position.x),
             static_cast<float>(shooter.position.y),
             static_cast<float>(shooter.position.z)},
            direction,
            network::world_player_zoomed(shooter.action_flags));

        if (!audio_started || feedback.shooter_id >= remote_fire_loops.size()) {
            return;
        }
        auto& state = remote_fire_loops[feedback.shooter_id];
        const auto* cosmetic = equipped_cosmetic(feedback.shooter_id,
            "weapon:"+std::to_string(feedback.tool_id)+":world");
        if (cosmetic && audio->has_cosmetic_fire(cosmetic->id)) {
            stop_remote_fire_loop(feedback.shooter_id, position, false);
            audio->play_weapon_shoot(feedback.tool_id,feedback.seed,position,
                audio::remote_weapon_report_gain(),false,audio::SpatialSoundProfile::weapon_report,cosmetic->id);
            return;
        }
        if (audio->has_weapon_cue(feedback.tool_id, audio::WeaponCue::fire_loop)) {
            if (state.voice != audio::invalid_loop_voice && state.tool_id != feedback.tool_id) {
                stop_remote_fire_loop(feedback.shooter_id, position, false);
            }
            if (state.voice == audio::invalid_loop_voice) {
                state.voice = audio->start_weapon_loop(
                    feedback.tool_id, audio::WeaponCue::fire_loop, position,
                    audio::remote_weapon_report_gain(),
                    false, audio::SpatialSoundProfile::weapon_report);
                state.tool_id = feedback.tool_id;
            }
            state.last_feedback_world_loop = latest_world_loop;
            audio->update_weapon_loop(state.voice, position, 1.0F,
                                      audio::remote_weapon_report_gain());
            return;
        }
        audio->play_weapon_shoot(feedback.tool_id, feedback.seed, position,
                                 audio::remote_weapon_report_gain(),
                                 false, audio::SpatialSoundProfile::weapon_report);
    }

    /** Repositions or closes a remote automatic-fire voice from WorldUpdate. */
    void update_remote_fire_loop(const network::WorldPlayerWeaponRow& row,
                                 const network::RemotePlayerReplica& player) {
        if (row.player_id >= remote_fire_loops.size())
            return;
        auto& state = remote_fire_loops[row.player_id];
        if (state.voice == audio::invalid_loop_voice)
            return;
        const auto position = remote_sound_position(player);
        audio->update_weapon_loop(state.voice, position, 1.0F,
                                  audio::remote_weapon_report_gain());
        if (row.health <= 0 || row.tool_id != state.tool_id) {
            // Death and unequip are hard ownership boundaries. Retail drops
            // the held loop silently here; only a trigger release gets a tail.
            stop_remote_fire_loop(row.player_id, position, false);
            return;
        }
        const bool primary_held = (row.action_flags & 0x01U) != 0U;
        // The feedback packet and the row share an ordered channel, but a row
        // with the same loop label may have been decoded immediately before the
        // feedback. Require a newer authority row before closing the voice.
        if (!primary_held && latest_world_loop > state.last_feedback_world_loop) {
            stop_remote_fire_loop(row.player_id, position, true);
        }
    }

    void update_remote_block_sucker_audio(const network::WorldPlayerWeaponRow& row,
                                          const network::RemotePlayerReplica& player) {
        if (row.player_id >= remote_block_sucker_audio.size())
            return;
        auto& state = remote_block_sucker_audio[row.player_id];
        const auto position = remote_sound_position(player);
        if (row.health <= 0 || row.tool_id != 63U) {
            set_block_sucker_audio(state, 0U, position, false);
            return;
        }
        if (state.voice != audio::invalid_loop_voice && audio_started) {
            audio->update_weapon_loop(state.voice, position);
        }
    }

    void update_remote_block_cannon_audio(const network::WorldPlayerWeaponRow& row,
                                          const network::RemotePlayerReplica& player) {
        if (row.player_id >= remote_block_cannon_audio.size())
            return;
        const auto selected = row.health > 0 && (row.tool_id == 29U || row.tool_id == 48U)
                                  ? std::optional<std::uint8_t>{row.tool_id}
                                  : std::nullopt;
        set_block_cannon_audio(remote_block_cannon_audio[row.player_id],
                               selected,
                               remote_sound_position(player),
                               false);
    }

    /**
     * Drives the minigun's barrel-spin loop from the runtime's spin fraction.
     *
     * Both curves are retail's, and both are exact rather than tuned:
     *
     *   pitch = spin_fraction
     *   gain  = clamp((spin_fraction - fade_threshold) / (1 - fade_threshold))
     *
     * Retail sets the pitch to `spin_speed / MINIGUN_BARREL_SPIN_SPEED_MAX` as a
     * RAW playback ratio -- not the 2^(semitones/12) conversion its one-shot
     * path uses -- and its own spin_speed is that maximum times exactly the
     * ratio this runtime already computes as spin_fraction(), so the division
     * cancels and the pitch IS the fraction.
     *
     * The gain floor exists so the loop is inaudible until the barrels are
     * actually turning, which is what stops a stationary minigun from humming.
     *
     * Nothing special happens on release: the runtime keeps easing the spin back
     * down on its own, so pitch and gain wind off together over about two and a
     * half seconds and the loop closes on the frame the fraction reaches zero.
     * There is no spin-down sample because retail authors none.
     */
    void advance_spin_loop(double spin_fraction,
                           std::optional<std::uint8_t> tool_id,
                           audio::SoundPosition position) {
        const bool wants_spin = spin_fraction > 0.0 && tool_id.has_value() &&
                                audio->has_weapon_cue(*tool_id, audio::WeaponCue::spin_loop);
        const bool tool_changed = spin_loop.voice != audio::invalid_loop_voice &&
                                  tool_id.value_or(0U) != spin_loop.tool_id;
        if (spin_loop.voice != audio::invalid_loop_voice && (!wants_spin || tool_changed)) {
            // No tail: retail's spin loop simply stops.
            audio->stop_weapon_loop(spin_loop.voice);
            spin_loop.voice = audio::invalid_loop_voice;
        }
        if (!wants_spin) {
            return;
        }
        if (spin_loop.voice == audio::invalid_loop_voice) {
            // Opened silent, then immediately retuned below, because the loop
            // starts at pitch 1.0 and would otherwise spend its first frame at
            // full speed.
            spin_loop.voice = audio->start_weapon_loop(
                *tool_id, audio::WeaponCue::spin_loop, position, 0.0F, true);
            spin_loop.tool_id = *tool_id;
        }
        if (spin_loop.voice == audio::invalid_loop_voice) {
            return;
        }
        constexpr double fade_threshold{0.03};
        const auto gain =
            std::clamp((spin_fraction - fade_threshold) / (1.0 - fade_threshold), 0.0, 1.0);
        audio->update_weapon_loop(
            spin_loop.voice, {}, static_cast<float>(spin_fraction), static_cast<float>(gain));
    }

    /**
     * Footsteps, and the land/jump impacts that go with them.
     *
     * The selection itself is a pure function in world/footstep_audio; this only
     * turns its answer into a voice. Retail picks between the dry and wading sets
     * on the wade bit alone -- there is no per-material lookup and no per-surface
     * samples ship -- and suppresses steps entirely while crouching or airborne.
     */
    void advance_footsteps(double dt, audio::SoundPosition position) {
        if (audio == nullptr || tutorial_session == nullptr) {
            return;
        }
        footstep_clock += dt;
        const auto input = tutorial_session->footstep_input();
        const auto step = world::step_footsteps(footstep_state, input, footstep_clock);
        if (step != world::MovementSound::none) {
            play_movement_sound(step, position);
        }

        const auto movement = tutorial_session->take_movement_events();
        world::LandJumpInput impact;
        // The movement core already distinguishes jump, climb and severe fall.
        // Reconstructing these from airborne edges made stairs sound like falls
        // and consumed the 0.1-second lockout before real jumps.
        impact.jumped = movement.jumped;
        impact.landed = movement.landed;
        impact.hard_landing = movement.hard_landing;
        impact.fall_damage = movement.landing_damage > 0;
        impact.wade = input.wade;
        const auto sounds = world::step_land_jump(land_jump_state, impact, dt);
        if (sounds.impact != world::MovementSound::none) {
            play_movement_sound(sounds.impact, position);
            switch (sounds.impact) {
            case world::MovementSound::jump:
                play_class_voice(world::ClassVoice::jump, position);
                break;
            case world::MovementSound::water_jump:
                play_class_voice(world::ClassVoice::water_jump, position);
                break;
            case world::MovementSound::land:
                play_class_voice(world::ClassVoice::land, position);
                break;
            case world::MovementSound::water_land:
                play_class_voice(world::ClassVoice::water_land, position);
                break;
            default:
                break;
            }
        }
        if (sounds.fall_hurt) {
            play_movement_sound(world::MovementSound::fall_hurt, position);
            play_class_voice(world::ClassVoice::fall_hurt, position);
        }

        const auto class_id = tutorial_session->debug_class_id();
        if (!network_match &&
            (!local_spawn_voice.has_previous_class ||
             local_spawn_voice.previous_class_id != class_id)) {
            // Offline/debug class changes have no CreatePlayer packet. They
            // still instantiate a new retail Character life, so arm the same
            // delayed, class-change-forced spawn cue locally.
            begin_local_spawn_audio(class_id);
        }
        if (const auto spawn = world::step_local_spawn_voice(local_spawn_voice, dt);
            spawn.has_value()) {
            play_class_voice_for(spawn->class_id,
                                 world::ClassVoice::spawn,
                                 position,
                                 voice_selection,
                                 spawn->force,
                                 true);
        }

        // The idle vocalisation. Only the zombie classes carry one, so for
        // everyone else this timer runs and finds an empty bank.
        if (world::step_periodic_voice(periodic_voice, dt, voice_rng())) {
            play_class_voice(world::ClassVoice::periodic, position);
        }
    }

    /**
     * Per-class voice: the spawn line, the movement vocals and the idle groan.
     *
     * Layered ON TOP of the generic foley rather than replacing it -- retail
     * plays both, so a soldier landing makes the same thud as everyone else and
     * may add a grunt over it.
     *
     * Several classes are deliberately mute in some slots, and the zombies have
     * no speech at all beyond a death cry and the idle groan, so "nothing
     * played" is very often the correct outcome here.
     */
    void play_class_voice_for(std::uint8_t class_id,
                              world::ClassVoice voice,
                              audio::SoundPosition position,
                              std::array<world::VoiceSelectionState,
                                         static_cast<std::size_t>(world::ClassVoice::count)>&
                                  selection,
                              bool force,
                              bool head_relative) {
        if (audio == nullptr) {
            return;
        }
        const auto* set = world::find_class_voice(class_id);
        if (set == nullptr) {
            return;
        }
        const auto slot = static_cast<std::size_t>(voice);
        auto& state = selection[slot < selection.size() ? slot : 0U];
        const auto stem = world::choose_voice_line(
            set->bank(voice), force ? 0U : voice_rng(), voice_rng(), state);
        if (!stem.empty()) {
            // Louder than foley: a voice line is meant to carry.
            static_cast<void>(
                audio->play_named_one_shot(stem,
                                           position,
                                           0.9F,
                                           head_relative,
                                           0.0F,
                                           0.15F,
                                           true));
        }
    }

    void play_class_voice(world::ClassVoice voice, audio::SoundPosition position) {
        if (tutorial_session == nullptr) {
            return;
        }
        play_class_voice_for(tutorial_session->debug_class_id(),
                             voice,
                             position,
                             voice_selection,
                             false,
                             true);
    }

    /**
     * Arm Character.update_spawn_sound for one authoritative local life.
     *
     * Retail waits uniformly 1-2 seconds. A first life or class change forces
     * the authored spawn bank; a same-class respawn keeps its 25/101 chance.
     * The Zombie countdown is a separate server PlaySound event and must never
     * be inferred here.
     */
    void begin_local_spawn_audio(std::uint8_t class_id) {
        periodic_voice = {};
        world::begin_local_spawn_voice(
            local_spawn_voice, class_id, world::local_spawn_voice_delay(voice_rng()));
    }

    /** Cheap deterministic-per-frame randomness for voice selection. */
    [[nodiscard]] std::uint32_t voice_rng() noexcept {
        voice_seed = voice_seed * 1664525U + 1013904223U;
        return voice_seed >> 8U;
    }

    std::array<world::VoiceSelectionState,
               static_cast<std::size_t>(world::ClassVoice::count)>
        voice_selection{};
    std::uint32_t voice_seed{0x9E3779B9U};
    world::PeriodicVoiceState periodic_voice{};
    world::LocalSpawnVoiceState local_spawn_voice{};

    /** Maps one movement decision onto a loaded buffer and plays it. */
    void play_movement_sound_for(std::uint8_t class_id,
                                 world::MovementSound sound,
                                 audio::SoundPosition position,
                                 std::uint32_t& variant_counter) {
        using audio::OpenAlFrontendAudio;
        const auto variants = world::movement_sound_variants(sound);
        // Rotate rather than randomise: four samples cycling is enough to break
        // the repetition, and a counter cannot accidentally repeat one twice.
        const auto pick = variants > 1U ? (variant_counter++ % variants) : 0U;
        const bool uses_named_class_foley = class_id == 4U || class_id == 14U ||
                                             class_id == 15U ||
                                             sound == world::MovementSound::jetpack_land;
        const float movement_gain = sound == world::MovementSound::wade ||
                                            sound == world::MovementSound::water_jump ||
                                            sound == world::MovementSound::water_land
                                        ? 0.78F
                                        : 0.52F;
        if (uses_named_class_foley) {
            const auto stem = world::class_movement_sound_stem(class_id, sound, pick);
            if (stem[0] != '\0') {
                static_cast<void>(
                    audio->play_named_one_shot(stem, position, movement_gain, false));
            }
            return;
        }
        audio::SoundHandle handle{};
        switch (sound) {
        case world::MovementSound::footstep:
            handle = static_cast<audio::SoundHandle>(OpenAlFrontendAudio::footstep_sound_1 + pick);
            break;
        case world::MovementSound::wade:
            handle = static_cast<audio::SoundHandle>(OpenAlFrontendAudio::wade_sound_1 + pick);
            break;
        case world::MovementSound::jump:
            handle = OpenAlFrontendAudio::jump_sound;
            break;
        case world::MovementSound::water_jump:
            handle = OpenAlFrontendAudio::water_jump_sound;
            break;
        case world::MovementSound::jetpack_land:
            return;
        case world::MovementSound::land:
            handle = OpenAlFrontendAudio::land_sound;
            break;
        case world::MovementSound::water_land:
            handle = OpenAlFrontendAudio::water_land_sound;
            break;
        case world::MovementSound::fall_hurt:
            handle = OpenAlFrontendAudio::fall_hurt_sound;
            break;
        case world::MovementSound::none:
            return;
        }
        // Quieter than gunfire on purpose: these fire twice a second while
        // moving, so at parity gain they would dominate the mix.
        audio->play_one_shot(handle, position, movement_gain);
    }

    void play_movement_sound(world::MovementSound sound, audio::SoundPosition position) {
        if (tutorial_session == nullptr) {
            return;
        }
        play_movement_sound_for(
            tutorial_session->debug_class_id(), sound, position, footstep_variant);
    }

    world::FootstepState footstep_state{};
    world::LandJumpState land_jump_state{};
    double footstep_clock{};
    std::uint32_t footstep_variant{};

    [[nodiscard]] static world::RemoteCharacterAudioSnapshot
    remote_character_audio_snapshot(const network::RemotePlayerReplica& player) noexcept {
        world::RemoteCharacterAudioSnapshot snapshot;
        snapshot.generation = player.generation;
        snapshot.class_id = player.class_id;
        // CreatePlayer carries a dead flag but no health field. The roster's
        // default health is intentionally useful for live spawns, so fold the
        // explicit life flag in here instead of arming VO for a dead replica.
        snapshot.health = player.dead ? 0 : player.health;
        snapshot.input_flags = player.input_flags;
        snapshot.action_flags = player.action_flags;
        snapshot.state_flags = player.state_flags;
        snapshot.horizontal_speed = std::hypot(player.velocity.x, player.velocity.y);
        snapshot.vertical_speed = player.velocity.z;
        return snapshot;
    }

    void update_jetpack_flight_voice(audio::LoopVoice& voice,
                                     bool active,
                                     audio::SoundPosition position,
                                     bool head_relative) {
        if (!audio_started || audio == nullptr) {
            voice = audio::invalid_loop_voice;
            return;
        }
        if (!active) {
            if (voice != audio::invalid_loop_voice) {
                audio->stop_weapon_loop(voice);
                voice = audio::invalid_loop_voice;
                static_cast<void>(audio->play_named_one_shot(
                    "JP_release", position, 0.72F, head_relative, 0.0F, 0.15F));
            }
            return;
        }
        if (voice == audio::invalid_loop_voice) {
            static_cast<void>(audio->play_named_one_shot(
                "JP_ignite", position, 0.82F, head_relative, 0.0F, 0.15F));
            voice = audio->start_named_voice_loop(
                "JP_flight_lp", position, 0.72F, head_relative);
        } else {
            audio->update_weapon_loop(
                voice, head_relative ? audio::SoundPosition{} : position, 1.0F, 0.72F);
        }
    }

    void stop_remote_jetpack_flight(std::uint8_t player_id,
                                    audio::SoundPosition position,
                                    bool play_release) {
        if (player_id >= remote_character_audio.size()) {
            return;
        }
        auto& state = remote_character_audio[player_id];
        if (state.jetpack_flight_voice != audio::invalid_loop_voice && audio_started &&
            audio != nullptr) {
            audio->stop_weapon_loop(state.jetpack_flight_voice);
            if (play_release) {
                static_cast<void>(audio->play_named_one_shot(
                    "JP_release", position, 0.72F, false, 0.0F, 0.15F));
            }
        }
        state.jetpack_flight_voice = audio::invalid_loop_voice;
        state.jetpack_particle_clock = 0.0;
    }

    void stop_all_jetpack_flight() {
        if (local_jetpack_flight_voice != audio::invalid_loop_voice && audio_started &&
            audio != nullptr) {
            audio->stop_weapon_loop(local_jetpack_flight_voice);
        }
        local_jetpack_flight_voice = audio::invalid_loop_voice;
        local_jetpack_particle_clock = 0.0;
        for (auto& state : remote_character_audio) {
            if (state.jetpack_flight_voice != audio::invalid_loop_voice && audio_started &&
                audio != nullptr) {
                audio->stop_weapon_loop(state.jetpack_flight_voice);
            }
            state.jetpack_flight_voice = audio::invalid_loop_voice;
            state.jetpack_particle_clock = 0.0;
        }
    }

    /** Stops fuse/fire entity loops before their owning world is discarded. */
    void stop_all_entity_effect_loops() {
        if (audio_started && audio != nullptr) {
            for (const auto& [entity_id, voice] : entity_effect_loops) {
                static_cast<void>(entity_id);
                audio->stop_weapon_loop(voice);
            }
        }
        entity_effect_loops.clear();
    }

    void emit_jetpack_flight_particles(double dt,
                                       double& clock,
                                       bool active,
                                       std::array<float, 3U> position,
                                       std::array<float, 3U> velocity,
                                       std::uint32_t seed) {
        if (!active) {
            clock = 0.0;
            return;
        }
        constexpr double emission_period{0.02};
        clock += std::clamp(dt, 0.0, 0.1);
        std::uint32_t emitted{};
        while (clock >= emission_period && emitted < 4U) {
            clock -= emission_period;
            world::emit_jetpack_flight_exhaust(
                particles, position, velocity, seed ^ (++emitted * 0x9E3779B9U));
        }
        // A long suspended frame must not create an unbounded catch-up burst.
        if (emitted == 4U) {
            clock = std::fmod(clock, emission_period);
        }
    }

    void advance_jetpack_flight(double dt) {
        if (tutorial_session == nullptr) {
            return;
        }
        const auto& local = tutorial_session->player();
        const bool local_active = tutorial_session->alive() && local.jetpack_active;
        const audio::SoundPosition local_position{static_cast<float>(local.position.x),
                                                  static_cast<float>(local.position.y),
                                                  static_cast<float>(local.position.z)};
        update_jetpack_flight_voice(
            local_jetpack_flight_voice, local_active, local_position, true);
        emit_jetpack_flight_particles(
            dt,
            local_jetpack_particle_clock,
            local_active,
            {local_position.x, local_position.y, local_position.z + 0.45F},
            {static_cast<float>(local.velocity.x),
             static_cast<float>(local.velocity.y),
             static_cast<float>(local.velocity.z)},
            static_cast<std::uint32_t>(local_player_id.value_or(127U)) << 24U);

        for (const auto& player : tutorial_roster.players()) {
            if (local_player_id == player.player_id ||
                player.player_id >= remote_character_audio.size()) {
                continue;
            }
            auto& jetpack_state = remote_character_audio[player.player_id];
            const bool active = !player.dead && (player.action_flags & 0x04U) != 0U;
            const auto position = remote_sound_position(player);
            update_jetpack_flight_voice(
                jetpack_state.jetpack_flight_voice, active, position, false);
            emit_jetpack_flight_particles(
                dt,
                jetpack_state.jetpack_particle_clock,
                active,
                {position.x, position.y, position.z + 0.45F},
                {static_cast<float>(player.velocity.x),
                 static_cast<float>(player.velocity.y),
                 static_cast<float>(player.velocity.z)},
                (static_cast<std::uint32_t>(player.player_id) << 24U) ^
                    player.generation);
        }
    }

    void present_remote_character_audio(std::uint8_t player_id,
                                        const world::CharacterAudioEvents& events,
                                        audio::SoundPosition position) {
        if (!audio_started || player_id >= remote_character_audio.size()) {
            return;
        }
        auto& character_audio = remote_character_audio[player_id];
        for (const auto& event : events.events()) {
            if (event.kind == world::CharacterAudioEventKind::movement) {
                play_movement_sound_for(character_audio.logic.class_id,
                                        event.movement,
                                        position,
                                        character_audio.movement_variant);
            } else {
                play_class_voice_for(character_audio.logic.class_id,
                                     event.voice,
                                     position,
                                     character_audio.voices,
                                     event.force_voice,
                                     false);
            }
        }
    }

    void begin_remote_character_audio(const network::RemotePlayerReplica& player) {
        if (!network_match || local_player_id == player.player_id ||
            player.player_id >= remote_character_audio.size()) {
            return;
        }
        auto& character_audio = remote_character_audio[player.player_id];
        stop_remote_jetpack_flight(
            player.player_id, remote_sound_position(player), false);
        character_audio = {};
        world::begin_remote_character_life(
            character_audio.logic,
            remote_character_audio_snapshot(player),
            world::remote_spawn_voice_delay(voice_rng()));
    }

    void observe_remote_character_audio(const network::RemotePlayerReplica& player) {
        if (!network_match || local_player_id == player.player_id ||
            player.player_id >= remote_character_audio.size()) {
            return;
        }
        auto& character_audio = remote_character_audio[player.player_id];
        if (!character_audio.logic.initialized ||
            character_audio.logic.generation != player.generation) {
            begin_remote_character_audio(player);
            return;
        }
        const auto events = world::observe_remote_character_audio(
            character_audio.logic, remote_character_audio_snapshot(player));
        present_remote_character_audio(player.player_id, events, remote_sound_position(player));
    }

    void announce_remote_character_death(const network::RemotePlayerReplica& player) {
        if (!network_match || local_player_id == player.player_id ||
            player.player_id >= remote_character_audio.size()) {
            return;
        }
        auto& character_audio = remote_character_audio[player.player_id];
        if (!character_audio.logic.initialized ||
            character_audio.logic.generation != player.generation) {
            begin_remote_character_audio(player);
        }
        auto snapshot = remote_character_audio_snapshot(player);
        snapshot.health = 0;
        const auto events =
            world::observe_remote_character_audio(character_audio.logic, snapshot);
        present_remote_character_audio(player.player_id, events, remote_sound_position(player));
    }

    void advance_remote_character_audio(double dt) {
        if (!network_match || tutorial_session == nullptr || !audio_started) {
            return;
        }
        for (const auto& player : tutorial_roster.players()) {
            if (local_player_id == player.player_id ||
                player.player_id >= remote_character_audio.size()) {
                continue;
            }
            auto& character_audio = remote_character_audio[player.player_id];
            if (!character_audio.logic.initialized ||
                character_audio.logic.generation != player.generation) {
                begin_remote_character_audio(player);
            }
            const auto events = world::tick_remote_character_audio(
                character_audio.logic, dt, voice_rng());
            present_remote_character_audio(
                player.player_id, events, remote_sound_position(player));
        }
    }

    [[nodiscard]] static audio::SoundPosition
    packet_sound_position(const std::array<float, 3U>& position) noexcept {
        return {position[0U], position[1U], position[2U]};
    }

    [[nodiscard]] audio::SoundPosition
    closest_ambient_point(const ServerAmbientDefinition& definition,
                          audio::SoundPosition listener,
                          audio::SoundPosition fallback) const noexcept {
        if (definition.points.empty()) {
            return fallback;
        }
        const auto distance_squared = [listener](audio::SoundPosition point) {
            const float x = point.x - listener.x;
            const float y = point.y - listener.y;
            const float z = point.z - listener.z;
            return (x * x) + (y * y) + (z * z);
        };
        return *std::ranges::min_element(definition.points, {}, distance_squared);
    }

    /** Keep a local emitter bound to the nearest authored map point. */
    void refresh_server_ambient_positions(audio::SoundPosition listener) {
        if (!audio_started || audio == nullptr) {
            return;
        }
        for (const auto& [loop_id, definition] : server_ambient_sounds) {
            if (!definition.points.empty()) {
                audio->update_named_loop(loop_id,
                                         closest_ambient_point(definition, listener, listener));
            }
        }
    }

    void play_server_sound(const network::PlaySoundPacket& packet) {
        if (!audio_started || audio == nullptr) {
            return;
        }
        // SOUND_MAP 28 is the same global sting inferred from a human->Zombie
        // CreatePlayer. Accept either server representation, but never play
        // both when they describe the same conversion/outbreak edge.
        if (packet.sound_id == 28U &&
            !zombie_conversion_audio.observe_explicit(
                ZombieConversionAudioGate::clock::now())) {
            return;
        }
        const auto group = audio::server_sound_group(packet.sound_id);
        if (group.empty()) {
            // Several ids are deliberately absent from retail SOUND_MAP.
            return;
        }
        const auto position = packet_sound_position(packet.position);
        std::string_view damage_stem;
        // SOUND_MAP 33..44 is the complete dry/water melee-impact range. Match
        // the immediately preceding Damage packet by position, then prefer its
        // recovered tool semantic. This preserves Machete/Riot variants that
        // cannot be named directly by the fixed 61-entry wire table.
        if (!packet.looping && packet.positioned && packet.sound_id >= 33U &&
            packet.sound_id <= 44U) {
            constexpr float maximum_pair_distance_squared{4.0F};
            auto best = pending_melee_sound_hints.end();
            float best_distance = maximum_pair_distance_squared;
            for (auto candidate = pending_melee_sound_hints.begin();
                 candidate != pending_melee_sound_hints.end();
                 ++candidate) {
                const float dx = candidate->position.x - position.x;
                const float dy = candidate->position.y - position.y;
                const float dz = candidate->position.z - position.z;
                const float distance = dx * dx + dy * dy + dz * dz;
                if (distance <= best_distance) {
                    best = candidate;
                    best_distance = distance;
                }
            }
            if (best != pending_melee_sound_hints.end()) {
                const bool submerged =
                    packet.sound_id >= 39U ||
                    position.z >= static_cast<float>(world::VxlMap::height) - 2.0F;
                damage_stem = melee_hit_stem(best->tool_id, submerged);
                const auto* cosmetic=equipped_cosmetic(best->player_id,"weapon:"+std::to_string(best->tool_id)+":world");
                const bool custom=cosmetic&&audio->play_cosmetic_cue(cosmetic->id,"melee-hit-block",0U,position,packet.volume,false);
                pending_melee_sound_hints.erase(best);
                if(custom)return;
            }
        }
        const auto stems = audio::sound_group_stems(group);
        if (stems.empty()) {
            return;
        }
        const auto stem =
            damage_stem.empty() ? stems[server_sound_variant++ % stems.size()] : damage_stem;
        const bool relative = !packet.positioned;
        if (packet.looping) {
            if (!audio->start_named_loop(packet.loop_id,
                                         stem,
                                         false,
                                         position,
                                         packet.volume,
                                         relative,
                                         packet.attenuation,
                                         packet.time)) {
                settings_warning = std::string{audio->last_error()};
            }
            return;
        }
        if (!audio->play_named_one_shot(
                stem, position, packet.volume, relative, packet.time, packet.attenuation)) {
            settings_warning = std::string{audio->last_error()};
        }
    }

    void play_server_ambient(const network::PlayAmbientSoundPacket& packet) {
        if (!audio_started || audio == nullptr) {
            return;
        }
        server_ambience_received = true;
        // The locally resolved stock bed is only a safety net for servers that
        // omit packet 22/24. Never layer it over the authoritative stream.
        audio->stop_ambience();
        audio::SoundPosition position = packet_sound_position(packet.position);
        if (const auto found = server_ambient_sounds.find(packet.loop_id);
            found != server_ambient_sounds.end() && !found->second.points.empty()) {
            const auto listener = tutorial_session != nullptr
                                      ? tutorial_session->eye_position()
                                      : std::array<double, 3U>{0.0, 0.0, 0.0};
            const audio::SoundPosition listener_position{static_cast<float>(listener[0U]),
                                                         static_cast<float>(listener[1U]),
                                                         static_cast<float>(listener[2U])};
            position = closest_ambient_point(found->second, listener_position, position);
        }
        if (packet.looping) {
            if (!audio->start_named_loop(packet.loop_id,
                                         packet.name,
                                         true,
                                         position,
                                         packet.volume,
                                         !packet.positioned,
                                         packet.attenuation,
                                         packet.time)) {
                settings_warning = std::string{audio->last_error()};
            }
        } else if (!audio->play_named_ambient_one_shot(packet.name,
                                                       position,
                                                       packet.volume,
                                                       !packet.positioned,
                                                       packet.attenuation,
                                                       packet.time)) {
            settings_warning = std::string{audio->last_error()};
        }
    }

    /**
     * Turns this tick's entity events into sound, VFX and HUD updates.
     *
     * Rate-limited per (type, cue) because SHIFT+F8 places one of everything at
     * once and a chain detonation would otherwise blow straight through the
     * 16-voice pool and steal voices from gunfire and footsteps.
     */
    void consume_entity_events(double dt) {
        entity_cue_now += dt;
        if (tutorial_session == nullptr) {
            return;
        }
        const auto events = tutorial_session->take_entity_events();
        if (audio == nullptr) {
            return;
        }
        // Projectile fuses follow packet-integrated motion; block fire stays
        // fixed. A missing row is also a hard stop if a destroy event was
        // coalesced during map transition.
        for (auto iterator = entity_effect_loops.begin(); iterator != entity_effect_loops.end();) {
            const auto entity = std::ranges::find(
                tutorial_session->entities(), iterator->first, &world::LocalEntity::id);
            if (entity == tutorial_session->entities().end()) {
                audio->stop_weapon_loop(iterator->second);
                iterator = entity_effect_loops.erase(iterator);
                continue;
            }
            audio->update_weapon_loop(iterator->second,
                                      {static_cast<float>(entity->position.x),
                                       static_cast<float>(entity->position.y),
                                       static_cast<float>(entity->position.z)});
            ++iterator;
        }
        const auto listener = tutorial_session->eye_position();
        for (const auto& event : events) {
            if (event.kind == world::EntityEventKind::health_changed) {
                game_hud.set_health(static_cast<int>(std::lround(event.value)));
                continue;
            }
            const auto* definition = world::find_entity_definition(event.type);
            if (definition == nullptr || audio == nullptr) {
                continue;
            }
            const audio::SoundPosition position{static_cast<float>(event.position.x),
                                                static_cast<float>(event.position.y),
                                                static_cast<float>(event.position.z)};
            if (event.kind == world::EntityEventKind::spawned) {
                const std::string_view loop_stem = event.type == 27U   ? "molotov_fuse_loop"
                                                   : event.type == 28U ? "molotov_blocks_loop"
                                                   : event.type == 32U ? "chemicalbomb_fuse_loop"
                                                                       : "";
                if (!loop_stem.empty() && !entity_effect_loops.contains(event.entity_id)) {
                    const auto voice =
                        audio->start_named_voice_loop(loop_stem, position, 0.75F, false);
                    if (voice != audio::invalid_loop_voice) {
                        entity_effect_loops.emplace(event.entity_id, voice);
                    }
                }
            } else if (event.kind == world::EntityEventKind::expired ||
                       event.kind == world::EntityEventKind::detonated) {
                if (const auto loop = entity_effect_loops.find(event.entity_id);
                    loop != entity_effect_loops.end()) {
                    audio->stop_weapon_loop(loop->second);
                    entity_effect_loops.erase(loop);
                }
            }
            const auto dx = event.position.x - listener[0U];
            const auto dy = event.position.y - listener[1U];
            const auto dz = event.position.z - listener[2U];
            if (dx * dx + dy * dy + dz * dz > entity_audible_range_squared) {
                // Never spend a voice on something the player cannot hear.
                continue;
            }
            std::string_view stem;
            std::array<float, 2U> pitch_bounds{};
            switch (event.kind) {
            case world::EntityEventKind::spawned:
                {
                    const bool submerged =
                        event.in_water || event.position.z >= world::VxlMap::height - 2.0;
                    const auto authored =
                        audio::retail_entity_place_sound(event.type, submerged);
                    stem = authored.group.empty() ? definition->sound_place : authored.group;
                    pitch_bounds = authored.pitch_semitones;
                }
                break;
            case world::EntityEventKind::collected:
                stem = definition->sound_trigger;
                break;
            case world::EntityEventKind::detonated:
                if (event.type == 11U) {
                    // The grave's TerrainImpactKind::grave_explosion owns the
                    // exact death_explode[_water] cue. Playing the entity
                    // catalog cue here as well stacks two identical blasts.
                    continue;
                }
                stem = event.in_water && !definition->sound_trigger_water.empty()
                           ? definition->sound_trigger_water
                           : definition->sound_trigger;
                break;
            case world::EntityEventKind::expired:
                if (event.type == 28U) {
                    stem = "molotov_blocks_burnout";
                }
                break;
            case world::EntityEventKind::target_changed:
                // The turret's acquire/lose cue. Without it a turret tracking
                // you is completely silent until the first rocket, and there is
                // no way to tell it has seen you.
                if (event.type == 8U) {
                    stem = event.value > 0.5 ? "turret_lockon" : "turret_lockoff";
                }
                break;
            default:
                break;
            }
            if (stem.empty() || !entity_cue_ready(event.type, event.kind)) {
                continue;
            }
            if (event.type == 28U) {
                pitch_bounds = {-0.4F, 0.4F};
            }
            const auto draw = static_cast<std::uint32_t>(event.entity_id) ^
                              static_cast<std::uint32_t>(latest_world_loop);
            const auto pitch = audio::retail_sound_pitch_ratio(
                pitch_bounds[0U], pitch_bounds[1U], draw);
            const auto stems = audio::sound_group_stems(stem);
            if (!stems.empty()) {
                static_cast<void>(audio->play_named_one_shot(stems[draw % stems.size()],
                                                              position,
                                                              0.8F,
                                                              false,
                                                              0.0F,
                                                              0.15F,
                                                              false,
                                                              pitch));
            }
        }
    }

    /**
     * Places the menu-selected entity where the player is looking.
     *
     * Reuses the crosshair resolver the block, prefab and deployable paths
     * already share, so a spawned crate lands on exactly the face a placed
     * block would. When the ray hits nothing, it drops the entity a few units
     * ahead in mid-air rather than silently doing nothing -- seeing it fall is
     * how the user knows they were aiming at sky.
     */
    void spawn_selected_entity() {
        if (!developer_tools_allowed()) {
            deny_developer_action();
            return;
        }
        if (tutorial_session == nullptr) {
            return;
        }
        const auto type = tutorial_session->debug_selected_entity_type();
        auto position = tutorial_session->placement_position(8.0);
        // placement_position returns the player's own position on a miss, which
        // is the documented "hit nothing" signal rather than a real target.
        const auto self = tutorial_session->diagnostics().position;
        if (position.x == self.x && position.y == self.y && position.z == self.z) {
            const auto yaw = tutorial_session->yaw() * std::numbers::pi / 180.0;
            position = {self.x - std::cos(yaw) * 3.0, self.y - std::sin(yaw) * 3.0, self.z};
        }
        if (tutorial_session->spawn_entity(type, position) == 0U) {
            settings_warning = "entity spawn refused: slot budget full";
            play_back();
            return;
        }
        play_confirm();
    }

    /**
     * The block-hit cue for one melee tool, dry or submerged.
     *
     * Retail authored a distinct pair for every digging implement -- a pickaxe
     * rings, a knife scrapes, a crowbar clangs, a zombie hand thuds -- and all
     * fourteen stems ship. We were playing the plain spade sample for every
     * one of them, so a knife and a super spade sounded identical.
     */
    [[nodiscard]] static std::string_view melee_hit_stem(std::uint8_t tool_id,
                                                         bool submerged) noexcept {
        switch (tool_id) {
        case 0U:  // PICKAXE
        case 44U: // UGC_PICKAXE
            return submerged ? "hitwater_pickaxe" : "hitground_pickaxe";
        case 1U: // KNIFE
            return submerged ? "hitwater_knife" : "hitground_knife_damage";
        case 3U:  // SUPERSPADE
        case 45U: // UGC_SUPERSPADE
            return submerged ? "hitwater_super" : "hitground_super";
        case 24U: // ZOMBIEHAND
            return submerged ? "hitwater_zomb" : "hitground_zombie";
        case 34U: // CROWBAR
            return submerged ? "hitwater_crowbar" : "hitground_crowbar_damage";
        case 49U: // RIOTSTICK
            return submerged ? "hitwater_riotstick" : "hitground_riotstick_damage";
        case 50U: // MACHETE
            return submerged ? "hitwater_machete" : "hitground_machete_damage";
        case 52U: // RIOTSHIELD
            return submerged ? "hitwater_riotshield" : "hitground_riotshield_damage";
        default:
            // SPADE and CLASSIC_SPADE are the baseline pair.
            return submerged ? "hitwater" : "hitground";
        }
    }

    /** Audible radius for entity cues, squared. */
    static constexpr double entity_audible_range_squared{96.0 * 96.0};
    /** Minimum gap between two identical entity cues. */
    static constexpr double entity_cue_interval{0.05};
    std::map<std::uint32_t, double> entity_cue_clock;
    /** Client-derived loops bounded by authoritative entity lifetime. */
    std::map<std::uint64_t, audio::LoopVoice> entity_effect_loops;
    double entity_cue_now{};

    [[nodiscard]] bool entity_cue_ready(std::uint8_t type, world::EntityEventKind kind) {
        const auto key = static_cast<std::uint32_t>(type) << 8U | static_cast<std::uint32_t>(kind);
        auto& last = entity_cue_clock[key];
        if (entity_cue_now - last < entity_cue_interval && last != 0.0) {
            return false;
        }
        last = entity_cue_now;
        return true;
    }

    /** Drops the spin loop without a tail; used on teardown and weapon change. */
    void close_spin_loop() {
        if (spin_loop.voice != audio::invalid_loop_voice) {
            audio->stop_weapon_loop(spin_loop.voice);
            spin_loop.voice = audio::invalid_loop_voice;
        }
    }

    [[nodiscard]] FrontendScreen screen() const noexcept {
        return navigation.active().value_or(FrontendScreen::select_menu);
    }

    [[nodiscard]] std::string supported_ui_skin(std::string_view requested) const {
        if (requested.empty() || requested == "default")
            return "default";
        const auto* skin = world::find_ui_skin(requested);
        return skin == nullptr ? std::string{"default"} : std::string{skin->id};
    }

    [[nodiscard]] bool accepts_input() const noexcept {
        return navigation.shell().accepts_input() &&
               (!is_create_match_screen(screen()) || create_match_page_shell.accepts_input());
    }

    /**
     * One fail-closed boundary for every developer surface and mutation.
     *
     * A locally hosted match is still network-authoritative, so it receives
     * the same treatment as a public server. The request and worker fields
     * close the loading-window gap before an ENet transport exists.
     */
    [[nodiscard]] bool developer_tools_allowed() const noexcept {
#if !AOS_ENABLE_DEVELOPER_TOOLS
        return false;
#else
        const bool connection_pending = active_match_request.has_value() ||
                                        pending_match_identity.has_value() ||
                                        active_local_host_generation != 0U;
        return offline_developer_tools_allowed(
            network_match, match_connection != nullptr, connection_pending);
#endif
    }

    void deny_developer_action() {
        tutorial_diagnostics_visible = false;
        entity_menu_visible = false;
        debug_arm_variant = 0;
        settings_warning = "Developer tools are disabled during online and hosted matches.";
    }

    /**
     * Closes a debug surface that survived underneath a route transition.
     *
     * Key handlers also check the policy at the point of mutation. This is
     * defense in depth for a debug page left in the navigation stack while a
     * connection is started from another page.
     */
    void enforce_developer_access() {
        if (developer_tools_allowed())
            return;
        const bool had_debug_state =
            tutorial_diagnostics_visible || entity_menu_visible || debug_arm_variant != 0 ||
            ui_layout_editor.active() || screen() == FrontendScreen::gameplay_debug ||
            screen() == FrontendScreen::parity_debug;
        tutorial_diagnostics_visible = false;
        entity_menu_visible = false;
        debug_arm_variant = 0;
        ui_layout_editor.set_active(false);
        gameplay_debug_lab.set_primary(false);
        gameplay_debug_lab.set_secondary(false);
        for (std::size_t attempt{}; attempt < 2U; ++attempt) {
            if (screen() != FrontendScreen::gameplay_debug &&
                screen() != FrontendScreen::parity_debug) {
                break;
            }
            if (!navigation.pop()) {
                static_cast<void>(
                    navigation.reset(FrontendScreen::select_menu, NavigationDirection::back));
                break;
            }
        }
        if (had_debug_state)
            deny_developer_action();
    }

    void reset_create_match_page_transition() {
        create_match_page_shell = FrontendShellModel{};
        static_cast<void>(
            create_match_page_shell.start(create_match_page_id(create_match_menu.page())));
        previous_create_match_page.reset();
    }

    void return_to_select() {
        static_cast<void>(navigation.reset(FrontendScreen::select_menu, NavigationDirection::back));
    }

    void return_to_settings() {
        if (screen() == FrontendScreen::resolution_confirmation) {
            static_cast<void>(navigation.pop());
        } else if (screen() != FrontendScreen::settings) {
            static_cast<void>(
                navigation.replace(FrontendScreen::settings, NavigationDirection::back));
        }
    }

    [[nodiscard]] SettingsMenuEnvironment
    make_settings_environment(SettingsMenuContext context,
                              settings::Resolution fallback_resolution) const {
        SettingsMenuEnvironment environment;
        environment.context = context;
        environment.multisampling_supported = true;
        environment.glsl_shader_quality_supported = true;
        environment.graphics_apis.clear();
        for (const auto backend : render::supported_graphics_backends()) {
            environment.graphics_apis.push_back(settings_api(backend));
        }
        environment.languages.clear();
        for (const auto& language : localization.languages()) {
            environment.languages.push_back({language.locale, language.native_name});
        }
        if (environment.languages.empty()) {
            environment.languages.push_back({"en", "English"});
        }
        for (const auto& mode : window.display_modes()) {
            const settings::Resolution resolution{mode.extent.width, mode.extent.height};
            if (std::ranges::find(environment.display_modes, resolution) ==
                environment.display_modes.end()) {
                environment.display_modes.push_back(resolution);
            }
        }
        if (environment.display_modes.empty()) {
            environment.display_modes.push_back(fallback_resolution);
        }
        return environment;
    }

    void rebuild_settings_menu(SettingsMenuContext context) {
        settings_menu = std::make_unique<SettingsMenuModel>(
            settings_session,
            make_settings_environment(context, settings_session.draft().graphics.resolution));
    }

    void load_settings() {
        settings_warning.clear();
        skin_variant_preferences=std::make_unique<world::SkinVariantPreferences>(
            config.settings_path.parent_path()/"skin-variants.json");
        if(!skin_variant_preferences->load(settings_warning))settings_warning="Skin choices: "+settings_warning;
        applied_skin_variant_revision=skin_variant_preferences->revision();
        settings_store = std::make_unique<settings::TomlSettingsStore>(config.settings_path);
        favourite_server_store = std::make_unique<FavoriteServerStore>(
            config.settings_path.parent_path() / "server_favorites.txt");
        favourite_servers = favourite_server_store->load();
        const auto loaded = settings_store->load();
        auto initial = loaded ? loaded.settings : settings::retail_default_settings();
        if (!loaded) {
            settings_warning = loaded.error;
        }
        if (!localization.set_active_locale(initial.main.language)) {
            initial.main.language = std::string{localization.active_locale()};
        }

        // Retail defaults describe a fullscreen first boot, but this native
        // launcher deliberately opens a safe window before a settings file
        // exists. Keep the draft truthful to that real window; otherwise the
        // menu says Fullscreen ON while SDL is still windowed and Cancel can
        // unexpectedly switch display modes. Persisted settings retain exact
        // retail semantics on every subsequent launch.
        if (!loaded || !loaded.file_found) {
            const auto current_extent = window.logical_extent();
            initial.main.fullscreen = window.is_fullscreen();
            initial.graphics.resolution = {
                current_extent.width,
                current_extent.height,
            };
        }
        std::vector<settings::GraphicsApi> supported_apis;
        for (const auto backend : render::supported_graphics_backends()) {
            supported_apis.push_back(settings_api(backend));
        }
        if (std::ranges::find(supported_apis, initial.graphics.graphics_api) ==
            supported_apis.end()) {
            const auto unavailable =
                std::string{settings::graphics_api_name(initial.graphics.graphics_api)};
            initial.graphics.graphics_api = settings::GraphicsApi::automatic;
            if (!settings_warning.empty()) {
                settings_warning += "; ";
            }
            settings_warning +=
                "graphics API '" + unavailable + "' is unavailable on this platform; using auto";
        }

        settings_session = settings::SettingsSession{initial};
        confirmed_settings = settings_session.committed();
        applied_settings = confirmed_settings;
        resolution_rollback.reset();
        resolution_restart_required = false;

        // Apply a previously confirmed display mode before bgfx attaches to
        // the native surface. A missing first-run file deliberately retains
        // the launcher window so automated and accessibility flows are not
        // surprised by an unsolicited exclusive-fullscreen transition.
        if (loaded && loaded.file_found &&
            !window.apply_display_mode(
                {initial.graphics.resolution.width, initial.graphics.resolution.height},
                initial.main.fullscreen)) {
            settings_warning = "saved display mode could not be applied";
            const auto actual_extent = window.logical_extent();
            applied_settings.main.fullscreen = window.is_fullscreen();
            applied_settings.graphics.resolution = {actual_extent.width, actual_extent.height};
        }

        rebuild_settings_menu(SettingsMenuContext::frontend);
    }

    [[nodiscard]] bool apply_display(const settings::ClientSettings& value) {
        const platform::WindowExtent requested{value.graphics.resolution.width,
                                               value.graphics.resolution.height};
        if (window.is_fullscreen() == value.main.fullscreen &&
            window.logical_extent() == requested) {
            return true;
        }
        if (!window.apply_display_mode(requested, value.main.fullscreen)) {
            settings_warning = "display mode change was rejected by SDL";
            return false;
        }
        return true;
    }

    void apply_cosmetic_preferences(const settings::MainSettings& value) {
        if (applied_settings.main.show_skins != value.show_skins) {
            uploaded_sandbox_tool.reset(); uploaded_tool.reset();
            loaded_tutorial_arm_class.reset(); view_model_meshes_uploaded=false;
        }
        // Remote rigs and world props compare their resolved appearance every
        // update and rebuild incrementally. Keep authoritative equipment cached
        // so turning visibility back on never needs an inventory request.
        applied_settings.main.show_skins=value.show_skins;
        applied_settings.main.show_other_skins=value.show_other_skins;
        applied_settings.main.weapon_motion=value.weapon_motion;
    }

    [[nodiscard]] bool apply_runtime_settings(const settings::ClientSettings& value,
                                              bool include_display) {
        bool success{true};
        const auto previous_locale = std::string{localization.active_locale()};
        if (!localization.set_active_locale(value.main.language)) {
            settings_warning = "selected language pack is unavailable";
            success = false;
        } else if (previous_locale != localization.active_locale()) {
            localization_generation = localization.generation();
            release_text_textures();
        }
        if (audio_started && audio != nullptr) {
            success =
                audio->set_master_volume(static_cast<float>(value.main.master_volume)) && success;
            success =
                audio->set_music_volume(static_cast<float>(value.main.music_volume)) && success;
        }
        if (renderer.is_initialized()) {
            success = renderer.set_presentation_options(
                          value.graphics.vsync, msaa_samples(value.graphics.antialiasing)) &&
                      success;
        }
        if (include_display) {
            success = apply_display(value) && success;
        }
        if (success) {
            apply_cosmetic_preferences(value.main);
            applied_settings = value;
            if (tutorial_session != nullptr) {
                tutorial_session->set_look_preferences(
                    value.controls.mouse_sensitivity, value.main.invert_mouse);
            }
        }
        return success;
    }

    [[nodiscard]] bool apply_live_preview(SettingsRowId source,
                                          const settings::ClientSettings& draft) {
        switch (source) {
        case SettingsRowId::show_skins:
        case SettingsRowId::show_other_skins:
        case SettingsRowId::weapon_motion:
            apply_cosmetic_preferences(draft.main);
            return true;
        case SettingsRowId::language:
            if (!localization.set_active_locale(draft.main.language)) {
                settings_warning = "selected language pack is unavailable";
                return false;
            }
            localization_generation = localization.generation();
            release_text_textures();
            applied_settings.main.language = draft.main.language;
            return true;
        case SettingsRowId::master_volume:
            if (audio_started && audio != nullptr &&
                !audio->set_master_volume(static_cast<float>(draft.main.master_volume))) {
                settings_warning = "master volume preview was rejected by OpenAL";
                return false;
            }
            applied_settings.main.master_volume = draft.main.master_volume;
            return true;
        case SettingsRowId::music_volume:
            if (audio_started && audio != nullptr &&
                !audio->set_music_volume(static_cast<float>(draft.main.music_volume))) {
                settings_warning = "music volume preview was rejected by OpenAL";
                return false;
            }
            applied_settings.main.music_volume = draft.main.music_volume;
            return true;
        case SettingsRowId::fullscreen:
            if (!apply_display(draft)) {
                // A failed live display mutation must not leave the draft
                // claiming a mode the active SDL window never entered.
                auto main = settings_session.draft().main;
                main.fullscreen = applied_settings.main.fullscreen;
                settings_session.set_main(main);
                return false;
            }
            applied_settings.main.fullscreen = draft.main.fullscreen;
            applied_settings.graphics.resolution = draft.graphics.resolution;
            return true;
        case SettingsRowId::vsync:
            if (renderer.is_initialized() &&
                !renderer.set_presentation_options(
                    draft.graphics.vsync, msaa_samples(applied_settings.graphics.antialiasing))) {
                settings_warning = "VSync preview was rejected by bgfx";
                return false;
            }
            applied_settings.graphics.vsync = draft.graphics.vsync;
            return true;
        default:
            return true;
        }
    }

    [[nodiscard]] bool save_settings(const settings::ClientSettings& value) {
        if (settings_store == nullptr) {
            settings_warning = "settings store is unavailable";
            return false;
        }
        const auto saved = settings_store->save(value);
        if (!saved) {
            settings_warning = saved.error;
            return false;
        } else {
            settings_warning.clear();
        }
        return true;
    }

    void handle_resolution_confirmation(ResolutionConfirmationAction action) {
        if (!resolution_rollback.has_value()) {
            return_to_settings();
            return;
        }
        if (action == ResolutionConfirmationAction::keep) {
            const auto candidate = settings_session.committed();
            if (!save_settings(candidate)) {
                const auto restored = *resolution_rollback;
                settings_session = settings::SettingsSession{restored};
                static_cast<void>(apply_runtime_settings(restored, true));
                resolution_rollback.reset();
                resolution_restart_required = false;
                if (settings_menu != nullptr) {
                    settings_menu->set_active_tab(settings::SettingsTab::graphics);
                }
                return_to_settings();
                if (audio_started) {
                    audio->play_menu_back();
                }
                return;
            }
            confirmed_settings = candidate;
            resolution_rollback.reset();
            if (resolution_restart_required) {
                settings_warning = "Restart required for graphics quality changes to take effect.";
            }
            resolution_restart_required = false;
            if (settings_opened_from_gameplay) {
                static_cast<void>(navigation.pop_instant());
                close_settings();
            } else {
                return_to_select();
            }
            if (audio_started) {
                audio->play_menu_confirm();
            }
            return;
        }

        const auto restored = *resolution_rollback;
        resolution_rollback.reset();
        resolution_restart_required = false;
        settings_session = settings::SettingsSession{restored};
        confirmed_settings = restored;
        static_cast<void>(apply_runtime_settings(restored, true));
        if (settings_menu != nullptr) {
            settings_menu->set_active_tab(settings::SettingsTab::graphics);
        }
        return_to_settings();
        if (audio_started) {
            audio->play_menu_back();
        }
    }

    void consume_settings_effects() {
        if (settings_menu == nullptr) {
            return;
        }
        for (auto& effect : settings_menu->take_effects()) {
            std::visit(
                [this](const auto& payload) {
                    using Payload = std::decay_t<decltype(payload)>;
                    if constexpr (std::is_same_v<Payload, SettingsSoundEffect>) {
                        if (!audio_started) {
                            return;
                        }
                        switch (payload.sound) {
                        case SettingsMenuSound::confirm:
                            audio->play_menu_confirm();
                            break;
                        case SettingsMenuSound::back:
                            audio->play_menu_back();
                            break;
                        case SettingsMenuSound::scroll:
                            audio->play_menu_scroll();
                            break;
                        }
                    } else if constexpr (std::is_same_v<Payload, SettingsPreviewEffect>) {
                        switch (payload.source) {
                        case SettingsRowId::show_skins:
                        case SettingsRowId::show_other_skins:
                        case SettingsRowId::weapon_motion:
                        case SettingsRowId::language:
                        case SettingsRowId::master_volume:
                        case SettingsRowId::music_volume:
                        case SettingsRowId::fullscreen:
                        case SettingsRowId::vsync:
                            static_cast<void>(apply_live_preview(payload.source, payload.draft));
                            break;
                        default:
                            break;
                        }
                    } else if constexpr (std::is_same_v<Payload, SettingsDefaultsCommand>) {
                        if (payload.tab == settings::SettingsTab::main) {
                            apply_cosmetic_preferences(payload.draft.main);
                            static_cast<void>(
                                apply_live_preview(SettingsRowId::language, payload.draft));
                            static_cast<void>(
                                apply_live_preview(SettingsRowId::master_volume, payload.draft));
                            static_cast<void>(
                                apply_live_preview(SettingsRowId::music_volume, payload.draft));
                            static_cast<void>(
                                apply_live_preview(SettingsRowId::fullscreen, payload.draft));
                        } else if (payload.tab == settings::SettingsTab::graphics) {
                            static_cast<void>(
                                apply_live_preview(SettingsRowId::vsync, payload.draft));
                        }
                    } else if constexpr (std::is_same_v<Payload, SettingsCommitCommand>) {
                        if (!payload.changed) {
                            close_settings();
                            return;
                        }
                        if (payload.resolution_changed) {
                            resolution_rollback = confirmed_settings;
                            if (!apply_runtime_settings(payload.settings, true)) {
                                const auto rollback = *resolution_rollback;
                                resolution_rollback.reset();
                                settings_session = settings::SettingsSession{rollback};
                                static_cast<void>(apply_runtime_settings(rollback, true));
                                if (settings_menu != nullptr) {
                                    settings_menu->set_active_tab(settings::SettingsTab::graphics);
                                }
                                return_to_settings();
                                suppress_next_settings_close = true;
                                return;
                            }
                            resolution_restart_required = payload.restart_required;
                            resolution_confirmation.restart();
                            static_cast<void>(
                                navigation.push(FrontendScreen::resolution_confirmation));
                        } else {
                            const auto restored = confirmed_settings;
                            if (!apply_runtime_settings(payload.settings, true)) {
                                settings_session = settings::SettingsSession{restored};
                                static_cast<void>(apply_runtime_settings(restored, true));
                                return_to_settings();
                                suppress_next_settings_close = true;
                                return;
                            }
                            if (!save_settings(payload.settings)) {
                                settings_session = settings::SettingsSession{restored};
                                static_cast<void>(apply_runtime_settings(restored, true));
                                return_to_settings();
                                suppress_next_settings_close = true;
                                return;
                            }
                            confirmed_settings = payload.settings;
                            close_settings();
                            if (payload.restart_required) {
                                settings_warning =
                                    "Restart required for graphics quality changes to take effect.";
                            }
                        }
                    } else if constexpr (std::is_same_v<Payload, SettingsRestoreCommand>) {
                        settings_session = settings::SettingsSession{confirmed_settings};
                        static_cast<void>(apply_runtime_settings(confirmed_settings, true));
                    } else if constexpr (std::is_same_v<Payload, SettingsCloseCommand>) {
                        if (suppress_next_settings_close) {
                            suppress_next_settings_close = false;
                            return;
                        }
                        if (screen() == FrontendScreen::settings) {
                            close_settings();
                        }
                    } else if constexpr (std::is_same_v<Payload, SettingsFavoriteServerCommand>) {
                        // Frontend Settings intentionally exposes Favourite as
                        // disabled; live server-list integration owns this effect.
                    } else if constexpr (std::is_same_v<Payload, SettingsBindingRejectedEffect>) {
                        settings_warning = "key binding was rejected";
                    }
                },
                effect);
        }
    }

