    [[nodiscard]] std::optional<std::filesystem::path> resolve_local_server_bundle() const {
        if (!config.local_server_root.empty()) {
            if (const auto found = newest_server_bundle_below(config.local_server_root);
                found.has_value()) {
                return found;
            }
        }
        if (const auto environment = environment_value("AOS_BATTLESPADES_SERVER");
            environment.has_value()) {
            if (const auto found = newest_server_bundle_below(std::filesystem::path{*environment});
                found.has_value()) {
                return found;
            }
        }
        const auto executable_adjacent = config.settings_path.parent_path();
        if (const auto found = newest_server_bundle_below(executable_adjacent / "server");
            found.has_value()) {
            return found;
        }
#if defined(AOS_DEV_BATTLESPADES_ROOT)
        if (const auto found =
                newest_server_bundle_below(std::filesystem::path{AOS_DEV_BATTLESPADES_ROOT});
            found.has_value()) {
            return found;
        }
#endif
        return std::nullopt;
    }

    /**
     * Start one client-owned server without blocking the presentation thread.
     *
     * Both Create Match and Map Creator use this boundary.  The child process
     * owns authoritative gameplay and project persistence; this client only
     * probes its LAN endpoint and then enters the normal Protocol 168
     * bootstrap.  Keeping both paths here prevents the UGC route from
     * fabricating a completed loading model without a server or VXL stream.
     */
    void begin_owned_local_server(platform::LocalServerLaunchConfig launch,
                                  std::string mode_key,
                                  bool classic,
                                  std::string skin,
                                  std::optional<network::RevivalRelayLobbyRequest>
                                      relay_request = std::nullopt) {
        // --steam-only isolates the Steam path. With both doors open, a friend
        // who arrives through the relay makes a broken Steam tunnel look like a
        // working one, which is exactly what a two-machine test must rule out.
        if (config.steam_only && relay_request.has_value()) {
            relay_request.reset();
            core::diagnostic("steam", "--steam-only: no AoSPlay relay lobby will be published");
        }
        // Include still-closing servers in the admission limit. A fast sequence
        // of Start/Back must not spawn an unbounded cleanup/process backlog.
        if (owned_local_server && !owned_local_server->running()) release_owned_local_match_host();
        auto cleanup = host_cleanup.try_reserve();
        if (!cleanup) {
            settings_warning = "The previous hosted sessions are still closing. Please try again shortly.";
            queue_social_start_failed(settings_warning);
            return;
        }
        if (relay_request && social_client != nullptr) {
            const auto snapshot = social_client->snapshot();
            if (snapshot.lobby) {
                owned_social_lobby_id = snapshot.lobby->id;
                owned_social_start_id = snapshot.lobby->start_id;
            }
        }
        match_ui_skin = supported_ui_skin(skin);
        match_loading.begin(launch.map_name, mode_key, classic, match_ui_skin);
        if (screen() != FrontendScreen::game_loading) {
            static_cast<void>(navigation.push(FrontendScreen::game_loading));
        }
        settings_warning = launch.program == platform::LocalServerProgram::map_creator
                               ? "Starting the private BattleSpades Map Creator"
                           : relay_request.has_value()
                               ? "Allocating and starting the public community match"
                               : "Starting a private local BattleSpades server";
        match_loading.set_status(settings_warning);
        std::fprintf(stderr, "[hosting] bundle=%s mode=%s map=%s\n",
                     path_utf8(launch.bundle_root).c_str(), launch.mode.c_str(), launch.map_name.c_str());
        const auto generation = next_local_host_generation++;
        active_local_host_generation = generation;
        local_host_cancel = std::make_shared<std::stop_source>();
        const auto cancellation = local_host_cancel;
        const auto identity = identity_service;
        local_host_worker = std::async(
            std::launch::async,
            [generation,
             launch = std::move(launch),
             mode_key = std::move(mode_key),
             classic,
             skin = std::move(skin),
             cancellation,
             cleanup = std::move(*cleanup),
             identity,
             relay_request = std::move(relay_request)]() mutable {
                std::optional<network::RevivalRelayLobby> relay;
                std::unique_ptr<platform::LocalServerProcess> process;
                std::unique_ptr<platform::RelayHostTunnel> tunnel;
                try {
                if (relay_request.has_value()) {
                    auto allocated = identity->create_relay_lobby(*relay_request, cancellation->get_token());
                    if (!allocated || !allocated.lobby.has_value()) {
                        return LocalHostOutcome{
                            generation, {}, {}, {}, {},
                            allocated.error.empty()
                                ? "AoSPlay could not allocate a public match relay."
                                : std::move(allocated.error)};
                    }
                    relay = std::move(*allocated.lobby);
                    launch.environment_overrides = {
                        {"AOS_MASTER_URL", relay->master_url},
                        {"AOS_MASTER_WRITE_TOKEN", relay->server_token},
                        {"AOS_PUBLIC_HOST", relay->relay_host},
                        {"AOS_PUBLIC_PORT", std::to_string(relay->relay_port)},
                        {"AOS_PUBLIC_QUERY_PORT", std::to_string(relay->relay_port)},
                        {"AOS_SERVER_ID", relay->server_id},
                        {"AOS_RELAY_LOBBY_ID", relay->lobby_id},
                    };
                    const auto results_directory = identity->hosted_results_directory();
                    if (!results_directory.empty()) {
                        launch.environment_overrides.emplace("AOS_MATCH_RESULTS_DIRECTORY", path_utf8(results_directory));
                    }
                    if (launch.program == platform::LocalServerProgram::map_creator) {
                        const auto account = identity->cached_account();
                        if (!account || account->legacy_id.empty()) {
                            static_cast<void>(identity->close_relay_lobby(*relay));
                            return LocalHostOutcome{generation, {}, {}, {}, {}, "Editor owner identity is unavailable."};
                        }
                        launch.environment_overrides.emplace("AOS_UGC_OWNER_ID", account->legacy_id);
                    }
                }
                if (cancellation->stop_requested()) {
                    if (relay) static_cast<void>(identity->close_relay_lobby(*relay));
                    return LocalHostOutcome{generation, {}, {}, {}, {}, "Local server startup was cancelled"};
                }
                process = std::make_unique<platform::LocalServerProcess>();
                std::string error;
                if (!process->start(launch, error)) {
                    if (relay.has_value()) {
                        static_cast<void>(identity->close_relay_lobby(*relay));
                    }
                    return LocalHostOutcome{generation, std::move(process), {}, {}, {},
                                            std::move(error)};
                }
                std::fprintf(stderr, "[hosting] process started on UDP %u\n",
                             static_cast<unsigned>(process->port()));
                if (relay.has_value()) {
                    tunnel = std::make_unique<platform::RelayHostTunnel>();
                    platform::RelayHostTunnelConfig tunnel_config;
                    tunnel_config.allocation_id = relay->allocation_id;
                    tunnel_config.relay_host = relay->relay_host;
                    tunnel_config.relay_port = relay->relay_port;
                    tunnel_config.host_key_base64url = relay->host_key;
                    tunnel_config.local_server_port = process->port();
                    tunnel_config.maximum_clients = launch.maximum_players;
                    tunnel_config.keepalive = std::chrono::seconds{
                        relay->keepalive_seconds};
                    if (!tunnel->start(std::move(tunnel_config), error)) {
                        process->stop();
                        static_cast<void>(identity->close_relay_lobby(*relay));
                        return LocalHostOutcome{generation, std::move(process),
                                                std::move(tunnel), {}, {},
                                                std::move(error)};
                    }
                }
                const auto endpoint = network::ServerEndpoint{"127.0.0.1", process->port()};
                const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds{20};
                auto next_legacy_probe = std::chrono::steady_clock::now() + std::chrono::milliseconds{500};
                while (!cancellation->stop_requested() &&
                       std::chrono::steady_clock::now() < deadline) {
                    if (!process->running()) {
                        error = "The local BattleSpades server exited during startup";
                        break;
                    }
                    const auto state = process->status();
                    bool ready = state == platform::LocalServerState::ready;
                    if (state == platform::LocalServerState::failed ||
                        state == platform::LocalServerState::stopped ||
                        state == platform::LocalServerState::stopping) {
                        error = "The local server could not finish starting. Check its startup log.";
                        break;
                    }
                    // New servers report readiness directly after map/mode/bot
                    // initialization. Older bundles still use their LAN probe.
                    if (state == platform::LocalServerState::unavailable &&
                        std::chrono::steady_clock::now() >= next_legacy_probe) {
                        const auto discovery = network::probe_lan_server(endpoint, std::chrono::milliseconds{150});
                        next_legacy_probe = std::chrono::steady_clock::now() + std::chrono::milliseconds{250};
                        if (discovery && !discovery.servers.empty()) {
                            if (discovery.servers.front().mode_code != launch.mode) {
                                error = "The local server started with the wrong game mode.";
                                break;
                            }
                            ready = true;
                        }
                    }
                    if (ready) {
                        std::fprintf(stderr, "[hosting] local server ready via %s\n",
                            state == platform::LocalServerState::ready ? "native bridge" : "LAN probe");
                        const auto relay_server_id = relay.has_value()
                                                         ? relay->server_id
                                                         : std::string{};
                        const auto identity_ticket = relay.has_value();
                        auto request = ServerConnectRequest{endpoint.identifier(),
                                                 endpoint.host,
                                                 endpoint.port,
                                                 launch.map_name,
                                                 mode_key,
                                                 skin,
                                                 classic,
                                                 relay_server_id,
                                                 identity_ticket};
                        return LocalHostOutcome{
                            generation,
                            std::move(process),
                            std::move(tunnel),
                            std::move(relay),
                            std::move(request),
                            {}, std::move(cleanup)};
                    }
                    std::this_thread::sleep_for(std::chrono::milliseconds{25});
                }
                if (cancellation->stop_requested()) {
                    error = "Local server startup was cancelled";
                } else if (error.empty()) {
                    error = "The local BattleSpades server did not become ready in 20 seconds";
                }
                const auto tail = bounded_log_tail(process->log_path());
                if (!tail.empty())
                    error += "\n" + tail;
                if (tunnel != nullptr) tunnel->stop();
                process->stop();
                if (relay.has_value()) {
                    static_cast<void>(identity->close_relay_lobby(*relay));
                }
                return LocalHostOutcome{generation, std::move(process), std::move(tunnel),
                                        {}, {}, std::move(error)};
                } catch (const std::exception& error) {
                    // Preserve remote allocation credentials as well as local
                    // ownership if startup throws between ordinary checks.
                    return LocalHostOutcome{generation, std::move(process), std::move(tunnel),
                        std::move(relay), {}, std::string{"Local server startup failed: "} + error.what(),
                        std::move(cleanup)};
                } catch (...) {
                    return LocalHostOutcome{generation, std::move(process), std::move(tunnel),
                        std::move(relay), {}, "Local server startup failed unexpectedly.", std::move(cleanup)};
                }
            });
    }

    void begin_local_match(const CreateMatchConfiguration& configuration,
                           bool public_lobby = true) {
        if (local_host_worker.valid() ||
            (owned_local_server != nullptr && owned_local_server->running())) {
            settings_warning = "A client-owned local match is already active";
            return;
        }
        const auto bundle = resolve_local_server_bundle();
        if (!bundle.has_value()) {
            settings_warning =
                "The complete BattleSpades server bundle is missing. Put it in server/ "
                "beside BattleSpadesClient.exe.";
            return;
        }
        const auto modes = retail_create_match_modes();
        const auto mode = std::ranges::find(modes,
                                            configuration.retail_playlist_id,
                                            &CreateMatchModeDefinition::retail_playlist_id);
        const auto mode_key =
            mode == modes.end() ? std::string{"TDM_TITLE"} : std::string{mode->label_key};
        const auto mode_code =
            mode == modes.end() ? std::string{"tdm"} : std::string{mode->mode_key};
        const auto classic = mode != modes.end() && mode->family == CreateMatchModeFamily::classic;
        const auto skin = mode != modes.end() && mode->family == CreateMatchModeFamily::mafia
                              ? std::string{"mafia"}
                              : std::string{"classic"};

        platform::LocalServerLaunchConfig launch;
        launch.bundle_root = *bundle;
        launch.session_parent = config.settings_path.parent_path() / "local-server-sessions";
        launch.server_name = create_match_menu.lobby_name();
        launch.mode = mode_code;
        launch.map_name = configuration.map_name;
        launch.rule_overrides = configuration.rule_overrides;
        launch.preferred_port = configuration.server_port == 0U ? config.preferred_local_server_port
                                                                : configuration.server_port;
        launch.maximum_players = configuration.max_players;
        launch.match_minutes = configuration.match_minutes;
        launch.bot_count = configuration.bot_count;
        launch.bot_difficulty = configuration.bot_difficulty;

        std::optional<network::RevivalRelayLobbyRequest> relay_request;
        if (public_lobby && social_client != nullptr) {
            const auto social = social_client->snapshot();
            if (social.lobby.has_value() &&
                social.lobby->owner_id == friends_lobby_menu.local_account_id()) {
                relay_request = network::RevivalRelayLobbyRequest{
                    launch.server_name,
                    launch.map_name,
                    mode_key,
                    mode_code,
                    launch.maximum_players,
                    configuration.retail_playlist_id,
                    skin,
                    classic};
            }
        }
        begin_owned_local_server(std::move(launch), mode_key, classic, skin,
                                 std::move(relay_request));
    }

    void pump_local_match_start() {
        // Shared worker/publish lifecycle handles ordinary and editor hosts.
        using namespace std::chrono_literals;
        if (owned_local_server &&
            (!owned_local_server->running() || (owned_relay_tunnel && !owned_relay_tunnel->running()))) {
            auto error = owned_relay_tunnel ? owned_relay_tunnel->last_error() : std::string{};
            if (error.empty()) error = "The hosted server stopped unexpectedly.";
            fail_social_host_start(error);
            teardown_tutorial();
            static_cast<void>(navigation.leave_match_instant());
            if (social_client) social_client->set_presence("online");
            return;
        }
        if (!local_host_worker.valid() ||
            local_host_worker.wait_for(0ms) != std::future_status::ready) {
            return;
        }
        LocalHostOutcome outcome;
        try {
            outcome = local_host_worker.get();
        } catch (const std::exception& error) {
            if (active_local_host_generation != 0U) {
                fail_social_host_start(std::string{"Local server startup failed: "} + error.what());
            } else {
                std::fprintf(stderr, "[hosting] canceled startup: %s\n", error.what());
            }
            return;
        }
        std::fprintf(stderr, "[hosting] startup worker completed\n");
        if (outcome.generation != active_local_host_generation) {
            retire_local_host(std::move(outcome));
            return;
        }
        active_local_host_generation = 0U;
        local_host_cancel.reset();
        if (!outcome.error.empty() || outcome.process == nullptr || !outcome.process->running()) {
            const auto message = outcome.error.empty() ? "The client-owned local server stopped"
                                                       : std::move(outcome.error);
            queue_social_start_failed(message);
            show_host_start_failure(message);
            retire_local_host(std::move(outcome));
            return;
        }
        owned_local_server = std::move(outcome.process);
        owned_host_cleanup = std::move(outcome.cleanup);
        owned_relay_tunnel = std::move(outcome.tunnel);
        owned_relay_lobby = std::move(outcome.relay);
        // Steam and the AoSPlay relay are independent doors to the same local
        // server. Open the Steam one first: it used to be tried only when the
        // relay had failed, so a healthy relay meant no Steam id was ever shown
        // and every friend arrived through the relay.
        steam_host_id = start_steam_host(owned_local_server->port(),
                                         owned_relay_lobby.has_value() ? owned_relay_lobby->server_id
                                                                       : std::string{});
        const std::string steam_invite =
            steam_host_id != 0U ? "Friends can join with steam:" + std::to_string(steam_host_id)
                                : std::string{};
        if (owned_relay_lobby.has_value()) {
            social_pending_owner_connect = std::move(outcome.request);
            const auto now = std::chrono::steady_clock::now();
            social_publish_deadline = now + std::chrono::seconds{20};
            social_publish_retry_at = now;
            social_publish_attempts = 0U;
            settings_warning = steam_invite.empty()
                                   ? "Local server ready; publishing its relay..."
                                   : steam_invite + "; publishing its relay...";
            match_loading.set_status(settings_warning);
            if (!queue_social_publish()) {
                social_publish_retry_at = now + std::chrono::milliseconds{250};
            }
            return;
        }
        settings_warning =
            !steam_invite.empty()
                ? steam_invite
                : "Local server ready on UDP " + std::to_string(owned_local_server->port());
        begin_match_loading(outcome.request);
    }

    void launch_social_session(const CreateMatchConfiguration& configuration) {
        if (social_pending_ugc_start) {
            const auto editor = *social_pending_ugc_start;
            social_pending_ugc_start.reset();
            begin_ugc_editor_loading(editor);
        } else {
            begin_local_match(configuration);
        }
    }

    void consume_create_match_effects(
        std::optional<CreateMatchMenuPresentation> interaction_snapshot = std::nullopt) {
        for (const auto& effect : create_match_menu.take_effects()) {
            std::visit(
                [this, &interaction_snapshot](const auto& payload) {
                    using Payload = std::decay_t<decltype(payload)>;
                    if constexpr (std::is_same_v<Payload, CreateMatchSoundEffect>) {
                        switch (payload.sound) {
                        case CreateMatchSound::confirm:
                            play_confirm();
                            break;
                        case CreateMatchSound::back:
                            play_back();
                            break;
                        case CreateMatchSound::scroll:
                            play_scroll();
                            break;
                        }
                    } else if constexpr (std::is_same_v<Payload, CreateMatchPageChangedEffect>) {
                        // Retail BaseSquadLobbyMenu keeps the lobby/player column fixed and
                        // replaces only its right-side panel. A full-screen navigation slide
                        // makes Mode, Map, and Rules look like unrelated screens.
                        previous_create_match_page.reset();
                        interaction_snapshot.reset();
                        create_match_page_shell = FrontendShellModel{};
                        static_cast<void>(create_match_page_shell.start(
                            create_match_page_id(payload.to)));
                    } else if constexpr (
                        std::is_same_v<Payload, CreateMatchPlatformActionEffect>) {
                        if (payload.action == CreateMatchPlatformAction::invite_friends) {
                            const auto now = std::chrono::steady_clock::now();
                            friends_lobby_menu.enter(now);
                            static_cast<void>(window.set_text_input_enabled(true));
                            if (!navigation.push(FrontendScreen::friends_lobby)) {
                                friends_lobby_menu.leave();
                                static_cast<void>(window.set_text_input_enabled(false));
                            }
                        }
                    } else if constexpr (
                        std::is_same_v<Payload, CreateMatchConfigurationChangedEffect>) {
                        queue_social_settings(payload.configuration);
                    } else if constexpr (std::is_same_v<Payload, CreateMatchMemberEffect>) {
                        if (!send_lobby_member_action(payload)) {
                            settings_warning = "The member action could not be queued. Refresh the lobby and retry.";
                        }
                    } else if constexpr (std::is_same_v<Payload, CreateMatchChatEffect>) {
                        if (!send_active_lobby_chat(payload.message)) {
                            settings_warning = "Could not send lobby chat. Please retry.";
                        }
                    } else if constexpr (std::is_same_v<Payload, CreateMatchRouteEffect>) {
                        if (payload.action == CreateMatchRouteAction::join_game) {
                            const auto snapshot = social_client != nullptr
                                ? social_client->snapshot() : network::RevivalSocialSnapshot{};
                            if (snapshot.lobby && !snapshot.lobby->server_id.empty() &&
                                (snapshot.lobby->state == "ready" || snapshot.lobby->state == "in_game")) {
                                submit_social_intent({FriendsLobbyActionKind::join_game,
                                                      snapshot.lobby->server_id, {}});
                            } else {
                                create_match_menu.set_match_join_available(false);
                                settings_warning = "The hosted match is no longer available. Waiting for the lobby to update.";
                            }
                        } else if (payload.action == CreateMatchRouteAction::start_local_game) {
                            if (social_start_generation || social_pending_owner_connect ||
                                local_host_worker.valid()) {
                                settings_warning = local_host_worker.valid() && active_local_host_generation == 0U
                                    ? "Finishing the previous server cleanup. Try Local Match again in a moment."
                                    : "A match is already starting. Use Back to cancel it first.";
                                return;
                            }
                            begin_local_match(payload.configuration, false);
                        } else if (payload.action == CreateMatchRouteAction::leave_lobby) {
                            if (social_open_match_generation && social_client != nullptr &&
                                !social_client->snapshot().lobby.has_value()) {
                                social_leave_after_create = true;
                                settings_warning = "Finishing the lobby request, then leaving...";
                                return;
                            }
                            if (social_client == nullptr ||
                                !social_client->snapshot().lobby.has_value()) {
                                static_cast<void>(navigation.pop());
                            } else if (!leave_active_social_lobby()) {
                                settings_warning = "Could not queue Leave Lobby. Please retry.";
                            }
                        } else {
                            if (social_client != nullptr &&
                                social_client->snapshot().lobby.has_value()) {
                                if (!start_active_social_lobby(payload.configuration)) {
                                    settings_warning = "Could not start the lobby. Please retry.";
                                }
                            } else {
                                if (social_client != nullptr) {
                                    submit_social_intent({FriendsLobbyActionKind::create_lobby, {}, {}});
                                } else {
                                    settings_warning = "Online lobbies are unavailable. Use Local Match to play on this computer.";
                                }
                            }
                        }
                    }
                },
                effect);
        }
    }

    void open_join_route(JoinMatchRoute route) {
        switch (route) {
        case JoinMatchRoute::server_browser:
            server_browser.set_source(ServerBrowserSource::all);
            begin_server_browser_refresh();
            static_cast<void>(navigation.push(FrontendScreen::server_browser));
            play_confirm();
            break;
        case JoinMatchRoute::direct_connect:
            direct_connect_menu.focus_input();
            static_cast<void>(window.set_text_input_enabled(true));
            static_cast<void>(navigation.push(FrontendScreen::direct_connect));
            play_confirm();
            break;
        case JoinMatchRoute::random_match:
            quick_play_menu.set_network_available(false);
            quick_play_menu.set_network_available(true);
            static_cast<void>(navigation.push(FrontendScreen::public_match));
            if (const auto search = quick_play_menu.begin_search()) {
                begin_quick_play_refresh(*search);
            }
            play_confirm();
            break;
        case JoinMatchRoute::custom_match:
            // The retained legacy entry uses the same social/relay service as
            // Friends and Create Match, including its availability errors.
            friends_lobby_menu.enter(std::chrono::steady_clock::now());
            static_cast<void>(window.set_text_input_enabled(true));
            static_cast<void>(navigation.push(FrontendScreen::friends_lobby));
            play_confirm();
            break;
        case JoinMatchRoute::select_menu:
            static_cast<void>(navigation.pop());
            play_back();
            break;
        }
    }

    void open_ugc_route(const UgcSelectActivation& activation) {
        switch (activation.action) {
        case UgcSelectAction::create_map: {
            play_confirm();
            // Retail routes through UGCSquadsMenu first. Discovery is an
            // adapter boundary, while local New Lobby remains usable.
            ugc_editor_browser = UgcEditorBrowserModel{};
            ugc_editor_browser.set_network_available(social_client != nullptr &&
                identity_service->has_online_session());
            static_cast<void>(navigation.push(FrontendScreen::ugc_editor_browser));
            consume_ugc_editor_browser_intent(ugc_editor_browser.request_refresh());
            break;
        }
        case UgcSelectAction::publish_map:
            play_confirm();
            refresh_ugc_publish_repository();
            static_cast<void>(navigation.push(FrontendScreen::ugc_publish));
            break;
        case UgcSelectAction::subscribe_workshop:
            play_confirm();
            if (!activation.external_url.has_value() ||
                !window.open_external_url(*activation.external_url)) {
                last_error = "the Workshop page could not be opened by the desktop";
            }
            break;
        case UgcSelectAction::back:
            play_back();
            static_cast<void>(navigation.pop());
            break;
        }
    }

    [[nodiscard]] std::filesystem::path ugc_maps_root() const {
        return config.settings_path.parent_path() / "hosted_ugc" / "maps";
    }

    /** Rebuild the Publish Map list from the same catalog Map Creator writes. */
    void refresh_ugc_publish_repository() {
        auto scan = scan_ugc_projects(ugc_maps_root());
        ugc_publish_menu.replace_local_maps(std::move(scan.maps));
        if (!scan.warnings.empty()) {
            settings_warning = scan.warnings.front();
            if (scan.warnings.size() > 1U) {
                settings_warning += " (and " + std::to_string(scan.warnings.size() - 1U) +
                                    " more UGC project warning(s))";
            }
        }
    }

    [[nodiscard]] static nlohmann::json ugc_social_settings(const UgcEditorConfiguration& value) {
        return {{"map_name", value.map_name}, {"ugc_mode", value.ugc_mode},
                {"prefab_set", value.prefab_set}, {"map_title", value.map_title}};
    }

    [[nodiscard]] static std::string ugc_social_privacy(UgcEditorPrivacy value) {
        return value == UgcEditorPrivacy::open ? "open"
             : value == UgcEditorPrivacy::friends_only ? "friends" : "invite";
    }

    void pump_ugc_social_settings(std::chrono::steady_clock::time_point now) {
        if (social_client == nullptr || ugc_social_lobby_id.empty() || ugc_settings_generation ||
            social_start_generation || social_leave_generation || now < ugc_settings_retry_at ||
            ugc_editor_lobby.title_editing()) return;
        const auto snapshot = social_client->snapshot();
        if (!snapshot.lobby || snapshot.lobby->id != ugc_social_lobby_id ||
            snapshot.lobby->lobby_type != "ugc" || snapshot.lobby->state != "forming" ||
            snapshot.lobby->owner_id != friends_lobby_menu.local_account_id()) return;
        const auto& desired = ugc_editor_lobby.configuration();
        const auto settings = ugc_social_settings(desired);
        const auto privacy = ugc_social_privacy(desired.privacy);
        if (settings == snapshot.lobby->settings && privacy == snapshot.lobby->privacy &&
            desired.maximum_players == snapshot.lobby->maximum_members) return;
        network::RevivalSocialRequest request;
        request.generation = background_social_generation();
        request.kind = network::RevivalSocialRequestKind::lobby_action;
        request.priority = true;
        request.coalesce_key = "ugc-settings";
        request.lobby_id = snapshot.lobby->id;
        request.action = "update";
        request.payload = {{"revision", snapshot.lobby->revision}, {"settings", settings},
            {"privacy", privacy}, {"max_members", desired.maximum_players}};
        const auto generation = request.generation;
        if (social_client->enqueue(std::move(request))) ugc_settings_generation = generation;
    }

    void sync_ugc_social_lobby(const network::RevivalSocialSnapshot& snapshot) {
        if (!snapshot.lobby || snapshot.lobby->lobby_type != "ugc") return;
        const auto& lobby = *snapshot.lobby;
        const auto owner = lobby.owner_id == friends_lobby_menu.local_account_id();
        if (!owner || ugc_social_lobby_id != lobby.id || ugc_social_owner_id != lobby.owner_id) {
            UgcEditorConfiguration value;
            try {
                value.map_name = lobby.settings.value("map_name", value.map_name);
                value.map_title = lobby.settings.value("map_title", value.map_title);
                value.ugc_mode = lobby.settings.value("ugc_mode", value.ugc_mode);
                const auto prefab = social_u16(lobby.settings, "prefab_set");
                value.prefab_set = prefab && *prefab < 6U ? static_cast<std::uint8_t>(*prefab) : 255U;
                value.maximum_players = static_cast<std::uint8_t>(std::min<std::size_t>(24U, lobby.maximum_members));
                value.privacy = lobby.privacy == "open" ? UgcEditorPrivacy::open
                              : lobby.privacy == "friends" ? UgcEditorPrivacy::friends_only : UgcEditorPrivacy::invite_only;
                if (!ugc_editor_lobby.apply_configuration(value)) settings_warning = "The editor lobby settings are invalid.";
            } catch (const nlohmann::json::exception&) {
                settings_warning = "The editor lobby settings are invalid.";
            }
        }
        ugc_social_lobby_id = lobby.id;
        ugc_social_owner_id = lobby.owner_id;
        ugc_editor_lobby.set_host_authority(owner && lobby.state == "forming");
        std::vector<std::pair<std::string, bool>> members;
        for (const auto& member : lobby.members) members.emplace_back(member.nickname, member.legacy_id == lobby.owner_id);
        ugc_editor_lobby.set_members(std::move(members));
    }

    void consume_ugc_editor_browser_intent(std::optional<UgcEditorBrowserIntent> intent) {
        if (!intent.has_value()) {
            return;
        }
        switch (intent->kind) {
        case UgcEditorBrowserIntentKind::back_to_ugc_select:
            ugc_discovery_generation.reset();
            static_cast<void>(navigation.pop());
            play_back();
            break;
        case UgcEditorBrowserIntentKind::create_lobby:
            if (social_client != nullptr && social_client->snapshot().lobby) {
                open_social_match_lobby(social_client->snapshot());
                break;
            }
            ugc_editor_lobby = UgcEditorLobbyModel{};
            ugc_social_lobby_id.clear();
            ugc_leave_after_create = false;
            static_cast<void>(navigation.push(FrontendScreen::ugc_editor_lobby));
            if (social_client != nullptr && identity_service->has_online_session()) {
                network::RevivalSocialRequest request;
                request.generation = background_social_generation();
                request.kind = network::RevivalSocialRequestKind::create_lobby;
                request.priority = true;
                request.payload = {{"lobby_type", "ugc"}, {"name", "Map Creator"},
                    {"privacy", "open"}, {"max_members", 12},
                    {"settings", ugc_social_settings(ugc_editor_lobby.configuration())}};
                social_open_match_generation = request.generation;
                ugc_create_deadline = std::chrono::steady_clock::now() + std::chrono::seconds{20};
                if (!social_client->enqueue(std::move(request))) {
                    social_open_match_generation.reset();
                    settings_warning = "Could not create the editor lobby. Local editing remains available.";
                }
            }
            play_confirm();
            break;
        case UgcEditorBrowserIntentKind::join_lobby:
            friends_lobby_menu.enter(std::chrono::steady_clock::now());
            submit_social_intent({FriendsLobbyActionKind::join_friend_lobby, intent->lobby_id, {}});
            break;
        case UgcEditorBrowserIntentKind::refresh_lobbies:
            if (social_client != nullptr) {
                network::RevivalSocialRequest request;
                request.generation = background_social_generation();
                request.kind = network::RevivalSocialRequestKind::list_lobbies;
                request.coalesce_key = "ugc-lobbies";
                ugc_discovery_generation = request.generation;
                if (social_client->enqueue(std::move(request))) break;
            }
            ugc_discovery_generation.reset();
            static_cast<void>(ugc_editor_browser.complete_refresh({}, false));
            break;
        }
    }

    void begin_ugc_editor_loading(const UgcEditorConfiguration& configuration) {
        if (local_host_worker.valid() ||
            (owned_local_server != nullptr && owned_local_server->running())) {
            settings_warning = "A client-owned local session is already active";
            return;
        }
        const auto bundle = resolve_local_server_bundle();
        if (!bundle.has_value()) {
            settings_warning =
                "The complete BattleSpades server bundle is missing. Put it in server/ "
                "beside BattleSpadesClient.exe.";
            return;
        }

        static constexpr std::array terrain_by_baseplate{
            std::pair{std::string_view{"DesertBaseplate"}, std::string_view{"desert"}},
            std::pair{std::string_view{"LunarBaseplate"}, std::string_view{"lunar"}},
            std::pair{std::string_view{"MountainBaseplate"}, std::string_view{"mountain"}},
            std::pair{std::string_view{"GrasslandBaseplate"}, std::string_view{"grassland"}},
            std::pair{std::string_view{"Templebaseplate"}, std::string_view{"temple"}},
            std::pair{std::string_view{"UrbanBaseplate"}, std::string_view{"urban"}},
            std::pair{std::string_view{"MarshTemplate"}, std::string_view{"marsh"}},
            std::pair{std::string_view{"SnowyBaseplate"}, std::string_view{"snowy"}},
            std::pair{std::string_view{"WaterBaseplate"}, std::string_view{"water"}},
        };
        const auto terrain = std::ranges::find_if(terrain_by_baseplate, [&](const auto& entry) {
            return entry.first == configuration.map_name;
        });
        if (terrain == terrain_by_baseplate.end()) {
            settings_warning = "The selected UGC baseplate is not supported";
            return;
        }

        platform::LocalServerLaunchConfig launch;
        launch.program = platform::LocalServerProgram::map_creator;
        launch.bundle_root = *bundle;
        launch.session_parent = config.settings_path.parent_path() / "local-server-sessions";
        launch.server_name = "Map Creator - " + configuration.map_title;
        launch.mode = "ugc";
        // InitialInfo advertises the retail baseplate stem.  The authored
        // project slug remains launcher metadata and must not replace it.
        launch.map_name = configuration.map_name;
        launch.preferred_port = config.preferred_local_server_port;
        launch.maximum_players = configuration.maximum_players;
        launch.match_minutes = 15U;
        launch.bot_count = 0U;
        launch.map_creator = platform::LocalMapCreatorLaunchConfig{
            .project = configuration.map_title,
            .terrain = std::string{terrain->second},
            .target_mode = configuration.ugc_mode,
            .title = configuration.map_title,
            .author = config.player_name,
            .publish_root = config.settings_path.parent_path() / "hosted_ugc",
            .retail_root = config.asset_root,
            .prefab_set = configuration.prefab_set,
        };
        ugc_map_title = configuration.map_title;
        std::optional<network::RevivalRelayLobbyRequest> relay;
        if (social_client != nullptr) {
            const auto social = social_client->snapshot();
            if (social.lobby && social.lobby->lobby_type == "ugc" &&
                social.lobby->owner_id == friends_lobby_menu.local_account_id()) {
                relay = network::RevivalRelayLobbyRequest{launch.server_name, launch.map_name,
                    "MAP_CREATOR", "ugc", launch.maximum_players, 0U, "ugc", false};
            }
        }
        begin_owned_local_server(std::move(launch), "MAP_CREATOR", false, "ugc", std::move(relay));
    }

    void consume_ugc_editor_lobby_intent(std::optional<UgcEditorLobbyIntent> intent) {
        if (!intent.has_value()) {
            return;
        }
        switch (intent->kind) {
        case UgcEditorLobbyIntentKind::leave_lobby:
            social_pending_ugc_start.reset();
            if (social_open_match_generation) ugc_leave_after_create = true;
            if (social_client != nullptr && social_client->snapshot().lobby &&
                !leave_active_social_lobby()) {
                settings_warning = "Could not queue Leave Lobby. Please retry.";
                break;
            }
            static_cast<void>(navigation.pop());
            play_back();
            break;
        case UgcEditorLobbyIntentKind::invite_friends:
            friends_lobby_menu.enter(std::chrono::steady_clock::now());
            static_cast<void>(window.set_text_input_enabled(true));
            static_cast<void>(navigation.push(FrontendScreen::friends_lobby));
            break;
        case UgcEditorLobbyIntentKind::start_editor:
            if (social_open_match_generation) {
                settings_warning = "Waiting for the editor lobby to be created.";
                break;
            }
            if (social_client != nullptr && social_client->snapshot().lobby) {
                social_pending_ugc_start = intent->configuration;
                if (!start_active_social_lobby(CreateMatchConfiguration{})) social_pending_ugc_start.reset();
            } else {
                begin_ugc_editor_loading(intent->configuration);
            }
            play_confirm();
            break;
        }
    }

    void consume_parity_debug_activation(std::optional<ParityDebugActivation> activation) {
        if (!developer_tools_allowed()) {
            deny_developer_action();
            return;
        }
        if (!activation.has_value()) {
            return;
        }
        if (activation->action == ParityDebugAction::back) {
            static_cast<void>(navigation.pop());
            play_back();
            return;
        }
        if (activation->action == ParityDebugAction::toggle_hitboxes) {
            play_scroll();
            return;
        }

        const auto catalog = retail_frontend_catalog();
        const auto selected = std::ranges::find_if(
            catalog, [&](const auto& entry) { return entry.id == activation->entry_id; });
        if (selected == catalog.end() || !selected->native_fixture || selected->route.empty()) {
            return;
        }

        const auto& route = selected->route;
        std::optional<FrontendScreen> target;
        if (route == "select_menu") {
            target = FrontendScreen::select_menu;
        } else if (route == "join_match") {
            target = FrontendScreen::join_match;
        } else if (route == "server_browser") {
            target = FrontendScreen::server_browser;
        } else if (route == "direct_connect") {
            target = FrontendScreen::direct_connect;
        } else if (route == "public_match") {
            target = FrontendScreen::public_match;
        } else if (route == "custom_match_list") {
            target = FrontendScreen::custom_match;
        } else if (route == "ugc_select") {
            target = FrontendScreen::ugc_select;
        } else if (route == "ugc_publish") {
            target = FrontendScreen::ugc_publish;
        } else if (route == "ugc_editor_lobbies") {
            ugc_editor_browser = UgcEditorBrowserModel{};
            ugc_editor_browser.set_network_available(false);
            target = FrontendScreen::ugc_editor_browser;
        } else if (route == "ugc_editor_lobby" || route.starts_with("ugc_editor_lobby/")) {
            ugc_editor_lobby = UgcEditorLobbyModel{};
            target = FrontendScreen::ugc_editor_lobby;
        } else if (route == "leaderboard") {
            load_parity_leaderboard_fixture();
            target = FrontendScreen::leaderboard;
        } else if (route == "player_profile") {
            load_parity_profile_fixture();
            target = FrontendScreen::player_profile;
        } else if (route == "inventory" || route == "inventory/crates" || route == "inventory/packs") {
            load_parity_profile_fixture();
            static_cast<void>(player_profile_menu.select_tab(PlayerProfileTab::inventory));
            inventory_menu.complete(inventory_preview_fixture());
            inventory_fixture=true;
            inventory_menu.online=false;
            inventory_menu.error="DESIGN PREVIEW - fixture items cannot be opened or equipped.";
            if (route=="inventory/crates") inventory_menu.section=InventorySection::crates;
            if (route=="inventory/packs") inventory_menu.section=InventorySection::packs;
            target = FrontendScreen::player_profile;
        } else if (route == "loading") {
            match_ui_skin = supported_ui_skin("classic");
            match_loading.begin("Atlantis", "CTF", false, match_ui_skin);
            match_loading.initial_info("Atlantis", "CTF", false, match_ui_skin);
            target = FrontendScreen::game_loading;
        } else if (route == "change_resolution") {
            resolution_confirmation.restart();
            target = FrontendScreen::resolution_confirmation;
        } else if (route == "settings" || route.starts_with("settings/")) {
            if (settings_menu != nullptr) {
                const auto tab = route == "settings/graphics"   ? settings::SettingsTab::graphics
                                 : route == "settings/controls" ? settings::SettingsTab::controls
                                                                : settings::SettingsTab::main;
                settings_menu->set_active_tab(tab);
                static_cast<void>(settings_menu->take_effects());
            }
            target = FrontendScreen::settings;
        } else if (route == "create_match_lobby" || route.starts_with("create_match_lobby/")) {
            auto page = CreateMatchPage::match_settings;
            if (route == "create_match_lobby/rules") {
                page = CreateMatchPage::game_rules;
            } else if (route == "create_match_lobby/playlists") {
                page = CreateMatchPage::choose_game_mode;
            } else if (route == "create_match_lobby/maps") {
                page = CreateMatchPage::choose_map;
            }
            static_cast<void>(create_match_menu.open_page(page));
            static_cast<void>(create_match_menu.take_effects());
            reset_create_match_page_transition();
            target = FrontendScreen::create_match;
        }

        if (target.has_value() && navigation.push(*target)) {
            if (*target == FrontendScreen::direct_connect) {
                direct_connect_menu.focus_input();
                static_cast<void>(window.set_text_input_enabled(true));
            }
            play_confirm();
        }
    }

    void pump_ugc_publication() {
        if (!ugc_publish_worker.valid() ||
            ugc_publish_worker.wait_for(std::chrono::milliseconds{0}) != std::future_status::ready) return;
        auto result = ugc_publish_worker.get();
        settings_warning = result.error.empty() ? result.warning : result.error;
        consume_ugc_publish_effect(ugc_publish_menu.finish_publish(static_cast<bool>(result), result.item_url));
    }

    void consume_ugc_publish_effect(std::optional<UgcPublishEffect> effect) {
        if (!effect.has_value()) {
            return;
        }
        if (effect->sound_asset == main_menu_assets::back_sound) {
            play_back();
        } else if (!effect->sound_asset.empty()) {
            play_confirm();
        }

        switch (effect->kind) {
        case UgcPublishEffectKind::publish_requested:
            if (effect->publish_request && !ugc_publish_worker.valid()) {
                ugc_publish_stop = std::stop_source{};
                auto service = identity_service;
                const auto request = *effect->publish_request;
                ugc_publish_worker = std::async(std::launch::async,
                    [service, request, root = ugc_maps_root(), stop = ugc_publish_stop.get_token()] {
                        return service->publish_ugc_project(root, request.local_uid, request.workshop_title, stop);
                    });
                settings_warning = "Uploading the saved map to the Revival Workshop...";
            }
            break;
        case UgcPublishEffectKind::delete_requested:
            if (effect->delete_request.has_value()) {
                std::string error;
                const auto& uid = effect->delete_request->local_uid;
                const bool deleted = delete_ugc_project(ugc_maps_root(), uid, error);
                static_cast<void>(ugc_publish_menu.finish_delete(uid, deleted));
                if (!deleted) settings_warning = std::move(error);
            }
            break;
        case UgcPublishEffectKind::return_to_ugc_select:
            static_cast<void>(navigation.pop());
            break;
        case UgcPublishEffectKind::publish_succeeded:
            if (effect->external_url.has_value() &&
                !window.open_external_url(*effect->external_url)) {
                last_error = "the Workshop page could not be opened by the desktop";
            }
            break;
        case UgcPublishEffectKind::show_name_map:
        case UgcPublishEffectKind::show_map_list:
        case UgcPublishEffectKind::show_publish_confirmation:
        case UgcPublishEffectKind::show_delete_confirmation:
        case UgcPublishEffectKind::dialog_dismissed:
        case UgcPublishEffectKind::publish_failed:
        case UgcPublishEffectKind::delete_succeeded:
        case UgcPublishEffectKind::delete_failed:
            break;
        }
    }

    [[nodiscard]] static bool contains(ui::Rect bounds, ui::Point point) noexcept {
        return bounds.contains(point);
    }

    void update_profile_control_states(std::optional<ui::Point> point) {
        const auto layout = player_profile_classic_layout();
        const auto state_for = [&](ui::DrawRect bounds, bool enabled = true) {
            if (!enabled || !point.has_value()) {
                return PlayerProfilePresentationContext::ControlState::normal;
            }
            const ui::Rect hit{static_cast<std::int32_t>(bounds.x),
                               static_cast<std::int32_t>(bounds.y),
                               static_cast<std::int32_t>(bounds.width),
                               static_cast<std::int32_t>(bounds.height)};
            if (!contains(hit, *point)) {
                return PlayerProfilePresentationContext::ControlState::normal;
            }
            return profile_pointer_down ? PlayerProfilePresentationContext::ControlState::pressed
                                        : PlayerProfilePresentationContext::ControlState::hovered;
        };
        profile_cancel_state = state_for(layout.cancel_button);
        profile_achievements_state = state_for(layout.achievements_button);
        profile_filter_state =
            state_for(layout.filter_dropdown, player_profile_menu.filter_visible());
    }

    void pointer_move(std::optional<ui::Point> point) {
        if (boot_loading || !accepts_input()) {
            return;
        }
        if (markup_inventory_active()) {
            inventory_view->pointer_move(settings_point(point).value_or(ui::Point{-1,-1}));
            return;
        }
        switch (screen()) {
        case FrontendScreen::identity:
            identity_menu.pointer_move(point);
            break;
        case FrontendScreen::friends_lobby:
            friends_lobby_menu.pointer_move(point);
            break;
        case FrontendScreen::select_menu:
            menu.pointer_move(point);
            break;
        case FrontendScreen::join_match:
            join_match_menu.pointer_move(point);
            break;
        case FrontendScreen::direct_connect:
            direct_connect_menu.pointer_move(point);
            break;
        case FrontendScreen::game_loading:
            if (loading_scrollbar_dragging) {
                if (const auto raw = settings_point(point)) {
                    const auto thumb = loading_layout::score_thumb(match_loading.snapshot());
                    const auto travel = loading_layout::score_track.height - thumb.height;
                    if (travel > 0.0) static_cast<void>(match_loading.set_score_scroll(
                        (raw->y - loading_scrollbar_grab_offset - loading_layout::score_track.y) / travel));
                }
            }
            break;
        case FrontendScreen::server_browser:
            server_browser_pointer = settings_point(point);
            break;
        case FrontendScreen::public_match:
            quick_play_menu.pointer_move(point);
            break;
        case FrontendScreen::custom_match:
            custom_match_menu.pointer_move(point);
            break;
        case FrontendScreen::ugc_select:
            ugc_select_menu.pointer_move(point);
            break;
        case FrontendScreen::ugc_editor_browser:
            ugc_editor_browser.pointer_move(point);
            break;
        case FrontendScreen::ugc_editor_lobby:
            ugc_editor_lobby.pointer_move(point);
            break;
        case FrontendScreen::parity_debug:
            parity_debug_menu.pointer_move(settings_point(point));
            break;
        case FrontendScreen::gameplay_debug:
            break;
        case FrontendScreen::class_selection:
            if (ugc_loadout_active) {
                ugc_loadout_menu.pointer_move(settings_point(point));
            } else {
                class_selection_menu.pointer_move(settings_point(point));
            }
            break;
        case FrontendScreen::tutorial_world:
            break;
        case FrontendScreen::pause_menu:
            pause_menu.pointer_move(settings_point(point));
            break;
        case FrontendScreen::change_team:
            change_team_menu.pointer_move(settings_point(point));
            break;
        case FrontendScreen::leaderboard:
            update_leaderboard_hover(settings_point(point));
            break;
        case FrontendScreen::player_profile:
            update_profile_control_states(settings_point(point));
            break;
        case FrontendScreen::settings:
            if (settings_menu != nullptr) {
                settings_menu->pointer_move(settings_point(point));
            }
            break;
        case FrontendScreen::resolution_confirmation:
            resolution_confirmation.pointer_move(point);
            break;
        case FrontendScreen::create_match:
        case FrontendScreen::create_match_rules:
        case FrontendScreen::create_match_maps:
        case FrontendScreen::create_match_lobby:
            create_match_menu.pointer_move(settings_point(point));
            break;
        default:
            break;
        }
    }

    void pointer_press(std::optional<ui::Point> point) {
        if (boot_loading || !accepts_input()) {
            return;
        }
        if (markup_inventory_active()) {
            inventory_view->pointer_move(settings_point(point).value_or(ui::Point{-1,-1}));
            inventory_view->pointer_button(true); return;
        }
        switch (screen()) {
        case FrontendScreen::identity:
            identity_menu.pointer_press(point);
            break;
        case FrontendScreen::friends_lobby:
            friends_lobby_menu.pointer_press(point, std::chrono::steady_clock::now());
            break;
        case FrontendScreen::select_menu:
            menu.pointer_press(point);
            break;
        case FrontendScreen::join_match:
            join_match_menu.pointer_press(point);
            break;
        case FrontendScreen::direct_connect:
            direct_connect_menu.pointer_press(point);
            break;
        case FrontendScreen::game_loading: {
            const auto raw = settings_point(point);
            const auto loading = match_loading.snapshot();
            const auto thumb = loading_layout::score_thumb(loading);
            loading_scrollbar_dragging = raw && loading.tabs[loading.selected_tab] == LoadingTab::scores &&
                thumb.height < loading_layout::score_track.height &&
                loading_layout::contains(thumb, raw->x, raw->y);
            if (loading_scrollbar_dragging) loading_scrollbar_grab_offset = raw->y - thumb.y;
            break;
        }
        case FrontendScreen::server_browser:
            server_browser_pointer = settings_point(point);
            server_browser_pointer_down = point.has_value();
            break;
        case FrontendScreen::public_match:
            quick_play_menu.pointer_press(point);
            break;
        case FrontendScreen::custom_match:
            custom_match_menu.pointer_press(point);
            break;
        case FrontendScreen::ugc_select:
            ugc_select_menu.pointer_press(point);
            break;
        case FrontendScreen::ugc_editor_browser:
            ugc_editor_browser.pointer_press(point);
            break;
        case FrontendScreen::ugc_editor_lobby:
            ugc_editor_lobby.pointer_press(point);
            break;
        case FrontendScreen::parity_debug:
            parity_debug_menu.pointer_press(settings_point(point));
            break;
        case FrontendScreen::gameplay_debug:
            break;
        case FrontendScreen::class_selection:
            if (ugc_loadout_active) {
                ugc_loadout_menu.pointer_move(settings_point(point));
            } else {
                class_selection_menu.pointer_move(settings_point(point));
            }
            break;
        case FrontendScreen::pause_menu:
            pause_menu.pointer_press(settings_point(point));
            break;
        case FrontendScreen::change_team:
            change_team_menu.pointer_press(settings_point(point));
            break;
        case FrontendScreen::player_profile:
            profile_pointer_down = point.has_value();
            update_profile_control_states(settings_point(point));
            break;
        case FrontendScreen::settings:
            if (settings_menu != nullptr) {
                if (const auto raw = settings_point(point); raw.has_value()) {
                    settings_menu->pointer_press(*raw);
                } else {
                    settings_menu->cancel_pointer_capture();
                }
            }
            break;
        case FrontendScreen::resolution_confirmation:
            resolution_confirmation.pointer_press(point);
            break;
        case FrontendScreen::create_match:
        case FrontendScreen::create_match_rules:
        case FrontendScreen::create_match_maps:
        case FrontendScreen::create_match_lobby:
            create_match_menu.pointer_press(settings_point(point));
            break;
        default:
            break;
        }
    }

    [[nodiscard]] static ServerBrowserEntry
    browser_entry(const network::DiscoveredServer& source,
                  const std::set<std::string, std::less<>>& favourites,
                  const std::set<std::string, std::less<>>& history) {
        const auto mode = resolve_server_mode(source.mode_code, source.classic);
        ServerBrowserEntry entry;
        entry.name = source.name;
        entry.address = source.game.host;
        entry.game_port = source.game.port;
        entry.query_port = source.query_port == 0U ? source.game.port : source.query_port;
        entry.ping_milliseconds = source.ping_milliseconds;
        entry.map = source.map;
        entry.mode = mode.title_key;
        entry.mode_id = mode.code;
        entry.mode_description = mode.description_key;
        entry.region = source.region;
        entry.texture_skin = source.texture_skin;
        entry.players = source.players;
        entry.maximum_players = source.maximum_players;
        entry.classic = mode.classic;
        entry.official = source.official;
        entry.local = source.local;
        entry.identity_server_id = source.master_identifier;
        entry.identity_ticket = source.identity_ticket;
        entry.favourite = favourites.contains(entry.identifier());
        entry.in_history = history.contains(entry.identifier());
        return entry;
    }

    void cancel_quick_play_refresh() {
        quick_play_refresh_stop.request_stop();
        pending_quick_play_refresh.reset();
        quick_play_menu.set_network_available(false);
    }

    void begin_quick_play_refresh(QuickPlaySearchIntent request) {
        if (quick_play_refresh_worker.valid()) {
            quick_play_refresh_stop.request_stop();
            pending_quick_play_refresh = request;
            return;
        }
        pending_quick_play_refresh.reset();
        quick_play_refresh_stop = std::stop_source{};
        quick_play_refresh_worker = std::async(
            std::launch::async,
            [request, url = config.public_server_list_url,
             stop = quick_play_refresh_stop.get_token()] {
                network::DiscoveryResult discovery;
                try {
                    network::PublicDiscoveryConfig web;
                    web.url = url;
                    discovery = network::discover_public_servers(web, stop);
                } catch (const std::exception& error) {
                    discovery.error = error.what();
                }
                return QuickPlayRefreshOutcome{request, std::move(discovery)};
            });
    }

    void pump_quick_play_refresh() {
        using namespace std::chrono_literals;
        if (!quick_play_refresh_worker.valid() ||
            quick_play_refresh_worker.wait_for(0ms) != std::future_status::ready) {
            return;
        }
        auto outcome = quick_play_refresh_worker.get();
        if (!outcome.discovery) {
            static_cast<void>(quick_play_menu.fail_search(outcome.request));
        } else {
            for (const auto& source : outcome.discovery.servers) {
                const auto mode = resolve_server_mode(source.mode_code, source.classic);
                QuickPlayServerResponse response;
                response.name = source.name;
                response.address = source.game.host;
                response.game_port = source.game.port;
                response.query_port = source.query_port;
                response.ping_seconds = static_cast<double>(source.ping_milliseconds) / 1'000.0;
                response.map = source.map;
                response.mode = mode.title_key;
                // Keep unknown modes out of playlists; the presentation resolver's
                // TDM fallback is a label fallback, not matchmaking authority.
                response.mode_id = source.mode_code;
                response.players = source.players;
                response.maximum_players = source.maximum_players;
                response.texture_skin = source.texture_skin;
                response.classic = mode.classic;
                response.identity_server_id = source.master_identifier;
                response.identity_ticket = source.identity_ticket;
                static_cast<void>(quick_play_menu.accept_public_server(outcome.request, response));
            }
            static_cast<void>(quick_play_menu.finish_search(outcome.request));
        }
        if (pending_quick_play_refresh) {
            begin_quick_play_refresh(*pending_quick_play_refresh);
        }
    }

    void launch_browser_refresh(ServerBrowserRefreshRequest request) {
        pending_browser_refresh.reset();
        const auto public_url = config.public_server_list_url;
        const auto local_ports = config.local_server_ports;
        std::vector<std::string> friend_server_ids;
        if (request.source == ServerBrowserSource::friends && social_client) {
            const auto social = social_client->snapshot();
            for (const auto& friend_row : social.friends) {
                if (friend_row.friendship_status == "accepted" &&
                    !friend_row.current_server_id.empty()) {
                    friend_server_ids.push_back(friend_row.current_server_id);
                }
            }
            std::ranges::sort(friend_server_ids);
            friend_server_ids.erase(
                std::unique(friend_server_ids.begin(), friend_server_ids.end()),
                friend_server_ids.end());
        }
        browser_refresh_worker =
            std::async(std::launch::async,
                       [request, public_url, local_ports,
                        friend_server_ids = std::move(friend_server_ids)]() mutable {
                network::DiscoveryResult discovery;
                if (request.source == ServerBrowserSource::local) {
                    network::LanDiscoveryConfig lan;
                    lan.ports = local_ports;
                    discovery = network::discover_lan_servers(lan);
                } else if (request.source == ServerBrowserSource::friends) {
                    network::PublicDiscoveryConfig web;
                    web.url = public_url;
                    discovery = network::select_discovered_servers(
                        network::discover_public_servers(web), friend_server_ids);
                } else {
                    network::PublicDiscoveryConfig web;
                    web.url = public_url;
                    discovery = network::discover_public_servers(web);
                }
                return BrowserRefreshOutcome{request, std::move(discovery)};
            });
    }

    void begin_server_browser_refresh() {
        const auto refresh = server_browser.begin_refresh();
        server_browser_status = refresh.source == ServerBrowserSource::local
                                    ? "QUERYING_LOCAL_SERVERS"
                                    : "GETTING_SERVER_LIST";
        if (browser_refresh_worker.valid()) {
            pending_browser_refresh = refresh;
            return;
        }
        launch_browser_refresh(refresh);
    }

    void pump_server_browser_refresh() {
        using namespace std::chrono_literals;
        if (!browser_refresh_worker.valid() ||
            browser_refresh_worker.wait_for(0ms) != std::future_status::ready) {
            return;
        }
        auto outcome = browser_refresh_worker.get();
        if (outcome.request.generation == server_browser.refresh_generation() &&
            server_browser.refreshing()) {
            for (const auto& discovered : outcome.discovery.servers) {
                auto entry = browser_entry(discovered, favourite_servers, history_servers);
                // The Friends request has already selected the authoritative
                // friend server IDs. Preserve that evidence through the menu's
                // own source filter instead of filtering every row back out.
                entry.friend_hosted = outcome.request.source == ServerBrowserSource::friends;
                static_cast<void>(server_browser.accept_response(
                    outcome.request.generation,
                    std::move(entry)));
            }
            static_cast<void>(server_browser.finish_refresh(outcome.request.generation));
            if (!outcome.discovery.error.empty()) {
                server_browser_status = outcome.discovery.error;
            } else {
                server_browser_status = "Received " +
                                        std::to_string(server_browser.visible_indices().size()) +
                                        " servers";
            }
        }
        if (pending_browser_refresh.has_value()) {
            const auto pending = *pending_browser_refresh;
            launch_browser_refresh(pending);
        }
    }

    /** Does this request dial the Steam tunnel this client opened? */
    [[nodiscard]] bool request_uses_steam_tunnel(const ServerConnectRequest& request) const {
        return steam_client.running() && request.host == "127.0.0.1" &&
               request.port == steam_client.local_port();
    }

    void retire_match_connection(bool keep_steam_tunnel = false) {
        // A Steam join opens its tunnel before the loader starts, so retiring
        // "the previous connection" on the way in must not close the tunnel the
        // new connection is about to dial: that ended every relayed join with
        // "client closed" 750 ms after the host accepted it.
        if (!keep_steam_tunnel) stop_steam_client();
        if (!match_connection) return;
        match_connection->request_stop();
        match_connection_cleanup.defer(std::packaged_task<void()>{
            [connection = std::move(match_connection)] { connection->stop(); }});
    }

    [[nodiscard]] bool start_match_transport(const ServerConnectRequest& request,
                                             std::uint32_t timeout_ms,
                                             std::string wire_name) {
        if (native_steam != nullptr && active_steam_ticket != 0U) {
            static_cast<void>(native_steam->cancel_ticket(active_steam_ticket));
            active_steam_ticket = 0U;
        }
        retire_match_connection(request_uses_steam_tunnel(request));
        auto cleanup = connection_cleanup.try_reserve();
        if (!cleanup) {
            settings_warning = "Previous connections are still closing. Please try again shortly.";
            return false;
        }
        match_connection_cleanup = std::move(*cleanup);
        active_join_wire_name = wire_name;
        join_code_issued_at = wire_name.starts_with('~')
                                  ? std::optional{std::chrono::steady_clock::now()}
                                  : std::nullopt;
        last_logged_connection_error.clear();
        match_connection = std::make_unique<network::LiveProtocol168Connection>();
        // Revoke local grants before any Protocol 168 packet can be queued.
        enforce_developer_access();
        network::Protocol168SessionConfig session;
        session.player_name = std::move(wire_name);
        // Interactive retail flow is Map/State -> SelectTeam -> SelectClass ->
        // NewPlayerConnection. Sending packet 15 here silently joined Blue.
        session.auto_join = false;
        if (native_steam != nullptr && native_steam->ready()) {
            if (auto ticket = native_steam->session_ticket(); ticket.has_value()) {
                active_steam_ticket = ticket->handle;
                session.steam_ticket = std::move(ticket->wire_bytes);
            } else {
                settings_warning = "Steam ticket unavailable; connecting in offline mode.";
            }
        }
        const bool transport_started = match_connection->start(
            network::EnetProtocol168Config{request.host, request.port, timeout_ms},
            std::move(session));
        if (!transport_started && native_steam != nullptr && active_steam_ticket != 0U) {
            static_cast<void>(native_steam->cancel_ticket(active_steam_ticket));
            active_steam_ticket = 0U;
        }
        if (transport_started && native_steam != nullptr && native_steam->ready()) {
            static_cast<void>(native_steam->set_server_presence(
                request.host + ":" + std::to_string(request.port)));
        }
        return transport_started;
    }

    [[nodiscard]] bool begin_match_identity(const ServerConnectRequest& request,
                                            std::uint32_t timeout_ms,
                                            bool map_transition) {
        if (!request.identity_ticket) {
            return start_match_transport(request, timeout_ms, config.player_name);
        }
        if (request.identity_server_id.empty() || !identity_service->has_online_session()) {
            settings_warning = "This server requires an online AoSPlay identity.";
            return false;
        }
        if (pending_match_identity.has_value()) {
            queued_match_identity = MatchIdentityRequest{request, timeout_ms, map_transition};
            return true;
        }

        MatchIdentityOutcome pending;
        pending.generation = next_match_identity_generation++;
        pending.request = request;
        pending.timeout_ms = timeout_ms;
        pending.map_transition = map_transition;
        pending_match_identity = pending;
        auto service = identity_service;
        const auto server_id = request.identity_server_id;
        match_identity_worker = std::async(
            std::launch::async, [service, pending = std::move(pending), server_id]() mutable {
                pending.ticket = service->game_ticket(server_id);
                return pending;
            });
        settings_warning = "Authorizing with AoSPlay...";
        match_loading.set_status(settings_warning);
        return true;
    }

    void pump_match_identity() {
        if (!pending_match_identity.has_value() || !match_identity_worker.valid() ||
            match_identity_worker.wait_for(std::chrono::milliseconds{0}) !=
                std::future_status::ready) {
            return;
        }
        auto outcome = match_identity_worker.get();
        const auto expected_generation = pending_match_identity->generation;
        pending_match_identity.reset();
        auto queued = std::move(queued_match_identity);
        queued_match_identity.reset();
        if (outcome.generation != expected_generation || !active_match_request.has_value() ||
            outcome.request.identifier != active_match_request->identifier ||
            outcome.request.identity_server_id != active_match_request->identity_server_id) {
            if (queued.has_value() && active_match_request.has_value() &&
                queued->request.identifier == active_match_request->identifier &&
                queued->request.identity_server_id == active_match_request->identity_server_id) {
                if (!begin_match_identity(queued->request, queued->timeout_ms, queued->map_transition)) {
                    if (queued->map_transition) schedule_map_transition_retry(settings_warning);
                    else match_loading.fail(settings_warning);
                }
                return;
            }
            // Nothing is waiting to replace the discarded ticket, and the
            // loader is still showing "Authorizing with AoSPlay...". Returning
            // here left a Steam joiner on that screen for as long as it cared
            // to wait: the ticket had arrived, and a teardown had already
            // zeroed the generation it was issued under.
            core::diagnostic("identity", "discarded the join ticket for " +
                                             outcome.request.identifier + ": generation " +
                                             std::to_string(outcome.generation) + " expected " +
                                             std::to_string(expected_generation) +
                                             (active_match_request.has_value()
                                                  ? ", active " + active_match_request->identifier
                                                  : ", no active match"));
            if (active_match_request.has_value() &&
                outcome.request.identifier == active_match_request->identifier) {
                settings_warning = "Server authorization was interrupted. Go back to retry.";
                if (outcome.map_transition) schedule_map_transition_retry(settings_warning);
                else match_loading.fail(settings_warning);
            }
            return;
        }
        if (!outcome.ticket) {
            if (outcome.map_transition) {
                schedule_map_transition_retry(outcome.ticket.error);
            } else {
                settings_warning = outcome.ticket.error.empty()
                    ? "Server authorization failed. Go back to retry." : outcome.ticket.error;
                match_loading.fail(settings_warning);
            }
            return;
        }
        settings_warning.clear();
        if (!start_match_transport(
                outcome.request, outcome.timeout_ms, std::move(outcome.ticket.join_code))) {
            const auto error = match_connection ? match_connection->status().error : settings_warning;
            if (outcome.map_transition) {
                schedule_map_transition_retry(error);
            } else {
                settings_warning = error.empty()
                    ? "Could not connect to the server. Go back to retry." : error;
                match_loading.fail(settings_warning);
            }
        } else {
            match_loading.set_status("CONNECTING_TO_SERVER");
        }
    }

    void fail_map_transition_reconnect(std::string error,
                                       std::string_view status_key = "SERVER_CONNECTION_FAILED") {
        retire_match_connection();
        map_transition_armed = false;
        map_transition_reconnecting = false;
        map_transition_attempts = 0U;
        match_loading.fail(std::string{status_key});
        settings_warning =
            error.empty() ? "The next map did not become available" : std::move(error);
    }

    /**
     * Show the server's reason on the loader. A drop during team or class
     * selection or gameplay otherwise leaves a frozen screen whose buttons
     * silently do nothing.
     */
    void fail_match_connection(const network::LiveProtocol168Status& status) {
        const auto key = status.disconnect_reason.has_value()
                             ? disconnect_status_key(*status.disconnect_reason)
                             : std::string_view{};
        fail_map_transition_reconnect(status.error,
                                      key.empty() ? std::string_view{"SERVER_CONNECTION_FAILED"} : key);
        initial_join_submitted = false;
        if (screen() != FrontendScreen::game_loading && navigation.leave_match_instant()) {
            static_cast<void>(navigation.push(FrontendScreen::game_loading));
        }
    }

    void schedule_map_transition_retry(std::string error) {
        // A map change on a Steam-hosted match reconnects through the same tunnel.
        retire_match_connection(steam_client.running());
        const auto now = std::chrono::steady_clock::now();
        if (map_transition_attempts >= map_transition_retry_delays.size() ||
            now >= map_transition_deadline) {
            fail_map_transition_reconnect(std::move(error));
            return;
        }
        const auto delay = map_transition_retry_delays[map_transition_attempts];
        map_transition_retry_at = std::min(now + delay, map_transition_deadline);
        settings_warning = "Map changing - reconnecting to the official server";
    }

    void begin_map_transition_reconnect(std::string error) {
        if (!active_match_request.has_value()) {
            fail_map_transition_reconnect(std::move(error));
            return;
        }
        // Teardown owns every map-local cache, renderer slot and prediction
        // record. Retain only the browser endpoint; replaying any old map state
        // into the new Protocol 168 bootstrap would create ghost terrain.
        const auto request = *active_match_request;
        teardown_tutorial(request_uses_steam_tunnel(request));
        active_match_request = request;
        map_transition_armed = true;
        map_transition_reconnecting = true;
        map_transition_attempts = 0U;
        const auto now = std::chrono::steady_clock::now();
        map_transition_retry_at = now + map_transition_retry_delays.front();
        map_transition_deadline = now + map_transition_reconnect_window;
        match_ui_skin = supported_ui_skin(request.expected_skin);
        match_loading.begin(
            request.expected_map, request.expected_mode, request.expected_classic, match_ui_skin);
        loading_scrollbar_dragging = false;
        if (screen() != FrontendScreen::game_loading) {
            static_cast<void>(
                navigation.replace(FrontendScreen::game_loading, NavigationDirection::forward));
        }
        settings_warning =
            error.empty() ? "Map changing - reconnecting to the official server" : std::move(error);
    }

    void pump_map_transition_reconnect() {
        if (!map_transition_reconnecting || !active_match_request.has_value()) {
            return;
        }
        if (screen() != FrontendScreen::game_loading) {
            // A route animation can temporarily reject replace(). Retry after
            // it settles; transport progress remains independent of UI motion.
            static_cast<void>(
                navigation.replace(FrontendScreen::game_loading, NavigationDirection::forward));
        }
        const auto now = std::chrono::steady_clock::now();
        if (now >= map_transition_deadline) {
            fail_map_transition_reconnect(
                "The official server did not publish its next map in time");
            return;
        }
        if (match_connection != nullptr || pending_match_identity.has_value() ||
            now < map_transition_retry_at) {
            return;
        }
        ++map_transition_attempts;
        const auto request = *active_match_request;
        if (!begin_match_identity(request, map_transition_handshake_timeout_ms, true)) {
            schedule_map_transition_retry(settings_warning);
        }
    }

    void begin_match_loading(const ServerConnectRequest& request) {
        if (request.host.empty() || request.port == 0U) {
            direct_connect_menu.set_error("The server endpoint is invalid");
            return;
        }
        // Stop advertising the previous public match before replacing its
        // transport. A successful Protocol 168 bootstrap below publishes the
        // new authoritative master-list identifier. Same-server map rotation
        // uses begin_map_transition_reconnect() and intentionally skips this
        // transient online state.
        if (network_match && social_client != nullptr) {
            social_client->set_presence("online");
        }
        teardown_tutorial(request_uses_steam_tunnel(request));
        match_ui_skin = supported_ui_skin(request.expected_skin);
        match_loading.begin(
            request.expected_map, request.expected_mode, request.expected_classic, match_ui_skin);
        if (screen() != FrontendScreen::game_loading) {
            static_cast<void>(navigation.push(FrontendScreen::game_loading));
        }
        play_confirm();
        active_match_request = request;
        loading_scrollbar_dragging = false;
        if (!begin_match_identity(request, 30'000U, false)) {
            if (settings_warning.empty()) {
                settings_warning = "Could not start the server connection.";
            }
            match_loading.fail(settings_warning);
        }
    }

    /**
     * Install the live map's sky and lighting on the gameplay/render thread.
     *
     * Official maps use the locally measured atmosphere and emissive identity;
     * UGC and unknown maps retain the server's packet-45 fog and packet-51
     * skybox. A failed local dome load leaves WorldRenderer's previous valid
     * environment resident and reports the problem through the normal warning.
     */
    void apply_retail_state_lighting() noexcept {
        render::RetailTerrainLighting retail_lighting;
        const auto normalized_color = [](const std::array<std::uint8_t, 3U>& color) {
            return std::array<float, 3U>{
                static_cast<float>(color[0U]) / 255.0F,
                static_cast<float>(color[1U]) / 255.0F,
                static_cast<float>(color[2U]) / 255.0F};
        };
        const auto float_direction = [](const std::array<double, 3U>& direction) {
            return std::array<float, 3U>{static_cast<float>(direction[0U]),
                                         static_cast<float>(direction[1U]),
                                         static_cast<float>(direction[2U])};
        };
        retail_lighting.light_color = normalized_color(match_state_info.light_color);
        retail_lighting.light_direction = float_direction(match_state_info.light_direction);
        retail_lighting.back_light_color =
            normalized_color(match_state_info.back_light_color);
        retail_lighting.back_light_direction =
            float_direction(match_state_info.back_light_direction);
        retail_lighting.ambient_color =
            normalized_color(match_state_info.ambient_light_color);
        retail_lighting.ambient_intensity =
            static_cast<float>(match_state_info.ambient_light_intensity);
        world_renderer.set_retail_lighting(retail_lighting);
    }

    [[nodiscard]] bool apply_live_map_environment(std::string_view server_skydome) {
        apply_retail_state_lighting();
        world_renderer.set_retail_fog_color(match_state_info.fog_color);

        const std::string selected_skydome = live_official_environment.has_value()
                                                 ? std::string{live_official_environment->skydome}
                                                 : std::string{server_skydome};

        // set_skydome deliberately preserves the currently installed fog.
        // Seed it from the server only on the fallback path; official maps
        // replace it with the locally derived horizon after the dome succeeds.
        if (!live_official_environment.has_value()) {
            world_renderer.set_fog_color(match_state_info.fog_color);
        }
        if (!world_renderer.set_skydome(selected_skydome)) {
            return false;
        }
        if (live_official_environment.has_value()) {
            auto atmosphere = world::resolve_map_atmosphere(config.asset_root, selected_skydome);
            const auto local_fog = atmosphere.fog_color;
            world_renderer.set_atmosphere(atmosphere);
            world_renderer.set_fog_color(local_fog);
            world_renderer.set_retail_fog_color(match_state_info.fog_color);
        }
        return true;
    }

    void clear_live_chunk_remeshes() noexcept {
        live_chunk_remesh_pending.fill(false);
        live_chunk_remesh_queue.clear();
        live_catchup_packet_sync = false;
        deferred_terrain_cursor = 0U;
        live_catchup_render_sync = false;
        live_catchup_remesh_total = 0U;
    }

    /** Coalesces terrain invalidations by 16x16 column-slab chunk. */
    void queue_live_chunk_remeshes(std::span<const world::ChunkKey> chunks) {
        for (const auto key : chunks) {
            if (key.x >= live_chunk_axis || key.y >= live_chunk_axis) {
                continue;
            }
            const auto index = static_cast<std::size_t>(key.y) * live_chunk_axis + key.x;
            if (live_chunk_remesh_pending[index]) {
                continue;
            }
            live_chunk_remesh_pending[index] = true;
            live_chunk_remesh_queue.push_back(key);
        }
        if (live_catchup_render_sync) {
            live_catchup_remesh_total =
                std::max(live_catchup_remesh_total, live_chunk_remesh_queue.size());
        }
    }

    [[nodiscard]] world::VxlColor ugc_water_color() const noexcept {
        if (!server_ground_colors.empty()) {
            const auto& row = server_ground_colors.back();
            return {row[0U], row[1U], row[2U], 255U};
        }
        return {18U, 67U, 94U, 255U};
    }

    void queue_all_live_chunks() {
        std::vector<world::ChunkKey> chunks;
        chunks.reserve(live_chunk_count);
        for (std::uint32_t y{}; y < live_chunk_axis; ++y) {
            for (std::uint32_t x{}; x < live_chunk_axis; ++x) {
                chunks.push_back({x, y});
            }
        }
        queue_live_chunk_remeshes(chunks);
    }

    [[nodiscard]] std::vector<std::string> available_ugc_skydomes() const {
        std::vector<std::string> result;
        const auto root = config.asset_root / "mesh";
        std::error_code error;
        for (std::filesystem::directory_iterator iterator{root, error}, end;
             !error && iterator != end;
             iterator.increment(error)) {
            if (!iterator->is_directory(error)) continue;
            const auto stem = iterator->path().filename().string();
            const auto definition = iterator->path() / (stem + ".txt");
            if (std::filesystem::is_regular_file(definition, error)) {
                result.push_back(stem + ".txt");
            }
            error.clear();
        }
        return result;
    }

    void open_ugc_ingame_settings() {
        // A retail peer-host advertises role 1. BattleSpades' crash-safe
        // dedicated Map Creator must advertise role 2 to every socket because
        // role 1 makes retail attempt to dereference absent Steam-lobby VXL
        // state. The client that spawned that dedicated process is still the
        // logical editor owner and may expose the same host-only panel.
        const bool owns_dedicated_editor =
            owned_local_server != nullptr && owned_local_server->running() &&
            match_initial_info.map_is_ugc();
        if (!network_match || !match_initial_info.map_is_ugc() ||
            (match_initial_info.ugc_role != network::UgcRole::host &&
             !owns_dedicated_editor)) {
            settings_warning = "Only the UGC editor host can change map settings";
            return;
        }
        const auto water = ugc_water_color();
        UgcIngameSettingsDraft draft;
        draft.skydome = live_skydome_name;
        draft.water = {water.red, water.green, water.blue, 255U};
        draft.target_mode = match_initial_info.ugc_mode;
        draft.map_title = ugc_map_title;
        if (!ugc_ingame_settings.open(true, std::move(draft), available_ugc_skydomes())) {
            settings_warning = "No valid retail skydomes are installed";
            return;
        }
        cancel_pointer_capture();
        play_confirm();
    }

    void apply_ugc_ingame_settings() {
        const auto applied = ugc_ingame_settings.apply();
        if (!applied.has_value() || match_connection == nullptr ||
            !local_player_id.has_value()) {
            return;
        }
        if (server_ground_colors.empty()) {
            server_ground_colors = {
                {80U, 96U, 80U, 0U},   {96U, 88U, 72U, 148U},
                {112U, 80U, 64U, 240U}, {128U, 72U, 56U, 168U},
                {112U, 64U, 58U, 199U}, {96U, 56U, 40U, 220U},
                {80U, 48U, 32U, 240U},  {64U, 40U, 24U, 254U},
                {5U, 85U, 156U, 255U},
            };
        }
        auto& water = server_ground_colors.back();
        water[0U] = applied->water[0U];
        water[1U] = applied->water[1U];
        water[2U] = applied->water[2U];

        const auto sky = network::encode_packet(network::SkyboxDataPacket{applied->skydome});
        const auto colors = network::encode_packet(
            network::SetGroundColorsPacket{server_ground_colors});
        const auto mode = network::encode_packet(
            network::SetUgcEditModePacket{applied->target_mode});
        const auto title = network::encode_packet(network::ChatMessagePacket{
            *local_player_id, 0U, "/__local_ugc_title " + applied->map_title});
        if (sky.empty() || colors.empty() || mode.empty() || title.empty() ||
            !match_connection->send(sky) || !match_connection->send(colors) ||
            !match_connection->send(mode) || !match_connection->send(title)) {
            settings_warning = "Failed to queue the atomic UGC settings update";
            return;
        }
        live_skydome_name = applied->skydome;
        match_initial_info.ugc_mode = applied->target_mode;
        ugc_map_title = applied->map_title;
        if (!apply_live_map_environment(live_skydome_name)) {
            settings_warning = "UGC skydome update failed: " +
                               std::string{world_renderer.last_error()};
        }
        queue_all_live_chunks();
        play_confirm();
    }

    void capture_ugc_overhead_preview() {
        if (tutorial_session == nullptr || !match_initial_info.map_is_ugc()) {
            settings_warning = "A loaded UGC world is required for map-preview capture";
            return;
        }
        if (minimap_pixels.size() !=
            static_cast<std::size_t>(world::VxlMap::width) * world::VxlMap::depth * 4U) {
            minimap_pixels = world::build_minimap_overview_rgba(tutorial_session->map());
        }
        std::string error;
        if (!write_ugc_overhead_preview(ugc_maps_root(),
                                        ugc_map_title,
                                        minimap_pixels,
                                        world::VxlMap::width,
                                        world::VxlMap::depth,
                                        server_ugc_preview_png,
                                        error)) {
            settings_warning = "UGC preview capture failed: " + error;
            return;
        }
        settings_warning = "UGC overhead preview saved";
        play_confirm();
    }

    /**
     * Routes retail's mouse-driven UGC settings rows in 800x600 design space.
     * The editor overlay owns the click completely so no gameplay action can
     * leak through while the host changes authored map properties.
     */
    void release_ugc_ingame_settings(std::optional<ui::Point> point) {
        if (!ugc_ingame_settings.visible() || !point.has_value()) return;
        constexpr auto subpixels = MainMenuModel::subpixels_per_pixel;
        const auto x = static_cast<double>(point->x) / subpixels;
        const auto y = static_cast<double>(point->y) / subpixels;
        const auto inside = [x, y](ui::DrawRect bounds) noexcept {
            return x >= bounds.x && x < bounds.x + bounds.width && y >= bounds.y &&
                   y < bounds.y + bounds.height;
        };
        const UgcIngameSettingsPresentation ugc_settings_presentation;
        const auto layout = ugc_ingame_settings_classic_layout();

        if (inside(layout.cancel_button)) {
            ugc_ingame_settings.cancel();
            play_back();
            return;
        }
        if (inside(layout.apply_button)) {
            apply_ugc_ingame_settings();
            return;
        }

        for (std::size_t index{}; index < UgcIngameSettingsModel::field_count; ++index) {
            const auto field = static_cast<UgcIngameSettingField>(index);
            const auto bounds =
                ugc_settings_presentation.field_bounds(ugc_ingame_settings, field);
            if (!bounds.has_value() || !inside(*bounds)) continue;
            const bool focus_changed = ugc_ingame_settings.set_focused_field(field);
            if (field == UgcIngameSettingField::map_title) {
                static_cast<void>(ugc_ingame_settings.begin_title_edit());
                play_confirm();
            } else if (field == UgcIngameSettingField::map_preview) {
                capture_ugc_overhead_preview();
            } else if (!focus_changed &&
                       ugc_ingame_settings.adjust_focused(x < bounds->x + bounds->width * 0.5
                                                               ? -1
                                                               : 1)) {
                // The first click selects the row; a second click on either
                // value half performs the same step as retail's arrow control.
                play_scroll();
            } else {
                play_scroll();
            }
            return;
        }
    }

    void complete_live_map_loading() {
        match_loading.syncing_map();
        assets::PreloadSnapshot uploaded;
        uploaded.state = assets::PreloadBatchState::ready;
        uploaded.progress = 1.0;
        match_loading.set_preload_snapshot(uploaded);
        live_catchup_render_sync = false;
        live_catchup_remesh_total = 0U;
    }

    /**
     * Applies historical block mutations in bounded batches before enabling
     * START. Incoming terrain packets remain queued behind this cursor, so
     * reconnect ordering is preserved while the loading animation keeps
     * rendering.
     */
    void pump_live_terrain_catchup(std::size_t budget) {
        if (!live_catchup_packet_sync || live_terrain_replica == nullptr) {
            return;
        }
        std::size_t consumed{};
        while (consumed < budget && deferred_terrain_cursor < deferred_terrain_packets.size()) {
            const auto& packet = deferred_terrain_packets[deferred_terrain_cursor++];
            ++consumed;
            if (packet.empty()) {
                continue;
            }
            const auto id = std::to_integer<std::uint8_t>(packet.front());
            const auto result = id == network::BuildPrefabActionPacket::id ||
                                        id == network::ErasePrefabActionPacket::id
                                    ? apply_live_prefab_mutation(packet)
                                : id == network::PrefabCompletePacket::id
                                    ? complete_live_prefab(false)
                                    : live_terrain_replica->apply(packet);
            if (!result.recognized || !result.error.empty()) {
                live_catchup_packet_sync = false;
                match_loading.fail("MAP_CATCHUP_FAILED");
                settings_warning = result.error;
                return;
            }
        }

        // Historical feedback is not presented. Draining every batch also
        // prevents thousands of old impact/falling events accumulating while
        // the canonical map is reconstructed.
        static_cast<void>(live_terrain_replica->take_impact_events());
        static_cast<void>(live_terrain_replica->take_falling_components());

        if (deferred_terrain_cursor < deferred_terrain_packets.size()) {
            assets::PreloadSnapshot uploaded;
            uploaded.state = assets::PreloadBatchState::active;
            uploaded.progress = deferred_terrain_packets.empty()
                                    ? 1.0
                                    : 0.5 * static_cast<double>(deferred_terrain_cursor) /
                                          static_cast<double>(deferred_terrain_packets.size());
            match_loading.set_preload_snapshot(uploaded);
            if (deferred_terrain_cursor >= 4'096U &&
                deferred_terrain_cursor * 2U >= deferred_terrain_packets.size()) {
                deferred_terrain_packets.erase(
                    deferred_terrain_packets.begin(),
                    deferred_terrain_packets.begin() +
                        static_cast<std::ptrdiff_t>(deferred_terrain_cursor));
                deferred_terrain_cursor = 0U;
            }
            return;
        }

        deferred_terrain_packets.clear();
        deferred_terrain_cursor = 0U;
        live_catchup_packet_sync = false;
        const auto dirty = live_terrain_replica->take_dirty_chunks();
        queue_live_chunk_remeshes(dirty);
        if (live_chunk_remesh_queue.empty()) {
            complete_live_map_loading();
        } else {
            live_catchup_render_sync = true;
            live_catchup_remesh_total = live_chunk_remesh_queue.size();
            match_loading.syncing_map();
        }
    }

    /**
     * Rebuilds a bounded number of coalesced terrain chunks on the render
     * thread. Collision is already authoritative; this lane only catches the
     * visible mesh up without allowing a reconnect burst to monopolize a tick.
     */
    void pump_live_chunk_remeshes(std::size_t budget) {
        if (live_chunk_remesh_queue.empty()) {
            if (live_catchup_render_sync) {
                complete_live_map_loading();
            }
            return;
        }
        const world::VxlMap* active_map =
            tutorial_session != nullptr ? &tutorial_session->map() : tutorial_ready_map.get();
        if (active_map == nullptr || !world_renderer.is_initialized()) {
            return;
        }
        const PerformanceScope performance{"terrain_remesh", std::chrono::microseconds{2'000}};

        world::ChunkMesherConfig remesh_config;
        remesh_config.bed_water_color = ugc_water_color();
        remesh_config.emissive = world::emissive_palette_for(tutorial_map_name);
        if (tutorial_session != nullptr) {
            remesh_config.static_lights = &tutorial_session->static_lights();
        }
        const world::ChunkMesher remesher{remesh_config};
        // A chunk count alone is not a time budget: 24 dense slabs can consume
        // an entire simulation frame. Finish at least one chunk, then yield at
        // the deadline. FIFO prevents sustained nearby edits starving an older
        // authoritative update indefinitely.
        const auto deadline = std::chrono::steady_clock::now() + std::chrono::milliseconds{2};
        while (budget > 0U && !live_chunk_remesh_queue.empty()) {
            const auto key = live_chunk_remesh_queue.front();
            if (!world_renderer.upload_chunk(remesher.mesh(*active_map, key))) {
                settings_warning = "terrain chunk synchronization failed: " +
                                   std::string{world_renderer.last_error()};
                if (live_catchup_render_sync) {
                    match_loading.fail("MAP_CATCHUP_FAILED");
                }
                return;
            }
            live_chunk_remesh_queue.pop_front();
            const auto index = static_cast<std::size_t>(key.y) * live_chunk_axis + key.x;
            live_chunk_remesh_pending[index] = false;
            skylight.refresh_region(*active_map,
                                    key.x * live_chunk_edge,
                                    key.y * live_chunk_edge,
                                    (key.x * live_chunk_edge) + live_chunk_edge - 1U,
                                    (key.y * live_chunk_edge) + live_chunk_edge - 1U);
            if (!minimap_pixels.empty()) {
                static_cast<void>(world::refresh_minimap_overview_rgba(
                    *active_map,
                    minimap_pixels,
                    key.x * live_chunk_edge,
                    key.y * live_chunk_edge,
                    (key.x * live_chunk_edge) + live_chunk_edge - 1U,
                    (key.y * live_chunk_edge) + live_chunk_edge - 1U));
                minimap_texture_upload_pending = true;
            }
            --budget;
            if (std::chrono::steady_clock::now() >= deadline) {
                break;
            }
        }
        if (live_chunk_remesh_queue.empty()) {
            minimap_map_revision = active_map->revision();
        }
        if (live_catchup_render_sync) {
            assets::PreloadSnapshot uploaded;
            uploaded.state = live_chunk_remesh_queue.empty() ? assets::PreloadBatchState::ready
                                                             : assets::PreloadBatchState::active;
            uploaded.progress = live_chunk_remesh_queue.empty() || live_catchup_remesh_total == 0U
                                    ? 1.0
                                    : 1.0 - static_cast<double>(live_chunk_remesh_queue.size()) /
                                                static_cast<double>(live_catchup_remesh_total);
            match_loading.set_preload_snapshot(uploaded);
            if (live_chunk_remesh_queue.empty()) {
                complete_live_map_loading();
            }
        }
    }

    std::string last_logged_connection_error;

    void record_connection_failure(const network::LiveProtocol168Status& status) {
        if (status.error.empty() || status.error == last_logged_connection_error) return;
        last_logged_connection_error = status.error;
        // Portable diagnostics for reports whose UI only says connection failed.
        // Never include account names, access tokens, join codes or Steam tickets.
        try {
            const auto path = config.executable_directory / "connection-diagnostics.log";
            std::error_code error;
            const auto size = std::filesystem::file_size(path, error);
            std::ofstream output{path, !error && size >= 256U * 1024U ? std::ios::trunc : std::ios::app};
            output << std::chrono::duration_cast<std::chrono::seconds>(
                std::chrono::system_clock::now().time_since_epoch()).count() << " endpoint=";
            if (active_match_request) output << active_match_request->host << ':' << active_match_request->port;
            output << " received=" << status.received_datagrams << " sent=" << status.sent_datagrams
                   << " queued=" << status.queued_inbound << " error=" << status.error.substr(0U, 1024U) << '\n';
        } catch (...) { /* Logging must never interrupt connection recovery. */ }
    }

    void pump_match_connection() {
        if (map_transition_reconnecting) {
            pump_map_transition_reconnect();
            if (!map_transition_reconnecting || match_connection == nullptr) return;
        }
        if (match_connection == nullptr) {
            return;
        }
        const auto status = match_connection->status();
        if (status.phase == network::LiveProtocol168Phase::failed ||
            status.phase == network::LiveProtocol168Phase::disconnected) {
            record_connection_failure(status);
            if (network::protocol168_should_reconnect_after_map_change(
                    status, map_transition_armed)) {
                if (!map_transition_reconnecting) {
                    begin_map_transition_reconnect(status.error);
                } else {
                    schedule_map_transition_retry(status.error);
                }
                return;
            }
            fail_match_connection(status);
            return;
        }
        auto bootstrap = match_connection->take_bootstrap();
        if (bootstrap == nullptr)
            return;
        if (!active_match_request.has_value()) {
            match_loading.fail("SERVER_CONNECTION_FAILED");
            settings_warning = "Protocol 168 bootstrap lost its selected endpoint";
            return;
        }
        const auto map = bootstrap->initial_info.map_name.empty()
                             ? active_match_request->expected_map
                             : bootstrap->initial_info.map_name;
        // InitialInfo is authoritative. Browser/A2S metadata is only a loading
        // prediction and may be absent for direct-connect or stale after a
        // same-endpoint map rotation.
        const auto mode = resolve_protocol168_mode(bootstrap->initial_info.mode_key,
                                                   bootstrap->initial_info.classic);
        match_ui_skin = supported_ui_skin(bootstrap->initial_info.texture_skin);
        match_loading.initial_info(
            map, mode.title_key, mode.classic, match_ui_skin, mode.code == "ugc",
            bootstrap->initial_info.friendly_fire);
        match_loading.set_infographic_captions(bootstrap->initial_info.mode_infographic_text);
        match_loading.receiving_map();
        tutorial_roster = std::move(bootstrap->roster);
        match_initial_info = std::move(bootstrap->initial_info);
        match_state_info = std::move(bootstrap->state_info);
        map_transition_armed = match_state_info.has_map_ended;
        map_transition_reconnecting = false;
        map_transition_attempts = 0U;
        live_official_environment = match_initial_info.map_is_ugc()
                                        ? std::nullopt
                                        : world::find_official_map_environment(map);
        live_skydome_name = bootstrap->skybox_info.definition_name;
        // This name also selects the emissive palette after the VXL finishes
        // loading. Previously live matches retained "Training", so Tokyo neon
        // and official flare fixtures never received their local light volume.
        tutorial_map_name = live_official_environment.has_value()
                                ? std::string{live_official_environment->stem}
                                : map;
        server_minimap_billboards.clear();
        server_minimap_zones.clear();
        server_team_map_visibility.fill(false);
        game_hud.reset_team_progress();
        game_hud.reset_territory_bases();
        death_camera.end_life();
        if (!apply_live_map_environment(bootstrap->skybox_info.definition_name)) {
            settings_warning =
                "live map environment failed: " + std::string{world_renderer.last_error()};
        }
        local_player_id = bootstrap->local_player_id;
        if (match_state_info.has_map_ended) {
            // Retail LoadingMenu enters ViewGameStats when the authoritative
            // StateData tail says this map already ended. This path matters
            // for clients that complete their bootstrap during the server's
            // end-screen dwell and never observed packet 53 in the old scene.
            // Resolve the local player first so the same transition can pick
            // the correct win/lose sting.
            match_results.on_map_ended(
                match_result_winner_from_scores(team_roster_state(false)));
            play_match_result_audio_if_ready();
        }
        awaiting_initial_spawn_create_player = false;
        local_spawn_confirmed = false;
        initial_join_team.reset();
        network_match = true;
        // Only a successful protocol bootstrap proves that the player is in
        // this match. Publish the opaque master-list ID, never a direct socket
        // supplied by an arbitrary user. Friends resolve it against AoSPlay's
        // current public list before they connect.
        if (social_client != nullptr && active_match_request.has_value() &&
            !active_match_request->identity_server_id.empty()) {
            social_client->set_presence(
                "in_game",
                nlohmann::json{{"server_id", active_match_request->identity_server_id}});
        }
        // Interactive bootstrap has not emitted ClientData yet. Diagnostic
        // auto-join sessions still report their exact next loop here.
        client_loop_count = static_cast<std::int32_t>(bootstrap->next_client_loop_count);
        latest_world_loop = 0;
        clock_sync_elapsed = 1.0;
        clock_sync_token = 0;
        played_hit_sound = false;
        pending_tool_selection.reset();
        last_sent_tool.reset();
        pending_class_selection.reset();
        live_terrain_replica.reset();
        live_prefab_placement.clear();
        live_prefab_model.reset();
        live_prefab_model_name.clear();
        timed_explosive_seconds.clear();
        deferred_terrain_packets.clear();
        clear_live_chunk_remeshes();
        local_palette_color.reset();
        server_ugc_items.clear();
        server_ugc_objectives.reset();
        server_ugc_preview_png.clear();
        server_ground_colors = match_initial_info.ground_colors;
        ugc_initial_requests_sent = false;
        server_ambient_sounds.clear();
        server_ambience_received = false;
        server_music_received = false;
        server_sound_variant = 0U;
        pending_melee_sound_hints.clear();
        predicted_terrain_hits.clear();
        if (audio_started) {
            stop_all_entity_effect_loops();
            audio->stop_named_loops();
            audio->stop_ambience();
        }
        block_line_start.reset();
        palette_selection = 16U;
        prefab_yaw_override = 1U;
        preview_prefab_name.clear();
        preview_prefab_model.reset();
        preview_prefab_placement.reset();
        preview_prefab_icon.clear();
        preview_prefab_position.reset();
        preview_prefab_pitch = 0U;
        preview_prefab_roll = 0U;
        preview_prefab_center = {};
        ugc_prefab_control.reset();
        preview_prefab_valid = false;
        preview_prefab_cost = 0;
        placement_cube_meshes_uploaded = false;
        preview_prefab_meshes_uploaded = false;
        preview_ugc_item_uploaded.reset();
        preview_deployable_type_uploaded.reset();
        preview_prefab_color = 0U;
        if (!start_world_bootstrap(std::move(bootstrap->map), tutorial_map_name)) {
            retire_match_connection();
            return;
        }
        history_servers.insert(active_match_request->identifier);
    }

    /** Drain complete live packets without allowing network work to block a tick. */
    void pump_live_match_packets() {
        if (!network_match || match_connection == nullptr)
            return;
        if (match_initial_info.map_is_ugc() && tutorial_session != nullptr &&
            local_spawn_confirmed && !ugc_initial_requests_sent) {
            const auto entities = network::encode_packet(network::RequestUgcEntitiesPacket{
                match_initial_info.ugc_mode, true});
            const auto map_info = network::encode_packet(
                network::UgcMessagePacket{network::UgcMessageCode::request_map_info});
            if (match_connection->send(entities) && match_connection->send(map_info)) {
                ugc_initial_requests_sent = true;
            }
        }
        const PerformanceScope performance{"network_packets", std::chrono::microseconds{2'000}};
        // Hints only pair packets drained in this pump. Carrying them into a
        // later tick could relabel an unrelated hit at the same voxel.
        pending_melee_sound_hints.clear();
        // Preserve FIFO ordering: terrain collision mutations that precede an
        // owner WorldUpdate must be visible to reconciliation.  A permanently
        // fixed 16-packet budget starved that authority behind reliable bursts
        // under jitter; the adaptive bound keeps ordinary frames small while
        // draining enough backlog to stop acknowledgement age from growing.
        const auto queued_inbound = match_connection->status().queued_inbound;
        const std::size_t packet_budget = network::protocol168_inbound_apply_budget(
            queued_inbound, tutorial_session != nullptr);
        for (const auto& packet : match_connection->take_inbound(packet_budget)) {
            if (packet.empty())
                continue;
            const auto id = std::to_integer<std::uint8_t>(packet.front());
            const PerformanceScope packet_performance{
                "network_packet", std::chrono::microseconds{2'000}, id};
            if (id == network::CosmeticAppearances::packet_id) {
                static_cast<void>(remote_cosmetics.ingest(packet));
                continue;
            }
            if (id == network::PrefabCompletePacket::id &&
                (live_terrain_replica == nullptr || live_catchup_packet_sync)) {
                // Keep packet 29 ordered with the packet-30 slices buffered
                // during join. Processing it early would reveal no prefab and
                // then leave every deferred slice staged forever.
                if (deferred_terrain_packets.size() >= 16'384U) {
                    settings_warning = "terrain catch-up exceeded its bounded queue";
                } else {
                    deferred_terrain_packets.push_back(packet);
                }
                continue;
            }
            if (id == network::SetColorPacket::id || id == network::DamagePacket::id ||
                id == network::BlockBuildColoredPacket::id || id == network::BlockLinePacket::id ||
                id == network::BlockBuildPacket::id || id == network::PaintBlockPacket::id ||
                id == network::BuildPrefabActionPacket::id ||
                id == network::ErasePrefabActionPacket::id) {
                std::optional<network::DamagePacket> terrain_damage;
                std::optional<network::BlockBuildColoredPacket> colored_build;
                if (id == network::DamagePacket::id || id == network::BlockBuildColoredPacket::id) {
                    const auto decoded = network::decode_terrain_packet(packet);
                    if (decoded) {
                        if (const auto* damage =
                                std::get_if<network::DamagePacket>(&*decoded.packet);
                            damage != nullptr) {
                            terrain_damage = *damage;
                        } else if (const auto* build =
                                       std::get_if<network::BlockBuildColoredPacket>(
                                           &*decoded.packet);
                                   build != nullptr) {
                            colored_build = *build;
                        }
                    }
                }
                if (id == network::SetColorPacket::id && local_player_id.has_value()) {
                    const auto decoded = network::decode_terrain_packet(packet);
                    const auto* palette =
                        decoded ? std::get_if<network::SetColorPacket>(&*decoded.packet) : nullptr;
                    if (palette != nullptr && palette->player_id == *local_player_id) {
                        local_palette_color = palette->color & 0x00FFFFFFU;
                        palette_selection = closest_palette_index(*local_palette_color);
                        preview_prefab_meshes_uploaded = false;
                        placement_cube_meshes_uploaded = false;
                        if (tutorial_session != nullptr) {
                            tutorial_session->set_block_color(world::VxlColor{
                                static_cast<std::uint8_t>(*local_palette_color >> 16U),
                                static_cast<std::uint8_t>(*local_palette_color >> 8U),
                                static_cast<std::uint8_t>(*local_palette_color),
                                255U});
                            // The selected block model has the palette baked
                            // into its mesh, so refresh it exactly once.
                            uploaded_sandbox_tool.reset();
                        }
                    }
                }
                if (live_terrain_replica == nullptr || live_catchup_packet_sync) {
                    if (deferred_terrain_packets.size() >= 16'384U) {
                        settings_warning = "terrain catch-up exceeded its bounded queue";
                    } else {
                        deferred_terrain_packets.push_back(packet);
                    }
                    continue;
                }
                const auto result = id == network::BuildPrefabActionPacket::id ||
                                            id == network::ErasePrefabActionPacket::id
                                        ? apply_live_prefab_mutation(packet)
                                        : live_terrain_replica->apply(packet);
                if (!result.recognized || !result.error.empty()) {
                    settings_warning = result.error;
                    continue;
                }
                if (tutorial_session != nullptr && local_player_id.has_value()) {
                    const auto block_cost =
                        network::confirmed_owner_block_cost(packet, result, *local_player_id);
                    if (block_cost != 0U) {
                        static_cast<void>(
                            tutorial_session->spend_server_confirmed_blocks(block_cost));
                    }
                }
                for (auto& component : live_terrain_replica->take_falling_components()) {
                    terrain_effects.spawn_falling(std::move(component));
                }
                if (tutorial_session != nullptr && terrain_damage.has_value() &&
                    result.mutation.accepted &&
                    (terrain_damage->type == 10U || terrain_damage->type == 33U)) {
                    // Damage(37) is the Drill.do_drill edge. It owns both the
                    // one-shot bore sample emitted below and a separate
                    // half-second drilling loop attached to the still-live
                    // CreateEntity projectile.
                    static_cast<void>(tutorial_session->apply_server_drill_contact(
                        terrain_damage->causer_id,
                        terrain_damage->player_id,
                        {terrain_damage->position[0U],
                         terrain_damage->position[1U],
                         terrain_damage->position[2U]}));
                }
                for (const auto& impact : live_terrain_replica->take_impact_events()) {
                    if (impact.source_tool == 63U && terrain_damage.has_value()) {
                        std::array<float, 3U> barrel{static_cast<float>(impact.cell.x) + 0.5F,
                                                     static_cast<float>(impact.cell.y) + 0.5F,
                                                     static_cast<float>(impact.cell.z) + 0.5F};
                        audio::SoundPosition shooter_position{barrel[0U], barrel[1U], barrel[2U]};
                        bool head_relative{};
                        if (local_player_id == terrain_damage->player_id &&
                            tutorial_session != nullptr) {
                            const auto eye = tutorial_session->eye_position();
                            const auto orientation = tutorial_session->player().orientation;
                            barrel = {static_cast<float>(eye[0U] + orientation.x * 0.8),
                                      static_cast<float>(eye[1U] + orientation.y * 0.8),
                                      static_cast<float>(eye[2U] + orientation.z * 0.8)};
                            shooter_position = {static_cast<float>(eye[0U]),
                                                static_cast<float>(eye[1U]),
                                                static_cast<float>(eye[2U])};
                            head_relative = true;
                        } else if (const auto* shooter =
                                       tutorial_roster.player(terrain_damage->player_id);
                                   shooter != nullptr) {
                            barrel = {static_cast<float>(shooter->position.x +
                                                         shooter->orientation.x * 0.8),
                                      static_cast<float>(shooter->position.y +
                                                         shooter->orientation.y * 0.8),
                                      static_cast<float>(shooter->position.z +
                                                         shooter->orientation.z * 0.8)};
                            shooter_position = remote_sound_position(*shooter);
                        }
                        world::emit_block_sucker_debris(
                            particles,
                            impact,
                            barrel,
                            static_cast<std::uint32_t>(terrain_damage->seed) ^
                                (static_cast<std::uint32_t>(terrain_damage->player_id) << 16U));
                        if (impact.destroyed && local_player_id == terrain_damage->player_id &&
                            tutorial_session != nullptr) {
                            tutorial_session->grant_blocks();
                        }
                        if (audio_started) {
                            audio->play_weapon_cue(63U,
                                                   audio::WeaponCue::tool_extra,
                                                   terrain_damage->seed,
                                                   shooter_position,
                                                   1.0F,
                                                   head_relative);
                        }
                        continue;
                    }
                    const bool server_drives_melee_audio =
                        impact.kind == world::TerrainImpactKind::melee;
                    const bool predicted_contact =
                        impact.kind == world::TerrainImpactKind::bullet &&
                        terrain_damage.has_value() &&
                        consume_predicted_terrain_hit(
                            terrain_damage->player_id, impact.cell);
                    if (server_drives_melee_audio) {
                        if (pending_melee_sound_hints.size() >= 32U) {
                            pending_melee_sound_hints.erase(pending_melee_sound_hints.begin());
                        }
                        pending_melee_sound_hints.push_back(
                            {impact.source_tool,
                             {static_cast<float>(impact.cell.x) + 0.5F,
                              static_cast<float>(impact.cell.y) + 0.5F,
                              static_cast<float>(impact.cell.z) + 0.5F},terrain_damage?terrain_damage->player_id:std::uint8_t{255U}});
                    }
                    if (predicted_contact && !impact.destroyed) {
                        // ShootFeedback already emitted the contact chips and
                        // sound at this cell. Damage(37) has committed its
                        // darkening to VXL; presenting it again would double
                        // every sublethal hit burst.
                        continue;
                    }
                    terrain_effects.spawn_impact(
                        impact,
                        server_drives_melee_audio
                            ? world::TerrainImpactSoundPolicy::silent
                        : predicted_contact
                            ? world::TerrainImpactSoundPolicy::destruction_only
                            : world::TerrainImpactSoundPolicy::full);
                }
                if (colored_build.has_value() && result.mutation.accepted) {
                    const auto* builder = tutorial_roster.player(colored_build->player_id);
                    const bool block_cannon =
                        builder != nullptr && (builder->tool_id == 29U || builder->tool_id == 48U);
                    if (block_cannon) {
                        const std::array<float, 3U> position{
                            static_cast<float>(colored_build->x) + 0.5F,
                            static_cast<float>(colored_build->y) + 0.5F,
                            static_cast<float>(colored_build->z) + 0.5F};
                        // A snowball already leaves the recovered smoke trail
                        // while flying. Retail acknowledges its placement with
                        // snowcan_build only; the old seven-puff impact burst
                        // was client-invented and read as an explosion.
                        if (audio_started) {
                            static_cast<void>(audio->play_named_one_shot(
                                "snowcan_build",
                                {position[0U], position[1U], position[2U]},
                                1.0F,
                                false));
                        }
                    }
                }
                if ((id == network::BlockBuildPacket::id ||
                     id == network::BlockBuildColoredPacket::id) &&
                    result.mutation.accepted && !result.mutation.changed_cells.empty()) {
                    const auto& cell = result.mutation.changed_cells.front();
                    const auto* builder = colored_build.has_value()
                                              ? tutorial_roster.player(colored_build->player_id)
                                              : nullptr;
                    const bool block_cannon = builder != nullptr &&
                                              (builder->tool_id == 29U || builder->tool_id == 48U);
                    if (!block_cannon) {
                        const auto color = tutorial_session->map().color(cell.x, cell.y, cell.z)
                                               .value_or(world::VxlColor{176U, 176U, 176U, 255U});
                        world::emit_block_placement(
                            particles,
                            {static_cast<std::int32_t>(cell.x),
                             static_cast<std::int32_t>(cell.y),
                             static_cast<std::int32_t>(cell.z)},
                            color,
                            static_cast<std::uint32_t>(latest_world_loop) ^
                                static_cast<std::uint32_t>(cell.x * 73856093U) ^
                                static_cast<std::uint32_t>(cell.y * 19349663U));
                        if (audio_started) {
                            static_cast<void>(audio->play_named_one_shot(
                                world::placement_sound_stem(
                                    world::PlacementFeedbackKind::block),
                                {static_cast<float>(cell.x) + 0.5F,
                                 static_cast<float>(cell.y) + 0.5F,
                                 static_cast<float>(cell.z) + 0.5F},
                                1.0F));
                        }
                    }
                }
                const auto dirty = live_terrain_replica->take_dirty_chunks();
                queue_live_chunk_remeshes(dirty);
            } else if (id == 2U) {
                const auto update = network::decode_world_update_weapon_rows(packet);
                if (!update) {
                    settings_warning = update.error;
                    continue;
                }
                const auto update_tail =
                    network::decode_world_update_tail(packet, update.consumed_bytes);
                if (!update_tail) {
                    settings_warning = update_tail.error;
                    continue;
                }
                latest_world_loop = update.loop_count;
                for (const auto& row : update.rows) {
                    const world::Vec3 position{
                        row.position[0U], row.position[1U], row.position[2U]};
                    const world::Vec3 velocity{
                        row.velocity[0U], row.velocity[1U], row.velocity[2U]};
                    if (row.player_id < last_known_player_positions.size()) {
                        last_known_player_positions[row.player_id] = position;
                    }
                    const auto* previous_replica = tutorial_roster.player(row.player_id);
                    const bool was_disguised = previous_replica != nullptr &&
                                               (previous_replica->state_flags & 0x02U) != 0U;
                    if (!tutorial_roster.update_world_state(row))
                        continue;
                    const auto* updated_replica = tutorial_roster.player(row.player_id);
                    if (updated_replica != nullptr && row.health > 0) {
                        remember_combat_tool(*updated_replica, row.tool_id);
                    }
                    if (updated_replica != nullptr &&
                        (!local_player_id.has_value() ||
                         row.player_id != *local_player_id)) {
                        observe_remote_character_audio(*updated_replica);
                    }
                    if (updated_replica != nullptr && row.health <= 0) {
                        // The authority continues publishing a jetpack corpse
                        // for exactly one second. Ordinary corpses never enter
                        // this state and therefore keep the immediate packet-36
                        // presentation used by the stock protocol.
                        if (!jetpack_deaths.update_authority(row.player_id,
                                                             updated_replica->generation,
                                                             position)) {
                            if (const auto jetpack = world::retail_jetpack_id(
                                    updated_replica->loadout, updated_replica->ugc_tools);
                                jetpack.has_value()) {
                                static_cast<void>(jetpack_deaths.begin(
                                    row.player_id,
                                    updated_replica->generation,
                                    *jetpack,
                                    position));
                            }
                        }
                        if (jetpack_deaths.active(row.player_id,
                                                  updated_replica->generation) &&
                            row.player_id < retained_corpse_positions.size()) {
                            // ExplodeCorpse carries no coordinates. Preserve
                            // the newest airborne authority point for its VFX.
                            retained_corpse_positions[row.player_id] = position;
                        }
                    }
                    const bool is_disguised = (row.state_flags & 0x02U) != 0U;
                    if (audio_started && was_disguised != is_disguised) {
                        const auto stem = is_disguised
                                              ? "AoS_soundfx_PLAYER_engineer_item_DISGUISE_on_001"
                                              : "AoS_soundfx_PLAYER_engineer_item_DISGUISE_off_001";
                        const bool local = local_player_id == row.player_id;
                        static_cast<void>(audio->play_named_one_shot(
                            stem,
                            {row.position[0U], row.position[1U], row.position[2U]},
                            1.0F,
                            local));
                    }
                    if (tutorial_session != nullptr && local_player_id == row.player_id) {
                        const bool was_alive = tutorial_session->alive();
                        if (local_spawn_confirmed) {
                            game_hud.set_health(row.health);
                            tutorial_session->set_server_health(row.health);
                            if (should_present_local_death(
                                    local_spawn_confirmed, was_alive, row.health)) {
                                begin_local_death(std::nullopt);
                            }
                        }
                        tutorial_session->note_authoritative_snapshot(row.acknowledged_client_loop,
                                                                      position);
                        tutorial_session->apply_server_jetpack_fuel(
                            row.jetpack_fuel, row.acknowledged_client_loop);
                        tutorial_session->apply_server_movement_state(
                            row.action_flags, row.state_flags, row.pickup_id,
                            row.acknowledged_client_loop);
                        // Character.pyx restores the exact ACK state and
                        // replays every later movement record. Delta-rebasing
                        // is observably wrong at voxel edges and jump/crouch
                        // transitions even when all ClientData bits match.
                        static_cast<void>(tutorial_session->reconcile_authoritative(
                            row.acknowledged_client_loop, position, velocity));
                        // Rows older than a local selection edge still carry
                        // the previous tool. Once the ACK covers that edge,
                        // the server byte is authoritative for HUD and hands.
                        const bool tool_acknowledged =
                            !pending_tool_selection.has_value() ||
                            row.acknowledged_client_loop >=
                                pending_tool_selection->first_client_loop;
                        if (tool_acknowledged && row.tool_id != 0xFFU) {
                            if (!tutorial_session->apply_server_tool(row.tool_id)) {
                                settings_warning =
                                    "owner WorldUpdate selected a tool outside the active loadout";
                            }
                            pending_tool_selection.reset();
                        } else if (tool_acknowledged) {
                            // Protocol 168 rewrites only the owner's tool byte
                            // to 0xFF. Retail treats it as "keep local tool" so
                            // palette/tool state is not replayed by a self row.
                            pending_tool_selection.reset();
                        }
                    } else if (const auto* replica = tutorial_roster.player(row.player_id);
                               replica != nullptr) {
                        static_cast<void>(sync_remote_player_rig(*replica));
                        auto rig = remote_player_rigs.find(row.player_id);
                        if (rig != remote_player_rigs.end()) {
                            const auto loop_delta =
                                rig->second.last_snapshot_world_loop < 0
                                    ? 2
                                    : std::max(1,
                                               latest_world_loop -
                                                   rig->second.last_snapshot_world_loop);
                            rig->second.motion.push(
                                {replica->position, replica->orientation, replica->velocity},
                                std::clamp(
                                    static_cast<double>(loop_delta) / 60.0, 1.0 / 120.0, 0.1));
                            rig->second.last_snapshot_world_loop = latest_world_loop;
                            // WorldUpdate has no explicit grounded flag. Latch
                            // airborne from meaningful vertical motion and
                            // require two settled authority rows before
                            // returning to the standing gait; this avoids
                            // slopes and quantization flickering the legs.
                            const bool jump_held = (row.input_flags & 0x10U) != 0U;
                            if (std::abs(row.velocity[2U]) > 0.07F ||
                                (jump_held && std::abs(row.velocity[2U]) > 0.02F)) {
                                rig->second.airborne = true;
                                rig->second.grounded_snapshot_count = 0U;
                            } else if (std::abs(row.velocity[2U]) < 0.02F) {
                                rig->second.grounded_snapshot_count =
                                    static_cast<std::uint8_t>(std::min<unsigned int>(
                                        2U,
                                        static_cast<unsigned int>(
                                            rig->second.grounded_snapshot_count) +
                                            1U));
                                if (rig->second.grounded_snapshot_count >= 2U) {
                                    rig->second.airborne = false;
                                }
                            }
                            update_remote_fire_loop(row, *replica);
                            update_remote_block_sucker_audio(row, *replica);
                            update_remote_block_cannon_audio(row, *replica);
                        }
                    }
                }
                if (tutorial_session != nullptr) {
                    const auto channel = [](float value) {
                        return static_cast<std::uint8_t>(std::clamp(std::lround(value), 0L, 255L));
                    };
                    for (const auto& row : update_tail.entities) {
                        world::LocalEntity entity;
                        entity.id = row.entity_id;
                        entity.type = row.type;
                        entity.position = {row.position[0U], row.position[1U], row.position[2U]};
                        entity.velocity = {row.velocity[0U], row.velocity[1U], row.velocity[2U]};
                        entity.yaw = row.yaw;
                        entity.aim_yaw = row.yaw;
                        entity.team = row.state;
                        entity.owner = row.player_id;
                        entity.face = row.face;
                        entity.fuse = row.fuse;
                        entity.color = {
                            channel(row.color[0U]), channel(row.color[1U]), channel(row.color[2U])};
                        entity.has_color = row.has_explicit_color();
                        // A WorldUpdate row refreshes only an entity introduced
                        // by reliable CreateEntity; racing rows are harmless.
                        static_cast<void>(tutorial_session->apply_server_entity_snapshot(entity));
                    }
                    for (const auto& turret : update_tail.rocket_turrets) {
                        static_cast<void>(tutorial_session->apply_server_turret_aim(
                            turret.entity_id, turret.yaw, turret.pitch));
                    }
                }
            } else if (id == network::UseOrientedItemPacket::id) {
                const auto decoded = network::decode_weapon_packet(packet);
                const auto* oriented =
                    decoded ? std::get_if<network::UseOrientedItemPacket>(&*decoded.packet)
                            : nullptr;
                if (oriented == nullptr) {
                    settings_warning = decoded.error.empty()
                                           ? "UseOrientedItem decoded to wrong variant"
                                           : decoded.error;
                    continue;
                }
                if (tutorial_session == nullptr ||
                    !tutorial_session->apply_server_oriented_item(
                        oriented->player_id,
                        oriented->tool_id,
                        oriented->value,
                        {oriented->position[0U], oriented->position[1U], oriented->position[2U]},
                        {oriented->velocity[0U], oriented->velocity[1U], oriented->velocity[2U]})) {
                    settings_warning = "UseOrientedItem referenced an unsupported projectile";
                    continue;
                }
                // Packet 10 is the observer's firing edge. Grenade variants
                // carry a throw sample; legacy servers may also relay launchers,
                // whose ordinary shoot sample is the correct fallback.
                if (audio_started) {
                    const audio::SoundPosition position{
                        oriented->position[0U], oriented->position[1U], oriented->position[2U]};
                    if (audio->has_weapon_cue(oriented->tool_id, audio::WeaponCue::throw_release)) {
                        audio->play_weapon_cue(oriented->tool_id,
                                               audio::WeaponCue::throw_release,
                                               static_cast<std::uint8_t>(oriented->loop_count),
                                               position,
                                               audio::remote_weapon_report_gain(),
                                               false,
                                               audio::SpatialSoundProfile::weapon_report);
                    } else {
                        audio->play_weapon_shoot(oriented->tool_id,
                                                 static_cast<std::uint8_t>(oriented->loop_count),
                                                 position,
                                                 audio::remote_weapon_report_gain(),
                                                 false,
                                                 audio::SpatialSoundProfile::weapon_report);
                    }
                }
            } else if (id == network::ShootFeedbackPacket::id) {
                const auto decoded = network::decode_weapon_packet(packet);
                const auto* feedback =
                    decoded ? std::get_if<network::ShootFeedbackPacket>(&*decoded.packet) : nullptr;
                if (feedback == nullptr) {
                    settings_warning = decoded.error.empty()
                                           ? "ShootFeedback decoded to wrong variant"
                                           : decoded.error;
                    continue;
                }
                const auto* shooter = tutorial_roster.player(feedback->shooter_id);
                if (shooter != nullptr) {
                    // ShootFeedback is the strongest observer-side evidence of
                    // the exact tool that can immediately produce KillAction.
                    remember_combat_tool(*shooter, feedback->tool_id);
                }
                if (local_player_id == feedback->shooter_id) {
                    // The owner already animated and played this action when
                    // it emitted Shoot(6); packet 8 is observer feedback.
                    continue;
                }
                auto rig = remote_player_rigs.find(feedback->shooter_id);
                if (rig != remote_player_rigs.end()) {
                    ++rig->second.action_serial;
                    rig->second.last_primary_world_loop = latest_world_loop;
                }
                if (shooter != nullptr) {
                    // Muzzle feedback remains visible when audio is disabled;
                    // the helper gates only its OpenAL half.
                    present_remote_shot(*feedback, *shooter);
                }
            } else if (id == network::ShootResponsePacket::id) {
                const auto decoded = network::decode_weapon_packet(packet);
                const auto* response =
                    decoded ? std::get_if<network::ShootResponsePacket>(&*decoded.packet) : nullptr;
                if (response == nullptr) {
                    settings_warning = decoded.error.empty()
                                           ? "ShootResponse decoded to wrong variant"
                                           : decoded.error;
                    continue;
                }
                if (response->blood) {
                    const auto seed =
                        static_cast<std::uint32_t>(response->damage_by) * 0x9E3779B9U ^
                        static_cast<std::uint32_t>(latest_world_loop);
                    world::emit_player_blood(particles, response->position, seed);
                    const auto* attacker=tutorial_roster.player(response->damage_by);
                    const auto* cosmetic=attacker?equipped_cosmetic(attacker->player_id,"weapon:"+std::to_string(attacker->tool_id)+":world"):nullptr;
                    if(audio_started&&cosmetic)static_cast<void>(audio->play_cosmetic_cue(cosmetic->id,"melee-hit-player",0U,{response->position[0],response->position[1],response->position[2]},1.F,false));
                }
                if (response->damaged != 0U && local_player_id == response->damage_by &&
                    !played_hit_sound) {
                    bool friendly_hit{};
                    const auto* local = tutorial_roster.player(*local_player_id);
                    double nearest_squared{4.0};
                    for (const auto& candidate : tutorial_roster.players()) {
                        if (candidate.dead || candidate.player_id == *local_player_id) {
                            continue;
                        }
                        const double dx = candidate.position.x - response->position[0U];
                        const double dy = candidate.position.y - response->position[1U];
                        const double dz = candidate.position.z - response->position[2U];
                        const double distance_squared = dx * dx + dy * dy + dz * dz;
                        if (distance_squared <= nearest_squared) {
                            nearest_squared = distance_squared;
                            friendly_hit = local != nullptr && local->team >= 2U &&
                                           candidate.team == local->team;
                        }
                    }
                    played_hit_sound = true;
                    if (!friendly_hit) {
                        game_hud.confirm_hit();
                    }
                    if (audio_started && !friendly_hit) {
                        // gameScene media.play(("you_hit",)) is a 2D cue:
                        // pin it to the listener rather than attenuating it at
                        // the world impact point.
                        static_cast<void>(audio->play_named_one_shot("you_hit", {}, 1.0F, true));
                    }
                }
            } else if (id == network::SetHpPacket::id) {
                const auto decoded = network::decode_runtime_packet(packet);
                const auto* health =
                    decoded ? std::get_if<network::SetHpPacket>(&*decoded.packet) : nullptr;
                if (health == nullptr) {
                    settings_warning = decoded.error;
                    continue;
                }
                const auto previous_health = game_hud.health();
                if (tutorial_session != nullptr && health->health < previous_health &&
                    health->has_directional_damage_source()) {
                    const auto& player = tutorial_session->player();
                    game_hud.add_damage_indicator(damage_indicator_angle_degrees(
                        static_cast<double>(health->source[0U]) - player.position.x,
                        static_cast<double>(health->source[1U]) - player.position.y,
                        player.orientation.x,
                        player.orientation.y));
                }
                if (health->health < previous_health && health->plays_local_hit_sound() &&
                    audio_started) {
                    // Retail SetHP uses one listener-local hitplayer cue for
                    // weapon/explosion damage. Fall/self damage and healing
                    // are intentionally silent at this packet boundary.
                    static_cast<void>(
                        audio->play_named_one_shot("hitplayer", {}, 1.0F, true));
                }
                if (local_player_id.has_value()) {
                    static_cast<void>(
                        tutorial_roster.update_health(*local_player_id, health->health));
                }
                if (tutorial_session != nullptr && local_spawn_confirmed) {
                    const bool was_alive = tutorial_session->alive();
                    tutorial_session->set_server_health(health->health);
                    if (should_present_local_death(
                            local_spawn_confirmed, was_alive, health->health)) {
                        begin_local_death(std::nullopt);
                    }
                }
                game_hud.set_health(health->health);
            } else if (id == network::CreatePlayerPacket::id) {
                const auto created = [&]() {
                    const PerformanceScope stage{"create_player_decode",
                                                 std::chrono::microseconds{1'000}};
                    return network::decode_create_player(packet);
                }();
                std::optional<std::uint8_t> previous_class;
                if (created) {
                    if (const auto* previous =
                            tutorial_roster.player(created.packet->player_id);
                        previous != nullptr) {
                        previous_class = previous->class_id;
                    }
                }
                {
                    const PerformanceScope stage{"create_player_audio",
                                                 std::chrono::microseconds{1'000}};
                    if (created && created.packet->player_id < retained_corpse_positions.size()) {
                        // Do not clear the previous life's death point here.
                        // Packet 36 may be processed after this new-life
                        // CreatePlayer and must still burst at the corpse.
                        last_known_player_positions[created.packet->player_id] = world::Vec3{
                            created.packet->position[0U], created.packet->position[1U],
                            created.packet->position[2U]};
                        const audio::SoundPosition spawn_position{created.packet->position[0U],
                                                                  created.packet->position[1U],
                                                                  created.packet->position[2U]};
                        stop_remote_fire_loop(created.packet->player_id, spawn_position, false);
                        set_block_sucker_audio(remote_block_sucker_audio[created.packet->player_id],
                                               0U,
                                               spawn_position,
                                               false);
                        set_block_cannon_audio(remote_block_cannon_audio[created.packet->player_id],
                                               std::nullopt,
                                               spawn_position,
                                               false);
                    }
                }
                std::string error;
                const bool roster_applied = [&]() {
                    const PerformanceScope stage{"create_player_roster",
                                                 std::chrono::microseconds{1'000}};
                    return tutorial_roster.apply(packet, &error);
                }();
                if (roster_applied && created &&
                    zombie_conversion_audio.observe_conversion(
                        previous_class, created.packet->class_id,
                        ZombieConversionAudioGate::clock::now()) &&
                    audio_started && audio != nullptr &&
                    !audio->play_named_one_shot(
                        "zombie_become", {}, 1.0F, true)) {
                    settings_warning = std::string{audio->last_error()};
                }
                if (roster_applied && created) {
                    if (const auto* player = tutorial_roster.player(created.packet->player_id);
                        player != nullptr) {
                        reset_combat_tool_memory(*player);
                    }
                }
                if (roster_applied && created &&
                    (!local_player_id.has_value() ||
                     created.packet->player_id != *local_player_id)) {
                    if (const auto* remote =
                            tutorial_roster.player(created.packet->player_id);
                        remote != nullptr) {
                        // CreatePlayer is the authoritative life-generation
                        // edge. Retail arms a fresh, guaranteed remote spawn
                        // line here and lets its 1-2 second timer run locally.
                        begin_remote_character_audio(*remote);
                    }
                }
                if (!roster_applied) {
                    settings_warning = error;
                } else if (created && local_player_id.has_value() &&
                           created.packet->player_id == *local_player_id &&
                           awaiting_initial_spawn_create_player && tutorial_session == nullptr) {
                    // The class confirmation is the authoritative beginning of
                    // the first life. Build the world from this spawn instead
                    // of the dead/menu replica received during bootstrap.
                    awaiting_initial_spawn_create_player = false;
                    local_spawn_confirmed = true;
                    start_tutorial_pressed();
                    if (!created.packet->dead) {
                        begin_local_spawn_audio(created.packet->class_id);
                    }
                } else {
                    // Presentation failures on another roster member cannot
                    // block the owner's authoritative life/camera transition.
                    if (tutorial_session != nullptr && !sync_roster_players()) {
                        settings_warning = "live CreatePlayer model failed: " + settings_warning;
                    }
                    if (created && is_local_create_player_boundary(
                                          created.packet->player_id,
                                          local_player_id,
                                          tutorial_session != nullptr)) {
                        if (const auto* local = tutorial_roster.player(*local_player_id);
                            local != nullptr) {
                            local_spawn_confirmed = true;
                            // InitialInfo carries the multiplier applied to the
                            // native per-class constants, not an already-composed
                            // sprint speed. Dividing by the class sprint constant
                            // made prediction ~40% slower than authority.
                            const auto speed_scale = network::protocol168_movement_scale(
                                match_initial_info, local->class_id);
                            tutorial_session->apply_server_class(local->class_id, speed_scale);
                            // A repeated local CreatePlayer is a new authoritative
                            // life, not an inventory-only update. Snap physics to
                            // its spawn and discard prediction samples/latches from
                            // the dead life before publishing the next ClientData.
                            tutorial_session->apply_authoritative_transform(
                                local->position, local->orientation, local->velocity);
                            if (!local->dead) {
                                // CreatePlayer, not KillAction, is retail's spawn
                                // audio boundary. Arm after the transform so an
                                // audio failure cannot interrupt respawn state.
                                begin_local_spawn_audio(local->class_id);
                            }
                            pending_tool_selection.reset();
                            last_sent_tool.reset();
                            end_local_death(local->team, local->dead);
                            const auto* class_definition =
                                world::find_class_definition(local->class_id);
                            const auto spawn_tool =
                                class_definition != nullptr
                                    ? world::preferred_spawn_tool(*class_definition, local->loadout)
                                    : std::optional<std::uint8_t>{};
                            if (!tutorial_session->apply_server_selection(local->class_id,
                                                                          local->loadout,
                                                                          local->prefabs,
                                                                          local->ugc_tools,
                                                                          spawn_tool)) {
                                settings_warning =
                                    "CreatePlayer loadout could not replace local inventory";
                            }
                            // CreatePlayer is the atomic class/team lifecycle
                            // boundary. Rebuild first-person materials here too;
                            // retaining the prior life left arms and team-tinted
                            // tools blue after a class or team change.
                            uploaded_sandbox_tool.reset();
                            if (!load_tutorial_class_arms(local->class_id)) {
                                settings_warning =
                                    "local CreatePlayer model refresh failed: " + settings_warning;
                            }
                        }
                        if (screen() == FrontendScreen::pause_menu ||
                            screen() == FrontendScreen::change_team) {
                            refresh_pause_menu();
                        }
                    }
                }
            } else if (id == network::SetClassLoadoutPacket::id) {
                const auto decoded = network::decode_weapon_packet(packet);
                if (!decoded) {
                    settings_warning = decoded.error;
                    continue;
                }
                const auto* loadout = std::get_if<network::SetClassLoadoutPacket>(&*decoded.packet);
                if (loadout == nullptr || !tutorial_roster.update_loadout(loadout->player_id,
                                                                          loadout->class_id,
                                                                          loadout->loadout,
                                                                          loadout->prefabs,
                                                                          loadout->ugc_tools)) {
                    settings_warning = "SetClassLoadout referenced an unknown player";
                } else if (tutorial_session != nullptr) {
                    if (local_player_id == loadout->player_id) {
                        const auto* class_definition =
                            world::find_class_definition(loadout->class_id);
                        const auto spawn_tool =
                            class_definition != nullptr
                                ? world::preferred_spawn_tool(*class_definition, loadout->loadout)
                                : std::optional<std::uint8_t>{};
                        if (!tutorial_session->apply_server_selection(loadout->class_id,
                                                                      loadout->loadout,
                                                                      loadout->prefabs,
                                                                      loadout->ugc_tools,
                                                                      spawn_tool)) {
                            settings_warning = "server loadout could not replace local inventory";
                        }
                    }
                    if (!sync_roster_players()) {
                        settings_warning = "live loadout model refresh failed: " + settings_warning;
                    }
                }
            } else if (id == network::RestockPacket::id) {
                const auto decoded = network::decode_weapon_packet(packet);
                if (!decoded) {
                    settings_warning = decoded.error;
                    continue;
                }
                const auto* restock = std::get_if<network::RestockPacket>(&*decoded.packet);
                if (restock == nullptr) {
                    settings_warning = "Restock packet decoded to wrong variant";
                    continue;
                }
                if (tutorial_session != nullptr && local_player_id == restock->player_id) {
                    // Retail entity ids are also the Restock type values:
                    // 0=spawn/general, 3=ammo, 5=blocks, 6=jetpack.
                    // Health (4) is carried by SetHP and must not touch ammo.
                    if (restock->type == 0U) {
                        tutorial_session->restock_ammunition();
                        tutorial_session->restock_jetpack_fuel();
                    } else if (restock->type == 3U) {
                        tutorial_session->restock_from_ammo_crate();
                    } else if (restock->type == 5U) {
                        tutorial_session->restock_blocks();
                    } else if (restock->type == 6U) {
                        // Character.restock updates the resource immediately;
                        // the following WorldUpdate remains authoritative.
                        tutorial_session->restock_jetpack_fuel();
                        static_cast<void>(tutorial_roster.update_jetpack_fuel(
                            restock->player_id,
                            static_cast<float>(game_hud_assets::retail_jetpack_max_fuel)));
                    }
                }
            } else if (id == network::PickPickupPacket::id) {
                const auto decoded = network::decode_runtime_packet(packet);
                const auto* pickup =
                    decoded ? std::get_if<network::PickPickupPacket>(&*decoded.packet) : nullptr;
                if (pickup == nullptr) {
                    settings_warning = decoded.error;
                    continue;
                }
                if (tutorial_session != nullptr && local_player_id == pickup->player_id) {
                    tutorial_session->apply_server_pickup_burden(pickup->burdensome);
                }
                static_cast<void>(
                    tutorial_roster.update_pickup(pickup->player_id, pickup->pickup_id));
            } else if (id == network::DropPickupPacket::id) {
                const auto decoded = network::decode_tool_action_packet(packet);
                const auto* pickup =
                    decoded ? std::get_if<network::DropPickupPacket>(&*decoded.packet) : nullptr;
                if (pickup == nullptr) {
                    settings_warning = decoded.error;
                    continue;
                }
                if (tutorial_session != nullptr && local_player_id == pickup->player_id) {
                    tutorial_session->apply_server_pickup_burden(false);
                }
                // 0xff is the WorldUpdate sentinel for carrying nothing.
                static_cast<void>(tutorial_roster.update_pickup(pickup->player_id, 0xFFU));
            } else if (id == network::WeaponReloadPacket::id) {
                const auto decoded = network::decode_weapon_packet(packet);
                const auto* reload =
                    decoded ? std::get_if<network::WeaponReloadPacket>(&*decoded.packet) : nullptr;
                if (reload == nullptr) {
                    settings_warning = decoded.error;
                    continue;
                }
                // The owner already predicts both reload edges. Observers need
                // the server relay for the audible reload state.
                if (local_player_id != reload->player_id) {
                    const auto* player = tutorial_roster.player(reload->player_id);
                    if (audio_started && player != nullptr) {
                        const audio::SoundPosition position{static_cast<float>(player->position.x),
                                                            static_cast<float>(player->position.y),
                                                            static_cast<float>(player->position.z)};
                        const auto seed = static_cast<std::uint8_t>(latest_world_loop);
                        const auto* cosmetic=equipped_cosmetic(reload->player_id,"weapon:"+std::to_string(reload->tool_id)+":world");
                        if(cosmetic&&audio->play_cosmetic_cue(cosmetic->id,reload->is_done?"reload-done":"reload",seed,position))continue;
                        if (reload->is_done) {
                            audio->play_weapon_reload_done(reload->tool_id, seed, position, 1.0F);
                        } else {
                            audio->play_weapon_reload(reload->tool_id, seed, position, 1.0F);
                        }
                    }
                }
            } else if (id == network::BlockSuckerPacket::id) {
                const auto decoded = network::decode_tool_action_packet(packet);
                const auto* sucker =
                    decoded ? std::get_if<network::BlockSuckerPacket>(&*decoded.packet) : nullptr;
                if (sucker == nullptr) {
                    settings_warning = decoded.error;
                    continue;
                }
                if (local_player_id != sucker->shooter_id) {
                    if (auto rig = remote_player_rigs.find(sucker->shooter_id);
                        rig != remote_player_rigs.end()) {
                        rig->second.block_sucker_state = sucker->state;
                        rig->second.block_sucker_state_world_loop = sucker->loop_count;
                        if (sucker->shot) {
                            ++rig->second.action_serial;
                        }
                    }
                    const auto* player = tutorial_roster.player(sucker->shooter_id);
                    if (player != nullptr &&
                        sucker->shooter_id < remote_block_sucker_audio.size()) {
                        set_block_sucker_audio(remote_block_sucker_audio[sucker->shooter_id],
                                               sucker->state,
                                               remote_sound_position(*player),
                                               false);
                    }
                }
            } else if (id == network::PlaceUgcPacket::id) {
                const auto decoded = network::decode_tool_action_packet(packet);
                const auto* placement =
                    decoded ? std::get_if<network::PlaceUgcPacket>(&*decoded.packet) : nullptr;
                if (placement == nullptr) {
                    settings_warning = decoded.error;
                    continue;
                }
                const auto found = std::ranges::find_if(
                    server_ugc_items, [&](const network::InitialUgcItem& item) {
                        return item.position == placement->position &&
                               item.item_id == placement->ugc_item_id;
                    });
                if (placement->placing) {
                    constexpr std::size_t maximum_ugc_items{65'536U};
                    if (found == server_ugc_items.end() &&
                        server_ugc_items.size() < maximum_ugc_items) {
                        server_ugc_items.push_back({match_state_info.mode_type,
                                                    placement->position,
                                                    placement->ugc_item_id});
                    }
                } else if (found != server_ugc_items.end()) {
                    server_ugc_items.erase(found);
                }
                sync_ugc_item_presentations();
            } else if (id == network::PlayerLeftPacket::id) {
                const auto decoded = network::decode_runtime_packet(packet);
                const auto* left =
                    decoded ? std::get_if<network::PlayerLeftPacket>(&*decoded.packet) : nullptr;
                if (left == nullptr) {
                    settings_warning = decoded.error;
                    continue;
                }
                remote_cosmetics.erase(left->player_id);
                if (const auto* player = tutorial_roster.player(left->player_id);
                    player != nullptr) {
                    const auto position = remote_sound_position(*player);
                    stop_remote_fire_loop(left->player_id, position, false);
                    if (left->player_id < remote_block_sucker_audio.size()) {
                        set_block_sucker_audio(
                            remote_block_sucker_audio[left->player_id], 0U, position, false);
                        set_block_cannon_audio(remote_block_cannon_audio[left->player_id],
                                               std::nullopt,
                                               position,
                                               false);
                    }
                } else {
                    stop_remote_fire_loop(left->player_id, {}, false);
                    if (left->player_id < remote_block_sucker_audio.size()) {
                        set_block_sucker_audio(
                            remote_block_sucker_audio[left->player_id], 0U, {}, false);
                        set_block_cannon_audio(
                            remote_block_cannon_audio[left->player_id], std::nullopt, {}, false);
                    }
                }
                if (left->player_id < remote_character_audio.size()) {
                    stop_remote_jetpack_flight(left->player_id, {}, false);
                    remote_character_audio[left->player_id] = {};
                }
                tutorial_roster.remove(left->player_id);
                server_player_scores[left->player_id] = 0;
                server_player_score_valid[left->player_id] = false;
                if (tutorial_session != nullptr) {
                    static_cast<void>(sync_roster_players());
                }
            } else if (id == network::ClockSyncPacket::id ||
                       id == network::ChangeEntityPacket::id ||
                       id == network::HitEntityPacket::id ||
                       id == network::PrefabCompletePacket::id ||
                       id == network::ExplodeCorpsePacket::id ||
                       id == network::DestroyEntityPacket::id ||
                       id == network::ChangePlayerPacket::id ||
                       id == network::CreateEntityPacket::id ||
                       id == network::MinimapBillboardPacket::id ||
                       id == network::MinimapBillboardClearPacket::id ||
                       id == network::MinimapZonePacket::id ||
                       id == network::MinimapZoneClearPacket::id ||
                       id == network::LockToZonePacket::id ||
                       id == network::CreateAmbientSoundPacket::id ||
                       id == network::PlaySoundPacket::id ||
                       id == network::PlayAmbientSoundPacket::id ||
                       id == network::StopSoundPacket::id || id == network::PlayMusicPacket::id ||
                       id == network::StopMusicPacket::id ||
                       id == network::UgcObjectivesPacket::id ||
                       id == network::FogColorPacket::id ||
                       id == network::InitialUgcBatchPacket::id ||
                       id == network::UgcMapInfoPacket::id ||
                       id == network::HelpMessagePacket::id ||
                       id == network::SetGroundColorsPacket::id ||
                       id == network::LockTeamPacket::id ||
                       id == network::TeamLockClassPacket::id ||
                       id == network::TeamLockScorePacket::id ||
                       id == network::TeamInfiniteBlocksPacket::id ||
                       id == network::TeamMapVisibilityPacket::id ||
                       id == network::DisplayCountdownPacket::id ||
                       id == network::SetScorePacket::id || id == network::KillActionPacket::id ||
                       id == network::GenericVoteMessagePacket::id ||
                       id == network::ChatMessagePacket::id ||
                       id == network::LocalisedMessagePacket::id ||
                       id == network::MapEndedPacket::id ||
                       id == network::ShowGameStatsPacket::id || id == network::RankUpsPacket::id ||
                       id == network::GameStatsPacket::id ||
                       id == network::ForceShowScoresPacket::id ||
                       id == network::ShowTextMessagePacket::id ||
                       id == network::TeamProgressPacket::id ||
                       id == network::TerritoryBaseStatePacket::id) {
                // These packets now cross a strict framing/type boundary even
                // where their presentation service is still being ported. A
                // malformed server packet must never silently desynchronise
                // the following gameplay state.
                const auto decoded = network::decode_runtime_packet(packet);
                if (!decoded) {
                    settings_warning = decoded.error;
                    continue;
                }
                if (const auto* clock = std::get_if<network::ClockSyncPacket>(&*decoded.packet);
                    clock != nullptr) {
                    if (clock->server_loop_count < 0 ||
                        clock->server_loop_count > std::numeric_limits<std::int32_t>::max() - 600) {
                        settings_warning = "ClockSync returned an invalid server loop";
                        continue;
                    }
                    // Never reuse a ClientData label: the server drops a
                    // repeated/older label as stale. A fresh server anchor may
                    // advance this timeline, but cannot rewind already-sent
                    // prediction history.
                    client_loop_count = std::max(client_loop_count, clock->server_loop_count);
                } else if (const auto* movement_lock =
                               std::get_if<network::LockToZonePacket>(&*decoded.packet);
                           movement_lock != nullptr) {
                    if (tutorial_session != nullptr &&
                        !tutorial_session->set_server_movement_bounds({
                            {static_cast<double>(movement_lock->minimum[0U]),
                             static_cast<double>(movement_lock->minimum[1U]),
                             static_cast<double>(movement_lock->minimum[2U])},
                            {static_cast<double>(movement_lock->maximum[0U]),
                             static_cast<double>(movement_lock->maximum[1U]),
                             static_cast<double>(movement_lock->maximum[2U])}})) {
                        settings_warning =
                            "LockToZone contained invalid movement bounds";
                    }
                } else if (const auto* ambient =
                               std::get_if<network::CreateAmbientSoundPacket>(&*decoded.packet);
                           ambient != nullptr) {
                    ServerAmbientDefinition definition;
                    definition.name = ambient->name;
                    definition.points.reserve(ambient->points.size());
                    for (const auto& point : ambient->points) {
                        // Retail GameSound centres voxel-space sources.
                        definition.points.push_back({static_cast<float>(point[0U]) + 0.5F,
                                                     static_cast<float>(point[1U]) + 0.5F,
                                                     static_cast<float>(point[2U]) + 0.5F});
                    }
                    server_ambient_sounds[ambient->loop_id] = std::move(definition);
                    server_ambience_received = true;
                    // Packet 22 announces the exact asset before packet 24
                    // starts it. Decode/upload while the loading gate is
                    // normally still visible so the first playable frame
                    // never performs cold Vorbis work.
                    if (audio_started && !audio->preload_named_ambience_async(ambient->name)) {
                        settings_warning = std::string{audio->last_error()};
                    }
                } else if (const auto* sound =
                               std::get_if<network::PlaySoundPacket>(&*decoded.packet);
                           sound != nullptr) {
                    play_server_sound(*sound);
                } else if (const auto* ambient_play =
                               std::get_if<network::PlayAmbientSoundPacket>(&*decoded.packet);
                           ambient_play != nullptr) {
                    play_server_ambient(*ambient_play);
                } else if (const auto* stop =
                               std::get_if<network::StopSoundPacket>(&*decoded.packet);
                           stop != nullptr) {
                    if (audio_started) {
                        audio->stop_named_loop(stop->loop_id);
                    }
                } else if (const auto* music =
                               std::get_if<network::PlayMusicPacket>(&*decoded.packet);
                           music != nullptr) {
                    server_music_received = true;
                    if (audio_started &&
                        !audio->play_named_music(music->name, music->seconds_played)) {
                        settings_warning = std::string{audio->last_error()};
                    }
                } else if (std::holds_alternative<network::StopMusicPacket>(*decoded.packet)) {
                    server_music_received = true;
                    if (audio_started) {
                        audio->stop_menu_music();
                    }
                } else if (const auto* entity_change =
                               std::get_if<network::ChangeEntityPacket>(&*decoded.packet);
                           entity_change != nullptr) {
                    if (tutorial_session == nullptr)
                        continue;
                    world::ServerEntityMutation mutation;
                    mutation.entity_id = entity_change->entity_id;
                    switch (entity_change->action) {
                    case network::ChangeEntityPacket::set_state:
                        mutation.property = world::ServerEntityProperty::state;
                        mutation.integer = entity_change->state;
                        break;
                    case network::ChangeEntityPacket::set_position:
                        mutation.property = world::ServerEntityProperty::position;
                        mutation.vector = {entity_change->position[0U],
                                           entity_change->position[1U],
                                           entity_change->position[2U]};
                        break;
                    case network::ChangeEntityPacket::set_velocity:
                        mutation.property = world::ServerEntityProperty::velocity;
                        mutation.vector = {entity_change->velocity[0U],
                                           entity_change->velocity[1U],
                                           entity_change->velocity[2U]};
                        break;
                    case network::ChangeEntityPacket::set_player:
                        mutation.property = world::ServerEntityProperty::owner;
                        mutation.integer = entity_change->player_id;
                        break;
                    case network::ChangeEntityPacket::set_forward_vector:
                        mutation.property = world::ServerEntityProperty::forward;
                        mutation.vector = {entity_change->forward[0U],
                                           entity_change->forward[1U],
                                           entity_change->forward[2U]};
                        break;
                    case network::ChangeEntityPacket::set_target:
                        mutation.property = world::ServerEntityProperty::target;
                        mutation.integer = entity_change->target_id;
                        break;
                    case network::ChangeEntityPacket::set_fuse:
                        mutation.property = world::ServerEntityProperty::fuse;
                        mutation.scalar = entity_change->fuse;
                        break;
                    case network::ChangeEntityPacket::set_ammo:
                        mutation.property = world::ServerEntityProperty::ammo;
                        mutation.scalar = entity_change->ammo;
                        break;
                    default:
                        settings_warning = "ChangeEntity carried an unsupported action";
                        continue;
                    }
                    if (!tutorial_session->apply_server_entity_update(mutation)) {
                        settings_warning = "ChangeEntity referenced an unknown or invalid entity";
                    }
                } else if (const auto* entity_hit =
                               std::get_if<network::HitEntityPacket>(&*decoded.packet);
                           entity_hit != nullptr) {
                    if (tutorial_session == nullptr)
                        continue;
                    const auto entities = tutorial_session->entities();
                    if (std::ranges::find(entities,
                                          entity_hit->entity_id,
                                          &world::LocalEntity::id) == entities.end()) {
                        settings_warning = "HitEntity referenced an unknown entity";
                        continue;
                    }
                    world::emit_entity_hit(particles,
                                           entity_hit->position,
                                           static_cast<std::uint32_t>(entity_hit->entity_id) ^
                                               static_cast<std::uint32_t>(latest_world_loop));
                } else if (std::holds_alternative<network::PrefabCompletePacket>(*decoded.packet)) {
                    const auto result = complete_live_prefab(true);
                    if (!result.recognized || !result.error.empty()) {
                        settings_warning = result.error;
                        continue;
                    }
                    if (live_terrain_replica != nullptr) {
                        queue_live_chunk_remeshes(live_terrain_replica->take_dirty_chunks());
                    }
                    preview_prefab_meshes_uploaded = false;
                } else if (const auto* corpse =
                               std::get_if<network::ExplodeCorpsePacket>(&*decoded.packet);
                           corpse != nullptr) {
                    if (corpse->player_id >= retained_corpse_positions.size()) {
                        settings_warning = "ExplodeCorpse player id exceeds the retail roster";
                        continue;
                    }
                    const auto* victim = tutorial_roster.player(corpse->player_id);
                    const auto jetpack_corpse = jetpack_deaths.finish(corpse->player_id);
                    const auto retained = retained_corpse_positions[corpse->player_id];
                    const auto last_known = last_known_player_positions[corpse->player_id];
                    if (victim == nullptr && !jetpack_corpse.has_value() &&
                        !retained.has_value() && !last_known.has_value()) {
                        settings_warning = "ExplodeCorpse referenced an unknown player";
                        continue;
                    }
                    if (!corpse->show_explosion_effect) {
                        // The boolean suppresses particles only. Retail still
                        // marks Character.exploded and hands the dead life to
                        // DeathController; an immediately following
                        // CreatePlayer then clears a pre-respawn cleanup.
                        finish_local_jetpack_death(jetpack_corpse);
                        retained_corpse_positions[corpse->player_id].reset();
                        continue;
                    }
                    const auto position = jetpack_corpse.has_value()
                                              ? jetpack_corpse->position
                                          : retained.has_value()
                                              ? *retained
                                              : victim != nullptr ? victim->position : *last_known;
                    const auto impact = make_corpse_explosion_impact(
                        *corpse,
                        {static_cast<float>(position.x), static_cast<float>(position.y),
                         static_cast<float>(position.z)},
                        victim != nullptr ? remote_team_color(victim->team)
                                          : world::VxlColor{104U, 94U, 88U, 255U});
                    if (impact.has_value()) {
                        if (jetpack_corpse.has_value() && audio_started) {
                            const audio::SoundPosition sound_position{
                                static_cast<float>(position.x),
                                static_cast<float>(position.y),
                                static_cast<float>(position.z)};
                            const bool local = local_player_id == corpse->player_id;
                            const bool submerged =
                                sound_position.z >=
                                static_cast<float>(world::VxlMap::height) - 2.0F;
                            static_cast<void>(audio->play_named_one_shot(
                                submerged ? "JP_death_explode_water" : "JP_death_explode",
                                sound_position,
                                1.0F,
                                local));
                        }
                        terrain_effects.spawn_impact(
                            *impact,
                            jetpack_corpse.has_value()
                                ? world::TerrainImpactSoundPolicy::silent
                                : world::TerrainImpactSoundPolicy::full);
                        if (jetpack_corpse.has_value()) {
                            terrain_effects.spawn_impact(
                                make_jetpack_death_airburst(
                                    {static_cast<float>(position.x),
                                     static_cast<float>(position.y),
                                     static_cast<float>(position.z)}),
                                world::TerrainImpactSoundPolicy::silent);
                        }
                    }
                    finish_local_jetpack_death(jetpack_corpse);
                    retained_corpse_positions[corpse->player_id].reset();
                } else if (const auto* changed =
                               std::get_if<network::ChangePlayerPacket>(&*decoded.packet);
                           changed != nullptr) {
                    const auto high =
                        changed->type == network::ChangePlayerPacket::set_high_minimap_visibility
                            ? std::optional<bool>{changed->high_minimap_visibility}
                            : std::nullopt;
                    const auto chase = changed->type == network::ChangePlayerPacket::set_chase_cam
                                           ? std::optional<bool>{changed->chase_cam}
                                           : std::nullopt;
                    if ((high.has_value() || chase.has_value()) &&
                        !tutorial_roster.update_mode_visibility(changed->player_id, high, chase)) {
                        settings_warning =
                            "ChangePlayer referenced a player absent from the roster";
                    }
                } else if (const auto* created =
                               std::get_if<network::CreateEntityPacket>(&*decoded.packet);
                           created != nullptr) {
                    if (tutorial_session == nullptr) {
                        continue;
                    }
                    world::LocalEntity entity;
                    entity.id = created->entity_id;
                    entity.type = created->type;
                    entity.position = {
                        created->position[0U], created->position[1U], created->position[2U]};
                    entity.velocity = {
                        created->velocity[0U], created->velocity[1U], created->velocity[2U]};
                    entity.yaw = created->yaw;
                    entity.aim_yaw = created->yaw;
                    entity.team = created->state;
                    entity.owner = created->player_id;
                    entity.local_launcher_muzzle = local_player_id == entity.owner &&
                        launcher_muzzle_tracker.consume(entity, std::chrono::steady_clock::now());
                    entity.face = created->face;
                    entity.fuse = created->fuse;
                    const auto channel = [](float value) {
                        return static_cast<std::uint8_t>(std::clamp(std::lround(value), 0L, 255L));
                    };
                    entity.color = {channel(created->color[0U]),
                                    channel(created->color[1U]),
                                    channel(created->color[2U])};
                    entity.has_color = created->has_explicit_color();
                    if (!tutorial_session->apply_server_entity(entity)) {
                        settings_warning =
                            "CreateEntity rejected invalid type, face, or entity budget";
                    } else if (entity.type == 11U && local_player_id == entity.owner &&
                               death_camera.active()) {
                        death_camera.bind_grave(entity.id, entity.position);
                    }
                } else if (const auto* destroyed =
                               std::get_if<network::DestroyEntityPacket>(&*decoded.packet);
                           destroyed != nullptr) {
                    if (tutorial_session != nullptr) {
                        const auto entity = std::ranges::find(
                            tutorial_session->entities(), destroyed->entity_id,
                            &world::LocalEntity::id);
                        if (entity != tutorial_session->entities().end() &&
                            entity->type >= 3U && entity->type <= 6U) {
                            // Crate.delete owns this presentation in retail.
                            // DestroyEntity is the only authoritative edge
                            // carrying both a retained position and proof that
                            // the pickup disappeared; Restock has no entity id.
                            world::emit_crate_pickup(
                                particles,
                                {static_cast<float>(entity->position.x),
                                 static_cast<float>(entity->position.y),
                                 static_cast<float>(entity->position.z)},
                                static_cast<std::uint32_t>(destroyed->entity_id) ^
                                    0xC8A7E168U);
                        }
                        static_cast<void>(
                            tutorial_session->destroy_server_entity(destroyed->entity_id));
                    }
                } else if (const auto* objectives =
                               std::get_if<network::UgcObjectivesPacket>(&*decoded.packet);
                           objectives != nullptr) {
                    server_ugc_objectives = *objectives;
                    if (ugc_loadout_active) {
                        ugc_loadout_menu.set_objectives(
                            ugc_loadout_objectives());
                    }
                } else if (const auto* edit_mode =
                               std::get_if<network::SetUgcEditModePacket>(&*decoded.packet);
                           edit_mode != nullptr) {
                    match_initial_info.ugc_mode = edit_mode->mode;
                } else if (const auto* loading =
                               std::get_if<network::UgcMapLoadingFromHostPacket>(&*decoded.packet);
                           loading != nullptr) {
                    if (screen() == FrontendScreen::game_loading) {
                        match_loading.map_progress(static_cast<double>(loading->percent) / 100.0);
                    }
                } else if (const auto* ugc_control =
                               std::get_if<network::UgcMessagePacket>(&*decoded.packet);
                           ugc_control != nullptr) {
                    if (ugc_control->message == network::UgcMessageCode::convert_to_game) {
                        // Conversion is server-owned. Refresh validation and
                        // object state instead of changing scenes locally.
                        ugc_initial_requests_sent = false;
                    }
                } else if (const auto* fog = std::get_if<network::FogColorPacket>(&*decoded.packet);
                           fog != nullptr) {
                    // Packet 74 is an explicit live/admin override and must
                    // win over even a locally authored official atmosphere.
                    match_state_info.fog_color = fog->color;
                    world_renderer.set_fog_color(fog->color);
                } else if (const auto* batch =
                               std::get_if<network::InitialUgcBatchPacket>(&*decoded.packet);
                           batch != nullptr) {
                    constexpr std::size_t maximum_ugc_items{65'536U};
                    for (const auto& item : batch->items) {
                        const auto duplicate = std::ranges::find_if(
                            server_ugc_items, [&](const network::InitialUgcItem& retained) {
                                return retained.mode == item.mode &&
                                       retained.position == item.position &&
                                       retained.item_id == item.item_id;
                            });
                        if (duplicate != server_ugc_items.end()) {
                            continue;
                        }
                        if (server_ugc_items.size() >= maximum_ugc_items) {
                            settings_warning =
                                "InitialUGCBatch exceeded the retained item budget";
                            break;
                        }
                        server_ugc_items.push_back(item);
                    }
                    sync_ugc_item_presentations();
                } else if (const auto* map_info =
                               std::get_if<network::UgcMapInfoPacket>(&*decoded.packet);
                           map_info != nullptr) {
                    server_ugc_preview_png = map_info->png_data;
                } else if (const auto* help =
                               std::get_if<network::HelpMessagePacket>(&*decoded.packet);
                           help != nullptr) {
                    const auto names = control_key_names();
                    std::vector<std::string> lines;
                    lines.reserve(help->message_ids.size());
                    for (const auto& key : help->message_ids) {
                        lines.push_back(resolve_control_placeholders(tutorial_string(key), names));
                    }
                    game_hud.set_help_messages(std::move(lines),
                                               resolve_control_placeholders(
                                                   tutorial_string("TOOL_HELP_PANEL_CLOSE"), names),
                                               help->delay);
                } else if (const auto* ground =
                               std::get_if<network::SetGroundColorsPacket>(&*decoded.packet);
                           ground != nullptr) {
                    server_ground_colors = ground->colors;
                    queue_all_live_chunks();
                } else if (const auto* billboard =
                               std::get_if<network::MinimapBillboardPacket>(&*decoded.packet);
                           billboard != nullptr) {
                    // The retail packet addresses billboards by entity_id.
                    // Bound retained mode state even if a hostile endpoint
                    // sends unique ids forever.
                    constexpr std::size_t maximum_billboards{128U};
                    if (server_minimap_billboards.contains(billboard->entity_id) ||
                        server_minimap_billboards.size() < maximum_billboards) {
                        server_minimap_billboards[billboard->entity_id] = *billboard;
                    }
                } else if (const auto* billboard_clear =
                               std::get_if<network::MinimapBillboardClearPacket>(&*decoded.packet);
                           billboard_clear != nullptr) {
                    server_minimap_billboards.erase(billboard_clear->entity_id);
                } else if (const auto* zone =
                               std::get_if<network::MinimapZonePacket>(&*decoded.packet);
                           zone != nullptr) {
                    const std::array<std::int16_t, 6U> key{zone->minimum[0U],
                                                           zone->minimum[1U],
                                                           zone->minimum[2U],
                                                           zone->maximum[0U],
                                                           zone->maximum[1U],
                                                           zone->maximum[2U]};
                    constexpr std::size_t maximum_zones{64U};
                    if (server_minimap_zones.contains(key) ||
                        server_minimap_zones.size() < maximum_zones) {
                        server_minimap_zones[key] = *zone;
                    }
                } else if (const auto* zone_clear =
                               std::get_if<network::MinimapZoneClearPacket>(&*decoded.packet);
                           zone_clear != nullptr) {
                    const std::array<std::int16_t, 6U> key{zone_clear->minimum[0U],
                                                           zone_clear->minimum[1U],
                                                           zone_clear->minimum[2U],
                                                           zone_clear->maximum[0U],
                                                           zone_clear->maximum[1U],
                                                           zone_clear->maximum[2U]};
                    server_minimap_zones.erase(key);
                } else if (const auto* visibility =
                               std::get_if<network::TeamMapVisibilityPacket>(&*decoded.packet);
                           visibility != nullptr) {
                    server_team_map_visibility[visibility->team_id] = visibility->visible;
                } else if (const auto* lock =
                               std::get_if<network::LockTeamPacket>(&*decoded.packet);
                           lock != nullptr) {
                    if (lock->team_id == 2U) match_state_info.team1_locked = lock->locked;
                    if (lock->team_id == 3U) match_state_info.team2_locked = lock->locked;
                    if (lock->team_id == 0U) spectator_team_locked = lock->locked;
                    refresh_pause_menu();
                } else if (const auto* lock_class =
                               std::get_if<network::TeamLockClassPacket>(&*decoded.packet);
                           lock_class != nullptr) {
                    if (lock_class->team_id == 2U) {
                        match_state_info.team1_locked_class = lock_class->locked;
                    } else {
                        match_state_info.team2_locked_class = lock_class->locked;
                    }
                    refresh_pause_menu();
                } else if (const auto* lock_score =
                               std::get_if<network::TeamLockScorePacket>(&*decoded.packet);
                           lock_score != nullptr) {
                    if (lock_score->team_id == 2U) {
                        match_state_info.team1_locked_score = lock_score->locked;
                    } else {
                        match_state_info.team2_locked_score = lock_score->locked;
                    }
                } else if (const auto* infinite =
                               std::get_if<network::TeamInfiniteBlocksPacket>(&*decoded.packet);
                           infinite != nullptr) {
                    if (infinite->team_id == 2U) {
                        match_state_info.team1_infinite_blocks = infinite->infinite;
                    } else {
                        match_state_info.team2_infinite_blocks = infinite->infinite;
                    }
                } else if (const auto* progress =
                               std::get_if<network::TeamProgressPacket>(&*decoded.packet);
                           progress != nullptr) {
                    std::optional<hud_layout::Team> team;
                    switch (progress->team_id) {
                    case 1U:
                        team = hud_layout::Team::neutral;
                        break;
                    case 2U:
                        team = hud_layout::Team::team1;
                        break;
                    case 3U:
                        team = hud_layout::Team::team2;
                        break;
                    default:
                        break;
                    }
                    if (team.has_value()) {
                        // The retail TeamProgressBar owns retained state:
                        // maximum/show mode are shared across all three rows,
                        // zero resets a row to maximum, and unknown icon ids
                        // retain the prior icon. Adapt the stock packet here;
                        // never require a server-side compatibility change.
                        game_hud.update_team_progress(GameHudTeamProgressUpdate{
                            *team,
                            progress->visible,
                            progress->show_particle,
                            progress->show_previous,
                            progress->show_as_percent,
                            progress->show_as_percent ? static_cast<double>(progress->percent)
                                                      : static_cast<double>(progress->numerator),
                            progress->show_as_percent ? 100.0
                                                      : static_cast<double>(progress->denominator),
                            team_progress_icon_from_wire(progress->icon_id)});
                    }
                } else if (const auto* territory =
                               std::get_if<network::TerritoryBaseStatePacket>(&*decoded.packet);
                           territory != nullptr) {
                    const auto team_from_wire =
                        [](std::uint8_t team_id) -> std::optional<hud_layout::Team> {
                        switch (team_id) {
                        case 0U:
                            return hud_layout::Team::spectator;
                        case 1U:
                            return hud_layout::Team::neutral;
                        case 2U:
                            return hud_layout::Team::team1;
                        case 3U:
                            return hud_layout::Team::team2;
                        default:
                            return std::nullopt;
                        }
                    };
                    const auto controlled = team_from_wire(territory->controlled_by);
                    const auto attacked = team_from_wire(territory->attacked_by);
                    if (controlled.has_value() && attacked.has_value()) {
                        // Map stock packet 106 into the retail-owned HUD
                        // state. The server protocol remains untouched.
                        game_hud.update_territory_base(GameHudTerritoryBaseUpdate{
                            territory->base_index,
                            static_cast<GameHudTerritoryBaseAction>(territory->action),
                            *controlled,
                            *attacked,
                            territory->capture_amount});
                    }
                } else if (const auto* countdown =
                               std::get_if<network::DisplayCountdownPacket>(&*decoded.packet);
                           countdown != nullptr) {
                    // shared.constants_gamemode.MODE_TUTORIAL is ordinal 10.
                    // Its draw_timer caller owns both the corner placement and
                    // the frame; ordinary modes keep the HeadCount placement.
                    constexpr std::uint8_t tutorial_mode_key{10U};
                    const bool tutorial =
                        match_initial_info.mode_key == tutorial_mode_key;
                    game_hud.set_match_clock(
                        countdown->timer, true,
                        tutorial ? hud_layout::TimerPlacement::tutorial_corner
                                 : hud_layout::TimerPlacement::head_count,
                        match_initial_info.enable_minimap);
                } else if (const auto* score =
                               std::get_if<network::SetScorePacket>(&*decoded.packet);
                           score != nullptr) {
                    // SCORE.TEAM=0 uses wire team ids 2/3. SCORE.PLAYER=1
                    // names one roster id. The reason byte drives a separate
                    // score-reason feed and must not alter the value here.
                    if (score->type == 0U) {
                        if (score->specifier == 2U) {
                            match_state_info.team1_score = score->value;
                        } else if (score->specifier == 3U) {
                            match_state_info.team2_score = score->value;
                        }
                        // Same-map BattleSpades rounds intentionally have no
                        // terminal packet 53/52.  The paired authoritative
                        // zero scores are their only safe round boundary; let
                        // the result model discard an unshown packet-67 batch.
                        match_results.observe_team_score(score->specifier,
                                                         score->value);
                    } else if (score->specifier < server_player_scores.size()) {
                        const bool had_previous =
                            server_player_score_valid[score->specifier];
                        const auto previous =
                            server_player_scores[score->specifier];
                        server_player_scores[score->specifier] = score->value;
                        server_player_score_valid[score->specifier] = true;
                        if (local_player_id == score->specifier) {
                            game_hud.set_player_score(
                                score->value, game_hud.player_score_visible());
                            // SetScore carries the new authoritative total,
                            // not the increment. Suppress the initial roster
                            // baseline and derive only subsequent local deltas
                            // for HUD.add_score_reason parity.
                            if (had_previous) {
                                const auto delta64 =
                                    static_cast<std::int64_t>(score->value) - previous;
                                const auto delta = static_cast<std::int32_t>(std::clamp(
                                    delta64,
                                    static_cast<std::int64_t>(
                                        std::numeric_limits<std::int32_t>::min()),
                                    static_cast<std::int64_t>(
                                        std::numeric_limits<std::int32_t>::max())));
                                game_hud.add_score_award(delta, score->reason);
                            }
                        }
                    }
                } else if (const auto* kill =
                               std::get_if<network::KillActionPacket>(&*decoded.packet);
                           kill != nullptr) {
                    if (local_player_id.has_value()) {
                        const bool team_change_kill =
                            kill->kill_type == retail::FORCED_TEAM_CHANGE_KILL ||
                            kill->kill_type == retail::TEAM_CHANGE_KILL;
                        static_cast<void>(tutorial_roster.apply_kill_relationships(
                            kill->player_id, kill->killer_id,
                            *local_player_id, kill->domination,
                            kill->revenge, team_change_kill));
                    }
                    const auto* victim = tutorial_roster.player(kill->player_id);
                    const auto* killer = tutorial_roster.player(kill->killer_id);
                    const auto last_known =
                        kill->player_id < last_known_player_positions.size()
                            ? last_known_player_positions[kill->player_id]
                            : std::nullopt;
                    if (victim == nullptr && !last_known.has_value()) {
                        settings_warning = "KillAction referenced a player absent from the roster";
                        continue;
                    }
                    if (kill->player_id >= retained_corpse_positions.size()) {
                        settings_warning = "KillAction player id exceeds the retail roster";
                        continue;
                    }
                    retained_corpse_positions[kill->player_id] =
                        victim != nullptr ? victim->position : *last_known;
                    if (victim == nullptr) {
                        // The packet-36 visual is still recoverable, while the
                        // feed cannot be authored without roster name/team.
                        continue;
                    }
                    const auto victim_position = remote_sound_position(*victim);
                    announce_remote_character_death(*victim);
                    const auto jetpack =
                        world::retail_jetpack_id(victim->loadout, victim->ugc_tools);
                    const bool jetpack_corpse =
                        jetpack.has_value() &&
                        jetpack_deaths.begin(victim->player_id,
                                             victim->generation,
                                             *jetpack,
                                             victim->position);
                    if (jetpack_corpse && audio_started) {
                        // Character.set_dead starts the authored one-second
                        // flight cue; packet 36 owns the separate blast cue.
                        static_cast<void>(audio->play_named_one_shot(
                            "JP_death_fly",
                            victim_position,
                            1.0F,
                            local_player_id == victim->player_id));
                    }
                    // Retail keeps death state and corpse VFX on different
                    // packets. KillAction drives the roster/death UI only;
                    // ExplodeCorpse later calls Player.explode_corpse(flag).
                    // Emitting here duplicates the separate 40-piece bright-red
                    // corpse burst and makes a death unlike the preserved client.
                    stop_remote_fire_loop(kill->player_id, victim_position, false);
                    set_block_sucker_audio(
                        remote_block_sucker_audio[kill->player_id], 0U, victim_position, false);
                    set_block_cannon_audio(remote_block_cannon_audio[kill->player_id],
                                           std::nullopt,
                                           victim_position,
                                           false);
                    static_cast<void>(tutorial_roster.update_health(kill->player_id, 0));
                    const auto feed_color = [this](const network::RemotePlayerReplica& player) {
                        if (local_player_id == player.player_id) {
                            return ui::ColorRgba8{255U, 255U, 255U, 255U};
                        }
                        const auto value = remote_team_color(player.team);
                        return ui::ColorRgba8{value.red, value.green, value.blue, value.alpha};
                    };
                    std::optional<std::string> killer_name;
                    ui::ColorRgba8 killer_color{};
                    if (killer != nullptr && killer->player_id != victim->player_id) {
                        killer_name = killer->name;
                        killer_color = feed_color(*killer);
                    }
                    game_hud.add_kill(std::move(killer_name),
                                      killer_color,
                                      kill_icon_asset(kill->kill_type,
                                                      killer,
                                                      remembered_combat_tool(killer)),
                                      kill->kill_type == 26U ? 256.0 : 330.0,
                                      victim->name,
                                      feed_color(*victim));
                    if (local_player_id == kill->player_id && local_spawn_confirmed) {
                        begin_local_death(kill->killer_id);
                        game_hud.set_respawn_time(kill->respawn_time);
                    }
                } else if (const auto* vote =
                               std::get_if<network::GenericVoteMessagePacket>(&*decoded.packet);
                           vote != nullptr) {
                    generic_vote.apply(*vote);
                } else if (const auto* message =
                               std::get_if<network::ChatMessagePacket>(&*decoded.packet);
                           message != nullptr) {
                    if (message->chat_type == chat_big_type) {
                        game_hud.set_big_message(message->value);
                    } else {
                        if (const auto* sender = tutorial_roster.player(message->player_id);
                            sender != nullptr) {
                            const auto color = remote_team_color(sender->team);
                            game_chat.add_player_message(
                                sender->name,
                                {color.red, color.green, color.blue, color.alpha},
                                message->value,
                                message->chat_type ==
                                    static_cast<std::uint8_t>(ChatChannel::team),
                                sender->local_language);
                        } else if (message->chat_type == 2U) {
                            game_chat.add(message->value,
                                          {244U, 236U, 187U, 255U});
                        } else {
                            game_chat.add(message->value);
                        }
                        if (audio_started) {
                            static_cast<void>(audio->play_named_one_shot("chat", {}, 0.70F, true));
                        }
                    }
                } else if (const auto* localized_message =
                               std::get_if<network::LocalisedMessagePacket>(&*decoded.packet);
                           localized_message != nullptr) {
                    if (localized_message->chat_type == chat_big_type) {
                        game_hud.set_big_message(
                            format_runtime_message(
                                localized_text(localized_message->string_id),
                                localized_message->parameters,
                                localized_message->localise_parameters,
                                [this](std::string_view key) { return localized_text(key); }),
                            localized_message->override_previous_message);
                    } else {
                        game_chat.add(
                            format_runtime_message(
                                localized_text(localized_message->string_id),
                                localized_message->parameters,
                                localized_message->localise_parameters,
                                [this](std::string_view key) { return localized_text(key); }),
                            {244U, 236U, 187U, 255U});
                        if (audio_started) {
                            static_cast<void>(audio->play_named_one_shot("chat", {}, 0.70F, true));
                        }
                    }
                } else if (std::holds_alternative<network::MapEndedPacket>(*decoded.packet)) {
                    // The retail GameScene only freezes here. Steam's lobby
                    // layer reconnects after ENet closes for the next map; our
                    // standalone browser must retain and reuse the endpoint.
                    match_state_info.has_map_ended = true;
                    map_transition_armed = true;
                    // Keep ViewGameStats intact until teardown_tutorial()
                    // retires the old scene. Clearing on packet 52 made the
                    // live leaderboard disappear during the server's
                    // disconnect/reconnect gap even though the isolated UI
                    // fixture rendered correctly.
                    apply_map_ended_overlay_boundary(
                        match_results, game_chat, generic_vote,
                        match_result_winner_from_scores(team_roster_state(false)));
                    play_match_result_audio_if_ready();
                    match_result_camera_timer = 0.0;
                    match_result_camera_index = 0U;
                    scoreboard_forced = false;
                    static_cast<void>(window.set_text_input_enabled(false));
                } else if (std::holds_alternative<network::ShowGameStatsPacket>(*decoded.packet)) {
                    match_results.show(match_result_winner_from_scores(
                        team_roster_state(false)));
                    match_result_camera_timer = 0.0;
                    match_result_camera_index = 0U;
                    play_match_result_audio_if_ready();
                } else if (const auto* rank_ups =
                               std::get_if<network::RankUpsPacket>(&*decoded.packet);
                           rank_ups != nullptr) {
                    match_results.apply(*rank_ups);
                } else if (const auto* statistics =
                               std::get_if<network::GameStatsPacket>(&*decoded.packet);
                           statistics != nullptr) {
                    match_results.apply(*statistics);
                    play_match_result_audio_if_ready();
                } else if (const auto* forced_scores =
                               std::get_if<network::ForceShowScoresPacket>(
                                   &*decoded.packet);
                           forced_scores != nullptr) {
                    scoreboard_forced = forced_scores->forced;
                } else if (const auto* result_message =
                               std::get_if<network::ShowTextMessagePacket>(
                                   &*decoded.packet);
                           result_message != nullptr) {
                    match_results.apply(*result_message);
                }
            } else if (id == 45U) {
                std::string error;
                auto state = network::decode_protocol168_state_info(packet, error);
                if (!state.has_value()) {
                    settings_warning = error;
                } else {
                    match_state_info = std::move(*state);
                    const auto result_camera_count = std::min(
                        match_state_info.screenshot_camera_points.size(),
                        match_state_info.screenshot_camera_rotations.size());
                    if (result_camera_count == 0U) {
                        match_result_camera_index = 0U;
                        match_result_camera_timer = 0.0;
                    } else {
                        match_result_camera_index %= result_camera_count;
                    }
                    // Some official rotations announce the ended round only
                    // through the StateData tail before closing ENet. Treat
                    // that retail flag exactly like MapEnded(52), but never
                    // disarm an already observed packet on a later stale
                    // state refresh.
                    map_transition_armed = map_transition_armed || match_state_info.has_map_ended;
                    if (match_state_info.has_map_ended) {
                        apply_map_ended_overlay_boundary(
                            match_results, game_chat, generic_vote,
                            match_result_winner_from_scores(team_roster_state(false)));
                        play_match_result_audio_if_ready();
                        static_cast<void>(window.set_text_input_enabled(false));
                    }
                    // Official-map fog is part of the locally measured
                    // atmosphere. Unknown and UGC maps remain server-authored.
                    if (!live_official_environment.has_value()) {
                        world_renderer.set_fog_color(match_state_info.fog_color);
                    }
                    // StateData can update mid-match; lighting is independent
                    // from the already-resident skydome and must not reload its
                    // textures on an otherwise small state refresh.
                    apply_retail_state_lighting();
                    refresh_pause_menu();
                    if (tutorial_session != nullptr) {
                        static_cast<void>(sync_roster_players());
                        if (local_player_id.has_value()) {
                            if (const auto* local = tutorial_roster.player(*local_player_id);
                                local != nullptr) {
                                uploaded_sandbox_tool.reset();
                                static_cast<void>(load_tutorial_class_arms(local->class_id));
                            }
                        }
                    }
                }
            } else if (id == 51U) {
                std::string error;
                const auto skybox = network::decode_protocol168_skybox_info(packet, error);
                if (!skybox.has_value()) {
                    settings_warning = std::move(error);
                } else if (!apply_live_map_environment(skybox->definition_name)) {
                    settings_warning = "live map environment update failed: " +
                                       std::string{world_renderer.last_error()};
                } else {
                    live_skydome_name = skybox->definition_name;
                }
            } else if (id == 115U && packet.size() >= 3U) {
                forced_team = std::to_integer<std::uint8_t>(packet[1U]);
                core::diagnostic("join", "ForceTeamJoin team=" + std::to_string(*forced_team) +
                    " team1_classes=" + std::to_string(match_state_info.team1_classes.size()) +
                    " team2_classes=" + std::to_string(match_state_info.team2_classes.size()));
                refresh_pause_menu();
                if (tutorial_session != nullptr && screen() == FrontendScreen::tutorial_world) {
                    send_client_in_menu(true);
                    static_cast<void>(navigation.push(FrontendScreen::change_team));
                }
            }
        }
    }

    [[nodiscard]] std::optional<DeathCameraTarget>
    death_camera_target(std::uint8_t player_id) const {
        const auto* replica = tutorial_roster.player(player_id);
        if (replica == nullptr || replica->dead || replica->health <= 0 ||
            local_player_id == player_id) {
            return std::nullopt;
        }
        auto position = replica->position;
        auto orientation = replica->orientation;
        if (const auto rig = remote_player_rigs.find(player_id); rig != remote_player_rigs.end()) {
            const auto& sample = rig->second.motion.sample();
            position = sample.position;
            orientation = sample.orientation;
        }
        return DeathCameraTarget{player_id, position, orientation};
    }

    /**
     * Pick a legal replicated chase character.
     *
     * The killer wins for an ordinary death. If it vanished or died, prefer a
     * living teammate, then any living player. The worker/server never receives
     * this choice; it is presentation state only.
     */
    [[nodiscard]] std::optional<DeathCameraTarget>
    choose_death_camera_target(std::optional<std::uint8_t> preferred = std::nullopt) const {
        if (preferred.has_value()) {
            if (auto target = death_camera_target(*preferred); target.has_value()) {
                return target;
            }
        }
        std::optional<std::uint8_t> local_team;
        if (local_player_id.has_value()) {
            if (const auto* local = tutorial_roster.player(*local_player_id);
                local != nullptr && (local->team == 2U || local->team == 3U)) {
                local_team = local->team;
            }
        }
        const auto players = tutorial_roster.players();
        for (const bool same_team_only : {true, false}) {
            for (const auto& player : players) {
                if (same_team_only && (!local_team.has_value() || player.team != *local_team)) {
                    continue;
                }
                if (auto target = death_camera_target(player.player_id); target.has_value()) {
                    return target;
                }
            }
        }
        return std::nullopt;
    }

    void cycle_death_camera_target(int direction) {
        std::vector<DeathCameraTarget> targets;
        for (const auto& player : tutorial_roster.players()) {
            if (auto target = death_camera_target(player.player_id); target.has_value()) {
                targets.push_back(*target);
            }
        }
        if (targets.empty()) {
            death_camera.set_chase_target(std::nullopt);
            return;
        }
        const auto current = death_camera.chase_player_id();
        auto index = std::size_t{};
        if (current.has_value()) {
            const auto found = std::ranges::find(targets, *current, &DeathCameraTarget::player_id);
            if (found != targets.end()) {
                index = static_cast<std::size_t>(std::distance(targets.begin(), found));
                const auto count = static_cast<int>(targets.size());
                index =
                    static_cast<std::size_t>((static_cast<int>(index) + direction + count) % count);
            }
        }
        death_camera.set_chase_target(targets[index]);
        death_camera.request_chase();
    }

    [[nodiscard]] const world::JetpackDeathSnapshot* local_jetpack_death_state() const noexcept {
        if (!local_player_id.has_value() || !pending_local_jetpack_death.has_value()) {
            return nullptr;
        }
        const auto* state = jetpack_deaths.state(*local_player_id);
        return state != nullptr &&
                       state->generation == pending_local_jetpack_death->generation
                   ? state
                   : nullptr;
    }

    /**
     * Packet 36 is retail's handoff from the flying Character to the grave
     * camera. The packet flag controls only explosion VFX; Character.exploded
     * changes on both paths and a following CreatePlayer clears cleanup state.
     */
    void finish_local_jetpack_death(
        const std::optional<world::JetpackDeathSnapshot>& corpse) {
        if (!corpse.has_value() || !local_player_id.has_value() ||
            corpse->player_id != *local_player_id ||
            !pending_local_jetpack_death.has_value() ||
            pending_local_jetpack_death->generation != corpse->generation) {
            return;
        }
        const auto killer_id = pending_local_jetpack_death->killer_id;
        pending_local_jetpack_death.reset();
        if (tutorial_session == nullptr || death_camera.active()) {
            return;
        }
        death_camera.begin_death(corpse->position,
                                 tutorial_session->yaw(),
                                 choose_death_camera_target(killer_id),
                                 !network_match || match_initial_info.enable_deathcam);
        game_hud.set_crosshair_visible(false);
    }

    void begin_local_death(std::optional<std::uint8_t> killer_id) {
        if (tutorial_session == nullptr) {
            return;
        }
        // Idempotent hard stop: a duplicate/local-late KillAction must not
        // leave any previous-life source alive merely because the camera is
        // already in its death state.
        close_spin_loop();
        cancel_fire_loop();
        // A Character that died before its 1-2 second spawn timer elapsed must
        // not speak from the death camera. Keep previous_class_id so the next
        // same-class CreatePlayer still uses retail's normal 25/101 chance.
        local_spawn_voice.armed = false;
        if (death_camera.active()) {
            if (killer_id.has_value()) {
                if (auto target = death_camera_target(*killer_id); target.has_value()) {
                    death_camera.set_chase_target(*target);
                }
            }
            return;
        }
        const auto& player = tutorial_session->player();
        const audio::SoundPosition death_position{static_cast<float>(player.position.x),
                                                  static_cast<float>(player.position.y),
                                                  static_cast<float>(player.position.z)};
        tutorial_session->set_server_health(0.0);
        if (!local_death_announced) {
            play_class_voice(world::ClassVoice::death, death_position);
            local_death_announced = true;
        }
        game_hud.set_crosshair_visible(false);

        if (local_player_id.has_value()) {
            const auto* replica = tutorial_roster.player(*local_player_id);
            const std::uint32_t generation = replica != nullptr ? replica->generation : 1U;
            auto jetpack = replica != nullptr
                               ? world::retail_jetpack_id(replica->loadout, replica->ugc_tools)
                               : std::optional<std::uint8_t>{};
            if (!jetpack.has_value() && player.jetpack >= 1U && player.jetpack <= 4U) {
                jetpack = static_cast<std::uint8_t>(player.jetpack + 65U);
            }
            if (jetpack.has_value() && jetpack_deaths.begin(
                                           *local_player_id,
                                           generation,
                                           *jetpack,
                                           player.position)) {
                if (!pending_local_jetpack_death.has_value() ||
                    pending_local_jetpack_death->generation != generation) {
                    pending_local_jetpack_death =
                        PendingLocalJetpackDeath{generation, killer_id};
                } else if (killer_id.has_value()) {
                    pending_local_jetpack_death->killer_id = killer_id;
                }
                // Retail does not activate its death controller until
                // Character.explode_corpse. Keeping this camera deferred lets
                // the player ride the authoritative rising corpse for the fuse.
                return;
            }
        }
        death_camera.begin_death(player.position,
                                 tutorial_session->yaw(),
                                 choose_death_camera_target(killer_id),
                                 !network_match || match_initial_info.enable_deathcam);
    }

    void end_local_death(std::uint8_t team, bool dead) {
        if (tutorial_session == nullptr)
            return;
        const bool spectator = local_player_is_spectator(
            team, match_initial_info.enable_spectator);
        if (dead && !spectator) {
            begin_local_death(std::nullopt);
            return;
        }
        local_death_announced = false;
        pending_local_jetpack_death.reset();
        tutorial_session->set_server_health(100.0);
        game_hud.clear_respawn();
        if (spectator) {
            tutorial_session->clear_input();
            death_camera.enter_spectator(tutorial_session->player().position,
                                         tutorial_session->yaw(),
                                         choose_death_camera_target());
        } else {
            death_camera.end_life();
        }
    }

    void refresh_death_camera(double dt) {
        if (!death_camera.active() || tutorial_session == nullptr)
            return;
        if (local_player_id.has_value()) {
            for (const auto& entity : tutorial_session->entities()) {
                if (entity.type == 11U && entity.owner == *local_player_id && entity.alive) {
                    if (!death_camera.grave_entity_id().has_value()) {
                        death_camera.bind_grave(entity.id, entity.position);
                    } else {
                        death_camera.update_grave(entity.id, entity.position);
                    }
                    break;
                }
            }
        }
        const auto current = death_camera.chase_player_id();
        auto target = current.has_value() ? death_camera_target(*current)
                                          : std::optional<DeathCameraTarget>{};
        if (!target.has_value()) {
            target = choose_death_camera_target();
        }
        death_camera.set_chase_target(std::move(target));
        death_camera.tick(dt);
    }

    /** Publish one retail ClientData sample for each fixed simulation tick. */
    void send_live_client_data() {
        if (!network_match || match_connection == nullptr || tutorial_session == nullptr ||
            !local_player_id.has_value()) {
            return;
        }
        const auto* local = tutorial_roster.player(*local_player_id);
        const bool spectator = local != nullptr && local_player_is_spectator(
            local->team, match_initial_info.enable_spectator);
        if (spectator) {
            // First ClientData is the server's scene-ready boundary. Keep
            // neutral samples flowing during incremental roster/map reveal,
            // without recording character prediction or authorizing actions.
            const auto orientation = tutorial_session->player().orientation;
            const auto packet = spectator_client_data(
                client_loop_count++, *local_player_id,
                {static_cast<float>(orientation.x), static_cast<float>(orientation.y),
                 static_cast<float>(orientation.z)});
            if (!match_connection->send(network::encode_packet(packet))) {
                const auto status = match_connection->status();
                if (!status.error.empty()) settings_warning = status.error;
            }
            return;
        }
        if (!tutorial_session->alive() || death_camera.active()) return;
        network::ClientDataPacket packet;
        packet.loop_count = client_loop_count++;
        tutorial_session->record_network_prediction(packet.loop_count);
        packet.player_id = *local_player_id;
        packet.tool_id = tutorial_session->selected_tool_id().value_or(0U);
        if (local != nullptr) {
            remember_combat_tool(*local, packet.tool_id);
        }
        if (!last_sent_tool.has_value() || *last_sent_tool != packet.tool_id) {
            pending_tool_selection = PendingToolSelection{packet.tool_id, packet.loop_count};
            last_sent_tool = packet.tool_id;
        }
        const auto orientation = tutorial_session->player().orientation;
        packet.orientation = {static_cast<float>(orientation.x),
                              static_cast<float>(orientation.y),
                              static_cast<float>(orientation.z)};
        packet.opaque_state = network::protocol168_client_data_opaque_state(packet.loop_count);
        packet.movement_flags = tutorial_session->movement_flags();
        packet.action_flags = tutorial_session->action_flags();
        if (!match_connection->send(network::encode_packet(packet))) {
            const auto status = match_connection->status();
            if (!status.error.empty())
                settings_warning = status.error;
        }
    }

    /**
     * Emit retail ClockSync(0) at a bounded one-hertz cadence.
     *
     * The echoed token only pairs a response with this session. The response's
     * loop anchor is applied in `pump_live_match_packets`; packet transport
     * remains on the ENet worker and never blocks the fixed gameplay tick.
     */
    void send_live_clock_sync(double dt) {
        if (!network_match || match_connection == nullptr)
            return;
        clock_sync_elapsed += std::max(0.0, dt);
        if (clock_sync_elapsed < 1.0)
            return;
        clock_sync_elapsed = std::fmod(clock_sync_elapsed, 1.0);
        if (clock_sync_token == std::numeric_limits<std::int32_t>::max()) {
            clock_sync_token = 1;
        } else {
            ++clock_sync_token;
        }
        const network::ClockSyncPacket packet{
            clock_sync_token,
            0,
        };
        if (!match_connection->send(network::encode_packet(packet))) {
            const auto status = match_connection->status();
            if (!status.error.empty())
                settings_warning = status.error;
        }
    }

    /** Refresh authoritative peer bodies before the local native move. */
    void refresh_live_player_collisions() {
        if (!network_match || tutorial_session == nullptr || !local_player_id.has_value()) {
            return;
        }
        auto bodies = network::protocol168_collision_bodies(
            tutorial_roster, *local_player_id, match_initial_info.same_team_collision);
        // Retail Character.update_alive reads each peer's current
        // world_object.position. Match that visible/interpolated pose rather
        // than colliding against the raw 30 Hz WorldUpdate target.
        for (auto& body : bodies) {
            const auto rig = remote_player_rigs.find(body.player_id);
            if (rig != remote_player_rigs.end()) {
                body.position = rig->second.motion.sample().position;
            }
        }
        tutorial_session->set_player_collision_bodies(bodies);
    }

    [[nodiscard]] bool palette_tool_selected() const noexcept {
        if (tutorial_session == nullptr)
            return false;
        const auto selected = tutorial_session->selected_tool_id();
        const auto* weapon =
            selected.has_value() ? world::find_weapon_definition(*selected) : nullptr;
        return weapon != nullptr && (weapon->mechanism == world::WeaponMechanism::block_builder ||
                                     weapon->mechanism == world::WeaponMechanism::flare_builder ||
                                     weapon->mechanism == world::WeaponMechanism::paintbrush ||
                                     weapon->mechanism == world::WeaponMechanism::disguise ||
                                     // SnowBlowerWeapon is the retail Block Cannon and consumes
                                     // the same selected block colour for each snowball.
                                     weapon->tool_id == 29U || weapon->tool_id == 48U);
    }

    [[nodiscard]] static std::size_t closest_palette_index(std::uint32_t color) noexcept {
        const auto red = static_cast<int>((color >> 16U) & 0xFFU);
        const auto green = static_cast<int>((color >> 8U) & 0xFFU);
        const auto blue = static_cast<int>(color & 0xFFU);
        const auto colors = retail_block_palette();
        std::size_t best{};
        auto best_distance = std::numeric_limits<int>::max();
        for (std::size_t index{}; index < colors.size(); ++index) {
            const auto dr = red - colors[index].red;
            const auto dg = green - colors[index].green;
            const auto db = blue - colors[index].blue;
            const auto distance = dr * dr + dg * dg + db * db;
            if (distance < best_distance) {
                best = index;
                best_distance = distance;
            }
        }
        return best;
    }

    [[nodiscard]] bool palette_enabled() const noexcept {
        return palette_tool_selected() &&
               (!network_match || match_initial_info.enable_colour_palette);
    }

    void apply_local_block_color(world::VxlColor color, bool hide_selector = false) {
        color.alpha = 255U;
        local_palette_color = (static_cast<std::uint32_t>(color.red) << 16U) |
                              (static_cast<std::uint32_t>(color.green) << 8U) |
                              static_cast<std::uint32_t>(color.blue);
        if (hide_selector) {
            palette_selection.reset();
        }
        if (tutorial_session != nullptr) {
            tutorial_session->set_block_color(color);
        }
        // The held block and prefab ghost are both colour-dependent meshes.
        uploaded_sandbox_tool.reset();
        preview_prefab_meshes_uploaded = false;
        if (network_match && match_connection != nullptr && local_player_id.has_value()) {
            const network::SetColorPacket packet{*local_player_id, *local_palette_color};
            if (!match_connection->send(network::encode_packet(packet))) {
                settings_warning = "failed to queue SetColor(11)";
            }
        }
    }

    void move_palette_selection(int horizontal, int vertical) {
        if (!palette_enabled())
            return;
        const auto colors = retail_block_palette();
        constexpr std::size_t columns{8U};
        const auto rows = colors.size() / columns;
        auto index = palette_selection.value_or(16U);
        auto column = static_cast<int>(index % columns);
        auto row = static_cast<int>(index / columns);
        column = (column + horizontal + static_cast<int>(columns)) % static_cast<int>(columns);
        row = (row + vertical + static_cast<int>(rows)) % static_cast<int>(rows);
        index = static_cast<std::size_t>(row) * columns + static_cast<std::size_t>(column);
        palette_selection = index;
        const auto selected = colors[index];
        apply_local_block_color(world::VxlColor{selected.red, selected.green, selected.blue, 255U});
    }

    void sync_palette_hud() {
        const auto colors = retail_block_palette();
        game_hud.set_palette_state(std::vector<ui::ColorRgba8>{colors.begin(), colors.end()},
                                   8U,
                                   palette_selection,
                                   palette_enabled(),
                                   network_match && match_initial_info.map_is_ugc());
    }

    [[nodiscard]] static std::uint8_t prefab_facing(const world::Vec3& orientation) noexcept {
        // shared.common.get_facing (common.pyd @ 0x1000CC70):
        // int(-atan2(y,x) * 2/pi + 1.5) % 4.
        const auto raw = static_cast<int>(
            -std::atan2(orientation.y, orientation.x) * (2.0 / std::numbers::pi) + 1.5);
        return static_cast<std::uint8_t>((raw % 4 + 4) % 4);
    }

    [[nodiscard]] static std::array<std::int32_t, 3U>
    rotate_prefab_xyz(std::int32_t x,
                      std::int32_t y,
                      std::int32_t z,
                      std::uint8_t yaw,
                      std::uint8_t pitch,
                      std::uint8_t roll) noexcept {
        const auto rotated = world::rotate_prefab_cell({x, y, z}, yaw, pitch, roll);
        return {rotated.x, rotated.y, rotated.z};
    }

    [[nodiscard]] std::optional<std::filesystem::path>
    resolve_prefab_asset(std::string_view name) const {
        if (name.empty())
            return std::nullopt;
        const std::filesystem::path requested{std::string{name}};
        if (requested.has_parent_path() || requested.filename().string() != requested.string()) {
            return std::nullopt;
        }
        auto asset_name = requested.string();
        if (!asset_name.ends_with(".kv6"))
            asset_name += ".kv6";
        std::vector<std::string> filenames{asset_name};
        if (!requested.string().starts_with("prefab_")) {
            filenames.push_back("prefab_" + asset_name);
        }
        const auto find_case_insensitive =
            [](const std::filesystem::path& directory,
               std::string_view filename) -> std::optional<std::filesystem::path> {
            std::error_code error;
            if (!std::filesystem::is_directory(directory, error)) {
                return std::nullopt;
            }
            auto expected = std::string{filename};
            std::ranges::transform(expected, expected.begin(), [](unsigned char value) {
                return static_cast<char>(std::tolower(value));
            });
            for (std::filesystem::directory_iterator iterator{directory, error}, end;
                 !error && iterator != end;
                 iterator.increment(error)) {
                auto candidate = iterator->path().filename().string();
                std::ranges::transform(candidate, candidate.begin(), [](unsigned char value) {
                    return static_cast<char>(std::tolower(value));
                });
                if (candidate == expected)
                    return iterator->path();
            }
            return std::nullopt;
        };
        for (const auto& directory :
             {config.asset_root / "kv6", config.asset_root / "ugc" / "kv6"}) {
            for (const auto& filename : filenames) {
                const auto direct = directory / filename;
                if (std::filesystem::is_regular_file(direct))
                    return direct;
                if (const auto matched = find_case_insensitive(directory, filename);
                    matched.has_value()) {
                    return matched;
                }
            }
        }
        return std::nullopt;
    }

    [[nodiscard]] network::TerrainReplicaResult
    apply_live_prefab_mutation(std::span<const std::byte> payload) {
        network::TerrainReplicaResult result;
        result.recognized = true;
        if (live_terrain_replica == nullptr) {
            result.error = "prefab mutation arrived before terrain replica";
            return result;
        }
        const auto decoded = network::decode_tool_action_packet(payload);
        if (!decoded) {
            result.recognized = false;
            result.error = decoded.error;
            return result;
        }

        std::string_view prefab_name;
        std::uint8_t yaw{};
        std::uint8_t pitch{};
        std::uint8_t roll{};
        std::int32_t first{};
        std::int32_t last{};
        std::array<std::int32_t, 3U> origin{};
        bool erase{};
        if (const auto* build_packet =
                std::get_if<network::BuildPrefabActionPacket>(&*decoded.packet);
            build_packet != nullptr) {
            prefab_name = build_packet->prefab_name;
            yaw = build_packet->yaw;
            pitch = build_packet->pitch;
            roll = build_packet->roll;
            first = build_packet->from_block_index;
            last = build_packet->to_block_index;
            origin = {
                build_packet->position[0U], build_packet->position[1U], build_packet->position[2U]};
        } else if (const auto* erase_packet =
                       std::get_if<network::ErasePrefabActionPacket>(&*decoded.packet);
                   erase_packet != nullptr) {
            prefab_name = erase_packet->prefab_name;
            yaw = erase_packet->yaw;
            pitch = erase_packet->pitch;
            roll = erase_packet->roll;
            first = erase_packet->from_block_index;
            last = erase_packet->to_block_index;
            origin = {static_cast<std::int32_t>(std::lround(erase_packet->position[0U])),
                      static_cast<std::int32_t>(std::lround(erase_packet->position[1U])),
                      static_cast<std::int32_t>(std::lround(erase_packet->position[2U]))};
            erase = true;
        } else {
            result.recognized = false;
            result.error = "packet is not a prefab terrain mutation";
            return result;
        }

        if (live_prefab_model_name != prefab_name || !live_prefab_model.has_value()) {
            const auto path = resolve_prefab_asset(prefab_name);
            if (!path.has_value()) {
                result.error = "server prefab asset is unavailable: " + std::string{prefab_name};
                return result;
            }
            std::string load_error;
            live_prefab_model = world::Kv6Model::load_file(*path, &load_error);
            if (!live_prefab_model.has_value()) {
                result.error = "server prefab asset failed to load: " +
                               (load_error.empty() ? path->string() : load_error);
                return result;
            }
            live_prefab_model_name = prefab_name;
        }
        const auto& model = live_prefab_model;
        const auto count = static_cast<std::int32_t>(std::min<std::size_t>(
            model->voxels().size(),
            static_cast<std::size_t>(std::numeric_limits<std::int32_t>::max())));
        // Retail VXL.place_prefab_in_world consumes [first,last). Rejecting
        // invalid ranges prevents a corrupt server packet from partially
        // mutating collision with a different shape than the authority.
        if (first < 0 || last <= first || last > count) {
            result.error = "server prefab packet contains an invalid voxel range";
            return result;
        }

        std::vector<world::PrefabPlacementVoxel> additions;
        std::vector<world::VoxelCell> removals;
        additions.reserve(static_cast<std::size_t>(last - first));
        removals.reserve(static_cast<std::size_t>(last - first));
        for (std::int32_t index = first; index < last; ++index) {
            const auto& voxel = model->voxels()[static_cast<std::size_t>(index)];
            const auto rotated = rotate_prefab_xyz(static_cast<std::int32_t>(voxel.x),
                                                   static_cast<std::int32_t>(voxel.y),
                                                   static_cast<std::int32_t>(voxel.z),
                                                   yaw,
                                                   pitch,
                                                   roll);
            const std::array<std::int32_t, 3U> cell{
                origin[0U] + rotated[0U], origin[1U] + rotated[1U], origin[2U] + rotated[2U]};
            if (cell[0U] < 0 || cell[1U] < 0 || cell[2U] < 0 ||
                cell[0U] >= static_cast<std::int32_t>(world::VxlMap::width) ||
                cell[1U] >= static_cast<std::int32_t>(world::VxlMap::depth) ||
                cell[2U] >= static_cast<std::int32_t>(world::VxlMap::height - 1U)) {
                continue;
            }
            const world::VoxelCell target{static_cast<std::uint32_t>(cell[0U]),
                                          static_cast<std::uint32_t>(cell[1U]),
                                          static_cast<std::uint32_t>(cell[2U])};
            if (erase) {
                removals.push_back(target);
            } else {
                auto color = voxel.color;
                color.alpha = 255U;
                additions.push_back(
                    {{static_cast<std::int32_t>(target.x),
                      static_cast<std::int32_t>(target.y),
                      static_cast<std::int32_t>(target.z)},
                     color});
            }
        }
        if (erase) {
            return live_terrain_replica->apply_removed_cells(removals);
        }
        if (!live_prefab_placement.stage(additions)) {
            live_prefab_placement.clear();
            result.error = "server prefab transaction exceeded its bounded voxel budget";
            return result;
        }
        // Packet 30 is transport, not presentation. Packet 29 commits the
        // complete construct through one TerrainReplica mutation.
        result.mutation.accepted = true;
        return result;
    }

    /** Atomically reveal every staged packet-30 slice at PrefabComplete(29). */
    [[nodiscard]] network::TerrainReplicaResult complete_live_prefab(bool present_feedback) {
        network::TerrainReplicaResult result;
        result.recognized = true;
        if (live_terrain_replica == nullptr) {
            live_prefab_placement.clear();
            result.error = "prefab completion arrived before terrain replica";
            return result;
        }
        if (live_prefab_placement.empty()) {
            return result;
        }

        const auto staged_view = live_prefab_placement.voxels();
        std::vector<world::PrefabPlacementVoxel> staged{staged_view.begin(), staged_view.end()};
        const world::VxlMap* current_map = tutorial_session != nullptr
                                               ? &tutorial_session->map()
                                               : tutorial_ready_map.get();
        if (current_map == nullptr) {
            live_prefab_placement.clear();
            result.error = "prefab completion has no active map";
            return result;
        }

        std::vector<network::ColoredTerrainCell> additions;
        additions.reserve(staged.size());
        for (const auto& voxel : staged) {
            const auto x = static_cast<std::uint32_t>(voxel.cell.x);
            const auto y = static_cast<std::uint32_t>(voxel.cell.y);
            const auto z = static_cast<std::uint32_t>(voxel.cell.z);
            // Legal overlap satisfies the authored footprint without
            // recolouring existing world geometry or consuming another block.
            if (!current_map->solid(x, y, z)) {
                additions.push_back({{x, y, z}, voxel.color});
            }
        }
        result = live_terrain_replica->apply_colored_cells(additions);
        live_prefab_placement.clear();

        if (present_feedback && result.mutation.accepted && !staged.empty()) {
            world::emit_prefab_placement(
                particles,
                staged,
                static_cast<std::uint32_t>(latest_world_loop) ^
                    static_cast<std::uint32_t>(staged.size() * 0x9E3779B9U));
            if (audio_started) {
                const auto& origin = staged.front().cell;
                static_cast<void>(audio->play_named_one_shot(
                    world::placement_sound_stem(world::PlacementFeedbackKind::prefab),
                    {static_cast<float>(origin.x) + 0.5F,
                     static_cast<float>(origin.y) + 0.5F,
                     static_cast<float>(origin.z) + 0.5F},
                    1.0F));
            }
        }
        return result;
    }

    void evaluate_prefab_candidate(const world::Kv6Model& model,
                                   const std::array<std::int32_t, 3U>& origin,
                                   std::uint8_t yaw,
                                   std::uint8_t pitch,
                                   std::uint8_t roll,
                                   bool& valid,
                                   std::int32_t& required_blocks) const {
        valid = false;
        required_blocks = 0;
        if (tutorial_session == nullptr || model.voxels().empty()) {
            return;
        }
        const auto evaluation = preview_prefab_placement.evaluate(
            tutorial_session->map(), {origin[0U], origin[1U], origin[2U]}, yaw, pitch, roll);
        required_blocks = static_cast<std::int32_t>(std::min<std::size_t>(
            evaluation.required_blocks,
            static_cast<std::size_t>(std::numeric_limits<std::int32_t>::max())));
        valid = evaluation.all_in_bounds && evaluation.touches_world &&
                evaluation.has_effect() &&
                (tutorial_session->infinite_blocks() ||
                 tutorial_session->blocks_remaining() >= required_blocks);
    }

    [[nodiscard]] std::optional<std::array<std::int16_t, 3U>>
    prefab_candidate(const world::Kv6Model& model,
                     std::uint8_t yaw,
                     std::uint8_t pitch,
                     std::uint8_t roll,
                     bool& valid,
                     std::int32_t& required_blocks,
                     std::array<double, 3U>& center) const {
        valid = false;
        required_blocks = 0;
        center = {};
        if (tutorial_session == nullptr || model.voxels().empty()) {
            return std::nullopt;
        }
        const auto& player = tutorial_session->player();
        const auto& footprint_bounds = preview_prefab_placement.bounds(yaw, pitch, roll);
        const auto& minimum = footprint_bounds.minimum;
        const auto& maximum = footprint_bounds.maximum;
        const auto world_x = maximum[0U] - minimum[0U] + 1;
        const auto world_y = maximum[1U] - minimum[1U] + 1;
        const auto world_z = maximum[2U] - minimum[2U] + 1;
        const auto radius = std::sqrt(static_cast<double>(world_x) * world_x +
                                      static_cast<double>(world_y) * world_y +
                                      static_cast<double>(world_z) * world_z) /
                            2.0;
        struct DistanceBand final {
            double radius;
            double factor;
            double maximum;
        };
        static constexpr std::array<DistanceBand, 6U> bands{{
            {0.0, 1.20, 12.0},
            {10.0, 1.20, 999999.0},
            {20.0, 1.15, 999999.0},
            {70.0, 1.10, 999999.0},
            {120.0, 1.05, 999999.0},
            {1000.0, 1.00, 999999.0},
        }};
        const auto band = std::min_element(
            bands.begin(), bands.end(), [radius](const auto& left, const auto& right) {
                return std::abs(left.radius - radius) < std::abs(right.radius - radius);
            });
        const auto distance = std::clamp(radius * band->factor + 1.0, 7.0, band->maximum);
        const std::array<double, 3U> footprint_center{
            (static_cast<double>(minimum[0U]) + maximum[0U]) / 2.0,
            (static_cast<double>(minimum[1U]) + maximum[1U]) / 2.0,
            (static_cast<double>(minimum[2U]) + maximum[2U]) / 2.0};
        // Packet 30 carries the prefab ANCHOR, not a rotated minimum corner.
        // Centering by unrotated width/height worked only at yaw zero. At the
        // other three facings it applied a second half-extent in the wrong
        // direction, so the ghost wrapped around the camera while the server
        // expanded the same anchor elsewhere.
        std::array<std::int32_t, 3U> origin{
            static_cast<std::int32_t>(std::floor(
                player.position.x + distance * player.orientation.x - footprint_center[0U])),
            static_cast<std::int32_t>(std::floor(
                player.position.y + distance * player.orientation.y - footprint_center[1U])),
            static_cast<std::int32_t>(
                std::floor(player.position.z + distance * player.orientation.z -
                           footprint_center[2U] - 0.4 * static_cast<double>(world_z))),
        };
        origin[2U] = std::min<std::int32_t>(origin[2U],
                                            static_cast<std::int32_t>(world::VxlMap::height) - 1);
        for (std::size_t axis{}; axis < 3U; ++axis) {
            center[axis] = static_cast<double>(origin[axis]) + footprint_center[axis];
        }
        evaluate_prefab_candidate(
            model, origin, yaw, pitch, roll, valid, required_blocks);
        return std::array<std::int16_t, 3U>{static_cast<std::int16_t>(origin[0U]),
                                            static_cast<std::int16_t>(origin[1U]),
                                            static_cast<std::int16_t>(origin[2U])};
    }

    void update_prefab_candidate() {
        preview_prefab_position.reset();
        preview_prefab_valid = false;
        preview_prefab_cost = 0;
        if (tutorial_session == nullptr || !preview_prefab_model.has_value()) {
            return;
        }
        if (ugc_prefab_control.active()) {
            const auto& controlled = ugc_prefab_control.placement();
            preview_prefab_yaw = controlled.yaw;
            preview_prefab_pitch = controlled.pitch;
            preview_prefab_roll = controlled.roll;
            preview_prefab_center = controlled.center;
            preview_prefab_position = std::array<std::int16_t, 3U>{
                static_cast<std::int16_t>(controlled.anchor[0U]),
                static_cast<std::int16_t>(controlled.anchor[1U]),
                static_cast<std::int16_t>(controlled.anchor[2U])};
            evaluate_prefab_candidate(*preview_prefab_model,
                                      controlled.anchor,
                                      preview_prefab_yaw,
                                      preview_prefab_pitch,
                                      preview_prefab_roll,
                                      preview_prefab_valid,
                                      preview_prefab_cost);
            return;
        }
        preview_prefab_yaw = static_cast<std::uint8_t>(
            (prefab_facing(tutorial_session->player().orientation) + prefab_yaw_override) % 4U);
        preview_prefab_pitch = 0U;
        preview_prefab_roll = 0U;
        preview_prefab_position = prefab_candidate(*preview_prefab_model,
                                                   preview_prefab_yaw,
                                                   preview_prefab_pitch,
                                                   preview_prefab_roll,
                                                   preview_prefab_valid,
                                                   preview_prefab_cost,
                                                   preview_prefab_center);
        const auto selected = tutorial_session->selected_tool_id();
        const auto* selected_weapon =
            selected.has_value() ? world::find_weapon_definition(*selected) : nullptr;
        if (preview_prefab_position.has_value() && selected_weapon != nullptr &&
            selected_weapon->mechanism == world::WeaponMechanism::ugc_prefab_editor) {
            ugc_prefab_control.prime(world::UgcPrefabPlacement{
                {(*preview_prefab_position)[0U],
                 (*preview_prefab_position)[1U],
                 (*preview_prefab_position)[2U]},
                preview_prefab_center,
                {static_cast<std::int32_t>(preview_prefab_model->size_x()),
                 static_cast<std::int32_t>(preview_prefab_model->size_y()),
                 static_cast<std::int32_t>(preview_prefab_model->size_z())},
                preview_prefab_yaw,
                preview_prefab_pitch,
                preview_prefab_roll});
        } else if (selected_weapon == nullptr ||
                   selected_weapon->mechanism != world::WeaponMechanism::ugc_prefab_editor) {
            ugc_prefab_control.reset();
        }
    }

    [[nodiscard]] bool ugc_prefab_selected() const noexcept {
        if (tutorial_session == nullptr) {
            return false;
        }
        const auto selected = tutorial_session->selected_tool_id();
        const auto* weapon =
            selected.has_value() ? world::find_weapon_definition(*selected) : nullptr;
        return weapon != nullptr &&
               weapon->mechanism == world::WeaponMechanism::ugc_prefab_editor &&
               !tutorial_session->selected_prefab().empty();
    }

    void activate_ugc_prefab_control() {
        if (!ugc_prefab_selected()) {
            return;
        }
        update_prefab_candidate();
        if (!preview_prefab_position.has_value() || !ugc_prefab_control.activate()) {
            return;
        }
        // UGCPrefabTool.activate_control_mode stops Character movement before
        // the prefab camera takes ownership of W/A/S/D/jump/crouch.
        tutorial_session->clear_input();
        update_prefab_candidate();
    }

    void send_ugc_prefab_erase() {
        if (!network_match || match_connection == nullptr ||
            !local_player_id.has_value() || !ugc_prefab_selected() ||
            !preview_prefab_model.has_value()) {
            return;
        }
        update_prefab_candidate();
        if (!preview_prefab_position.has_value()) {
            return;
        }
        const auto packet = network::ErasePrefabActionPacket{
            std::max<std::int32_t>(0, client_loop_count - 1),
            preview_prefab_name,
            *local_player_id,
            preview_prefab_yaw,
            preview_prefab_pitch,
            preview_prefab_roll,
            0,
            static_cast<std::int32_t>(std::min<std::size_t>(
                preview_prefab_model->voxels().size(),
                static_cast<std::size_t>(std::numeric_limits<std::int32_t>::max()))),
            {static_cast<float>((*preview_prefab_position)[0U]),
             static_cast<float>((*preview_prefab_position)[1U]),
             static_cast<float>((*preview_prefab_position)[2U])}};
        if (!match_connection->send(network::encode_packet(packet))) {
            settings_warning = "failed to queue ErasePrefabAction(31)";
        }
    }

    void send_live_weapon_actions(std::span<const world::WeaponAction> actions) {
        if (tutorial_session == nullptr)
            return;
        for (const auto& action : actions) {
            if (action.kind == world::WeaponActionKind::hitscan ||
                action.kind == world::WeaponActionKind::melee) {
                // One local firing action may yield multiple server blood
                // responses (shotgun pellets or several victims), but retail
                // plays one confirmation and one crosshair transition.
                played_hit_sound = false;
            }
            if (action.kind == world::WeaponActionKind::block_line_begin) {
                block_line_start =
                    tutorial_session->placement_cell(match_initial_info.classic ? 5.0 : 10.0);
                continue;
            }
            if (action.kind == world::WeaponActionKind::block_line_cancel) {
                block_line_start.reset();
                continue;
            }
            if (action.kind == world::WeaponActionKind::prefab_rotate) {
                const auto* rotated_tool = world::find_weapon_definition(action.tool_id);
                if (rotated_tool != nullptr &&
                    rotated_tool->mechanism == world::WeaponMechanism::ugc_prefab_editor &&
                    ugc_prefab_control.active()) {
                    ugc_prefab_control.rotate_yaw(1);
                } else {
                    prefab_yaw_override =
                        static_cast<std::uint8_t>((prefab_yaw_override + 1U) % 4U);
                }
                update_prefab_candidate();
                continue;
            }
            if (action.kind == world::WeaponActionKind::color_pick) {
                if ((!network_match || match_initial_info.enable_colour_picker) &&
                    tutorial_session != nullptr) {
                    if (const auto color = tutorial_session->looked_at_block_color(
                            match_initial_info.classic ? 5.0 : 10.0);
                        color.has_value()) {
                        apply_local_block_color(*color, true);
                    }
                }
                continue;
            }
            if (!network_match || match_connection == nullptr || !local_player_id.has_value()) {
                continue;
            }
            network::WeaponActionWireContext wire;
            wire.loop_count = std::max<std::int32_t>(0, client_loop_count - 1);
            wire.shot_on_world_update = latest_world_loop;
            wire.player_id = *local_player_id;
            const auto& player = tutorial_session->player();
            auto position = player.position;
            switch (action.kind) {
            case world::WeaponActionKind::block_line_begin:
            case world::WeaponActionKind::block_line_commit:
            case world::WeaponActionKind::flare_place:
            case world::WeaponActionKind::prefab_place:
            case world::WeaponActionKind::ugc_entity_use:
            case world::WeaponActionKind::paint_single:
            case world::WeaponActionKind::paint_area:
                position = tutorial_session->placement_position();
                break;
            default:
                break;
            }
            wire.position = {static_cast<float>(position.x),
                             static_cast<float>(position.y),
                             static_cast<float>(position.z)};
            wire.orientation = {static_cast<float>(player.orientation.x),
                                static_cast<float>(player.orientation.y),
                                static_cast<float>(player.orientation.z)};
            const auto launch = tutorial_session->action_velocity(action);
            wire.velocity = {static_cast<float>(launch.x),
                             static_cast<float>(launch.y),
                             static_cast<float>(launch.z)};
            if (const auto* weapon = world::find_weapon_definition(action.tool_id);
                weapon != nullptr) {
                wire.damage = static_cast<std::int16_t>(
                    std::clamp(std::lround(weapon->base_damage),
                               static_cast<long>(std::numeric_limits<std::int16_t>::min()),
                               static_cast<long>(std::numeric_limits<std::int16_t>::max())));
                wire.penetration = static_cast<std::int16_t>(
                    std::clamp(std::lround(weapon->block_damage),
                               0L,
                               static_cast<long>(std::numeric_limits<std::int16_t>::max())));
            }
            // PlaceMG/PlaceRocketTurret store degree yaw directly. This is not
            // the radian angle used by ordinary C++ trigonometry; retail feeds
            // Character.yaw into the packet's signed 1/64 field unchanged.
            wire.yaw = static_cast<float>(tutorial_session->yaw());
            wire.color = local_palette_color.value_or(0x006E6E6EU);
            if (action.kind == world::WeaponActionKind::ugc_entity_use) {
                const auto item = tutorial_session->selected_ugc_item();
                const auto target = tutorial_session->placement_cell(10.0);
                if (!item.has_value() || !target.has_value()) {
                    settings_warning = "UGC Game Data placement is not valid here";
                    continue;
                }
                const auto pointed = std::ranges::find_if(
                    server_ugc_items, [&](const network::InitialUgcItem& retained) {
                        const auto dx = static_cast<int>(retained.position[0U]) - (*target)[0U];
                        const auto dy = static_cast<int>(retained.position[1U]) - (*target)[1U];
                        const auto dz = static_cast<int>(retained.position[2U]) - (*target)[2U];
                        return dx * dx + dy * dy + dz * dz <= 1;
                    });

                if (action.secondary) {
                    if (pointed == server_ugc_items.end()) {
                        // Retail RMB over empty ground changes only the selected
                        // health/ammo/blocks or small/medium/large variant.
                        static_cast<void>(tutorial_session->cycle_selected_ugc_item_variant());
                        continue;
                    }
                    // RMB over an existing marker replaces it in place with the
                    // next variant. The wire owns this as two ordered packet-97
                    // operations; collapsing it into one fabricated update
                    // leaves retail observers with duplicate metadata.
                    const auto next = world::next_ugc_item_variant(pointed->item_id);
                    const network::PlaceUgcPacket remove{
                        wire.loop_count, pointed->position, pointed->item_id, false};
                    const network::PlaceUgcPacket replace{
                        wire.loop_count, pointed->position, next, true};
                    if (!match_connection->send(network::encode_packet(remove)) ||
                        !match_connection->send(network::encode_packet(replace))) {
                        settings_warning = "failed to queue UGC variant replacement";
                        return;
                    }
                    continue;
                }

                // Primary click toggles the pointed marker. It never removes a
                // different selected variant from the same location.
                wire.ugc_item_id = pointed == server_ugc_items.end() ? *item : pointed->item_id;
                wire.ugc_placing = pointed == server_ugc_items.end();
                position = {static_cast<double>((*target)[0U]),
                            static_cast<double>((*target)[1U]),
                            static_cast<double>((*target)[2U])};
                const auto& ugc_position = pointed == server_ugc_items.end()
                                               ? *target
                                               : pointed->position;
                wire.position = {static_cast<float>(ugc_position[0U]),
                                 static_cast<float>(ugc_position[1U]),
                                 static_cast<float>(ugc_position[2U])};
            }
            if (action.kind == world::WeaponActionKind::deployable_place) {
                const auto target = tutorial_session->deployable_target(action.tool_id);
                if (!target.has_value()) {
                    settings_warning = "deployable placement is not valid here";
                    continue;
                }
                position = {static_cast<double>(target->cell[0U]),
                            static_cast<double>(target->cell[1U]),
                            static_cast<double>(target->cell[2U])};
                wire.position = {static_cast<float>(target->cell[0U]),
                                 static_cast<float>(target->cell[1U]),
                                 static_cast<float>(target->cell[2U])};
                wire.face = target->face;
            }
            auto raw =
                std::array<std::int16_t, 3U>{static_cast<std::int16_t>(std::lround(position.x)),
                                             static_cast<std::int16_t>(std::lround(position.y)),
                                             static_cast<std::int16_t>(std::lround(position.z))};
            if (action.kind == world::WeaponActionKind::block_line_commit) {
                const auto end =
                    tutorial_session->placement_cell(match_initial_info.classic ? 5.0 : 10.0);
                if (!block_line_start.has_value() || !end.has_value()) {
                    block_line_start.reset();
                    continue;
                }
                wire.block_line_start = *block_line_start;
                wire.block_line_end = *end;
                raw = *end;
                block_line_start.reset();
            } else {
                wire.block_line_start = raw;
                wire.block_line_end = raw;
            }
            wire.paint_positions.push_back(raw);
            wire.prefab_name = std::string{tutorial_session->selected_prefab()};
            std::vector<network::ColoredTerrainCell> expected_prefab_colors;
            if (action.kind == world::WeaponActionKind::prefab_place) {
                update_prefab_candidate();
                if (!preview_prefab_position.has_value() || !preview_prefab_valid) {
                    settings_warning = "prefab placement is not valid here";
                    continue;
                }
                wire.prefab_yaw = preview_prefab_yaw;
                wire.prefab_pitch = preview_prefab_pitch;
                wire.prefab_roll = preview_prefab_roll;
                // Native VXL prefab expansion consumes an inclusive/exclusive
                // authored-voxel range.  0..0 is an empty placement on retail
                // clients even if a permissive server expands the name itself.
                wire.prefab_from_block_index = 0;
                wire.prefab_to_block_index = static_cast<std::int32_t>(std::min<std::size_t>(
                    preview_prefab_model->voxels().size(),
                    static_cast<std::size_t>(std::numeric_limits<std::int32_t>::max())));
                wire.position = {static_cast<float>((*preview_prefab_position)[0U]),
                                 static_cast<float>((*preview_prefab_position)[1U]),
                                 static_cast<float>((*preview_prefab_position)[2U])};
                // UGCPrefabTool.confirm_prefab_placement explicitly passes
                // False. Competitive prefab builders pass True and spend the
                // player's stock. This protocol bit must not be shared.
                wire.prefab_add_to_user_blocks =
                    world::find_weapon_definition(action.tool_id) == nullptr ||
                    world::find_weapon_definition(action.tool_id)->mechanism !=
                        world::WeaponMechanism::ugc_prefab_editor;

                // Competitive servers expand packet 30 and acknowledge the
                // owner with one compact BlockBuild(32) per accepted voxel.
                // Packet 32 carries no RGB, yet the canonical color is a
                // 50/50 player/KV6 blend. Associate the action loop and exact
                // rotated cells now so those delayed acknowledgements render
                // identically to observer packet 33.
                const world::VxlColor base_color{static_cast<std::uint8_t>(wire.color >> 16U),
                                                 static_cast<std::uint8_t>(wire.color >> 8U),
                                                 static_cast<std::uint8_t>(wire.color),
                                                 255U};
                expected_prefab_colors.reserve(preview_prefab_model->voxels().size());
                for (const auto& voxel : preview_prefab_model->voxels()) {
                    const auto rotated = rotate_prefab_xyz(static_cast<std::int32_t>(voxel.x),
                                                           static_cast<std::int32_t>(voxel.y),
                                                           static_cast<std::int32_t>(voxel.z),
                                                           wire.prefab_yaw,
                                                           wire.prefab_pitch,
                                                           wire.prefab_roll);
                    const std::array<std::int32_t, 3U> cell{
                        (*preview_prefab_position)[0U] + rotated[0U],
                        (*preview_prefab_position)[1U] + rotated[1U],
                        (*preview_prefab_position)[2U] + rotated[2U]};
                    if (cell[0U] < 0 || cell[1U] < 0 || cell[2U] < 0 ||
                        cell[0U] >= static_cast<std::int32_t>(world::VxlMap::width) ||
                        cell[1U] >= static_cast<std::int32_t>(world::VxlMap::depth) ||
                        cell[2U] > 238) {
                        continue;
                    }
                    if (tutorial_session->map().solid(
                            static_cast<std::uint32_t>(cell[0U]),
                            static_cast<std::uint32_t>(cell[1U]),
                            static_cast<std::uint32_t>(cell[2U]))) {
                        // Retail leaves authored world cells in place and the
                        // server charges only the cells that actually become
                        // solid. Do not expect a colour acknowledgement for a
                        // zero-cost overlap.
                        continue;
                    }
                    expected_prefab_colors.push_back(
                        {{static_cast<std::uint32_t>(cell[0U]),
                          static_cast<std::uint32_t>(cell[1U]),
                          static_cast<std::uint32_t>(cell[2U])},
                         {static_cast<std::uint8_t>(
                              (static_cast<unsigned int>(base_color.red) + voxel.color.red) / 2U),
                          static_cast<std::uint8_t>(
                              (static_cast<unsigned int>(base_color.green) + voxel.color.green) /
                              2U),
                          static_cast<std::uint8_t>(
                              (static_cast<unsigned int>(base_color.blue) + voxel.color.blue) / 2U),
                          255U}});
                }
            }

            auto encoded = network::encode_weapon_action(action, wire);
            if (!encoded) {
                // A generic prefab-tool slot has no selected variant; retain
                // the input locally and wait until a prefab slot is chosen.
                settings_warning = encoded.error;
                continue;
            }
            for (const auto& packet : encoded.packets) {
                if (!match_connection->send(packet)) {
                    settings_warning = "failed to queue a weapon action packet";
                    return;
                }
            }
            if (action.kind == world::WeaponActionKind::oriented_item) {
                launcher_muzzle_tracker.remember(
                    action.tool_id,
                    {wire.position[0U], wire.position[1U], wire.position[2U]},
                    {wire.velocity[0U], wire.velocity[1U], wire.velocity[2U]},
                    std::chrono::steady_clock::now());
            }
            if (!expected_prefab_colors.empty() && live_terrain_replica != nullptr) {
                live_terrain_replica->expect_owner_build_colors(
                    wire.loop_count, wire.player_id, expected_prefab_colors);
            }
            if (action.kind == world::WeaponActionKind::prefab_place &&
                world::find_weapon_definition(action.tool_id) != nullptr &&
                world::find_weapon_definition(action.tool_id)->mechanism ==
                    world::WeaponMechanism::ugc_prefab_editor &&
                ugc_prefab_control.active()) {
                // Source exits the prefab camera only after confirm returned
                // true, i.e. after a valid BuildPrefabAction was queued.
                ugc_prefab_control.deactivate();
            }
        }
    }

    void consume_direct_connect(std::optional<DirectConnectAction> action) {
        if (!action.has_value())
            return;
        if (action->kind == DirectConnectActionKind::back) {
            static_cast<void>(navigation.pop());
            play_back();
            return;
        }
        if (const auto steam_id = parse_steam_endpoint(action->endpoint); steam_id != 0U) {
            if (action->kind == DirectConnectActionKind::add_favourite) {
                direct_connect_menu.set_error("Steam matches cannot be saved as favorites");
                return;
            }
            std::string steam_error;
            const auto port = start_steam_client(steam_id, steam_error);
            if (port == 0U) {
                direct_connect_menu.set_error(steam_error.empty()
                                                  ? "Could not reach that Steam host"
                                                  : std::move(steam_error));
                return;
            }
            begin_match_loading(ServerConnectRequest{"steam:" + std::to_string(steam_id),
                                                     "127.0.0.1", port, {}, {}, {}, false,
                                                     steam_join_server_id,
                                                     steam_join_wants_ticket()});
            return;
        }
        network::ServerEndpoint endpoint;
        std::string error;
        if (!network::parse_server_endpoint(action->endpoint, endpoint, error)) {
            direct_connect_menu.set_error(std::move(error));
            return;
        }
        if (action->kind == DirectConnectActionKind::add_favourite) {
            const bool inserted = favourite_servers.insert(endpoint.identifier()).second;
            if (inserted) {
                persist_favourite_servers();
            }
            direct_connect_menu.set_notice(inserted ? "Added to Favorites"
                                                    : "Already in Favorites");
            play_confirm();
            return;
        }
        begin_match_loading(ServerConnectRequest{endpoint.identifier(),
                                                 endpoint.host,
                                                 endpoint.port,
                                                 {},
                                                 {},
                                                 {},
                                                 false,
                                                 {},
                                                 false});
    }

    void handle_server_browser_click(ui::Point point, std::uint8_t click_count) {
        if (contains({45, 532, 135, 45}, point)) {
            static_cast<void>(navigation.pop());
            play_back();
            return;
        }
        if (contains({140, 88, 28, 36}, point)) {
            server_browser.cycle_source(-1);
            begin_server_browser_refresh();
            play_scroll();
            return;
        }
        if (contains({273, 88, 28, 36}, point)) {
            server_browser.cycle_source(1);
            begin_server_browser_refresh();
            play_scroll();
            return;
        }
        if (server_browser.region_tabs_visible() && point.y >= 125 && point.y < 150) {
            constexpr std::array regions{ServerBrowserRegion::us_west,
                                         ServerBrowserRegion::us_east,
                                         ServerBrowserRegion::europe,
                                         ServerBrowserRegion::australia};
            for (std::size_t index{}; index < regions.size(); ++index) {
                const auto left = 61 + static_cast<std::int32_t>(index) * 120;
                if (point.x >= left && point.x < left + 110) {
                    server_browser.set_region(regions[index]);
                    begin_server_browser_refresh();
                    play_scroll();
                    return;
                }
            }
        }
        if (contains({530, 88, 38, 34}, point)) {
            server_browser.set_show_empty_servers(!server_browser.show_empty_servers());
            play_scroll();
            return;
        }
        if (contains({706, 88, 38, 34}, point)) {
            server_browser.set_show_full_servers(!server_browser.show_full_servers());
            play_scroll();
            return;
        }
        constexpr std::array<std::int32_t, 6U> columns{69, 172, 240, 340, 472, 517};
        if (point.y >= 164 && point.y < 191) {
            for (std::size_t index{}; index + 1U < columns.size(); ++index) {
                if (point.x >= columns[index] && point.x < columns[index + 1U]) {
                    server_browser.select_sort_column(static_cast<ServerSortColumn>(index));
                    play_scroll();
                    return;
                }
            }
        }
        if (point.x >= 69 && point.x < 517 && point.y >= 191 && point.y < 461) {
            const auto row = static_cast<std::size_t>((point.y - 191) / 18);
            const auto absolute_row = server_browser.first_visible_row() + row;
            const auto previous_selection = server_browser.selected_visible_row();
            if (const auto request = server_browser.activate_visible_row(absolute_row, click_count);
                request.has_value()) {
                begin_match_loading(*request);
            } else if (server_browser.selected_visible_row() != previous_selection) {
                play_scroll();
            }
            return;
        }
        if (contains({512, 163, 20, 20}, point)) {
            server_browser.scroll_rows(-1);
            play_scroll();
            return;
        }
        if (contains({512, 445, 20, 20}, point)) {
            server_browser.scroll_rows(1);
            play_scroll();
            return;
        }
        if (contains({288, 470, 120, 30}, point)) {
            begin_server_browser_refresh();
            play_confirm();
            return;
        }
        if (contains({417, 470, 113, 30}, point)) {
            const auto selected_identifier = server_browser.selected() == nullptr
                                                 ? std::string{}
                                                 : server_browser.selected()->identifier();
            if (server_browser.toggle_selected_favourite()) {
                const auto* selected = server_browser.selected();
                if (selected != nullptr && selected->favourite) {
                    favourite_servers.insert(selected_identifier);
                } else {
                    favourite_servers.erase(selected_identifier);
                }
                persist_favourite_servers();
                play_confirm();
            }
            return;
        }
        if (contains({543, 447, 190, 54}, point)) {
            if (const auto request = server_browser.connect_request(); request.has_value()) {
                begin_match_loading(*request);
            }
        }
    }

    void consume_custom_match_intent(std::optional<CustomMatchIntent> intent) {
        if (!intent.has_value()) {
            return;
        }
        switch (intent->kind) {
        case CustomMatchIntentKind::back_to_join_match:
            static_cast<void>(navigation.pop());
            play_back();
            break;
        case CustomMatchIntentKind::refresh_lobbies:
            // No lobby discovery adapter is attached yet. Complete with an
            // explicit failure instead of manufacturing rows or leaving an
            // endless in-progress state on screen.
            static_cast<void>(custom_match_menu.complete_refresh({}, false));
            break;
        case CustomMatchIntentKind::join_lobby:
        case CustomMatchIntentKind::create_lobby:
            // The offline model disables both operations. A future lobby
            // service consumes these typed handoffs without changing the UI.
            break;
        }
    }

    void consume_quick_play_intent(std::optional<QuickPlayIntent> intent) {
        if (!intent.has_value()) {
            return;
        }
        std::visit(
            [this](const auto& payload) {
                using Payload = std::decay_t<decltype(payload)>;
                if constexpr (std::is_same_v<Payload, QuickPlayBackIntent>) {
                    cancel_quick_play_refresh();
                    static_cast<void>(navigation.pop());
                    play_back();
                } else if constexpr (std::is_same_v<Payload, QuickPlaySearchIntent>) {
                    begin_quick_play_refresh(payload);
                    play_confirm();
                } else if constexpr (std::is_same_v<Payload, QuickPlayDirectStartIntent>) {
                    network::ServerEndpoint endpoint;
                    std::string error;
                    if (network::parse_server_endpoint(payload.identifier, endpoint, error)) {
                        begin_match_loading(ServerConnectRequest{payload.identifier,
                            endpoint.host, endpoint.port, payload.expected_map,
                            payload.expected_mode, payload.expected_skin,
                            payload.expected_classic, payload.identity_server_id,
                            payload.identity_ticket});
                    }
                } else if constexpr (std::is_same_v<Payload, QuickPlayPlaylistStartIntent>) {
                    if (const auto search = quick_play_menu.begin_search()) {
                        begin_quick_play_refresh(*search);
                    }
                } else if constexpr (std::is_same_v<Payload, QuickPlayBuyIntent>) {
                    if (!window.open_external_url("https://store.steampowered.com/app/420650")) {
                        last_error = "the Mafia DLC store page could not be opened";
                    }
                    play_confirm();
                }
            },
            *intent);
    }

    void update_leaderboard_hover(std::optional<ui::Point> point) {
        if (!point.has_value() || leaderboard_menu.state() != LeaderboardLoadState::ready ||
            leaderboard_menu.open_dropdown() != LeaderboardDropdown::none) {
            static_cast<void>(leaderboard_menu.hover_row(std::nullopt));
            return;
        }
        LeaderboardPresentationContext context;
        context.measure_header_text = [this](std::string_view key, double size) {
            return measure_big_message_line(localized_text(key), size);
        };
        const auto grid = leaderboard_grid_layout(leaderboard_menu, context);
        constexpr double row_height{25.0};
        const auto row_top = grid.header.y + row_height;
        const auto row_bottom = row_top + row_height * static_cast<double>(grid.visible_rows);
        if (static_cast<double>(point->x) < grid.header.x ||
            static_cast<double>(point->x) >= grid.header.x + grid.header.width ||
            static_cast<double>(point->y) < row_top ||
            static_cast<double>(point->y) >= row_bottom) {
            static_cast<void>(leaderboard_menu.hover_row(std::nullopt));
            return;
        }
        const auto visible = static_cast<std::size_t>(
            (static_cast<double>(point->y) - row_top) / row_height);
        const auto row_index = leaderboard_menu.first_visible_row() + visible;
        if (row_index >= leaderboard_menu.rows().size()) {
            static_cast<void>(leaderboard_menu.hover_row(std::nullopt));
            return;
        }
        static_cast<void>(leaderboard_menu.hover_row(row_index));
    }

    void handle_leaderboard_click(ui::Point point) {
        const auto layout = leaderboard_classic_layout();
        LeaderboardPresentationContext presentation_context;
        presentation_context.measure_header_text = [this](std::string_view key, double size) {
            return measure_big_message_line(localized_text(key), size);
        };
        const auto grid = leaderboard_grid_layout(leaderboard_menu, presentation_context);
        const auto as_rect = [](ui::DrawRect value) {
            return ui::Rect{static_cast<std::int32_t>(value.x),
                            static_cast<std::int32_t>(value.y),
                            static_cast<std::int32_t>(value.width),
                            static_cast<std::int32_t>(value.height)};
        };
        const auto dropdown_option = [&](ui::DrawRect title,
                                         std::size_t count)
            -> std::optional<std::size_t> {
            constexpr std::int32_t row_height{20};
            const ui::Rect area{
                static_cast<std::int32_t>(title.x),
                static_cast<std::int32_t>(title.y + title.height + 1.0),
                static_cast<std::int32_t>(title.width),
                row_height * static_cast<std::int32_t>(count)};
            if (!contains(area, point)) return std::nullopt;
            return static_cast<std::size_t>((point.y - area.y) / row_height);
        };

        // DropBoxControl owns focus while open. Its list is tested before the
        // covered grid, and clicking another control first closes this owner.
        if (leaderboard_menu.open_dropdown() == LeaderboardDropdown::type) {
            if (contains(as_rect(layout.type_dropdown), point)) {
                static_cast<void>(
                    leaderboard_menu.toggle_dropdown(LeaderboardDropdown::type));
                play_scroll();
                return;
            }
            if (const auto option = dropdown_option(
                    layout.type_dropdown, LeaderboardMenuModel::type_count);
                option.has_value()) {
                const auto changed = leaderboard_menu.select_type(
                    static_cast<LeaderboardType>(*option));
                if (changed) dispatch_leaderboard_request();
                play_scroll();
                return;
            }
            static_cast<void>(leaderboard_menu.close_dropdown());
        } else if (leaderboard_menu.open_dropdown() ==
                   LeaderboardDropdown::scope) {
            if (contains(as_rect(layout.scope_dropdown), point)) {
                static_cast<void>(
                    leaderboard_menu.toggle_dropdown(LeaderboardDropdown::scope));
                play_scroll();
                return;
            }
            if (const auto option = dropdown_option(
                    layout.scope_dropdown, LeaderboardMenuModel::scope_count);
                option.has_value()) {
                const auto changed = leaderboard_menu.select_scope(
                    static_cast<LeaderboardScope>(*option));
                if (changed) dispatch_leaderboard_request();
                play_scroll();
                return;
            }
            static_cast<void>(leaderboard_menu.close_dropdown());
        }
        if (contains(as_rect(layout.back_button), point)) {
            static_cast<void>(navigation.pop());
            play_back();
        } else if (grid.shows_horizontal_scrollbar &&
                   contains(as_rect({grid.horizontal_scrollbar.x,
                                     grid.horizontal_scrollbar.y,
                                     22.0,
                                     grid.horizontal_scrollbar.height}),
                            point)) {
            if (leaderboard_menu.scroll_stat_columns(-1, grid.visible_stat_columns)) {
                play_scroll();
            }
        } else if (grid.shows_horizontal_scrollbar &&
                   contains(as_rect({grid.horizontal_scrollbar.x +
                                         grid.horizontal_scrollbar.width - 22.0,
                                     grid.horizontal_scrollbar.y,
                                     22.0,
                                     grid.horizontal_scrollbar.height}),
                            point)) {
            if (leaderboard_menu.scroll_stat_columns(1, grid.visible_stat_columns)) {
                play_scroll();
            }
        } else if (grid.shows_vertical_scrollbar &&
                   contains(as_rect({grid.vertical_scrollbar.x,
                                     grid.vertical_scrollbar.y,
                                     grid.vertical_scrollbar.width,
                                     22.0}),
                            point)) {
            if (leaderboard_menu.scroll_rows(-1, grid.visible_rows)) {
                play_scroll();
            }
        } else if (grid.shows_vertical_scrollbar &&
                   contains(as_rect({grid.vertical_scrollbar.x,
                                     grid.vertical_scrollbar.y +
                                         grid.vertical_scrollbar.height - 22.0,
                                     grid.vertical_scrollbar.width,
                                     22.0}),
                            point)) {
            if (leaderboard_menu.scroll_rows(1, grid.visible_rows)) {
                play_scroll();
            }
        } else if (leaderboard_menu.state() == LeaderboardLoadState::ready &&
                   contains(as_rect(layout.table), point)) {
            constexpr std::int32_t header_height{25};
            constexpr std::int32_t row_height{25};
            const auto relative_y = point.y - static_cast<std::int32_t>(grid.header.y);
            if (relative_y >= 0 && relative_y < header_height) {
                const auto column = std::ranges::find_if(grid.columns, [&](const auto& item) {
                    return contains(as_rect(item.bounds), point);
                });
                if (column != grid.columns.end()) {
                    static_cast<void>(leaderboard_menu.sort_by(column->source_index));
                    play_scroll();
                }
            } else if (relative_y >= header_height &&
                       point.x >= static_cast<std::int32_t>(grid.header.x) &&
                       point.x < static_cast<std::int32_t>(grid.header.x + grid.header.width)) {
                const auto visible =
                    static_cast<std::size_t>((relative_y - header_height) / row_height);
                const auto row_index = leaderboard_menu.first_visible_row() + visible;
                const auto rows = leaderboard_menu.rows();
                if (visible < grid.visible_rows && row_index < rows.size()) {
                    // Retail LeaderboardListPanel only selects its row and
                    // paints the green highlight. LeaderboardMenu.on_start
                    // does not attach a profile-opening row callback.
                    if (leaderboard_menu.select_row(row_index)) {
                        play_scroll();
                    }
                }
            }
        } else if (contains(as_rect(layout.type_dropdown), point)) {
            if (leaderboard_menu.toggle_dropdown(LeaderboardDropdown::type)) {
                play_scroll();
            }
        } else if (contains(as_rect(layout.scope_dropdown), point)) {
            if (leaderboard_menu.toggle_dropdown(LeaderboardDropdown::scope)) {
                play_scroll();
            }
        }
    }

    void handle_profile_click(ui::Point point) {
        const auto layout = player_profile_classic_layout();
        const auto as_rect = [](ui::DrawRect value) {
            return ui::Rect{static_cast<std::int32_t>(value.x),
                            static_cast<std::int32_t>(value.y),
                            static_cast<std::int32_t>(value.width),
                            static_cast<std::int32_t>(value.height)};
        };
        if (player_profile_menu.selected_tab()==PlayerProfileTab::inventory && point.y>=138) {
            if (contains({60,500,170,48},point) && !inventory_menu.reveal) {
                static_cast<void>(navigation.pop()); play_back(); return;
            }
            dispatch_inventory_action(inventory_menu.click(point));
            play_scroll(); return;
        }
        if (contains(as_rect(layout.cancel_button), point)) {
            static_cast<void>(navigation.pop());
            play_back();
            return;
        }
        if (contains(as_rect(layout.achievements_button), point)) {
            player_profile_menu.activate_achievements();
            for (const auto& effect : player_profile_menu.take_effects()) {
                if (effect.kind == PlayerProfileEffectKind::show_achievements_overlay &&
                    !window.open_external_url("https://www.aosplay.net/account")) {
                    last_error = "the achievements page could not be opened";
                }
            }
            play_confirm();
            return;
        }
        if (player_profile_menu.filter_open()) {
            const auto& definition =
                player_profile_tab_definition(player_profile_menu.selected_tab());
            constexpr std::int32_t option_height{25};
            const auto option_top = static_cast<std::int32_t>(layout.filter_dropdown.y +
                                                              layout.filter_dropdown.height + 1.0);
            const auto option_count = definition.filter_keys.size() + 1U;
            const ui::Rect options{static_cast<std::int32_t>(layout.filter_dropdown.x),
                                   option_top,
                                   static_cast<std::int32_t>(layout.filter_dropdown.width),
                                   option_height * static_cast<std::int32_t>(option_count)};
            if (contains(options, point)) {
                const auto option =
                    static_cast<std::size_t>((point.y - option_top) / option_height);
                static_cast<void>(player_profile_menu.select_filter(option));
                play_scroll();
                return;
            }
            static_cast<void>(player_profile_menu.close_filter());
        }
        if (contains(as_rect(layout.tab_strip), point)) {
            const auto relative = point.x - static_cast<std::int32_t>(layout.tab_strip.x);
            const auto width =
                std::max(1,
                         static_cast<std::int32_t>(layout.tab_strip.width) /
                             static_cast<std::int32_t>(PlayerProfileMenuModel::tab_count));
            const auto tab = static_cast<std::size_t>(
                std::clamp(relative / width,
                           0,
                           static_cast<std::int32_t>(PlayerProfileMenuModel::tab_count - 1U)));
            static_cast<void>(player_profile_menu.select_tab(static_cast<PlayerProfileTab>(tab)));
            if (player_profile_menu.selected_tab()==PlayerProfileTab::inventory)
                dispatch_inventory_action(InventoryAction::refresh);
            play_scroll();
        } else if (player_profile_menu.filter_visible() &&
                   contains(as_rect(layout.filter_dropdown), point)) {
            static_cast<void>(player_profile_menu.toggle_filter());
            play_scroll();
        }
    }

    void handle_ugc_publish_click(ui::Point point) {
        const auto layout = ugc_publish_classic_layout();
        const auto as_rect = [](ui::DrawRect value) {
            return ui::Rect{static_cast<std::int32_t>(value.x),
                            static_cast<std::int32_t>(value.y),
                            static_cast<std::int32_t>(value.width),
                            static_cast<std::int32_t>(value.height)};
        };

        const auto dialog = ugc_publish_menu.dialog();
        if (dialog != UgcPublishDialog::none) {
            const auto confirm_top = dialog == UgcPublishDialog::confirm_publish ? 410 : 365;
            if (dialog == UgcPublishDialog::confirm_publish ||
                dialog == UgcPublishDialog::confirm_delete) {
                if (contains({205, confirm_top, 160, 50}, point)) {
                    consume_ugc_publish_effect(ugc_publish_menu.confirm_dialog());
                } else if (contains({435, confirm_top, 160, 50}, point)) {
                    consume_ugc_publish_effect(ugc_publish_menu.cancel_dialog());
                }
            } else if (dialog != UgcPublishDialog::uploading &&
                       dialog != UgcPublishDialog::deleting &&
                       contains({320, 365, 160, 50}, point)) {
                consume_ugc_publish_effect(ugc_publish_menu.acknowledge_dialog());
            }
            return;
        }

        if (contains(as_rect(layout.back), point)) {
            consume_ugc_publish_effect(ugc_publish_menu.back());
            return;
        }
        if (ugc_publish_menu.page() == UgcPublishPage::map_list) {
            if (contains(as_rect(layout.delete_button), point)) {
                consume_ugc_publish_effect(ugc_publish_menu.request_delete());
                return;
            }
            const auto rows =
                ui::Rect{static_cast<std::int32_t>(layout.map_first_row.x),
                         static_cast<std::int32_t>(layout.map_first_row.y),
                         static_cast<std::int32_t>(layout.map_first_row.width),
                         static_cast<std::int32_t>(layout.map_first_row.height) *
                             static_cast<std::int32_t>(UgcPublishMenuModel::visible_map_rows)};
            if (contains(rows, point)) {
                const auto row = static_cast<std::size_t>(
                    (point.y - rows.y) /
                    std::max(1,
                             rows.height /
                                 static_cast<std::int32_t>(UgcPublishMenuModel::visible_map_rows)));
                static_cast<void>(ugc_publish_menu.select_visible_row(row));
                play_scroll();
                return;
            }
        }
        if (contains(as_rect(layout.primary_button), point)) {
            consume_ugc_publish_effect(ugc_publish_menu.activate_primary());
        }
    }

    void pointer_release(std::optional<ui::Point> point, std::uint8_t click_count) {
        if (boot_loading || !accepts_input()) {
            return;
        }
        if (markup_inventory_active()) {
            inventory_view->pointer_move(settings_point(point).value_or(ui::Point{-1,-1}));
            inventory_view->pointer_button(false); consume_inventory_view(); return;
        }
        switch (screen()) {
        case FrontendScreen::identity:
            if (const auto action = identity_menu.pointer_release(point); action.has_value()) {
                submit_identity(*action);
            }
            break;
        case FrontendScreen::friends_lobby:
            if (const auto action = friends_lobby_menu.pointer_release(
                    point, std::chrono::steady_clock::now()); action.has_value()) {
                submit_social_intent(*action);
            }
            break;
        case FrontendScreen::select_menu:
            if (const auto action = menu.pointer_release(point); action.has_value()) {
                activate(*action);
            }
            break;
        case FrontendScreen::join_match:
            if (const auto route = join_match_menu.pointer_release(point); route.has_value()) {
                open_join_route(*route);
            }
            break;
        case FrontendScreen::direct_connect:
            consume_direct_connect(direct_connect_menu.pointer_release(point));
            break;
        case FrontendScreen::ugc_select:
            if (const auto action = ugc_select_menu.pointer_release(point); action.has_value()) {
                open_ugc_route(*action);
            }
            break;
        case FrontendScreen::ugc_editor_browser:
            consume_ugc_editor_browser_intent(ugc_editor_browser.pointer_release(point));
            break;
        case FrontendScreen::ugc_editor_lobby:
            consume_ugc_editor_lobby_intent(ugc_editor_lobby.pointer_release(point));
            break;
        case FrontendScreen::tutorial_world:
            // World input is handled by the gameplay event path, not frontend widgets.
            break;
        case FrontendScreen::parity_debug:
            consume_parity_debug_activation(
                parity_debug_menu.pointer_release(settings_point(point)));
            break;
        case FrontendScreen::gameplay_debug:
            break;
        case FrontendScreen::game_loading:
            if (std::exchange(loading_scrollbar_dragging, false)) break;
            if (const auto raw = settings_point(point); raw.has_value()) {
                handle_loading_click(*raw);
            }
            break;
        case FrontendScreen::class_selection:
            if (const auto raw = settings_point(point); raw.has_value()) {
                if (ugc_loadout_active) {
                    auto action = ugc_loadout_menu.click(*raw);
                    if (action.has_value()) {
                        // Terminal paths play their cue after the network or
                        // navigation transaction succeeds.
                        static_cast<void>(ugc_loadout_menu.take_audio_cue());
                    } else {
                        consume_ugc_loadout_audio();
                    }
                    handle_ugc_loadout_action(action);
                } else {
                    auto action = class_selection_menu.click(*raw);
                    if (action.has_value()) {
                        // Terminal paths already play their cue in the navigation
                        // handler; drain the model edge so it cannot leak into the
                        // next selection event.
                        static_cast<void>(class_selection_menu.take_audio_cue());
                    } else {
                        consume_class_selection_audio();
                    }
                    handle_class_selection_action(action);
                }
            }
            break;
        case FrontendScreen::pause_menu:
            consume_pause_action(pause_menu.pointer_release(settings_point(point)));
            break;
        case FrontendScreen::change_team:
            consume_change_team_action(change_team_menu.pointer_release(settings_point(point)));
            break;
        case FrontendScreen::settings:
            if (settings_menu != nullptr) {
                if (const auto raw = settings_point(point); raw.has_value()) {
                    settings_menu->pointer_release(*raw);
                } else {
                    settings_menu->cancel_pointer_capture();
                }
                consume_settings_effects();
            }
            break;
        case FrontendScreen::resolution_confirmation:
            if (const auto action = resolution_confirmation.pointer_release(point);
                action.has_value()) {
                handle_resolution_confirmation(*action);
            }
            break;
        case FrontendScreen::server_browser:
            if (const auto raw = settings_point(point); raw.has_value()) {
                handle_server_browser_click(*raw, click_count);
            }
            server_browser_pointer_down = false;
            break;
        case FrontendScreen::public_match:
            consume_quick_play_intent(quick_play_menu.pointer_release(point));
            break;
        case FrontendScreen::custom_match:
            consume_custom_match_intent(custom_match_menu.pointer_release(point));
            break;
        case FrontendScreen::create_match:
        case FrontendScreen::create_match_rules:
        case FrontendScreen::create_match_maps:
        case FrontendScreen::create_match_lobby:
            if (const auto raw = settings_point(point); raw.has_value()) {
                auto before = create_match_menu.presentation();
                create_match_menu.pointer_release(*raw);
                static_cast<void>(window.set_text_input_enabled(
                    create_match_menu.chat_focused()));
                consume_create_match_effects(std::move(before));
            } else {
                create_match_menu.pointer_press(std::nullopt);
            }
            break;
        case FrontendScreen::leaderboard:
            if (const auto raw = settings_point(point); raw.has_value()) {
                handle_leaderboard_click(*raw);
            }
            break;
        case FrontendScreen::player_profile:
            if (const auto raw = settings_point(point); raw.has_value()) {
                handle_profile_click(*raw);
            }
            profile_pointer_down = false;
            update_profile_control_states(settings_point(point));
            break;
        case FrontendScreen::ugc_publish:
            if (const auto raw = settings_point(point); raw.has_value()) {
                handle_ugc_publish_click(*raw);
            }
            break;
        case FrontendScreen::startup_loading:
            break;
        }
    }

    void cancel_pointer_capture() {
        if (inventory_view) inventory_view->cancel_pointer_capture();
        // Retail MenuScene sends an off-canvas mouse-motion event to both the
        // outgoing and incoming menu whenever a route changes. Clear hover as
        // well as press capture so cached screens cannot re-enter highlighted.
        menu.pointer_move(std::nullopt);
        menu.pointer_press(std::nullopt);
        static_cast<void>(menu.pointer_release(std::nullopt));
        identity_menu.pointer_move(std::nullopt);
        identity_menu.pointer_press(std::nullopt);
        static_cast<void>(identity_menu.pointer_release(std::nullopt));
        friends_lobby_menu.pointer_move(std::nullopt);
        friends_lobby_menu.pointer_press(std::nullopt, std::chrono::steady_clock::now());
        static_cast<void>(friends_lobby_menu.pointer_release(
            std::nullopt, std::chrono::steady_clock::now()));
        join_match_menu.pointer_move(std::nullopt);
        join_match_menu.pointer_press(std::nullopt);
        static_cast<void>(join_match_menu.pointer_release(std::nullopt));
        direct_connect_menu.pointer_move(std::nullopt);
        direct_connect_menu.pointer_press(std::nullopt);
        static_cast<void>(direct_connect_menu.pointer_release(std::nullopt));
        class_selection_menu.pointer_move(std::nullopt);
        ugc_loadout_menu.pointer_move(std::nullopt);
        change_team_menu.pointer_move(std::nullopt);
        change_team_menu.pointer_press(std::nullopt);
        static_cast<void>(change_team_menu.pointer_release(std::nullopt));
        server_browser_pointer.reset();
        server_browser_pointer_down = false;
        loading_scrollbar_dragging = false;
        quick_play_menu.pointer_move(std::nullopt);
        quick_play_menu.pointer_press(std::nullopt);
        static_cast<void>(quick_play_menu.pointer_release(std::nullopt));
        custom_match_menu.pointer_move(std::nullopt);
        custom_match_menu.pointer_press(std::nullopt);
        static_cast<void>(custom_match_menu.pointer_release(std::nullopt));
        ugc_select_menu.pointer_move(std::nullopt);
        ugc_select_menu.pointer_press(std::nullopt);
        static_cast<void>(ugc_select_menu.pointer_release(std::nullopt));
        ugc_editor_browser.pointer_move(std::nullopt);
        ugc_editor_browser.pointer_press(std::nullopt);
        static_cast<void>(ugc_editor_browser.pointer_release(std::nullopt));
        ugc_editor_lobby.pointer_move(std::nullopt);
        ugc_editor_lobby.pointer_press(std::nullopt);
        static_cast<void>(ugc_editor_lobby.pointer_release(std::nullopt));
        parity_debug_menu.pointer_move(std::nullopt);
        parity_debug_menu.pointer_press(std::nullopt);
        static_cast<void>(parity_debug_menu.pointer_release(std::nullopt));
        static_cast<void>(leaderboard_menu.hover_row(std::nullopt));
        profile_pointer_down = false;
        update_profile_control_states(std::nullopt);
        if (settings_menu != nullptr) {
            settings_menu->cancel_pointer_capture();
            settings_menu->pointer_move(std::nullopt);
        }
        resolution_confirmation.cancel_pointer_capture();
        resolution_confirmation.pointer_move(std::nullopt);
        create_match_menu.pointer_move(std::nullopt);
        create_match_menu.pointer_press(std::nullopt);
    }

    [[nodiscard]] bool handle_input(ui::InputEvent event) {
        if (boot_loading || !accepts_input()) {
            return false;
        }
        if (markup_inventory_active()) { inventory_view->input(event); consume_inventory_view(); return true; }
        if (event.action == ui::InputAction::cancel && event.phase == ui::InputPhase::pressed) {
            // Recovered EscapeMenu flow: Escape in the world opens the pause
            // menu with the open cue; Escape inside it resumes with confirm.
            if (screen() == FrontendScreen::tutorial_world) {
                // A multiplayer pause is an overlay, not a simulation pause.
                // Clear held input immediately, then keep fixed-step gravity
                // and prediction running beneath the menu.
                if (tutorial_session != nullptr) {
                    tutorial_session->clear_input();
                }
                refresh_pause_menu();
                if (navigation.push_instant(FrontendScreen::pause_menu)) {
                    send_client_in_menu(true);
                    play_back();
                }
                return true;
            }
            if (screen() == FrontendScreen::pause_menu) {
                send_client_in_menu(false);
                static_cast<void>(navigation.pop_instant());
                play_confirm();
                return true;
            }
            if (screen() == FrontendScreen::change_team) {
                consume_change_team_action(ChangeTeamAction::back);
                return true;
            }
            if (screen() == FrontendScreen::class_selection) {
                if (ugc_loadout_active) {
                    handle_ugc_loadout_action(UgcLoadoutAction::back);
                } else {
                    handle_class_selection_action(ClassSelectionAction::back);
                }
                return true;
            }
            if (screen() == FrontendScreen::friends_lobby) {
                submit_social_intent({FriendsLobbyActionKind::back, {}, {}});
                return true;
            }
        }
        if (event.action == ui::InputAction::cancel && event.phase == ui::InputPhase::pressed &&
            screen() != FrontendScreen::select_menu && screen() != FrontendScreen::identity &&
            screen() != FrontendScreen::resolution_confirmation &&
            screen() != FrontendScreen::ugc_publish &&
            screen() != FrontendScreen::ugc_editor_browser &&
            screen() != FrontendScreen::ugc_editor_lobby && !is_create_match_screen(screen())) {
            if (screen() == FrontendScreen::settings && settings_menu != nullptr) {
                const auto handled = settings_menu->handle(event);
                consume_settings_effects();
                return handled;
            }
            static_cast<void>(navigation.pop());
            play_back();
            return true;
        }

        switch (screen()) {
        case FrontendScreen::identity:
            if (event.action == ui::InputAction::focus_next &&
                event.phase == ui::InputPhase::pressed) {
                identity_menu.focus_next();
                return true;
            }
            if (event.action == ui::InputAction::activate &&
                event.phase == ui::InputPhase::pressed) {
                submit_identity(IdentityAction::login);
                return true;
            }
            return false;
        case FrontendScreen::friends_lobby:
            if (!event.triggers_action()) return false;
            if (event.action == ui::InputAction::navigate_up || event.action == ui::InputAction::navigate_down) {
                if (friends_lobby_menu.move_selection(event.action == ui::InputAction::navigate_down ? 1 : -1))
                    play_scroll();
                return true;
            }
            if (event.action == ui::InputAction::navigate_left || event.action == ui::InputAction::navigate_right ||
                event.action == ui::InputAction::focus_next || event.action == ui::InputAction::focus_previous) {
                if (friends_lobby_menu.cycle_tab(event.action == ui::InputAction::navigate_left ||
                    event.action == ui::InputAction::focus_previous ? -1 : 1)) play_scroll();
                return true;
            }
            if (event.action == ui::InputAction::activate) {
                if (friends_lobby_menu.search_focused()) {
                    if (!friends_lobby_menu.search_text().empty())
                        submit_social_intent({FriendsLobbyActionKind::search, {},
                                              std::string{friends_lobby_menu.search_text()}});
                } else if (const auto action = friends_lobby_menu.primary_button().intent) {
                    submit_social_intent(*action);
                }
                return true;
            }
            return false;
        case FrontendScreen::player_profile:
            if (!event.triggers_action()) return false;
            if (player_profile_menu.selected_tab()==PlayerProfileTab::inventory) {
                if (event.action==ui::InputAction::navigate_up || event.action==ui::InputAction::navigate_down) {
                    inventory_menu.move_selection(event.action==ui::InputAction::navigate_down?1:-1); return true;
                }
                if (event.action==ui::InputAction::navigate_left || event.action==ui::InputAction::navigate_right) {
                    const auto index=static_cast<int>(inventory_menu.section);
                    inventory_menu.section=static_cast<InventorySection>((index+(event.action==ui::InputAction::navigate_right?1:3))%4);
                    inventory_menu.page=inventory_menu.selected=0U; return true;
                }
                if (event.action==ui::InputAction::activate && event.phase==ui::InputPhase::pressed) { dispatch_inventory_action(inventory_menu.click({625,524})); return true; }
            }
            if (event.action==ui::InputAction::focus_next) {
                const auto tab=(static_cast<std::size_t>(player_profile_menu.selected_tab())+1U)%PlayerProfileMenuModel::tab_count;
                static_cast<void>(player_profile_menu.select_tab(static_cast<PlayerProfileTab>(tab)));
                if (player_profile_menu.selected_tab()==PlayerProfileTab::inventory && !inventory_menu.loaded) dispatch_inventory_action(InventoryAction::refresh);
                return true;
            }
            return false;
        case FrontendScreen::select_menu:
            if (const auto action = menu.handle(event); action.has_value()) {
                activate(*action);
                return true;
            }
            return false;
        case FrontendScreen::join_match:
            if (const auto route = join_match_menu.handle(event); route.has_value()) {
                open_join_route(*route);
                return true;
            }
            return false;
        case FrontendScreen::direct_connect:
            if (event.action == ui::InputAction::activate && event.triggers_action()) {
                consume_direct_connect(direct_connect_menu.submit());
                return true;
            }
            return false;
        case FrontendScreen::public_match:
            consume_quick_play_intent(quick_play_menu.handle(event));
            return true;
        case FrontendScreen::custom_match:
            consume_custom_match_intent(custom_match_menu.handle(event));
            return true;
        case FrontendScreen::ugc_select:
            if (const auto action = ugc_select_menu.handle(event); action.has_value()) {
                open_ugc_route(*action);
                return true;
            }
            return false;
        case FrontendScreen::ugc_editor_browser:
            consume_ugc_editor_browser_intent(ugc_editor_browser.handle(event));
            return true;
        case FrontendScreen::ugc_editor_lobby:
            consume_ugc_editor_lobby_intent(ugc_editor_lobby.handle(event));
            return true;
        case FrontendScreen::ugc_publish:
            consume_ugc_publish_effect(ugc_publish_menu.handle(event));
            return true;
        case FrontendScreen::parity_debug:
            consume_parity_debug_activation(parity_debug_menu.handle(event));
            return true;
        case FrontendScreen::gameplay_debug:
            return false;
        case FrontendScreen::class_selection:
            if (!event.triggers_action())
                return false;
            if (event.action == ui::InputAction::activate) {
                if (ugc_loadout_active) {
                    handle_ugc_loadout_action(UgcLoadoutAction::submit);
                } else {
                    handle_class_selection_action(ClassSelectionAction::submit);
                }
                return true;
            }
            if (event.action == ui::InputAction::navigate_left ||
                event.action == ui::InputAction::navigate_right) {
                if (ugc_loadout_active) {
                    const auto tab_count = ugc_loadout_menu.tabs().size();
                    if (tab_count > 0U) {
                        auto index = ugc_loadout_menu.current_tab_index();
                        if (event.action == ui::InputAction::navigate_right) {
                            index = (index + 1U) % tab_count;
                        } else {
                            index = index == 0U ? tab_count - 1U : index - 1U;
                        }
                        ugc_loadout_menu.select_tab(index);
                        play_scroll();
                    }
                } else {
                    class_selection_menu.cycle_class(
                        event.action == ui::InputAction::navigate_right ? 1 : -1);
                    consume_class_selection_audio();
                }
                return true;
            }
            return false;
        case FrontendScreen::settings:
            if (settings_menu != nullptr) {
                const auto handled = settings_menu->handle(event);
                consume_settings_effects();
                return handled;
            }
            return false;
        case FrontendScreen::create_match:
        case FrontendScreen::create_match_rules:
        case FrontendScreen::create_match_maps:
        case FrontendScreen::create_match_lobby: {
            auto before = create_match_menu.presentation();
            const auto handled = create_match_menu.handle(event);
            consume_create_match_effects(std::move(before));
            return handled;
        }
        default:
            return false;
        }
    }

    void mouse_wheel(ui::Point point, std::int32_t steps) {
        if (boot_loading || !accepts_input() || steps == 0) {
            return;
        }
        switch (screen()) {
        case FrontendScreen::friends_lobby:
            if (friends_lobby_menu.scroll_rows_at(steps > 0 ? -1 : 1,
                    ui::Point{point.x * FriendsLobbyMenuModel::subpixels_per_pixel,
                              point.y * FriendsLobbyMenuModel::subpixels_per_pixel})) play_scroll();
            break;
        case FrontendScreen::game_loading:
            if (loading_layout::contains(loading_layout::score_viewport, point.x, point.y) &&
                match_loading.scroll_scores(-steps)) play_scroll();
            break;
        case FrontendScreen::settings:
            if (settings_menu != nullptr) {
                static_cast<void>(settings_menu->mouse_wheel(point, steps));
                consume_settings_effects();
            }
            break;
        case FrontendScreen::server_browser: {
            server_browser.scroll_rows(steps > 0 ? -1 : 1);
            play_scroll();
            break;
        }
        case FrontendScreen::public_match:
            break;
        case FrontendScreen::custom_match:
            custom_match_menu.scroll_rows(steps > 0 ? -1 : 1);
            play_scroll();
            break;
        case FrontendScreen::ugc_editor_browser:
            ugc_editor_browser.scroll_rows(steps > 0 ? -1 : 1);
            play_scroll();
            break;
        case FrontendScreen::leaderboard:
            {
                LeaderboardPresentationContext context;
                context.measure_header_text = [this](std::string_view key, double size) {
                    return measure_big_message_line(localized_text(key), size);
                };
                const auto grid = leaderboard_grid_layout(leaderboard_menu, context);
                if (leaderboard_menu.scroll_rows(-steps, grid.visible_rows)) {
                    play_scroll();
                }
            }
            break;
        case FrontendScreen::player_profile:
            if (markup_inventory_active()) { inventory_view->wheel(steps); break; }
            if (player_profile_menu.selected_tab()==PlayerProfileTab::inventory) inventory_menu.move_selection(-steps);
            else static_cast<void>(player_profile_menu.scroll_rows(-steps));
            play_scroll();
            break;
        case FrontendScreen::class_selection:
            // Retail routes vertical wheel motion into the horizontal class
            // scrollbar. It moves the five-card viewport by one item and does
            // not silently change the selected class.
            if (ugc_loadout_active) {
                ugc_loadout_menu.scroll_rows(steps > 0 ? -1 : 1);
                consume_ugc_loadout_audio();
            } else {
                class_selection_menu.scroll_classes(steps > 0 ? -1 : 1);
                consume_class_selection_audio();
            }
            break;
        case FrontendScreen::ugc_publish:
            ugc_publish_menu.scroll_rows(-steps);
            play_scroll();
            break;
        case FrontendScreen::parity_debug: {
            const auto delta = steps > 0 ? -1 : 1;
            if (point.x >= 401 && point.x < 741 && point.y >= 95 && point.y < 449) {
                parity_debug_menu.scroll_details(delta);
            } else {
                parity_debug_menu.scroll_rows(delta);
            }
            play_scroll();
            break;
        }
        case FrontendScreen::gameplay_debug:
            gameplay_debug_lab.cycle_tool(steps > 0 ? -1 : 1);
            break;
        case FrontendScreen::create_match:
        case FrontendScreen::create_match_rules:
        case FrontendScreen::create_match_maps:
        case FrontendScreen::create_match_lobby: {
            auto before = create_match_menu.presentation();
            static_cast<void>(create_match_menu.mouse_wheel(steps));
            consume_create_match_effects(std::move(before));
        } break;
        default:
            break;
        }
    }

    [[nodiscard]] text::TextRasterizer* configured_font(std::string_view asset) noexcept {
        if (asset == main_menu_assets::button_font) {
            return spades_font.get();
        }
        if (asset == main_menu_assets::welcome_font || asset == settings_standard_font) {
            return welcome_font.get();
        }
        if (asset == settings_edo_font) {
            return edo_font.get();
        }
        if (asset == settings_bold_font) {
            return bold_font.get();
        }
        if (asset == tuffy_font_asset) {
            return tuffy_font.get();
        }
        if (asset == mplus_font_asset || asset == mplus_compact_font_asset) {
            return mplus_font.get();
        }
        if (asset == noto_japanese_font_asset || asset == noto_japanese_compact_font_asset) {
            return noto_japanese_font.get();
        }
        return nullptr;
    }

    /**
     * Apply the font aliases selected by aoslib.strings before text.set_fonts().
     *
     * The retail client did not merely fall back when a glyph was missing: it
     * replaced complete font roles for Russian, Polish, Turkish and Japanese.
     * Preserving those aliases prevents one translated screen from mixing
     * A750, Edo, Tuffy and Noto depending on the particular letters in a row.
     */
    [[nodiscard]] text::TextRasterizer* locale_font(std::string_view asset) noexcept {
        auto locale = localization.active_locale();
        if (const auto separator = locale.find('-'); separator != std::string_view::npos) {
            locale = locale.substr(0U, separator);
        }
        const auto standard_role = asset == main_menu_assets::welcome_font ||
                                   asset == settings_standard_font ||
                                   asset == settings_bold_font;
        const auto aldo_role = asset == main_menu_assets::button_font;
        const auto edo_role = asset == settings_edo_font;

        if (locale == "ru" || locale == "pl") {
            if (standard_role) return tuffy_font.get();
            if (edo_role) return spades_font.get();
        } else if (locale == "tr") {
            if (standard_role) return tuffy_font.get();
            if (aldo_role) return edo_font.get();
        } else if (locale == "ja") {
            if (standard_role) return noto_japanese_font.get();
            if (aldo_role || edo_role) return mplus_font.get();
        } else if (locale == "bg" || locale == "uk") {
            // These revival community packs have no retail font policy. Use
            // their declared Cyrillic face consistently rather than allowing
            // partial glyph coverage in the decorative Latin fonts to split
            // a single screen across unrelated typefaces.
            return configured_font(localization.active_font_asset());
        }
        return configured_font(asset);
    }

    /** Prefer complete coverage, then render unavailable symbols as .notdef. */
    [[nodiscard]] text::TextRasterizer* font_for_text(std::string_view asset,
                                                      std::string_view utf8,
                                                      text::TextCase text_case =
                                                          text::TextCase::preserve) noexcept {
        std::array<text::TextRasterizer*, 6U> candidates{
            locale_font(asset),
            configured_font(asset),
            configured_font(localization.active_font_asset()),
            tuffy_font.get(),
            noto_japanese_font.get(),
            mplus_font.get(),
        };
        // Legacy servers can supply arbitrary Unicode names (including flag
        // emoji). Exhaust the locale faces first, but never end a match just
        // because the installed fonts lack one symbol in a roster/chat row.
        if (auto* selected = text::select_text_font(candidates, utf8, text_case))
            return selected;
        last_error = "no loaded UI font covers text for locale '" +
                     std::string{localization.active_locale()} + "' (faces:";
        for (const auto* candidate : candidates) {
            if (candidate == nullptr) {
                last_error += " <null>";
            } else {
                last_error += " ";
                last_error += candidate->font_asset_id();
                last_error += candidate->ready() ? "[ready]" : "[failed]";
            }
        }
        last_error += "; utf8=";
        constexpr char hex_digits[]{"0123456789ABCDEF"};
        for (const auto byte : utf8) {
            const auto value = static_cast<std::uint8_t>(byte);
            last_error.push_back(hex_digits[value >> 4U]);
            last_error.push_back(hex_digits[value & 0x0FU]);
        }
        last_error += ")";
        return nullptr;
    }

    std::string cosmetic_weapon_icon(std::uint8_t tool,std::string_view fallback,bool blue_team){
        const auto* item=local_equipped_cosmetic("weapon:"+std::to_string(tool)+":view");
        if(!item)item=local_equipped_cosmetic("weapon:"+std::to_string(tool)+":world");
        if(!item)return std::string{fallback};
        if(!cosmetic_icons)cosmetic_icons=std::make_unique<CosmeticIconCache>(config.asset_root);
        CosmeticIconRequest request;request.item=*item;request.blue_team=blue_team;
        if(skin_variant_preferences)request.variants=skin_variant_preferences->selection(item->id);
        return cosmetic_icons->request(request,fallback);
    }
    std::string cosmetic_class_icon(std::uint8_t klass,bool blue_team,bool portrait,std::string_view fallback){
        const auto* body=local_equipped_cosmetic("class:"+std::to_string(klass)+":body");
        const auto* hat=local_equipped_cosmetic("class:"+std::to_string(klass)+":hat");
        if(!body&&!hat)return std::string{fallback};
        if(!cosmetic_icons)cosmetic_icons=std::make_unique<CosmeticIconCache>(config.asset_root);
        CosmeticIconRequest request;request.item=body?*body:*hat;request.class_id=klass;request.blue_team=blue_team;
        request.kind=portrait?CosmeticIconKind::class_body:CosmeticIconKind::class_head;
        if(body&&hat)request.hat=*hat;
        return cosmetic_icons->request(request,fallback);
    }
    ClassSelectionAppearance class_selection_icons(){
        ClassSelectionAppearance appearance;const bool blue=class_selection_menu.team()!=3U;const auto team=blue?0U:1U;
        const auto classes=class_selection_menu.classes();
        const auto first=class_selection_menu.visible_class_offset(),last=std::min(classes.size(),first+class_selection_menu.classes_per_page());
        for(auto i=first;i<last;++i)if(const auto* klass=world::find_class_definition(classes[i]))
            appearance.class_icons[classes[i]]=cosmetic_class_icon(classes[i],blue,false,klass->team_icon_assets[team]);
        if(const auto* klass=world::find_class_definition(class_selection_menu.selected_class())){
            appearance.class_portraits[klass->class_id]=cosmetic_class_icon(klass->class_id,blue,true,klass->team_portrait_assets[team]);
            for(const auto group:klass->item_groups)for(const auto tool:group)if(tool<world::weapon_catalog().size())
                appearance.weapon_icons[tool]=cosmetic_weapon_icon(static_cast<std::uint8_t>(tool),class_selection_item_icon(tool),blue);
        }
        return appearance;
    }

    [[nodiscard]] std::optional<render::UiTextureInfo> image_texture(std::string_view asset,
                                                                     render::TextureFilter filter) {
        if(cosmetic_icons&&asset.starts_with("runtime/cosmetic/"))return cosmetic_icons->texture(asset);
        // `png/high/white.png` is retail's solid-quad source. Loading the tiny
        // uniform PNG through the image decoder may select a single-channel
        // texture format; the UI shader then observes only red and every
        // blue/green roster stripe becomes red/black. The startup-created
        // RGBA8 white pixel is the canonical equivalent for every sampling
        // request (filtering cannot change a uniform 1x1 image).
        if (asset == game_hud_assets::white_pixel) {
            const auto solid_key = texture_key(
                game_hud_assets::white_pixel, render::TextureFilter::nearest);
            if (const auto solid = image_textures.find(solid_key);
                solid != image_textures.end()) {
                return solid->second;
            }
        }
        std::string selected_asset{asset};
        if (!asset.starts_with("runtime/") && active_ui_skin != "default") {
            if (const auto* skin = world::find_ui_skin(active_ui_skin);
                skin != nullptr && !skin->asset_prefix.empty()) {
                const auto candidate =
                    std::filesystem::path{skin->asset_prefix} / std::filesystem::path{asset};
                if (std::filesystem::is_regular_file(config.asset_root / candidate)) {
                    selected_asset = candidate.generic_string();
                }
            }
        }
        const auto key = texture_key(selected_asset, filter);
        if (const auto existing = image_textures.find(key); existing != image_textures.end()) {
            return existing->second;
        }
        const auto loaded = renderer.load_texture(std::filesystem::path{selected_asset}, filter);
        if (!loaded.has_value()) {
            last_error = "failed to load UI texture '" + selected_asset +
                         "': " + std::string{renderer.last_error()};
            return std::nullopt;
        }
        image_textures.emplace(key, *loaded);
        return loaded;
    }

    [[nodiscard]] std::optional<render::UiTextureInfo>
    text_texture(text::TextRasterizer& rasterizer, const text::TextRasterResult& raster) {
        if (!raster || raster.output->bitmap.width == 0U || raster.output->bitmap.height == 0U) {
            return std::nullopt;
        }
        const auto key = std::string{rasterizer.font_asset_id()} + ':' + raster.cache_key.canonical;
        if (const auto existing = text_textures.find(key); existing != text_textures.end()) {
            existing->second.last_prepared_frame = text_cache_frame;
            return existing->second.info;
        }
        if (text_textures.size() >= 512U) {
            last_error = "UI glyph texture cache reached its bounded 512-entry limit";
            return std::nullopt;
        }
        const auto& bitmap = raster.output->bitmap;
        const auto uploaded =
            renderer.create_texture_rgba8(bitmap.pixels,
                                          render::UiExtent{bitmap.width, bitmap.height},
                                          // Design-space text is rasterized at
                                          // the drawable's physical scale.
                                          // Point sampling keeps the solved
                                          // FreeType edges intact instead of
                                          // blurring them a second time.
                                          render::TextureFilter::nearest);
        if (!uploaded.has_value()) {
            last_error = "failed to upload UI glyph texture: " + std::string{renderer.last_error()};
            return std::nullopt;
        }
        text_textures.emplace(key, CachedTextTexture{*uploaded, text_cache_frame});
        return uploaded;
    }

    /** Must run outside begin/end frame: releasing textures mid-frame is illegal. */
    void evict_stale_text_textures() {
        if (text_textures.size() <= text_cache_soft_limit) {
            return;
        }
        for (auto entry = text_textures.begin(); entry != text_textures.end();) {
            if (entry->second.last_prepared_frame != text_cache_frame) {
                static_cast<void>(renderer.release_texture(entry->second.info.texture));
                entry = text_textures.erase(entry);
            } else {
                ++entry;
            }
        }
    }

    void release_text_textures() noexcept {
        for (const auto& [key, texture] : text_textures) {
            static_cast<void>(key);
            static_cast<void>(renderer.release_texture(texture.info.texture));
        }
        text_textures.clear();
    }

    [[nodiscard]] bool draw_sprite(const ui::SpriteDrawCommand& command) {
        const auto filter = texture_filter(command.sampling);
        const auto texture = image_texture(command.asset_id, filter);
        if (!texture.has_value()) {
            return false;
        }
        return renderer.draw(render::UiSprite{
            texture->texture,
            rectangle(command.destination),
            command.source_pixels.has_value()
                ? std::optional<render::UiRect>{rectangle(*command.source_pixels)}
                : std::nullopt,
            command.clip_pixels.has_value()
                ? std::optional<render::UiRect>{rectangle(*command.clip_pixels)}
                : std::nullopt,
            color(command.modulation),
            draw_space(command.space),
            static_cast<float>(command.rotation_degrees),
        });
    }

    [[nodiscard]] text::TextRasterResult rasterized_text(
        const ui::TextDrawCommand& command, std::string_view display_text,
        std::uint32_t pixel_height) {
        const auto text_case = command.transform == ui::TextTransform::uppercase
                                   ? text::TextCase::unicode_uppercase
                                   : text::TextCase::preserve;
        auto* const rasterizer =
            font_for_text(command.preferred_font_asset, display_text, text_case);
        if (rasterizer == nullptr || !rasterizer->ready()) {
            last_error = rasterizer == nullptr ? last_error
                                               : std::string{rasterizer->initialization_error()};
            return {nullptr,
                    {},
                    text::TextErrorCode::not_ready,
                    last_error,
                    false};
        }
        return rasterizer->rasterize(text::TextRasterRequest{
            std::string{display_text},
            text_case,
            pixel_height,
            command.retail_outline_stroke,
        });
    }

    [[nodiscard]] text::TextRasterResult rasterized(const ui::TextDrawCommand& command,
                                                    std::uint32_t pixel_height) {
        return rasterized_text(command, localized_text(command.localization_key), pixel_height);
    }

    struct FittedText final {
        text::TextRasterResult raster;
        /** Converts physical glyph-bitmap metrics back to 800x600 design pixels. */
        double design_pixels_per_bitmap_pixel{1.0};
        /** Post-raster FTGL-style width scale used by retail text helpers. */
        double layout_scale{1.0};

        [[nodiscard]] explicit operator bool() const noexcept {
            return static_cast<bool>(raster);
        }
    };

    [[nodiscard]] ui::CanvasTextRasterization
    text_rasterization(const ui::TextDrawCommand& command,
                       std::uint32_t design_pixel_height) const noexcept {
        const ui::CanvasTextRasterization retail{
            .pixel_height = design_pixel_height,
            .design_pixels_per_bitmap_pixel = 1.0,
        };
        if (command.space != ui::DrawSpace::design_pixels || drawable_extent.width == 0U ||
            drawable_extent.height == 0U) {
            return retail;
        }
        const auto viewport = design_canvas.viewport(ui::PixelExtent{
            static_cast<std::int32_t>(drawable_extent.width),
            static_cast<std::int32_t>(drawable_extent.height),
        });
        if (!viewport.has_value()) {
            return retail;
        }
        return ui::resolve_canvas_text_rasterization(
                   static_cast<double>(design_pixel_height), *viewport)
            .value_or(retail);
    }

    [[nodiscard]] FittedText fitted_text(const ui::TextDrawCommand& command) {
        auto requested_height = static_cast<std::uint32_t>(
            std::max(1.0, std::floor(command.requested_font_size_pixels + 0.5)));
        auto raster = rasterized(command, requested_height);
        if (!raster) {
            return FittedText{std::move(raster), 1.0, 1.0};
        }
        if (command.fit == ui::TextFit::shrink_to_fit) {
            const auto geometry_scale =
                std::isfinite(command.geometric_scale)
                    ? std::max(0.0, command.geometric_scale)
                    : 1.0;
            const auto width = static_cast<double>(
                                   raster.output->metrics.content_width_pixels) *
                               geometry_scale;
            const auto height = static_cast<double>(
                                    raster.output->metrics.line_height_pixels) *
                                geometry_scale;
            const auto scale = std::min({1.0,
                                         width > 0.0 ? command.destination.width / width : 1.0,
                                         height > 0.0 ? command.destination.height / height : 1.0});
            const auto fitted_height = static_cast<std::uint32_t>(
                std::max(1.0, std::floor(static_cast<double>(requested_height) * scale)));
            if (fitted_height < requested_height) {
                requested_height = fitted_height;
                raster = rasterized(command, fitted_height);
                if (!raster) {
                    return FittedText{std::move(raster), 1.0, 1.0};
                }
            }
        }

        // The Python Font(enable_resize=True) path re-created menu glyphs for
        // the active aspect scale. Match that without moving any recovered
        // 800x600 layout: upload a physical-resolution bitmap, then express its
        // quad and metrics back in design pixels.
        const auto rasterization = text_rasterization(command, requested_height);
        if (rasterization.pixel_height != requested_height) {
            raster = rasterized(command, rasterization.pixel_height);
        }
        auto layout_scale = 1.0;
        if (command.fit == ui::TextFit::retail_width_scale) {
            const auto content_width =
                static_cast<double>(raster.output->metrics.content_width_pixels) *
                rasterization.design_pixels_per_bitmap_pixel;
            if (content_width >= command.destination.width && content_width > 0.0) {
                layout_scale = command.destination.width / content_width;
            }
        }
        return FittedText{std::move(raster),
                          rasterization.design_pixels_per_bitmap_pixel,
                          layout_scale};
    }

    struct RetailWrappedText final {
        std::vector<text::TextRasterResult> lines;
        double design_pixels_per_bitmap_pixel{1.0};
        double line_scale{1.0};
        double line_advance_pixels{};
        std::string error;

        [[nodiscard]] explicit operator bool() const noexcept {
            return error.empty();
        }
    };

    /**
     * Reproduce text.py:split_text_to_fit_screen(..., frame_offset=10,
     * allow_word_breaking=False) with the active font metrics.
     */
    [[nodiscard]] std::vector<std::string> retail_wrap_lines(
        const ui::TextDrawCommand& command, std::string_view display_text,
        std::uint32_t pixel_height, double design_pixels_per_bitmap_pixel,
        bool& valid) {
        std::vector<std::string> output;
        const auto measured_width = [&](std::string_view value) -> std::optional<double> {
            auto raster = rasterized_text(command, value, pixel_height);
            if (!raster) {
                valid = false;
                return std::nullopt;
            }
            return static_cast<double>(raster.output->metrics.content_width_pixels) *
                   design_pixels_per_bitmap_pixel;
        };
        const auto append_source_line = [&](std::string_view source_line) {
            const auto whole_width = measured_width(source_line);
            if (!whole_width.has_value()) return;
            if (*whole_width + 10.0 < command.destination.width) {
                output.emplace_back(source_line);
                return;
            }

            std::vector<std::string> words;
            std::size_t word_begin{};
            while (true) {
                const auto separator = source_line.find(' ', word_begin);
                words.emplace_back(source_line.substr(
                    word_begin, separator == std::string_view::npos
                                    ? source_line.size() - word_begin
                                    : separator - word_begin));
                if (separator == std::string_view::npos) break;
                word_begin = separator + 1U;
            }

            std::optional<std::string> pending;
            for (const auto& word : words) {
                if (!pending.has_value()) {
                    pending = word;
                    continue;
                }
                const auto joined = *pending + " " + word;
                const auto joined_width = measured_width(joined);
                if (!joined_width.has_value()) return;
                if (*joined_width + 10.0 < command.destination.width) {
                    *pending = joined;
                } else {
                    output.push_back(*pending);
                    pending = word;
                }
            }
            if (pending.has_value()) output.push_back(*pending);
        };

        std::size_t line_begin{};
        while (true) {
            const auto newline = display_text.find('\n', line_begin);
            append_source_line(display_text.substr(
                line_begin, newline == std::string_view::npos
                                ? display_text.size() - line_begin
                                : newline - line_begin));
            if (!valid || newline == std::string_view::npos) break;
            line_begin = newline + 1U;
        }
        return output;
    }

    [[nodiscard]] RetailWrappedText fitted_retail_wrapped_text(
        const ui::TextDrawCommand& command) {
        RetailWrappedText fitted;
        const auto display_text = localized_text(command.localization_key);
        if (display_text.empty()) return fitted;

        auto font_height = static_cast<std::uint32_t>(
            std::max(1.0, std::floor(command.requested_font_size_pixels + 0.5)));
        std::vector<std::string> lines;
        ui::CanvasTextRasterization rasterization{};
        text::TextRasterResult metric_raster;
        while (true) {
            rasterization = text_rasterization(command, font_height);
            bool valid = true;
            lines = retail_wrap_lines(command, display_text,
                                      rasterization.pixel_height,
                                      rasterization.design_pixels_per_bitmap_pixel,
                                      valid);
            metric_raster = rasterized_text(command, "M", rasterization.pixel_height);
            if (!valid || !metric_raster) {
                fitted.error = last_error.empty() ? "failed to measure wrapped retail text"
                                                  : last_error;
                return fitted;
            }
            const auto char_height =
                static_cast<double>(metric_raster.output->metrics.line_height_pixels) *
                rasterization.design_pixels_per_bitmap_pixel;
            const auto line_count = static_cast<double>(lines.size());
            const auto lines_height =
                (command.line_spacing_pixels + char_height) * line_count;
            if (command.layout == ui::TextLayout::bounded_wrapped_lines) {
                const auto limit = std::max<std::size_t>(1U, std::min<std::size_t>(
                    command.maximum_lines, static_cast<std::size_t>(std::max(1.0,
                        std::floor(command.destination.height / std::max(1.0, char_height))))));
                const bool overflow = lines.size() > limit;
                if (overflow) lines.resize(limit);
                for (std::size_t index{}; index < lines.size(); ++index) {
                    auto& line = lines[index];
                    const auto measure = [&](std::string_view value) {
                        const auto raster = rasterized_text(command, value, rasterization.pixel_height);
                        return raster ? static_cast<double>(raster.output->metrics.content_width_pixels) *
                            rasterization.design_pixels_per_bitmap_pixel : command.destination.width + 1.0;
                    };
                    if ((overflow && index + 1U == lines.size()) || measure(line) > command.destination.width) {
                        while (!line.empty() && measure(line + "...") > command.destination.width) {
                            auto boundary = line.size() - 1U;
                            while (boundary > 0U && (static_cast<unsigned char>(line[boundary]) & 0xC0U) == 0x80U)
                                --boundary;
                            line.resize(boundary);
                        }
                        line += "...";
                    }
                }
                break;
            }
            if (lines_height <= command.destination.height || font_height <= 1U) break;
            --font_height;
        }

        fitted.design_pixels_per_bitmap_pixel =
            rasterization.design_pixels_per_bitmap_pixel;
        fitted.lines.reserve(lines.size());
        for (const auto& line : lines) {
            auto raster = rasterized_text(command, line, rasterization.pixel_height);
            if (!raster) {
                fitted.error = last_error.empty() ? "failed to rasterize wrapped retail text"
                                                  : last_error;
                return fitted;
            }
            const auto content_width =
                static_cast<double>(raster.output->metrics.content_width_pixels) *
                fitted.design_pixels_per_bitmap_pixel;
            if (content_width >= command.destination.width && content_width > 0.0) {
                fitted.line_scale =
                    std::min(fitted.line_scale, command.destination.width / content_width);
            }
            fitted.lines.push_back(std::move(raster));
        }

        // FTGL exposes Descender as a negative metric; TextRasterizer stores
        // its positive magnitude. text.py adds the two values, hence subtract.
        auto line_span =
            static_cast<double>(metric_raster.output->metrics.ascender_pixels -
                                metric_raster.output->metrics.descender_pixels) *
            fitted.design_pixels_per_bitmap_pixel;
        if (line_span <= 0.0) {
            line_span =
                static_cast<double>(metric_raster.output->metrics.line_height_pixels) *
                fitted.design_pixels_per_bitmap_pixel;
        }
        fitted.line_advance_pixels =
            line_span * fitted.line_scale + command.line_spacing_pixels * 2.0;
        if (command.layout == ui::TextLayout::bounded_wrapped_lines)
            fitted.line_advance_pixels = static_cast<double>(metric_raster.output->metrics.line_height_pixels) *
                fitted.design_pixels_per_bitmap_pixel + command.line_spacing_pixels;
        return fitted;
    }

    [[nodiscard]] bool prepare_text(const ui::TextDrawCommand& command) {
        const auto display_text = localized_text(command.localization_key);
        if (command.layout != ui::TextLayout::single_line) {
            const auto fitted = fitted_retail_wrapped_text(command);
            if (!fitted) {
                last_error = fitted.error;
                return false;
            }
            auto* const rasterizer =
                font_for_text(command.preferred_font_asset, display_text);
            if (rasterizer == nullptr) return false;
            for (const auto& line : fitted.lines) {
                if (line.output->bitmap.width != 0U && line.output->bitmap.height != 0U &&
                    !text_texture(*rasterizer, line).has_value()) {
                    return false;
                }
            }
            return true;
        }
        const auto fitted = fitted_text(command);
        if (!fitted) {
            last_error = "failed to rasterize '" + command.localization_key + "': " +
                         fitted.raster.error;
            return false;
        }
        const auto& raster = fitted.raster;
        if (raster.output->bitmap.width == 0U || raster.output->bitmap.height == 0U) {
            return true;
        }
        auto* const rasterizer = font_for_text(command.preferred_font_asset, display_text);
        return rasterizer != nullptr && text_texture(*rasterizer, raster).has_value();
    }

    [[nodiscard]] bool prepare_name_plate(const ui::PlayerNamePlateDrawRequest& command) {
        if (drawable_extent.width == 0U || drawable_extent.height == 0U) {
            last_error = "welcome font is unavailable while preparing the player-name plate";
            return false;
        }
        if (!image_texture(command.frame_asset_id, render::TextureFilter::linear).has_value()) {
            return false;
        }

        // Retail creates this FTGL font once at 16 design pixels. The scene's
        // projection scales the resulting glyph bitmap along with the rest of
        // the 800x600 canvas; it does not request a larger hinted font after a
        // window resize. Keeping that distinction matters on wide/high-DPI
        // windows because re-hinting at the physical size changes both the
        // name-frame width and the glyph silhouettes.
        const auto font_height = static_cast<std::uint32_t>(
            std::max(1.0, std::floor(command.requested_font_size_pixels + 0.5)));
        const auto welcome = localized_text(command.welcome_localization_key) + ' ';
        const auto player = core::utf8_code_point_prefix(command.player_name,
                                                         command.maximum_player_name_code_points);
        auto* const name_font =
            font_for_text(main_menu_assets::welcome_font, welcome + player);
        if (name_font == nullptr) {
            last_error = "no UI font covers the localized player-name plate";
            return false;
        }
        const auto welcome_raster = name_font->rasterize(
            text::TextRasterRequest{welcome, text::TextCase::preserve, font_height});
        const auto player_raster = name_font->rasterize(
            text::TextRasterRequest{player, text::TextCase::preserve, font_height});
        if (!welcome_raster || !player_raster) {
            last_error = "failed to rasterize player-name plate segments";
            return false;
        }
        const auto welcome_ready = welcome_raster.output->bitmap.width == 0U ||
                                   text_texture(*name_font, welcome_raster).has_value();
        const auto player_ready = player_raster.output->bitmap.width == 0U ||
                                  text_texture(*name_font, player_raster).has_value();
        return welcome_ready && player_ready;
    }

    [[nodiscard]] bool prepare_resources(const ui::DrawList& list) {
        for (const auto& command : list.commands()) {
            const auto ready = std::visit(
                [this](const auto& payload) {
                    using Payload = std::decay_t<decltype(payload)>;
                    if constexpr (std::is_same_v<Payload, ui::SpriteDrawCommand>) {
                        return image_texture(payload.asset_id, texture_filter(payload.sampling))
                            .has_value();
                    } else if constexpr (std::is_same_v<Payload, ui::TextDrawCommand>) {
                        return prepare_text(payload);
                    } else {
                        return prepare_name_plate(payload);
                    }
                },
                command);
            if (!ready) {
                return false;
            }
        }
        return true;
    }

    [[nodiscard]] bool draw_text(const ui::TextDrawCommand& command) {
        const auto display_text = localized_text(command.localization_key);
        if (command.layout != ui::TextLayout::single_line) {
            const auto fitted = fitted_retail_wrapped_text(command);
            if (!fitted) {
                last_error = fitted.error;
                return false;
            }
            auto* const rasterizer =
                font_for_text(command.preferred_font_asset, display_text);
            if (rasterizer == nullptr) return false;
            const auto geometry_scale =
                std::isfinite(command.geometric_scale)
                    ? std::max(0.0, command.geometric_scale)
                    : 1.0;
            const auto bitmap_to_design =
                fitted.design_pixels_per_bitmap_pixel * geometry_scale *
                fitted.line_scale;
            auto baseline_y = command.destination.y;
            if (command.layout == ui::TextLayout::bounded_wrapped_lines && !fitted.lines.empty())
                baseline_y += static_cast<double>(fitted.lines.front().output->metrics.ascender_pixels) * bitmap_to_design;
            for (const auto& line : fitted.lines) {
                const auto& metrics = line.output->metrics;
                const auto content_width =
                    static_cast<double>(metrics.content_width_pixels) *
                    bitmap_to_design;
                double content_left = command.destination.x;
                if (command.horizontal_alignment ==
                    ui::HorizontalTextAlignment::center) {
                    content_left +=
                        (command.destination.width - content_width) * 0.5;
                } else if (command.horizontal_alignment ==
                           ui::HorizontalTextAlignment::right) {
                    content_left += command.destination.width - content_width;
                }

                if (line.output->bitmap.width != 0U &&
                    line.output->bitmap.height != 0U) {
                    const auto texture = text_texture(*rasterizer, line);
                    if (!texture.has_value()) return false;
                    const auto origin_x =
                        content_left -
                        static_cast<double>(metrics.content_left_pixels) *
                            bitmap_to_design;
                    const render::UiRect destination{
                        static_cast<float>(
                            origin_x -
                            static_cast<double>(metrics.baseline_x_in_bitmap) *
                                bitmap_to_design),
                        static_cast<float>(
                            baseline_y -
                            static_cast<double>(metrics.baseline_y_in_bitmap) *
                                bitmap_to_design),
                        static_cast<float>(
                            static_cast<double>(line.output->bitmap.width) *
                            bitmap_to_design),
                        static_cast<float>(
                            static_cast<double>(line.output->bitmap.height) *
                            bitmap_to_design),
                    };
                    if (!renderer.draw(render::UiSprite{
                            texture->texture,
                            destination,
                            std::nullopt,
                            std::nullopt,
                            color(command.modulation),
                            draw_space(command.space),
                        })) {
                        return false;
                    }
                }
                baseline_y += fitted.line_advance_pixels;
            }
            return true;
        }

        auto fitted = fitted_text(command);
        if (!fitted) {
            if (last_error.empty()) {
                last_error =
                    "failed to rasterize '" + command.localization_key + "': " +
                    fitted.raster.error;
            }
            return false;
        }
        const auto& raster = fitted.raster;

        auto* const rasterizer = font_for_text(command.preferred_font_asset, display_text);
        if (rasterizer == nullptr) {
            last_error = "no UI font covers localized text '" + command.localization_key + "'";
            return false;
        }
        const auto texture = text_texture(*rasterizer, raster);
        if (!texture.has_value()) {
            return raster.output->bitmap.width == 0U || raster.output->bitmap.height == 0U;
        }

        const auto& metrics = raster.output->metrics;
        const auto geometry_scale =
            std::isfinite(command.geometric_scale)
                ? std::max(0.0, command.geometric_scale)
                : 1.0;
        const auto bitmap_to_design =
            fitted.design_pixels_per_bitmap_pixel * geometry_scale *
            fitted.layout_scale;
        const auto content_width =
            static_cast<double>(metrics.content_width_pixels) * bitmap_to_design;
        double content_left = command.destination.x;
        if (command.horizontal_alignment == ui::HorizontalTextAlignment::center) {
            content_left += (command.destination.width - content_width) * 0.5;
        } else if (command.horizontal_alignment == ui::HorizontalTextAlignment::right) {
            content_left += command.destination.width - content_width;
        }
        const auto origin_x =
            content_left - static_cast<double>(metrics.content_left_pixels) * bitmap_to_design;

        double line_top = command.destination.y;
        if (command.vertical_alignment == ui::VerticalTextAlignment::center) {
            line_top +=
                (command.destination.height -
                 static_cast<double>(metrics.line_height_pixels) * bitmap_to_design) *
                0.5;
        } else if (command.vertical_alignment == ui::VerticalTextAlignment::bottom) {
            line_top += command.destination.height -
                        static_cast<double>(metrics.line_height_pixels) * bitmap_to_design;
        }
        const auto baseline_y = [&]() {
            if (command.vertical_alignment == ui::VerticalTextAlignment::baseline) {
                return command.destination.y;
            }
            if (command.vertical_alignment == ui::VerticalTextAlignment::retail_center) {
                // text.py:559 uses y + h/2 - (ascender + descender)/2 in
                // bottom-left space. FTGL's descender is negative while our
                // raster metrics store its positive magnitude; converting to
                // top-left space produces + (ascender - descender)/2.
                return command.destination.y + command.destination.height * 0.5 +
                       static_cast<double>(metrics.ascender_pixels -
                                           metrics.descender_pixels) *
                           bitmap_to_design * 0.5;
            }
            return line_top + static_cast<double>(metrics.ascender_pixels) *
                                  bitmap_to_design;
        }();
        const render::UiRect destination{
            static_cast<float>(origin_x -
                               static_cast<double>(metrics.baseline_x_in_bitmap) *
                                   bitmap_to_design),
            static_cast<float>(baseline_y -
                               static_cast<double>(metrics.baseline_y_in_bitmap) *
                                   bitmap_to_design),
            static_cast<float>(static_cast<double>(raster.output->bitmap.width) *
                               bitmap_to_design),
            static_cast<float>(static_cast<double>(raster.output->bitmap.height) *
                               bitmap_to_design),
        };
        return renderer.draw(render::UiSprite{
            texture->texture,
            destination,
            std::nullopt,
            std::nullopt,
            color(command.modulation),
            draw_space(command.space),
        });
    }

    [[nodiscard]] bool draw_text_segment(text::TextRasterizer& rasterizer,
                                         const text::TextRasterResult& raster,
                                         double baseline_x,
                                         double baseline_y,
                                         double scale,
                                         render::UiColor tint) {
        if (!raster) {
            last_error = "failed to rasterize player-name text: " + raster.error;
            return false;
        }
        if (raster.output->bitmap.width == 0U || raster.output->bitmap.height == 0U) {
            return true;
        }
        const auto texture = text_texture(rasterizer, raster);
        if (!texture.has_value()) {
            return false;
        }
        const auto& metrics = raster.output->metrics;
        return renderer.draw(render::UiSprite{
            texture->texture,
            render::UiRect{
                static_cast<float>(baseline_x - metrics.baseline_x_in_bitmap * scale),
                static_cast<float>(baseline_y - metrics.baseline_y_in_bitmap * scale),
                static_cast<float>(raster.output->bitmap.width * scale),
                static_cast<float>(raster.output->bitmap.height * scale),
            },
            std::nullopt,
            std::nullopt,
            tint,
            render::UiDrawSpace::window_pixels,
        });
    }

    [[nodiscard]] bool draw_name_plate(const ui::PlayerNamePlateDrawRequest& command) {
        if (drawable_extent.width == 0U || drawable_extent.height == 0U) {
            last_error = "welcome font is unavailable";
            return false;
        }

        // See prepare_name_plate(): FTGL rasterizes at the fixed design size,
        // then OpenGL scales the cached glyph image through the scene matrix.
        const auto font_height = static_cast<std::uint32_t>(
            std::max(1.0, std::floor(command.requested_font_size_pixels + 0.5)));
        const auto welcome = localized_text(command.welcome_localization_key) + ' ';
        const auto player = core::utf8_code_point_prefix(command.player_name,
                                                         command.maximum_player_name_code_points);
        auto* const name_font =
            font_for_text(main_menu_assets::welcome_font, welcome + player);
        if (name_font == nullptr) {
            last_error = "no UI font covers the localized player-name plate";
            return false;
        }
        const auto combined = name_font->rasterize(
            text::TextRasterRequest{welcome + player, text::TextCase::preserve, font_height});
        const auto welcome_raster = name_font->rasterize(
            text::TextRasterRequest{welcome, text::TextCase::preserve, font_height});
        const auto player_raster = name_font->rasterize(
            text::TextRasterRequest{player, text::TextCase::preserve, font_height});
        if (!combined || !welcome_raster || !player_raster) {
            last_error = "failed to shape the player-name plate";
            return false;
        }

        const auto text_width = static_cast<double>(combined.output->metrics.content_width_pixels);
        const auto geometry = resolve_player_name_plate_geometry(command, text_width);
        if (!geometry.has_value()) {
            last_error = "invalid player-name plate geometry";
            return false;
        }
        const auto scale = geometry->scale;
        const auto frame = image_texture(command.frame_asset_id, render::TextureFilter::linear);
        if (!frame.has_value()) {
            return false;
        }
        if (!renderer.draw(render::UiSprite{
                frame->texture,
                render::UiRect{static_cast<float>(geometry->frame.x),
                               static_cast<float>(geometry->frame.y),
                               static_cast<float>(geometry->frame.width),
                               static_cast<float>(geometry->frame.height)},
                std::nullopt,
                std::nullopt,
                render::UiColor{},
                render::UiDrawSpace::window_pixels,
            })) {
            return false;
        }

        // selectMenu.py supplies the bottom-left FTGL baseline as
        // y + frameHeight / 2 - 5. This is its direct top-left equivalent.
        if (!draw_text_segment(*name_font,
                               welcome_raster,
                               geometry->text_left,
                               geometry->baseline_y,
                               scale,
                               color(command.welcome_color))) {
            return false;
        }
        return draw_text_segment(*name_font,
                                 player_raster,
                                 geometry->text_left +
                                     welcome_raster.output->metrics.advance_width_pixels * scale,
                                 geometry->baseline_y,
                                 scale,
                                 color(command.player_name_color));
    }

    [[nodiscard]] ui::DrawList build_screen_draw_list_base(FrontendScreen target,
                                                           platform::WindowExtent extent) {
        const ui::PixelExtent pixels{static_cast<std::int32_t>(extent.width),
                                     static_cast<std::int32_t>(extent.height)};
        if (target == FrontendScreen::identity) {
            return identity_presentation.build(identity_menu,
                                               IdentityPresentationContext{pixels, 1'000U});
        }
        if (target == FrontendScreen::friends_lobby) {
            return friends_lobby_presentation.build(
                friends_lobby_menu, FriendsLobbyPresentationContext{pixels, 1'000U});
        }
        if (target == FrontendScreen::select_menu || settings_menu == nullptr) {
            return presentation.build(menu,
                                      MainMenuPresentationContext{
                                          pixels,
                                          config.player_name,
                                          1'000U,
                                      });
        }

        if (target == FrontendScreen::join_match) {
            return join_match_presentation.build(join_match_menu,
                                                 JoinMatchPresentationContext{pixels, 1'000U});
        }
        if (target == FrontendScreen::direct_connect) {
            return direct_connect_presentation.build(direct_connect_menu,
                                                     JoinMatchPresentationContext{pixels, 1'000U});
        }
        if (target == FrontendScreen::ugc_select) {
            return ugc_select_presentation.build(ugc_select_menu,
                                                 UgcSelectPresentationContext{pixels, 1'000U});
        }
        if (target == FrontendScreen::ugc_publish) {
            return ugc_publish_presentation.build(ugc_publish_menu,
                                                  UgcPublishPresentationContext{pixels, 1'000U});
        }
        if (target == FrontendScreen::ugc_editor_browser) {
            return ugc_editor_browser_presentation.build(
                ugc_editor_browser,
                UgcEditorPresentationContext{pixels, 1'000U, config.player_name});
        }
        if (target == FrontendScreen::ugc_editor_lobby) {
            return ugc_editor_lobby_presentation.build(
                ugc_editor_lobby, UgcEditorPresentationContext{pixels, 1'000U, config.player_name});
        }
        if (target == FrontendScreen::server_browser) {
            auto status = server_browser_status;
            if (server_browser.servers().empty() && status.empty()) {
                status = server_browser.refreshing() ? "GETTING_SERVER_LIST" : "NO_SERVERS_FOUND";
            }
            const auto* selected = server_browser.selected();
            const auto preview = selected == nullptr
                                     ? std::string{}
                                     : resolve_server_map_preview_asset(selected->map);
            return server_browser_presentation.build(
                server_browser,
                ServerBrowserPresentationContext{pixels,
                                                 1'000U,
                                                 std::move(status),
                                                 preview,
                                                 server_browser.first_visible_row(),
                                                 server_browser.visible_row_capacity(),
                                                 server_browser_pointer,
                                                 server_browser_pointer_down});
        }
        if (target == FrontendScreen::public_match) {
            return quick_play_presentation.build(quick_play_menu,
                                                 QuickPlayPresentationContext{pixels, 1'000U});
        }
        if (target == FrontendScreen::custom_match) {
            return custom_match_presentation.build(custom_match_menu,
                                                   CustomMatchPresentationContext{pixels, 1'000U});
        }
        if (target == FrontendScreen::create_match ||
            target == FrontendScreen::create_match_rules ||
            target == FrontendScreen::create_match_maps ||
            target == FrontendScreen::create_match_lobby) {
            auto active_page = create_match_presentation.build(
                create_match_menu.presentation(),
                CreateMatchPresentationContext{pixels, 1'000U, settings_warning});
            if (!create_match_page_shell.transitioning() &&
                create_match_page_shell.active_offset() == 0.0) {
                return active_page;
            }

            std::optional<ui::DrawList> previous_page;
            if (previous_create_match_page.has_value()) {
                previous_page = create_match_presentation.build(
                    *previous_create_match_page, CreateMatchPresentationContext{pixels, 1'000U});
            }
            ui::DrawList composed;
            composed.reserve(1U + (previous_page.has_value() ? previous_page->size() : 0U) +
                             active_page.size());
            const auto background =
                std::ranges::find_if(active_page.commands(), stationary_background);
            if (background != active_page.commands().end()) {
                composed.push(*background);
            }
            if (previous_page.has_value() && create_match_page_shell.transitioning()) {
                const auto slide_width = transition_design_width(pixels);
                append_transition_layer(composed,
                                        *previous_page,
                                        create_match_page_shell.previous_offset() * slide_width,
                                        create_match_page_shell.previous_offset() *
                                            static_cast<double>(extent.width));
            }
            const auto slide_width = transition_design_width(pixels);
            append_transition_layer(composed,
                                    active_page,
                                    create_match_page_shell.active_offset() * slide_width,
                                    create_match_page_shell.active_offset() *
                                        static_cast<double>(extent.width));
            return composed;
        }
        if (target == FrontendScreen::leaderboard) {
            LeaderboardPresentationContext context{pixels, 1'000U};
            context.measure_header_text = [this](std::string_view key, double size) {
                return measure_big_message_line(localized_text(key), size);
            };
            context.measure_row_text = [this](std::string_view value, double size) {
                return measure_kill_feed_name(value, size);
            };
            return leaderboard_presentation.build(leaderboard_menu, context);
        }
        if (target == FrontendScreen::player_profile) {
            auto list = player_profile_presentation.build(
                player_profile_menu,
                PlayerProfilePresentationContext{pixels,
                                                 1'000U,
                                                 profile_cancel_state,
                                                 profile_achievements_state,
                                                 profile_filter_state});
            if (player_profile_menu.selected_tab()==PlayerProfileTab::inventory) {
                if (inventory_view) {
                    ui::DrawList background;
                    if (!list.commands().empty()) background.push(list.commands().front());
                    return background;
                }
                const auto panel=inventory_menu.build();
                for (const auto& command:panel.commands()) list.push(command);
            }
            return list;
        }
        if (target == FrontendScreen::game_loading || target == FrontendScreen::startup_loading) {
            // Recovered START glow toggles every 0.4 s = 24 frames at 60 Hz.
            const bool glow_phase = ((text_cache_frame / 24U) % 2U) == 0U;
            return match_loading_presentation.build(
                match_loading.snapshot(), LoadingPresentationContext{pixels, 1'000U, glow_phase});
        }
        if (target == FrontendScreen::class_selection) {
            if (ugc_loadout_active) {
                return ugc_loadout_presentation.build(ugc_loadout_menu, pixels);
            }
            const bool in_game =
                class_selection_from_pause || class_selection_team_change.has_value();
            return class_selection_presentation.build(class_selection_menu, pixels, in_game,class_selection_icons());
        }
        if (target == FrontendScreen::tutorial_world) {
            // The 3D world pass renders beneath the UI views; this list is
            // only the crosshair/diagnostics overlay.
            return tutorial_world_draw_list();
        }
        if (target == FrontendScreen::pause_menu) {
            // The frozen world stays visible behind the recovered EscapeMenu.
            return pause_menu_presentation.build(pause_menu, PauseMenuPresentationContext{pixels});
        }
        if (target == FrontendScreen::change_team) {
            return change_team_presentation.build(change_team_menu, pixels);
        }
        if (target == FrontendScreen::parity_debug) {
            if (!developer_tools_allowed())
                return {};
            return parity_debug_presentation.build(parity_debug_menu,
                                                   ParityDebugPresentationContext{pixels, 1'000U});
        }
        if (target == FrontendScreen::gameplay_debug) {
            if (!developer_tools_allowed())
                return {};
            // `--debug-vfx` is a production-renderer oracle, not the
            // interactive gameplay lab.  Keeping the lab panel over the
            // particles hid almost half of the recovered burst and made a
            // screenshot comparison meaningless.  The normal F10 lab keeps
            // its controls; only the explicit command-line oracle renders a
            // clean world frame.
            if (config.debug_vfx.has_value())
                return {};
            return gameplay_debug_presentation.build(gameplay_debug_lab, pixels);
        }

        SettingsPresentationSnapshot snapshot;
        if (target == FrontendScreen::resolution_confirmation) {
            snapshot.screen = SettingsPresentationScreen::resolution_confirmation;
            snapshot.selected_tab = SettingsPresentationTab::graphics;
            snapshot.resolution_countdown_seconds =
                static_cast<double>(resolution_confirmation.seconds_remaining());
            snapshot.done_button.visual_state =
                resolution_confirmation.keep_pressed()   ? SettingsPresentationVisualState::pressed
                : resolution_confirmation.keep_hovered() ? SettingsPresentationVisualState::hovered
                                                         : SettingsPresentationVisualState::normal;
            snapshot.cancel_button.visual_state = resolution_confirmation.revert_pressed()
                                                      ? SettingsPresentationVisualState::pressed
                                                  : resolution_confirmation.revert_hovered()
                                                      ? SettingsPresentationVisualState::hovered
                                                      : SettingsPresentationVisualState::normal;
        } else {
            snapshot = presentation_snapshot(settings_menu->presentation());
            if (!settings_warning.empty() && snapshot.error_key.empty()) {
                snapshot.error_key = settings_warning;
                snapshot.tooltip_is_error = true;
            }
            if (snapshot.error_key.empty() && config.enable_audio && !audio_started &&
                audio != nullptr && !audio->last_error().empty()) {
                snapshot.error_key = std::string{audio->last_error()};
                snapshot.tooltip_is_error = true;
            }
        }
        return settings_presentation.build(snapshot, SettingsPresentationContext{pixels, 1'000U});
    }

    [[nodiscard]] ui::DrawList build_screen_draw_list(FrontendScreen target,
                                                      platform::WindowExtent extent) {
        auto list = build_screen_draw_list_base(target, extent);
        const auto screen_name = layout_screen_name(target);
        ui_layout_store.apply(screen_name, list);
        if (ui_layout_editor.active() && target == screen()) {
            ui_layout_editor.observe(std::string{screen_name}, list);
            ui_layout_editor.decorate(list);
        }
        return list;
    }

    [[nodiscard]] static bool stationary_background(const ui::DrawCommand& command) {
        const auto* sprite = std::get_if<ui::SpriteDrawCommand>(&command);
        return sprite != nullptr && sprite->space == ui::DrawSpace::window_pixels &&
               sprite->asset_id == main_menu_assets::background;
    }

    static void append_transition_layer(ui::DrawList& destination,
                                        const ui::DrawList& source,
                                        double design_offset,
                                        double window_offset) {
        for (const auto& command : source.commands()) {
            if (stationary_background(command)) {
                continue;
            }
            ui::DrawList single;
            single.push(command);
            ui::append_translated(destination, single, design_offset, window_offset);
        }
    }

    [[nodiscard]] double transition_design_width(ui::PixelExtent pixels) const noexcept {
        const auto viewport = design_canvas.viewport(pixels);
        if (!viewport.has_value() || viewport->scale <= 0.0) {
            return static_cast<double>(MainMenuModel::reference_width_pixels);
        }
        // menuScene.py translates by current_x * window.width before applying
        // the 800x600 aspect scale. Design-space commands therefore need the
        // full window width expressed back in unscaled canvas units; using a
        // fixed 800 shears design- and window-space layers on widescreen.
        return static_cast<double>(pixels.width) / viewport->scale;
    }

    [[nodiscard]] ui::DrawList build_active_draw_list(platform::WindowExtent extent) {
        const ui::PixelExtent pixels{static_cast<std::int32_t>(extent.width),
                                     static_cast<std::int32_t>(extent.height)};
        if (boot_loading) {
            auto preload = texture_preloader.snapshot();
            constexpr double texture_share{0.8};
            const auto warmup_progress =
                frontend_warmup_lists.empty()
                    ? 1.0
                    : static_cast<double>(frontend_warmup_cursor) /
                          static_cast<double>(frontend_warmup_lists.size());
            preload.progress = texture_share * preload.progress;
            if (preload.state == assets::PreloadBatchState::ready ||
                preload.state == assets::PreloadBatchState::ready_with_warnings) {
                preload.progress = texture_share + (1.0 - texture_share) * warmup_progress;
                if (frontend_warmup_cursor < frontend_warmup_lists.size()) {
                    preload.state = assets::PreloadBatchState::active;
                }
            }
            return boot_loading_presentation.build(boot_loading_snapshot(preload),
                                                   LoadingPresentationContext{pixels, 1'000U});
        }

        const auto active = screen();
        auto active_list = build_screen_draw_list(active, extent);
        const auto previous = navigation.previous();
        const auto& shell = navigation.shell();
        if (!previous.has_value() && shell.active_offset() == 0.0) {
            return active_list;
        }

        std::optional<ui::DrawList> previous_list;
        if (previous.has_value()) {
            previous_list = build_screen_draw_list(*previous, extent);
        }
        ui::DrawList composed;
        composed.reserve(1U + (previous_list.has_value() ? previous_list->size() : 0U) +
                         active_list.size());
        const auto background = std::ranges::find_if(active_list.commands(), stationary_background);
        if (background != active_list.commands().end()) {
            composed.push(*background);
        }
        if (previous_list.has_value()) {
            const auto slide_width = transition_design_width(pixels);
            append_transition_layer(composed,
                                    *previous_list,
                                    shell.previous_offset() * slide_width,
                                    shell.previous_offset() * static_cast<double>(extent.width));
        }
        const auto slide_width = transition_design_width(pixels);
        append_transition_layer(composed,
                                active_list,
                                shell.active_offset() * slide_width,
                                shell.active_offset() * static_cast<double>(extent.width));
        return composed;
    }

    [[nodiscard]] std::vector<TexturePreloadRequest>
    frontend_texture_manifest(platform::WindowExtent extent) {
        std::vector<TexturePreloadRequest> manifest;
        std::set<std::string, std::less<>> ids;
        const auto add = [&](std::string_view asset, render::TextureFilter filter) {
            if (asset.empty() || asset == loading_screen_assets::splash ||
                asset == loading_screen_assets::boot_title ||
                asset == loading_screen_assets::boot_bullet ||
                asset == loading_screen_assets::boot_bullet_dark) {
                return;
            }
            auto id = texture_key(asset, filter);
            if (!ids.insert(id).second) {
                return;
            }
            std::uint32_t weight{1U};
            std::error_code error;
            const auto bytes =
                std::filesystem::file_size(config.asset_root / std::filesystem::path{asset}, error);
            if (!error) {
                constexpr std::uintmax_t weight_unit{64U * 1'024U};
                const auto units =
                    std::max<std::uintmax_t>(1U, (bytes + weight_unit - 1U) / weight_unit);
                weight = static_cast<std::uint32_t>(
                    std::min<std::uintmax_t>(units, std::numeric_limits<std::uint32_t>::max()));
            }
            manifest.push_back(TexturePreloadRequest{
                std::move(id), std::filesystem::path{asset}, filter, weight, true});
        };
        const auto collect = [&](const ui::DrawList& list) {
            frontend_warmup_lists.push_back(list);
            for (const auto& command : list.commands()) {
                if (const auto* sprite = std::get_if<ui::SpriteDrawCommand>(&command)) {
                    add(sprite->asset_id, texture_filter(sprite->sampling));
                } else if (const auto* plate =
                               std::get_if<ui::PlayerNamePlateDrawRequest>(&command)) {
                    add(plate->frame_asset_id, render::TextureFilter::linear);
                }
            }
        };

        collect(presentation.build(
            menu,
            MainMenuPresentationContext{
                {static_cast<std::int32_t>(extent.width), static_cast<std::int32_t>(extent.height)},
                config.player_name,
                1'000U}));
        collect(identity_presentation.build(
            identity_menu,
            IdentityPresentationContext{
                {static_cast<std::int32_t>(extent.width), static_cast<std::int32_t>(extent.height)},
                1'000U}));
        collect(friends_lobby_presentation.build(
            friends_lobby_menu,
            FriendsLobbyPresentationContext{
                {static_cast<std::int32_t>(extent.width), static_cast<std::int32_t>(extent.height)},
                1'000U}));
        for (const auto& asset : main_menu_assets::required()) {
            if (asset.kind == MainMenuAssetKind::texture) {
                add(asset.path,
                    asset.sampling == TextureSampling::nearest ? render::TextureFilter::nearest
                                                               : render::TextureFilter::linear);
            }
        }
        for (const auto& asset : join_match_assets::required()) {
            if (asset.kind == MainMenuAssetKind::texture) {
                add(asset.path,
                    asset.sampling == TextureSampling::nearest ? render::TextureFilter::nearest
                                                               : render::TextureFilter::linear);
            }
        }

        const ui::PixelExtent pixels{static_cast<std::int32_t>(extent.width),
                                     static_cast<std::int32_t>(extent.height)};
        collect(join_match_presentation.build(join_match_menu,
                                              JoinMatchPresentationContext{pixels, 1'000U}));
        collect(direct_connect_presentation.build(direct_connect_menu,
                                                  JoinMatchPresentationContext{pixels, 1'000U}));
        collect(ugc_select_presentation.build(ugc_select_menu,
                                              UgcSelectPresentationContext{pixels, 1'000U}));
        // SelectUGC shares the class-selection route but owns a distinct stock
        // frame family. Warm its fixed chrome before a live UGC join.
        collect(ugc_loadout_presentation.build(ugc_loadout_menu, pixels));
        for (const auto& asset : ugc_select_assets::required()) {
            if (asset.kind == MainMenuAssetKind::texture) {
                add(asset.path,
                    asset.sampling == TextureSampling::nearest ? render::TextureFilter::nearest
                                                               : render::TextureFilter::linear);
            }
        }
        collect(ugc_publish_presentation.build(ugc_publish_menu,
                                               UgcPublishPresentationContext{pixels, 1'000U}));
        collect(ugc_editor_browser_presentation.build(
            ugc_editor_browser, UgcEditorPresentationContext{pixels, 1'000U, config.player_name}));
        collect(ugc_editor_lobby_presentation.build(
            ugc_editor_lobby, UgcEditorPresentationContext{pixels, 1'000U, config.player_name}));
        for (const auto& asset : ugc_publish_assets::required()) {
            if (asset.kind == MainMenuAssetKind::texture) {
                add(asset.path,
                    asset.sampling == TextureSampling::nearest ? render::TextureFilter::nearest
                                                               : render::TextureFilter::linear);
            }
        }
        collect(server_browser_presentation.build(
            server_browser,
            ServerBrowserPresentationContext{pixels,
                                             1'000U,
                                             {},
                                             {},
                                             server_browser.first_visible_row(),
                                             server_browser.visible_row_capacity(),
                                             {},
                                             false}));
        collect(quick_play_presentation.build(quick_play_menu,
                                              QuickPlayPresentationContext{pixels, 1'000U}));
        for (const auto& asset : quick_play_assets::required()) {
            if (asset.kind == MainMenuAssetKind::texture) {
                add(asset.path,
                    asset.sampling == TextureSampling::nearest ? render::TextureFilter::nearest
                                                               : render::TextureFilter::linear);
            }
        }
        collect(custom_match_presentation.build(custom_match_menu,
                                                CustomMatchPresentationContext{pixels, 1'000U}));
        collect(parity_debug_presentation.build(parity_debug_menu,
                                                ParityDebugPresentationContext{pixels, 1'000U}));
        for (const auto& asset : custom_match_assets::required()) {
            if (asset.kind == MainMenuAssetKind::texture) {
                add(asset.path,
                    asset.sampling == TextureSampling::nearest ? render::TextureFilter::nearest
                                                               : render::TextureFilter::linear);
            }
        }
        collect(create_match_presentation.build(create_match_menu.presentation(),
                                                CreateMatchPresentationContext{pixels, 1'000U}));
        for (const auto page : {CreateMatchPage::choose_game_mode,
                                CreateMatchPage::choose_map,
                                CreateMatchPage::game_rules}) {
            CreateMatchMenuModel nested_create;
            static_cast<void>(nested_create.open_page(page));
            static_cast<void>(nested_create.take_effects());
            collect(create_match_presentation.build(
                nested_create.presentation(), CreateMatchPresentationContext{pixels, 1'000U}));
        }
        collect(leaderboard_presentation.build(leaderboard_menu,
                                               LeaderboardPresentationContext{pixels, 1'000U}));
        collect(player_profile_presentation.build(
            player_profile_menu, PlayerProfilePresentationContext{pixels, 1'000U}));

        if (settings_menu != nullptr) {
            for (const auto tab : {settings::SettingsTab::main,
                                   settings::SettingsTab::graphics,
                                   settings::SettingsTab::controls}) {
                settings_menu->set_active_tab(tab);
                collect(settings_presentation.build(
                    presentation_snapshot(settings_menu->presentation()),
                    SettingsPresentationContext{pixels, 1'000U}));
            }
            settings_menu->set_active_tab(settings::SettingsTab::main);
            static_cast<void>(settings_menu->take_effects());
        }

        MatchLoadingModel loading;
        loading.begin("Atlantis", "CTF", false, "classic");
        loading.initial_info("Atlantis", "CTF", false, "classic");
        collect(match_loading_presentation.build(loading.snapshot(),
                                                 LoadingPresentationContext{pixels, 1'000U}));
        // Tool images are not present in a startup draw list. Preload every
        // catalogued retail image now so a server-driven class/loadout change
        // never performs synchronous PNG work during combat.
        for (const auto asset : {game_hud_assets::weapon_frame,
                                 game_hud_assets::weapon_frame_selected,
                                 game_hud_assets::ammo_frame,
                                 game_hud_assets::score_frame,
                                 game_hud_assets::damage_indicator,
                                 game_hud_assets::inside_zone_tint,
                                 game_hud_assets::minimap_frame,
                                 game_hud_assets::full_map_frame,
                                 game_hud_assets::minimap_player,
                                 game_hud_assets::minimap_view_cone,
                                 game_hud_assets::minimap_vip_player,
                                 game_hud_assets::minimap_base,
                                 game_hud_assets::minimap_grave,
                                 game_hud_assets::minimap_turret,
                                 game_hud_assets::minimap_landmine,
                                 game_hud_assets::minimap_dynamite,
                                 game_hud_assets::minimap_medpack,
                                 game_hud_assets::minimap_radar,
                                 game_hud_assets::minimap_c4,
                                 game_hud_assets::minimap_bomb,
                                 game_hud_assets::minimap_diamond,
                                 game_hud_assets::minimap_intel,
                                 game_hud_assets::minimap_height,
                                 game_hud_assets::minimap_zone_base,
                                 game_hud_assets::minimap_zone_multihill,
                                 game_hud_assets::minimap_zone_occupation,
                                 game_hud_assets::minimap_zone_diamond,
                                 game_hud_assets::minimap_zone_vip,
                                 game_hud_assets::minimap_zone_spawn,
                                 game_hud_assets::minimap_zone_territory_a,
                                 game_hud_assets::minimap_zone_territory_b,
                                 game_hud_assets::minimap_zone_territory_c,
                                 game_hud_assets::minimap_zone_territory_d,
                                 game_hud_assets::minimap_zone_territory_e,
                                 game_hud_assets::minimap_zone_territory_f,
                                 game_hud_assets::minimap_zone_territory_g,
                                 game_hud_assets::territory_backplate,
                                 game_hud_assets::territory_frame,
                                 game_hud_assets::intel_blue,
                                 game_hud_assets::intel_green}) {
            add(asset, render::TextureFilter::linear);
        }
        for (const auto asset : objective_billboard_assets) {
            add(asset, render::TextureFilter::linear);
        }
        for (const auto asset : game_hud_assets::territory_letters) {
            add(asset, render::TextureFilter::linear);
        }
        for (const auto& tool : world::weapon_catalog()) {
            for (const auto asset : {tool.toolbar_icon_asset,
                                     tool.first_person_image_asset,
                                     tool.first_person_blue_asset,
                                     tool.first_person_green_asset,
                                     tool.first_person_neutral_asset}) {
                if (!asset.empty()) {
                    add(asset, render::TextureFilter::linear);
                }
            }
        }
        return manifest;
    }

    [[nodiscard]] bool pump_frontend_preload() {
        for (auto& uploaded : texture_preloader.pump_uploads(renderer, 2U)) {
            const auto [position, inserted] =
                image_textures.emplace(std::move(uploaded.id), uploaded.texture);
            static_cast<void>(position);
            if (!inserted) {
                static_cast<void>(renderer.release_texture(uploaded.texture.texture));
            }
        }
        const auto snapshot = texture_preloader.snapshot();
        if (snapshot.state == assets::PreloadBatchState::failed) {
            last_error = "required frontend texture preload failed";
            return false;
        }
        if (snapshot.state == assets::PreloadBatchState::ready ||
            snapshot.state == assets::PreloadBatchState::ready_with_warnings) {
            // PNG decode is worker-owned, but bgfx uploads and FreeType glyph
            // textures stay on the render thread. Warm one complete screen per
            // frame so opening a destination does not synchronously rasterize
            // its entire first view while still keeping startup work bounded.
            if (frontend_warmup_cursor < frontend_warmup_lists.size()) {
                if (!prepare_resources(frontend_warmup_lists[frontend_warmup_cursor])) {
                    return false;
                }
                ++frontend_warmup_cursor;
            } else if (boot_frames_remaining == 0U) {
                boot_loading = false;
                frontend_warmup_lists.clear();
                frontend_warmup_lists.shrink_to_fit();
            }
        }
        return true;
    }

    [[nodiscard]] bool tutorial_world_in_stack() const {
        for (const auto id : navigation.stack()) {
            if (frontend_screen(id) == FrontendScreen::tutorial_world) {
                return true;
            }
        }
        return false;
    }

    /** Settings from the in-game pause menu returns there, not to Select. */
    void close_settings() {
        if (screen() == FrontendScreen::settings && settings_opened_from_gameplay) {
            settings_opened_from_gameplay = false;
            static_cast<void>(navigation.pop());
            return;
        }
        settings_opened_from_gameplay = false;
        return_to_select();
    }

    /** Report the same MenuScene boundary the retail client exposes. */
    void send_client_in_menu(bool in_menu) {
        if (!network_match || match_connection == nullptr)
            return;
        const std::array<std::byte, 2U> packet{
            std::byte{110U}, static_cast<std::byte>(in_menu ? 1U : 0U)};
        if (!match_connection->send(packet)) {
            settings_warning = "failed to queue ClientInMenu(110)";
        }
    }

    /** Commit the initial player only after both retail chooser gates. */
    [[nodiscard]] bool send_initial_player(std::uint8_t team, std::uint8_t class_id) {
        if (match_connection == nullptr || team > 3U || class_id > 17U) {
            return false;
        }
        network::Protocol168SessionConfig join;
        join.player_name =
            active_join_wire_name.empty() ? config.player_name : active_join_wire_name;
        join.team = team;
        join.class_id = class_id;
        join.auto_join = false;
        if (!match_connection->send(network::encode_protocol168_new_player_connection(join))) {
            settings_warning = "failed to queue NewPlayerConnection(15)";
            return false;
        }
        awaiting_initial_spawn_create_player = true;
        return true;
    }

    [[nodiscard]] ChangeTeamServerState team_roster_state(bool initial_join) const {
        ChangeTeamServerState state;
        state.team1_name = match_state_info.team1_name;
        state.team2_name = match_state_info.team2_name;
        if (state.team1_name == "TEAM1_COLOR")
            state.team1_name = "Blue";
        if (state.team2_name == "TEAM2_COLOR")
            state.team2_name = "Green";
        state.team1_color = match_state_info.team1_color;
        state.team2_color = match_state_info.team2_color;
        state.team1_score = match_state_info.team1_score;
        state.team2_score = match_state_info.team2_score;
        state.score_limit = match_state_info.score_limit;
        state.team1_show_score = match_state_info.team1_show_score;
        state.team2_show_score = match_state_info.team2_show_score;
        state.team1_show_max_score = match_state_info.team1_show_max_score;
        state.team2_show_max_score = match_state_info.team2_show_max_score;
        state.current_team = 255U;
        if (!initial_join && local_player_id.has_value()) {
            if (const auto* local = tutorial_roster.player(*local_player_id); local != nullptr) {
                state.current_team = local->team;
            }
        }
        state.forced_team = forced_team;
        state.team1_locked = match_state_info.team1_locked;
        state.team2_locked = match_state_info.team2_locked;
        state.spectator_enabled = match_initial_info.enable_spectator;
        state.spectator_locked = spectator_team_locked;
        state.lock_team_swap = match_state_info.lock_team_swap;
        state.lock_spectator_swap = match_state_info.lock_spectator_swap;
        state.initial_join = initial_join;
        for (const auto& replica : tutorial_roster.players()) {
            TeamRosterPlayer row;
            row.name = replica.name;
            row.player_id = replica.player_id;
            row.class_id = replica.class_id;
            row.dead = replica.dead;
            row.demo_player = replica.demo_player;
            row.high_minimap_visibility = replica.high_minimap_visibility;
            row.local_language = replica.local_language;
            row.dominating_local_player =
                replica.dominating_local_player;
            row.dominated_by_local_player =
                replica.dominated_by_local_player;
            row.lobby_host = owned_local_server != nullptr &&
                             owned_local_server->running() &&
                             local_player_id == replica.player_id;
            if (server_player_score_valid[replica.player_id]) {
                row.score = server_player_scores[replica.player_id];
            }
            row.ping = static_cast<std::uint16_t>(std::max<std::int32_t>(0, replica.ping));
            if (replica.team == 2U) {
                state.team1_players.push_back(std::move(row));
            } else if (replica.team == 3U) {
                state.team2_players.push_back(std::move(row));
            }
        }
        return state;
    }

    [[nodiscard]] std::string scoreboard_mode_title() const {
        return std::string{retail_scoreboard_mode_title(
            match_state_info.mode_type, match_initial_info.classic)};
    }

    /**
     * Resolve the currently selected retail result camera without making a
     * missing UGC screenshot fatal to the renderer.
     */
    [[nodiscard]] MatchScreenshotPreview match_screenshot_preview() const {
        MatchScreenshotPreview preview{
            match_initial_info.map_name, match_result_camera_index, false};
        if (match_state_info.screenshot_camera_points.empty()) {
            return preview;
        }
        const auto asset = retail_level_screenshot_asset(
            preview.map_name, preview.camera_index);
        if (!asset.has_value()) {
            return preview;
        }
        std::error_code error;
        preview.visible = std::filesystem::is_regular_file(
            config.asset_root / std::filesystem::path{*asset}, error);
        return preview;
    }

    /** Play retail's local win/lose sting once the server names a winner. */
    void play_match_result_audio_if_ready() {
        if (match_result_audio_played || !audio_started ||
            !local_player_id.has_value()) {
            return;
        }
        const auto* local = tutorial_roster.player(*local_player_id);
        if (local == nullptr) {
            return;
        }
        const auto stem =
            match_result_audio_stem(match_results.winner_team(), local->team);
        if (stem.has_value() &&
            audio->play_named_one_shot(*stem, {}, 1.0F, true)) {
            match_result_audio_played = true;
        }
    }

    /** Resolve packet-68 objective ids through retail UGC_OBJECTIVES_TYPES. */
    [[nodiscard]] std::vector<std::uint8_t> allowed_ugc_loadout_tools() const {
        std::vector<std::uint8_t> result;
        if (!server_ugc_objectives.has_value()) return result;
        for (const auto& objective : server_ugc_objectives->objectives) {
            for (const auto id : ugc_loadout_entity_ids_for_objective(objective.id)) {
                if (std::ranges::find(result, id) == result.end()) result.push_back(id);
            }
        }
        return result;
    }

    /** Resolve the live packet-68 values into the source objective rows. */
    [[nodiscard]] std::vector<UgcLoadoutObjective>
    ugc_loadout_objectives() const {
        std::vector<UgcLoadoutObjective> result;
        if (!server_ugc_objectives.has_value()) return result;
        result.reserve(server_ugc_objectives->objectives.size());
        for (const auto& objective : server_ugc_objectives->objectives) {
            if (auto row = ugc_loadout_objective(objective.id,
                                                 objective.value);
                row.has_value()) {
                result.push_back(std::move(*row));
            }
        }
        return result;
    }

    /**
     * Configure the source SelectPrefabs/SelectGameData model from live server
     * authority. Existing backpack choices come only from the local replica;
     * the initial join deliberately starts empty like GameClass does.
     */
    void configure_ugc_loadout(UgcLoadoutLibrary library,
                               std::uint8_t team,
                               bool in_game) {
        std::span<const std::string> selected_prefabs;
        std::span<const std::uint8_t> selected_tools;
        if (in_game && local_player_id.has_value()) {
            if (const auto* local = tutorial_roster.player(*local_player_id);
                local != nullptr) {
                selected_prefabs = local->prefabs;
                selected_tools = local->ugc_tools;
            }
        }
        const auto allowed_tools = allowed_ugc_loadout_tools();
        const auto objectives = ugc_loadout_objectives();
        ugc_loadout_menu.configure(library,
                                   match_state_info.prefabs,
                                   allowed_tools,
                                   selected_prefabs,
                                   selected_tools,
                                   team,
                                   in_game,
                                   objectives);
        ugc_loadout_active = true;
    }

    /** Rebuild pause and ChangeTeam gates from the latest server snapshot. */
    void refresh_pause_menu() {
        if (!network_match || !local_player_id.has_value()) {
            pause_menu = PauseMenuModel{PauseMenuEnvironment{false, false, false, false}};
            return;
        }
        const auto* local = tutorial_roster.player(*local_player_id);
        if (local == nullptr)
            return;
        const bool on_team2 = local->team == 3U;
        const auto& classes =
            on_team2 ? match_state_info.team2_classes : match_state_info.team1_classes;
        pause_menu = PauseMenuModel{pause_menu_environment_for({
            match_state_info.mode_type,
            local->team,
            local->class_id,
            classes.size(),
            on_team2 ? match_state_info.team2_locked_class : match_state_info.team1_locked_class,
            match_state_info.team1_locked,
            match_state_info.team2_locked,
            match_state_info.lock_team_swap,
            match_state_info.lock_spectator_swap,
            match_initial_info.enable_spectator,
            match_state_info.has_map_ended,
            match_state_info.mode_type == 12U,
        })};

        const bool initial_join =
            screen() == FrontendScreen::change_team && change_team_menu.state().initial_join;
        change_team_menu.configure(team_roster_state(initial_join));
    }

    void consume_change_team_action(std::optional<ChangeTeamAction> action) {
        if (!action.has_value())
            return;
        const bool initial_join = change_team_menu.state().initial_join;
        if (*action == ChangeTeamAction::back) {
            if (initial_join) {
                class_selection_initial_join = false;
                initial_join_team.reset();
                static_cast<void>(
                    navigation.replace(FrontendScreen::game_loading, NavigationDirection::back));
            } else {
                static_cast<void>(navigation.pop());
            }
            play_back();
            return;
        }
        if (!network_match || match_connection == nullptr || !local_player_id.has_value()) {
            return;
        }
        const auto target_team = static_cast<std::uint8_t>(*action);
        if (should_send_change_team(initial_join)) {
            const std::array<std::byte, 3U> packet{std::byte{77U},
                                                   static_cast<std::byte>(*local_player_id),
                                                   static_cast<std::byte>(target_team)};
            if (!match_connection->send(packet)) {
                settings_warning = "failed to queue ChangeTeam(77)";
                return;
            }
        } else {
            // SelectTeam only updates GameScene.selected_team in retail. The
            // server first sees this choice in NewPlayerConnection(15).
            initial_join_team = target_team;
        }
        play_confirm();
        if (target_team == 0U) {
            class_selection_team_change.reset();
            class_selection_initial_join = false;
            ugc_loadout_active = false;
            send_client_in_menu(false);
            if (audio_started) {
                audio->stop_menu_music();
            }
            if (initial_join) {
                if (!send_initial_player(0U, 0U)) {
                    send_client_in_menu(true);
                }
            } else {
                static_cast<void>(
                    navigation.reset(FrontendScreen::tutorial_world, NavigationDirection::back));
            }
            return;
        }
        if (match_initial_info.map_is_ugc()) {
            // Retail enters SelectPrefabs, not the ordinary SelectClass cards,
            // after choosing a team in a creator session.
            configure_ugc_loadout(UgcLoadoutLibrary::constructs,
                                  target_team,
                                  !initial_join);
        } else {
            const auto& advertised =
                target_team == 3U ? match_state_info.team2_classes
                                  : match_state_info.team1_classes;
            const auto* current_player = !initial_join && local_player_id.has_value()
                                             ? tutorial_roster.player(*local_player_id)
                                             : nullptr;
            const auto initial_class =
                current_player != nullptr ? current_player->class_id
                                          : advertised.empty() ? std::uint8_t{0U}
                                                               : advertised.front();
            class_selection_menu.configure(advertised, target_team, initial_class);
            if (current_player != nullptr &&
                class_selection_menu.selected_class() == current_player->class_id) {
                class_selection_menu.restore_loadout(current_player->loadout, current_player->prefabs);
            }
            ugc_loadout_active = false;
        }
        class_selection_from_pause = false;
        class_selection_initial_join = initial_join;
        if (initial_join) {
            class_selection_team_change.reset();
        } else {
            class_selection_team_change = target_team;
        }
        static_cast<void>(
            navigation.replace(FrontendScreen::class_selection, NavigationDirection::forward));
        start_secondary_selection_music();
    }

    void consume_pause_action(std::optional<PauseMenuAction> action) {
        if (!action.has_value()) {
            return;
        }
        switch (*action) {
        case PauseMenuAction::resume:
            send_client_in_menu(false);
            static_cast<void>(navigation.pop_instant());
            play_confirm();
            break;
        case PauseMenuAction::settings:
            if (settings_menu != nullptr) {
                settings_session = settings::SettingsSession{confirmed_settings};
                rebuild_settings_menu(SettingsMenuContext::in_game);
                settings_menu->cancel_pointer_capture();
                settings_menu->cancel_binding_capture();
                settings_menu->set_active_tab(settings::SettingsTab::main);
                settings_warning.clear();
                settings_opened_from_gameplay =
                    navigation.push(FrontendScreen::settings);
                if (settings_opened_from_gameplay) {
                    play_confirm();
                }
            }
            break;
        case PauseMenuAction::disconnect:
            // The route reset drops the tutorial from the stack; the route
            // exit hook tears the world down and restores the menu music.
            play_back();
            return_to_select();
            break;
        case PauseMenuAction::change_class:
            if (network_match && local_player_id.has_value()) {
                const auto* replica = tutorial_roster.player(*local_player_id);
                if (replica != nullptr) {
                    // Retail honours ForceTeamJoin while opening SelectClass;
                    // the class catalog must belong to the forced team even
                    // if CreatePlayer for that transition has not arrived yet.
                    const auto selection_team = forced_team.value_or(replica->team);
                    const auto& advertised = selection_team == 3U ? match_state_info.team2_classes
                                                                  : match_state_info.team1_classes;
                    class_selection_menu.configure(advertised, selection_team, replica->class_id);
                    if (class_selection_menu.selected_class() == replica->class_id) {
                        class_selection_menu.restore_loadout(replica->loadout, replica->prefabs);
                    }
                    ugc_loadout_active = false;
                    class_selection_from_pause = true;
                    class_selection_initial_join = false;
                    class_selection_team_change.reset();
                    static_cast<void>(navigation.push(FrontendScreen::class_selection));
                    play_confirm();
                    start_secondary_selection_music();
                }
            }
            break;
        case PauseMenuAction::change_team:
            refresh_pause_menu();
            static_cast<void>(navigation.push(FrontendScreen::change_team));
            play_confirm();
            start_secondary_selection_music();
            break;
        case PauseMenuAction::constructs:
        case PauseMenuAction::game_data:
            if (network_match && match_initial_info.map_is_ugc() &&
                local_player_id.has_value()) {
                const auto* replica = tutorial_roster.player(*local_player_id);
                if (replica != nullptr) {
                    configure_ugc_loadout(
                        *action == PauseMenuAction::constructs
                            ? UgcLoadoutLibrary::constructs
                            : UgcLoadoutLibrary::game_data,
                        replica->team,
                        true);
                    class_selection_from_pause = true;
                    class_selection_initial_join = false;
                    class_selection_team_change.reset();
                    static_cast<void>(navigation.push(FrontendScreen::class_selection));
                    play_confirm();
                    start_secondary_selection_music();
                }
            }
            break;
        }
    }

    /** True while a stacked route still owns a tutorial or network match. */
    [[nodiscard]] bool tutorial_route_active() const {
        for (const auto id : navigation.stack()) {
            const auto route = frontend_screen(id);
            if (route == FrontendScreen::tutorial_world ||
                route == FrontendScreen::class_selection || route == FrontendScreen::change_team ||
                (route == FrontendScreen::game_loading &&
                 (tutorial_bootstrap != nullptr || tutorial_ready_map != nullptr ||
                  match_connection != nullptr || active_match_request.has_value() ||
                  active_local_host_generation != 0U ||
                  owned_local_server != nullptr))) {
                // A public host waits for lobby publication and an identity
                // ticket after its startup worker finishes. The owned server
                // must survive that gap before match_connection is created.
                return true;
            }
        }
        return false;
    }

    /**
     * True while an already-created world remains below a frontend overlay.
     *
     * Retail multiplayer never stops local physics for Escape/settings/team
     * menus because the authoritative server keeps advancing. Input capture is
     * released separately; this predicate only preserves simulation, gravity,
     * ClientData cadence, and reconciliation.
     */
    [[nodiscard]] bool world_simulation_active() const {
        return live_world_simulation_allowed(
            tutorial_session != nullptr, tutorial_world_in_stack(), window_suspended);
    }

    /**
     * Retire the prior map's runtime minimap before accepting another map.
     *
     * A map revision is local to one VXL instance and commonly restarts at the
     * same value after a rotation. Reusing the permanent `runtime/minimap`
     * cache key therefore let a draw command or backend descriptor retain the
     * previous map even though the CPU pixels belonged to the new session.
     * Each map receives a new UI asset identity; the superseded GPU allocation
     * is released immediately when the render thread is available.
     */
    void advance_minimap_texture_generation() {
        const auto old_key = texture_key(minimap_texture_asset, render::TextureFilter::linear);
        if (const auto existing = image_textures.find(old_key);
            existing != image_textures.end() && renderer.is_initialized() &&
            renderer.release_texture(existing->second.texture)) {
            image_textures.erase(existing);
        }
        ++minimap_texture_generation;
        minimap_texture_asset = std::string{game_hud_assets::minimap_texture} + "/" +
                                std::to_string(minimap_texture_generation);
    }

    void retire_world_bootstrap() {
        if (!tutorial_bootstrap) {
            tutorial_bootstrap_cleanup.reset();
            return;
        }
        tutorial_bootstrap->cancel();
        tutorial_bootstrap_cleanup.defer(std::packaged_task<void()>{
            [bootstrap = std::move(tutorial_bootstrap)]() mutable { bootstrap.reset(); }});
    }

    template <typename... Arguments>
    [[nodiscard]] bool start_world_bootstrap(Arguments&&... arguments) {
        retire_world_bootstrap();
        auto cleanup = bootstrap_cleanup.try_reserve();
        if (!cleanup) {
            settings_warning = "Previous maps are still closing. Go back and try again shortly.";
            match_loading.fail(settings_warning);
            return false;
        }
        try {
            tutorial_bootstrap = std::make_unique<world::TutorialWorldBootstrap>(
                std::forward<Arguments>(arguments)...);
            tutorial_bootstrap_cleanup = std::move(*cleanup);
            tutorial_bootstrap->start();
            return true;
        } catch (const std::exception& error) {
            retire_world_bootstrap();
            settings_warning = std::string{"Could not prepare the map: "} + error.what();
            match_loading.fail(settings_warning);
            return false;
        }
    }

    /**
     * ``keep_steam_tunnel`` preserves a Steam join's tunnel: loading a match
     * tears the offline world down first, and the tunnel that join is about to
     * dial was opened before that teardown.
     */
    void teardown_tutorial(bool keep_steam_tunnel = false) {
        initial_join_submitted = false;
        // Keep an outstanding future drainable without blocking the UI. Its
        // response must never authorize a later host attempt at the same port.
        if (pending_match_identity) pending_match_identity->generation = 0U;
        queued_match_identity.reset();
        if (join_ticket_refresh) join_ticket_refresh->generation = 0U;
        join_code_issued_at.reset();
        retire_match_connection(keep_steam_tunnel);
        map_transition_armed = false;
        map_transition_reconnecting = false;
        map_transition_attempts = 0U;
        map_transition_retry_at = {};
        map_transition_deadline = {};
        active_match_request.reset();
        local_player_id.reset();
        launcher_muzzle_tracker.clear();
        active_join_wire_name.clear();
        awaiting_initial_spawn_create_player = false;
        local_spawn_confirmed = false;
        network_match = false;
        client_loop_count = 0;
        latest_world_loop = 0;
        clock_sync_elapsed = 0.0;
        clock_sync_token = 0;
        pending_tool_selection.reset();
        last_sent_tool.reset();
        match_initial_info = {};
        match_state_info = {};
        match_ui_skin = "default";
        server_player_scores.fill(0);
        server_player_score_valid.fill(false);
        combat_tool_memory.fill({});
        live_official_environment.reset();
        live_skydome_name = "Classic_B.txt";
        server_minimap_billboards.clear();
        server_minimap_zones.clear();
        zombie_conversion_audio.reset();
        server_team_map_visibility.fill(false);
        game_hud.reset_team_progress();
        game_hud.reset_territory_bases();
        class_selection_from_pause = false;
        class_selection_team_change.reset();
        class_selection_initial_join = false;
        ugc_loadout_active = false;
        initial_join_team.reset();
        scoreboard_visible = false;
        scoreboard_forced = false;
        generic_vote.clear();
        match_results.clear();
        match_result_camera_timer = 0.0;
        match_result_camera_index = 0U;
        match_result_audio_played = false;
        game_chat.cancel();
        static_cast<void>(window.set_text_input_enabled(false));
        forced_team.reset();
        spectator_team_locked = false;
        pending_class_selection.reset();
        live_terrain_replica.reset();
        live_prefab_placement.clear();
        live_prefab_model.reset();
        live_prefab_model_name.clear();
        timed_explosive_seconds.clear();
        deferred_terrain_packets.clear();
        clear_live_chunk_remeshes();
        local_palette_color.reset();
        server_ugc_items.clear();
        server_ugc_objectives.reset();
        server_ugc_preview_png.clear();
        server_ground_colors.clear();
        ugc_ingame_settings = UgcIngameSettingsModel{};
        ugc_initial_requests_sent = false;
        server_ambient_sounds.clear();
        server_ambience_received = false;
        server_music_received = false;
        server_sound_variant = 0U;
        pending_melee_sound_hints.clear();
        predicted_terrain_hits.clear();
        cancel_fire_loop();
        close_spin_loop();
        stop_all_remote_fire_loops();
        stop_all_block_sucker_audio();
        stop_all_block_cannon_audio();
        stop_all_drill_audio();
        stop_all_jetpack_flight();
        stop_all_entity_effect_loops();
        if (audio_started) {
            audio->stop_named_loops();
        }
        retire_world_bootstrap();
        tutorial_ready_map.reset();
        tutorial_session.reset();
        clear_scripted_weapon();
        advance_minimap_texture_generation();
        minimap_pixels.clear();
        minimap_map_revision = std::numeric_limits<std::uint64_t>::max();
        minimap_texture_upload_pending = true;
        game_hud.set_minimap({});
        tutorial_chunks_uploaded = 0U;
        tutorial_chunks_expected = 0U;
        world_loading_warmup_complete = false;
        uploaded_tool.reset();
        uploaded_sandbox_tool.reset();
        sandbox_tool_part_count = 0U;
        sandbox_sight_slot.reset();
        sandbox_pin_slot.reset();
        sandbox_arm_upper_slot.reset();
        sandbox_arm_lower_slot.reset();
        tutorial_sight_slot.reset();
        tutorial_pin_slot.reset();
        view_model_meshes_uploaded = false;
        // Movement and voice state belong to the session that just ended. The
        // next GameScene owns a fresh Character spawn latch, even when it uses
        // the same class as the previous map/server.
        local_spawn_voice = {};
        voice_selection = {};
        periodic_voice = {};
        footstep_state = {};
        land_jump_state = {};
        footstep_clock = 0.0;
        terrain_effects.clear();
        particles.clear();
        terrain_effect_slots.clear();
        projectile_slots.clear();
        entity_part_slots.clear();
        entity_part_appearances.clear();
        entity_part_minimum_y.clear();
        entity_menu_visible = false;
        tutorial_diagnostics_visible = false;
        debug_arm_variant = 0;
        tutorial_roster.clear();
        remote_cosmetics.clear();
        remote_player_rigs.clear();
        remote_character_audio = {};
        pending_remote_mesh_clears.clear();
        retained_corpse_positions.fill(std::nullopt);
        last_known_player_positions.fill(std::nullopt);
        jetpack_deaths.clear();
        pending_local_jetpack_death.reset();
        local_death_announced = false;
        preview_deployable_type_uploaded.reset();
        preview_deployable_minimum_y.clear();
        parachute_mesh_attempted.fill(false);
        parachute_mesh_uploaded.fill(false);
        if (world_renderer.is_initialized()) {
            world_renderer.clear_chunks();
            world_renderer.clear_view_model();
            const world::ChunkMesh empty;
            for (std::uint32_t slot = render::WorldRenderer::terrain_effect_slot_base;
                 slot < render::WorldRenderer::world_model_slot_count;
                 ++slot) {
                static_cast<void>(world_renderer.set_world_model_mesh(slot, empty));
            }
            for (std::uint32_t slot{}; slot < 3U; ++slot) {
                static_cast<void>(world_renderer.set_world_model_mesh(slot, empty));
            }
            static_cast<void>(world_renderer.set_world_model_mesh(parachute_world_slot, empty));
            static_cast<void>(world_renderer.set_world_model_mesh(parachute_first_person_slot, empty));
            for (std::uint32_t slot = placement_deployable_slot;
                 slot < placement_deployable_slot + placement_deployable_slot_count; ++slot) {
                static_cast<void>(world_renderer.set_world_model_mesh(slot, empty));
            }
            for (std::uint32_t slot = placement_block_valid_slot;
                 slot <= placement_prefab_invalid_slot;
                 ++slot) {
                static_cast<void>(world_renderer.set_world_model_mesh(slot, empty));
            }
        }
    }

    void begin_tutorial() {
        auto tutorial_path = config.tutorial_map_path;
        if (!std::filesystem::is_regular_file(tutorial_path)) {
            // Packaged builds read the installer-verified retail Training map.
            const auto packaged = config.asset_root / "maps/Training.vxl";
            const auto legacy = config.asset_root.parent_path() / "maps/Training.vxl";
            if (std::filesystem::is_regular_file(packaged)) {
                tutorial_path = packaged;
            } else if (std::filesystem::is_regular_file(legacy)) {
                tutorial_path = legacy;
            }
#if defined(AOS_DEV_TRAINING_VXL)
            else if (std::filesystem::is_regular_file(AOS_DEV_TRAINING_VXL)) {
                tutorial_path = AOS_DEV_TRAINING_VXL;
            }
#endif
        }
        // Developer visual verification: judge a lighting change against a night
        // city or a desert, not only against Training's overcast sky.
        if (config.tutorial_map.has_value()) {
            const auto requested = config.asset_root / "maps" / (*config.tutorial_map + ".vxl");
            if (std::filesystem::is_regular_file(requested)) {
                tutorial_path = requested;
            } else {
                settings_warning = "requested tutorial map not found: " + requested.string();
            }
        }
        tutorial_map_name = tutorial_path.stem().string();
        teardown_tutorial();
        if (world_renderer.is_initialized()) {
            // Retail Training selects Classic_B through the same SkyDome path
            // used by packet 51 in network matches. Keep this explicit: the
            // tutorial has no server connection that can deliver SkyboxData.
            // An explicit --tutorial-skydome always wins. Otherwise resolve the
            // map's own dome: the names frequently do not match (TokyoNeon uses
            // Tokyo.txt, AncientEgypt uses Egypt.txt, SpookyMansion uses
            // BranCastle.txt), and since all per-map lighting is derived FROM the
            // dome, the wrong one silently gives the map the wrong sun, ambient
            // and fog. Falls back to the neutral daytime dome for anything
            // unrecognised, including UGC.
            std::string dome = config.tutorial_skydome.value_or(std::string{});
            if (dome.empty()) {
                world::SkydomeConfidence confidence{};
                dome = world::resolve_map_skydome(config.asset_root, tutorial_map_name, confidence);
            }
            live_skydome_name = dome;
            // Offline worlds must not inherit the last server's two-light state.
            world_renderer.set_retail_lighting(render::RetailTerrainLighting{});
            world_renderer.set_fog_color({111U, 215U, 223U});
            if (!world_renderer.set_skydome(dome)) {
                settings_warning =
                    "tutorial skydome failed: " + std::string{world_renderer.last_error()};
            } else {
                // The derived atmosphere carries this dome's own horizon colour,
                // so an overridden dome must fog to match rather than keep
                // Training's cyan.
                world_renderer.set_fog_color(world_renderer.atmosphere().horizon_color);
            }
        }
        match_ui_skin = supported_ui_skin("classic");
        match_loading.begin("Training", "TUTORIAL", false, match_ui_skin);
        match_loading.initial_info("Training", "TUTORIAL", false, match_ui_skin);
        match_loading.receiving_map();
        static_cast<void>(navigation.push(FrontendScreen::game_loading));
        static_cast<void>(start_world_bootstrap(tutorial_path));
    }

    /**
     * Drives the bounded Tutorial load: mirrors bootstrap progress into the
     * retail loading model, uploads finished chunk meshes within the
     * per-tick GPU budget and enters the world once everything is resident.
     */
    void pump_tutorial_loading() {
        if (tutorial_bootstrap == nullptr) {
            return;
        }
        const auto progress = tutorial_bootstrap->progress();
        if (progress.stage == world::BootstrapStage::failed) {
            match_loading.fail("LOAD_FAILED");
            settings_warning = progress.error;
            retire_world_bootstrap();
            return;
        }
        if (world_renderer.is_initialized()) {
            for (const auto& mesh : tutorial_bootstrap->take_ready_meshes(tutorial_upload_budget)) {
                if (world_renderer.upload_chunk(mesh)) {
                    ++tutorial_chunks_uploaded;
                }
            }
        }
        tutorial_chunks_expected = progress.chunks_total;
        const auto uploads_pending =
            progress.chunks_total == 0U || tutorial_chunks_uploaded < progress.chunks_total;
        double fraction = progress.fraction;
        if (progress.chunks_total != 0U) {
            // Blend mesh production and GPU residency so the bar reflects the
            // real remaining work instead of finishing before uploads do.
            fraction = std::min(progress.fraction,
                                0.25 + 0.75 * static_cast<double>(tutorial_chunks_uploaded) /
                                           static_cast<double>(progress.chunks_total));
        }
        match_loading.map_progress(fraction);
        if (progress.stage != world::BootstrapStage::ready || uploads_pending) {
            return;
        }

        auto shared_map = tutorial_bootstrap->map();
        auto derived_world = tutorial_bootstrap->take_derived_world();
        retire_world_bootstrap();
        if (shared_map == nullptr || !derived_world.has_value()) {
            match_loading.fail("LOAD_FAILED");
            return;
        }
        // Install renderer-neutral map products while the loading gate still
        // owns the screen. Historical terrain packets refresh the affected
        // skylight/minimap regions through the normal dirty-chunk lane.
        skylight = std::move(derived_world->skylight);
        emissive_volume = std::move(derived_world->emissive);
        minimap_pixels = std::move(derived_world->minimap_rgba);
        minimap_map_revision = derived_world->map_revision;
        minimap_texture_upload_pending = true;
        if (world_renderer.is_initialized()) {
            const auto emissive_palette = world::emissive_palette_for(tutorial_map_name);
            world_renderer.set_emissive_cast_gain(emissive_palette.cast_gain);
            world_renderer.set_emissive_volume(emissive_volume.data(),
                                               world::EmissiveVolume::width,
                                               world::EmissiveVolume::depth,
                                               world::EmissiveVolume::height);
            world_renderer.set_skylight_horizon(skylight.data(), world::SkylightMap::edge);
            skylight.clear_dirty();
        }
        // Decode the shared block/spade/pistol meshes while the loading gate
        // is still visible. The first playable tick must not perform cold KV6
        // file I/O merely because this is the process's first joined match.
        load_tool_meshes();
        if (audio_started && !server_ambience_received) {
            const auto ambience = world::default_map_ambient(tutorial_map_name, live_skydome_name);
            if (!audio->preload_named_ambience(ambience)) {
                settings_warning = std::string{audio->last_error()};
            }
        }
        // Retail does NOT auto-enter the world: the loading screen finishes
        // its arc (sync + initialise), pins the bar at 100%%, empties the
        // status line and waits for the glowing START button.
        tutorial_ready_map = std::move(shared_map);
        if (network_match) {
            live_terrain_replica =
                std::make_unique<network::Protocol168TerrainReplica>(*tutorial_ready_map);
            if (!deferred_terrain_packets.empty()) {
                live_catchup_packet_sync = true;
                deferred_terrain_cursor = 0U;
                match_loading.syncing_map();
                assets::PreloadSnapshot uploaded;
                uploaded.state = assets::PreloadBatchState::active;
                uploaded.progress = 0.0;
                match_loading.set_preload_snapshot(uploaded);
                return;
            }
        }
        if (live_chunk_remesh_queue.empty()) {
            complete_live_map_loading();
        } else {
            live_catchup_render_sync = true;
            live_catchup_remesh_total = live_chunk_remesh_queue.size();
            match_loading.syncing_map();
            assets::PreloadSnapshot uploaded;
            uploaded.state = assets::PreloadBatchState::active;
            uploaded.progress = 0.0;
            match_loading.set_preload_snapshot(uploaded);
        }
    }

    /** The retail START press: instant music stop, confirm cue, reveal. */
    void start_tutorial_pressed() {
        initial_join_submitted = false;
        if (tutorial_ready_map == nullptr) {
            return;
        }
        const PerformanceScope performance{"enter_world", std::chrono::microseconds{2'000}};
        {
            const PerformanceScope stage{"enter_confirm", std::chrono::microseconds{1'000}};
            if (audio_started) {
                audio->stop_menu_music();
                audio->play_menu_confirm();
            }
        }
        if (network_match && screen() == FrontendScreen::game_loading &&
            local_player_id.has_value()) {
            send_client_in_menu(true);
            start_secondary_selection_music();
            class_selection_from_pause = false;
            class_selection_team_change.reset();
            class_selection_initial_join = false;
            ugc_loadout_active = false;
            // ForceTeamJoin is the one retail path that legitimately skips
            // SelectTeam. Every ordinary connection must show SelectTeam
            // before SelectClass; the previous C++ flow skipped this gate.
            if (forced_team == 2U || forced_team == 3U) {
                const auto team = *forced_team;
                if (match_initial_info.map_is_ugc()) {
                    configure_ugc_loadout(UgcLoadoutLibrary::constructs, team, false);
                } else {
                    const auto& advertised = team == 3U ? match_state_info.team2_classes
                                                        : match_state_info.team1_classes;
                    const auto initial_class =
                        advertised.empty() ? std::uint8_t{0U} : advertised.front();
                    class_selection_menu.configure(advertised, team, initial_class);
                    ugc_loadout_active = false;
                }
                class_selection_initial_join = true;
                initial_join_team = team;
                static_cast<void>(navigation.replace(FrontendScreen::class_selection,
                                                     NavigationDirection::forward));
            } else {
                initial_join_team.reset();
                change_team_menu.configure(team_roster_state(true));
                static_cast<void>(
                    navigation.replace(FrontendScreen::change_team, NavigationDirection::forward));
            }
            return;
        }
        world::TutorialSessionConfig session_config;
        session_config.flight_profile = network_match ? match_initial_info.flight_profile
                                                       : world::balanced_flight_profile();
        session_config.mouse_sensitivity = applied_settings.controls.mouse_sensitivity;
        session_config.invert_mouse = applied_settings.main.invert_mouse;
        if (network_match) {
            // StateData, not InitialInfo, owns the map's native world gravity.
            // Passing it into every prediction/replay step prevents the
            // continuous LunarBase correction loop against the server.
            session_config.gravity = match_state_info.gravity;
        }
        // Training spawns inside an enclosed corridor, so an outdoor capture
        // otherwise depends on synthetic input reaching the window.
        // Any map other than Training needs its own spawn resolved. The default
        // initial_position is Training's authored anchor, and reusing it on
        // another map is how every non-Training capture ended up standing in the
        // sea at feet 240 or falling in from above: that column happens to be
        // open water or empty air on most of the catalogue. resolve_map_spawn
        // searches outward using the real ground predicate, and reproduces
        // Training's own anchor exactly when asked for its column, so this is a
        // derivation rather than a second guess at the same value.
        const bool loaded_other_map = config.tutorial_map.has_value();
        if (!network_match && tutorial_ready_map &&
            (loaded_other_map || config.tutorial_stand.has_value())) {
            const auto column =
                config.tutorial_stand.value_or(std::array<double, 2U>{256.0, 256.0});
            const auto resolved =
                world::resolve_map_spawn(*tutorial_ready_map,
                                         static_cast<std::uint32_t>(std::lround(column[0U])),
                                         static_cast<std::uint32_t>(std::lround(column[1U])));
            session_config.initial_position = resolved.position;
            if (!resolved.derived) {
                settings_warning = "no standable ground near the requested column";
            }
        }
        if (config.tutorial_spawn.has_value()) {
            const auto& spawn = *config.tutorial_spawn;
            session_config.initial_position = {spawn[0U], spawn[1U], spawn[2U]};
        }
        if (config.tutorial_look.has_value()) {
            const auto& target = *config.tutorial_look;
            const auto& from = session_config.initial_position;
            const world::Vec3 delta{target[0U] - from.x, target[1U] - from.y, target[2U] - from.z};
            const double length =
                std::sqrt((delta.x * delta.x) + (delta.y * delta.y) + (delta.z * delta.z));
            // A target coincident with the spawn has no direction to offer;
            // leaving the default beats normalising by zero.
            if (length > 1e-6) {
                session_config.initial_orientation = {
                    delta.x / length, delta.y / length, delta.z / length};
            }
        }
        if (network_match && local_player_id.has_value()) {
            const auto* replica = tutorial_roster.player(*local_player_id);
            if (replica == nullptr) {
                match_loading.fail("PLAYER_STATE_MISSING");
                settings_warning = "server map completed without the local CreatePlayer";
                return;
            }
            session_config.network_authoritative = true;
            session_config.initial_position = replica->position;
            session_config.initial_orientation = replica->orientation;
            session_config.initial_velocity = replica->velocity;
            session_config.initial_crouch = (replica->input_flags & 0x20U) != 0U;
            session_config.initial_wade = (replica->state_flags & 0x08U) != 0U;
            if (pending_class_selection.has_value()) {
                session_config.initial_class_id = pending_class_selection->class_id;
                session_config.initial_loadout = pending_class_selection->loadout;
                session_config.initial_prefabs = pending_class_selection->prefabs;
                session_config.initial_ugc_tools = pending_class_selection->ugc_tools;
            } else {
                session_config.initial_class_id = replica->class_id;
                session_config.initial_loadout = replica->loadout;
                session_config.initial_prefabs = replica->prefabs;
                session_config.initial_ugc_tools = replica->ugc_tools;
            }
            if (const auto* class_definition =
                    world::find_class_definition(session_config.initial_class_id);
                class_definition != nullptr) {
                session_config.initial_tool =
                    world::preferred_spawn_tool(*class_definition, session_config.initial_loadout);
            }
            // InitialInfo stores the multiplier applied to every native class
            // movement constant. It is not an already-composed sprint speed;
            // dividing it by the class sprint value made Soldier prediction
            // roughly 45% slower than the authoritative server.
            session_config.movement_speed_scale = network::protocol168_movement_scale(
                match_initial_info, session_config.initial_class_id);
            local_spawn_confirmed = true;
        }
        {
            const PerformanceScope stage{"enter_session", std::chrono::microseconds{1'000}};
            tutorial_session = std::make_unique<world::TutorialWorldSession>(
                std::move(tutorial_ready_map), session_config);
        }
        if (network_match && local_player_id.has_value()) {
            const auto* replica = tutorial_roster.player(*local_player_id);
            if (replica != nullptr && replica->acknowledged_client_loop >= 0) {
                tutorial_session->apply_server_jetpack_fuel(
                    replica->jetpack_fuel, replica->acknowledged_client_loop);
                tutorial_session->apply_server_movement_state(
                    replica->action_flags, replica->state_flags, replica->pickup_id,
                    replica->acknowledged_client_loop);
            }
        }
        tutorial_ready_map.reset();
        if (local_palette_color.has_value()) {
            tutorial_session->set_block_color(
                world::VxlColor{static_cast<std::uint8_t>(*local_palette_color >> 16U),
                                static_cast<std::uint8_t>(*local_palette_color >> 8U),
                                static_cast<std::uint8_t>(*local_palette_color),
                                255U});
        }
        {
            const PerformanceScope stage{"enter_minimap", std::chrono::microseconds{1'000}};
            if (!sync_minimap_texture()) {
                // A presentation-only upload failure must not invalidate the
                // authoritative map or strand the loading state.
                minimap_pixels.clear();
                minimap_texture_upload_pending = true;
            }
        }
        // Skylight, the minimap and emissive spill were prepared beside chunk
        // meshing on the loader thread. START now performs only bounded GPU
        // uploads instead of freezing the class-selection transition.
        if (developer_tools_allowed() && config.tutorial_debug_tool.has_value()) {
            tutorial_session->debug_grant_full_loadout();
            static_cast<void>(tutorial_session->equip_inventory_slot(
                static_cast<std::size_t>(*config.tutorial_debug_tool)));
        }
        if (developer_tools_allowed() && config.tutorial_debug_aim) {
            tutorial_session->set_secondary_held(true);
            tutorial_session->set_secondary_held(false);
        }
        if (!network_match || !local_player_id.has_value()) {
            pause_menu = PauseMenuModel{PauseMenuEnvironment{false, false, false, false}};
        } else if (const auto* local = tutorial_roster.player(*local_player_id); local != nullptr) {
            const bool team2 = local->team == 3U;
            const auto& classes =
                team2 ? match_state_info.team2_classes : match_state_info.team1_classes;
            pause_menu = PauseMenuModel{pause_menu_environment_for({
                match_state_info.mode_type,
                local->team,
                local->class_id,
                classes.size(),
                team2 ? match_state_info.team2_locked_class : match_state_info.team1_locked_class,
                match_state_info.team1_locked,
                match_state_info.team2_locked,
                match_state_info.lock_team_swap,
                match_state_info.lock_spectator_swap,
                match_initial_info.enable_spectator,
                match_state_info.has_map_ended,
                match_state_info.mode_type == 12U,
            })};
        }
        {
            const PerformanceScope stage{"enter_tools", std::chrono::microseconds{1'000}};
            load_tool_meshes();
        }
        if (!network_match && !load_tutorial_class_arms(tutorial_session->debug_class_id())) {
            settings_warning = "tutorial arm model failed: " + settings_warning;
        }
        uploaded_tool.reset();
        view_model_meshes_uploaded = false;
        {
            const PerformanceScope stage{"enter_viewmodel_clear", std::chrono::microseconds{1'000}};
            world_renderer.clear_view_model();
        }
        // Live WorldUpdates stream remote rigs through the one-upload-per-tick
        // presentation lane. Loading the complete roster here recreated the
        // exact first-playable-frame hitch that lane is intended to prevent.
        // The fixture roster is a parity-lab gallery, not part of retail's
        // Tutorial. Player releases enter Training with only the local player;
        // developer builds retain the gallery for model/packet inspection.
        const bool players_loaded =
            network_match || !developer_tools_allowed() || load_tutorial_packet_players();
        if (!players_loaded) {
            settings_warning = "tutorial CreatePlayer fixtures failed: " + settings_warning;
        }
        // Retail reveal: INTRO help plus StopMusic + PlayMusic and the map's
        // own ambient bed. Live servers may replace the local safety bed with
        // CreateAmbientSound(22)+PlayAmbientSound(24).
        game_hud = GameHudModel{};
        if (!network_match) {
            show_lesson_help(world::TutorialLessonStage::intro);
            if (audio_started &&
                (!audio->play_tutorial_music() ||
                 !audio->play_named_ambience(
                     world::default_map_ambient(tutorial_map_name, live_skydome_name), 1.0F))) {
                settings_warning = std::string{audio->last_error()};
            }
        } else if (const auto* local = tutorial_roster.player(*local_player_id); local != nullptr) {
            // The first CreatePlayer arrived before this world session
            // existed. Apply that same authoritative life boundary now;
            // otherwise initial spectators retain the default live FPS view.
            end_local_death(local->team, local->dead);
            {
                const PerformanceScope stage{"enter_arms", std::chrono::microseconds{1'000}};
                static_cast<void>(load_tutorial_class_arms(local->class_id));
            }
            if (audio_started) {
                const PerformanceScope stage{"enter_audio", std::chrono::microseconds{1'000}};
                // Main-menu music must never leak into the match. The server's
                // PlayMusic packet replaces this silence when it owns a track.
                if (!server_music_received) {
                    audio->stop_menu_music();
                }
                if (!server_ambience_received &&
                    !audio->play_named_ambience(
                        world::default_map_ambient(tutorial_map_name, live_skydome_name), 1.0F)) {
                    settings_warning = std::string{audio->last_error()};
                }
            }
        }
        pending_class_selection.reset();
        if (screen() == FrontendScreen::game_loading || screen() == FrontendScreen::change_team ||
            screen() == FrontendScreen::class_selection) {
            const PerformanceScope stage{"enter_navigation", std::chrono::microseconds{1'000}};
            static_cast<void>(
                navigation.replace(FrontendScreen::tutorial_world, NavigationDirection::forward));
        }
    }

    /**
     * A join code is one-use and expires on the master (90 s on the live site)
     * while it is only sent with NewPlayerConnection, after the map loaded and
     * the player chose a team and a class. A host that read chat for three
     * minutes on those screens was refused with ERROR_NOTICKET.
     */
    [[nodiscard]] bool join_code_stale() const {
        return join_code_issued_at.has_value() &&
               std::chrono::steady_clock::now() - *join_code_issued_at >
                   std::chrono::seconds{30};
    }

    void begin_join_ticket_refresh(world::ClassSelection selection, std::uint8_t fallback_team) {
        if (join_ticket_refresh.has_value()) {
            // A live refresh already holds a pick; an abandoned one is still
            // draining and a second future would block on it, so the code we
            // hold goes out as it is.
            if (join_ticket_refresh->generation != 0U) return;
            if (join_ticket_refresh->ticket.valid() &&
                join_ticket_refresh->ticket.wait_for(std::chrono::milliseconds{0}) !=
                    std::future_status::ready) {
                join_code_issued_at.reset();
                submit_loadout_selection(std::move(selection), fallback_team);
                return;
            }
            join_ticket_refresh.reset();
        }
        if (!active_match_request.has_value() || active_match_request->identity_server_id.empty() ||
            identity_service == nullptr) {
            join_code_issued_at.reset();
            submit_loadout_selection(std::move(selection), fallback_team);
            return;
        }
        auto service = identity_service;
        const auto server_id = active_match_request->identity_server_id;
        JoinTicketRefresh refresh;
        refresh.selection = std::move(selection);
        refresh.fallback_team = fallback_team;
        refresh.generation = next_join_ticket_refresh_generation++;
        refresh.ticket = std::async(std::launch::async, [service, server_id] {
            return service->game_ticket(server_id);
        });
        join_ticket_refresh = std::move(refresh);
        settings_warning = "Authorizing with AoSPlay...";
        core::diagnostic("identity", "join code older than 30 s; fetching a fresh one before joining");
    }

    void pump_join_ticket_refresh() {
        if (!join_ticket_refresh.has_value() || !join_ticket_refresh->ticket.valid() ||
            join_ticket_refresh->ticket.wait_for(std::chrono::milliseconds{0}) !=
                std::future_status::ready) {
            return;
        }
        auto refresh = std::move(*join_ticket_refresh);
        join_ticket_refresh.reset();
        auto ticket = refresh.ticket.get();
        if (refresh.generation == 0U || match_connection == nullptr ||
            !class_selection_initial_join) {
            return;
        }
        if (ticket) {
            active_join_wire_name = std::move(ticket.join_code);
            join_code_issued_at = std::chrono::steady_clock::now();
        } else {
            // Send the code we hold and let the server decide.
            core::diagnostic("identity", "join code refresh failed: " + ticket.error);
            join_code_issued_at.reset();
        }
        settings_warning.clear();
        submit_loadout_selection(std::move(refresh.selection), refresh.fallback_team);
    }

    /** Commit either SelectClass or SelectUGC through the same packet-13 transaction. */
    void submit_loadout_selection(world::ClassSelection selection,
                                  std::uint8_t fallback_team) {
        if (match_connection == nullptr || !local_player_id.has_value()) return;
        // The first press already sent NewPlayerConnection. A repeat press
        // before CreatePlayer arrives would resend the loadout without a team.
        if (initial_join_submitted) return;
        if (class_selection_initial_join && join_code_stale()) {
            begin_join_ticket_refresh(std::move(selection), fallback_team);
            return;
        }
        if (selection.loadout.empty()) {
            settings_warning = "selected class has no valid Protocol 168 loadout";
            return;
        }
        network::SetClassLoadoutPacket packet;
        packet.player_id = *local_player_id;
        packet.class_id = selection.class_id;
        // Join selection is instant; pause/team changes stage the complete
        // loadout at the authoritative death/respawn boundary.
        const bool in_game_change =
            !class_selection_initial_join &&
            (class_selection_from_pause || class_selection_team_change.has_value());
        packet.instant = !in_game_change;
        packet.loadout = selection.loadout;
        packet.prefabs = selection.prefabs;
        packet.ugc_tools = selection.ugc_tools;
        if (!match_connection->send(network::encode_packet(packet))) {
            settings_warning = "failed to queue SetClassLoadout(13)";
            return;
        }
        const bool initial_join = class_selection_initial_join;
        static_cast<void>(tutorial_roster.update_loadout(*local_player_id,
                                                         selection.class_id,
                                                         selection.loadout,
                                                         selection.prefabs,
                                                         selection.ugc_tools));
        pending_class_selection = std::move(selection);
        play_confirm();
        if (in_game_change) {
            const std::array<std::byte, 3U> change_class{
                std::byte{78U}, static_cast<std::byte>(*local_player_id),
                static_cast<std::byte>(packet.class_id)};
            if (!match_connection->send(change_class)) {
                settings_warning = "failed to queue ChangeClass(78)";
            }
            class_selection_from_pause = false;
            class_selection_team_change.reset();
            class_selection_initial_join = false;
            ugc_loadout_active = false;
            send_client_in_menu(false);
            if (audio_started) audio->stop_menu_music();
            static_cast<void>(
                navigation.reset(FrontendScreen::tutorial_world, NavigationDirection::back));
            return;
        }

        send_client_in_menu(false);
        const auto join_team = initial_join_team.value_or(fallback_team);
        if (!initial_join || !send_initial_player(join_team, packet.class_id)) {
            settings_warning = !initial_join
                                   ? "initial class selection lost its team transaction"
                                   : settings_warning;
            send_client_in_menu(true);
            return;
        }
        class_selection_initial_join = false;
        initial_join_team.reset();
        initial_join_submitted = true;
        // The authoritative CreatePlayer calls start_tutorial_pressed(). No
        // provisional dead/player replica is manufactured locally.
    }

    void handle_ugc_loadout_action(std::optional<UgcLoadoutAction> action) {
        if (!action.has_value()) return;
        if (*action == UgcLoadoutAction::back) {
            ugc_loadout_active = false;
            if (class_selection_initial_join) {
                class_selection_initial_join = false;
                initial_join_team.reset();
                change_team_menu.configure(team_roster_state(true));
                static_cast<void>(
                    navigation.replace(FrontendScreen::change_team, NavigationDirection::back));
            } else if (class_selection_from_pause) {
                class_selection_from_pause = false;
                static_cast<void>(navigation.pop());
            } else if (class_selection_team_change.has_value()) {
                class_selection_team_change.reset();
                refresh_pause_menu();
                static_cast<void>(
                    navigation.replace(FrontendScreen::change_team, NavigationDirection::back));
            } else {
                static_cast<void>(
                    navigation.replace(FrontendScreen::game_loading, NavigationDirection::back));
            }
            play_back();
            return;
        }
        submit_loadout_selection(ugc_loadout_menu.selection(), ugc_loadout_menu.team());
    }

    void handle_class_selection_action(std::optional<ClassSelectionAction> action) {
        if (!action.has_value())
            return;
        if (*action == ClassSelectionAction::back) {
            if (class_selection_initial_join) {
                class_selection_initial_join = false;
                initial_join_team.reset();
                change_team_menu.configure(team_roster_state(true));
                static_cast<void>(
                    navigation.replace(FrontendScreen::change_team, NavigationDirection::back));
            } else if (class_selection_from_pause) {
                class_selection_from_pause = false;
                static_cast<void>(navigation.pop());
            } else if (class_selection_team_change.has_value()) {
                class_selection_team_change.reset();
                refresh_pause_menu();
                static_cast<void>(
                    navigation.replace(FrontendScreen::change_team, NavigationDirection::back));
            } else {
                static_cast<void>(
                    navigation.replace(FrontendScreen::game_loading, NavigationDirection::back));
            }
            play_back();
            return;
        }
        submit_loadout_selection(class_selection_menu.selection(),
                                 class_selection_menu.team());
    }

    void handle_loading_click(ui::Point point) {
        // Retail large navbar BACK strip, bottom-left.
        if (loading_layout::contains(loading_layout::back, point.x, point.y)) {
            if (navigation.pop()) {
                play_back();
            }
            return;
        }
        const auto snapshot = match_loading.snapshot();
        for (std::size_t index = 0U; index < snapshot.tabs.size(); ++index) {
            if (loading_layout::contains(loading_layout::tab(index), point.x, point.y)) {
                static_cast<void>(match_loading.select_tab(index));
                play_scroll();
                return;
            }
        }
        if (match_loading.handle_score_click(point.x, point.y)) {
            play_scroll();
            return;
        }
        if (tutorial_bootstrap == nullptr && tutorial_ready_map == nullptr) {
            return;
        }
        if (snapshot.start_enabled && loading_layout::contains(loading_layout::start, point.x, point.y)) {
            start_tutorial_pressed();
        }
    }

    /** Display names for common SDL scancodes, retail bracket style. */
    [[nodiscard]] static std::string scancode_display_name(std::uint32_t scancode) {
        if (scancode >= 4U && scancode <= 29U) {
            return std::string{static_cast<char>('A' + (scancode - 4U))};
        }
        if (scancode >= 30U && scancode <= 38U) {
            return std::string{static_cast<char>('1' + (scancode - 30U))};
        }
        switch (scancode) {
        case 39U:
            return "0";
        case scancode_space:
            return "SPACE";
        case scancode_return:
            return "ENTER";
        case scancode_tab:
            return "TAB";
        case 224U:
            return "LCTRL";
        case 225U:
            return "LSHIFT";
        case 226U:
            return "LALT";
        case 228U:
            return "RCTRL";
        case 229U:
            return "RSHIFT";
        default:
            // SDL reserves one contiguous scancode range for F1..F12.
            // Retail's voting HUD prints these actual bindings; omitting the
            // range made the correctly-bound F1/F2/F3 actions fall back to the
            // misleading labels "1", "2" and "3".
            if (scancode >= 58U && scancode <= 69U) {
                return "F" + std::to_string(scancode - 57U);
            }
            return "?";
        }
    }

    [[nodiscard]] ControlKeyNames control_key_names() const {
        const auto name_for = [&](settings::ControlAction action, std::string fallback) {
            const auto binding = applied_settings.controls.binding(action);
            if (binding.kind != settings::BindingKind::keyboard_scancode) {
                return fallback;
            }
            auto name = scancode_display_name(binding.code);
            return name == "?" ? fallback : name;
        };
        ControlKeyNames names;
        names.forward = name_for(settings::ControlAction::forward, "W");
        names.backward = name_for(settings::ControlAction::backward, "S");
        names.left = name_for(settings::ControlAction::left, "A");
        names.right = name_for(settings::ControlAction::right, "D");
        names.jump = name_for(settings::ControlAction::jump, "SPACE");
        names.crouch = name_for(settings::ControlAction::crouch, "LCTRL");
        names.tool_help = name_for(settings::ControlAction::tool_help, "H");
        return names;
    }

    /** Shows one lesson stage's recovered help copy with retail pacing. */
    void show_lesson_help(world::TutorialLessonStage stage) {
        const auto names = control_key_names();
        std::vector<std::string> lines;
        for (const auto key : world::TutorialLessons::message_keys(stage)) {
            lines.push_back(resolve_control_placeholders(tutorial_string(key), names));
        }
        game_hud.set_help_messages(
            std::move(lines),
            resolve_control_placeholders(tutorial_string("TOOL_HELP_PANEL_CLOSE"), names),
            world::TutorialLessons::help_transition_delay);
    }

    [[nodiscard]] bool binding_matches(settings::ControlAction action,
                                       std::uint32_t scancode) const noexcept {
        const auto binding = applied_settings.controls.binding(action);
        return binding.kind == settings::BindingKind::keyboard_scancode && binding.code == scancode;
    }

    void begin_chat(ChatChannel channel) {
        if (!network_match || match_connection == nullptr || !local_player_id.has_value()) {
            return;
        }
        if (tutorial_session != nullptr)
            tutorial_session->clear_input();
        if (mouse_captured) {
            static_cast<void>(window.set_relative_mouse_mode(false));
            mouse_captured = false;
        }
        game_chat.begin(channel);
        if (!window.set_text_input_enabled(true)) {
            settings_warning = "platform text input could not be enabled";
        }
    }

    void close_chat(bool submit) {
        std::optional<std::pair<ChatChannel, std::string>> outgoing;
        if (submit) {
            outgoing = game_chat.submit();
        } else {
            game_chat.cancel();
        }
        static_cast<void>(window.set_text_input_enabled(false));
        if (!outgoing.has_value() || match_connection == nullptr || !local_player_id.has_value()) {
            return;
        }
        network::ChatMessagePacket packet;
        packet.player_id = *local_player_id;
        packet.chat_type = static_cast<std::uint8_t>(outgoing->first);
        packet.value = std::move(outgoing->second);
        const auto encoded = network::encode_packet(packet);
        if (encoded.empty() || !match_connection->send(encoded)) {
            settings_warning = "failed to queue ChatMessage(49)";
        }
    }

    [[nodiscard]] std::array<std::string, 3U> vote_key_names() const {
        const auto key = [this](settings::ControlAction action, std::string fallback) {
            const auto binding = applied_settings.controls.binding(action);
            if (binding.kind != settings::BindingKind::keyboard_scancode) {
                return fallback;
            }
            auto name = scancode_display_name(binding.code);
            return name == "?" ? fallback : name;
        };
        return {
            key(settings::ControlAction::map_vote_1, "F1"),
            key(settings::ControlAction::map_vote_2, "F2"),
            key(settings::ControlAction::map_vote_3, "F3"),
        };
    }

    void cast_vote(std::size_t candidate_index) {
        if (match_connection == nullptr || !local_player_id.has_value()) {
            return;
        }
        const auto candidate = generic_vote.cast(candidate_index);
        if (!candidate.has_value())
            return;
        const auto encoded = network::encode_generic_vote_cast(*local_player_id, *candidate);
        if (encoded.empty() || !match_connection->send(encoded)) {
            settings_warning = "failed to queue GenericVoteMessage(47) CAST";
        }
    }

    void route_tutorial_key(std::uint32_t scancode, bool pressed) {
        if (tutorial_session == nullptr) {
            return;
        }
        if (binding_matches(settings::ControlAction::show_map, scancode)) {
            game_hud.set_full_map_visible(pressed);
        }
        if (ugc_prefab_selected() &&
            binding_matches(settings::ControlAction::carve_prefab, scancode)) {
            ugc_prefab_control.set_input(world::UgcPrefabControlInput::carve, pressed);
            return;
        }
        if (ugc_prefab_control.active()) {
            static constexpr std::array ugc_movement_bindings{
                std::pair{settings::ControlAction::forward,
                          world::UgcPrefabControlInput::forward},
                std::pair{settings::ControlAction::backward,
                          world::UgcPrefabControlInput::backward},
                std::pair{settings::ControlAction::left,
                          world::UgcPrefabControlInput::left},
                std::pair{settings::ControlAction::right,
                          world::UgcPrefabControlInput::right},
                std::pair{settings::ControlAction::jump,
                          world::UgcPrefabControlInput::up},
                std::pair{settings::ControlAction::crouch,
                          world::UgcPrefabControlInput::down},
                std::pair{settings::ControlAction::sprint,
                          world::UgcPrefabControlInput::sprint},
                std::pair{settings::ControlAction::palette_left,
                          world::UgcPrefabControlInput::rotate_left},
                std::pair{settings::ControlAction::palette_right,
                          world::UgcPrefabControlInput::rotate_right},
                std::pair{settings::ControlAction::palette_up,
                          world::UgcPrefabControlInput::rotate_up},
                std::pair{settings::ControlAction::palette_down,
                          world::UgcPrefabControlInput::rotate_down},
            };
            for (const auto& [setting, input] : ugc_movement_bindings) {
                if (binding_matches(setting, scancode)) {
                    ugc_prefab_control.set_input(input, pressed);
                    return;
                }
            }
            if (binding_matches(settings::ControlAction::cancel_prefab_placement,
                                scancode)) {
                if (pressed) {
                    ugc_prefab_control.deactivate();
                    update_prefab_candidate();
                }
                return;
            }
        }
        if (death_camera.active()) {
            // Death/chase cameras consume look and target-selection input, but
            // never leak W/A/S/D/jump/tool state into the dead player object.
            return;
        }
        static constexpr std::array<std::pair<settings::ControlAction, world::TutorialAction>, 9U>
            movement_bindings{{
                {settings::ControlAction::forward, world::TutorialAction::forward},
                {settings::ControlAction::backward, world::TutorialAction::backward},
                {settings::ControlAction::left, world::TutorialAction::left},
                {settings::ControlAction::right, world::TutorialAction::right},
                {settings::ControlAction::jump, world::TutorialAction::jump},
                {settings::ControlAction::crouch, world::TutorialAction::crouch},
                {settings::ControlAction::sneak, world::TutorialAction::sneak},
                {settings::ControlAction::sprint, world::TutorialAction::sprint},
                {settings::ControlAction::hover, world::TutorialAction::hover},
            }};
        for (const auto& [setting, action] : movement_bindings) {
            const auto binding = applied_settings.controls.binding(setting);
            if (binding.kind == settings::BindingKind::keyboard_scancode &&
                binding.code == scancode) {
                tutorial_session->set_action_held(action, pressed);
            }
        }
        if (!pressed) {
            return;
        }
        if (binding_matches(settings::ControlAction::palette_left, scancode)) {
            move_palette_selection(-1, 0);
        } else if (binding_matches(settings::ControlAction::palette_right, scancode)) {
            move_palette_selection(1, 0);
        } else if (binding_matches(settings::ControlAction::palette_up, scancode)) {
            move_palette_selection(0, -1);
        } else if (binding_matches(settings::ControlAction::palette_down, scancode)) {
            move_palette_selection(0, 1);
        }
    }

