    static constexpr std::uint32_t view_model_slot_debug_lower_b{7U};
    // Character.draw_sight's own two models. The tutorial tools own fixed
    // slots rather than the sandbox's running counter, so these are fixed too.
    static constexpr std::uint32_t view_model_slot_sight{8U};
    static constexpr std::uint32_t view_model_slot_pin{9U};
    static constexpr std::uint32_t placement_deployable_slot{12U};
    static constexpr std::uint32_t placement_deployable_slot_count{4U};
    static constexpr std::uint32_t parachute_world_slot{16U};
    static constexpr std::uint32_t parachute_first_person_slot{17U};
    static constexpr std::uint32_t placement_block_valid_slot{20U};
    static constexpr std::uint32_t placement_block_invalid_slot{21U};
    static constexpr std::uint32_t placement_prefab_valid_slot{22U};
    static constexpr std::uint32_t placement_prefab_invalid_slot{23U};
    /** Catalog row behind TutorialTool::pistol, the only tutorial tool that aims. */
    static constexpr std::uint8_t tutorial_pistol_tool_id{17U};

    /**
     * 4x4 matrices in the row-vector convention whose memory layout matches
     * bgfx::setTransform (translation at [12..14]). mat_mul(a, b) applies a
     * first, then b — the reverse of retail's glRotate/glTranslate call
     * order, so recovered GL chains are composed back-to-front.
     */
    using Mat4 = std::array<float, 16U>;

    [[nodiscard]] static Mat4 mat_identity() {
        return {1.0F,
                0.0F,
                0.0F,
                0.0F,
                0.0F,
                1.0F,
                0.0F,
                0.0F,
                0.0F,
                0.0F,
                1.0F,
                0.0F,
                0.0F,
                0.0F,
                0.0F,
                1.0F};
    }

    [[nodiscard]] static Mat4 mat_mul(const Mat4& a, const Mat4& b) {
        Mat4 result{};
        for (std::size_t row{}; row < 4U; ++row) {
            for (std::size_t column{}; column < 4U; ++column) {
                float sum{};
                for (std::size_t k{}; k < 4U; ++k) {
                    sum += a[row * 4U + k] * b[k * 4U + column];
                }
                result[row * 4U + column] = sum;
            }
        }
        return result;
    }

    [[nodiscard]] static Mat4 mat_translate(float x, float y, float z) {
        auto result = mat_identity();
        result[12U] = x;
        result[13U] = y;
        result[14U] = z;
        return result;
    }

    [[nodiscard]] static Mat4 mat_scale(float scale) {
        auto result = mat_identity();
        result[0U] = scale;
        result[5U] = scale;
        result[10U] = scale;
        return result;
    }

    [[nodiscard]] static Mat4 mat_rotate_x(float degrees) {
        const auto radians = static_cast<float>(degrees * std::numbers::pi / 180.0);
        const float c = std::cos(radians);
        const float s = std::sin(radians);
        auto result = mat_identity();
        result[5U] = c;
        result[6U] = s;
        result[9U] = -s;
        result[10U] = c;
        return result;
    }

    [[nodiscard]] static Mat4 mat_rotate_y(float degrees) {
        const auto radians = static_cast<float>(degrees * std::numbers::pi / 180.0);
        const float c = std::cos(radians);
        const float s = std::sin(radians);
        auto result = mat_identity();
        result[0U] = c;
        result[2U] = -s;
        result[8U] = s;
        result[10U] = c;
        return result;
    }

    [[nodiscard]] static Mat4 mat_rotate_z(float degrees) {
        const auto radians = static_cast<float>(degrees * std::numbers::pi / 180.0);
        const float c = std::cos(radians);
        const float s = std::sin(radians);
        auto result = mat_identity();
        result[0U] = c;
        result[1U] = s;
        result[4U] = -s;
        result[5U] = c;
        return result;
    }

    [[nodiscard]] static std::array<float, 3U>
    mat_transform_point(const Mat4& matrix,
                        const std::array<float, 3U>& point) noexcept {
        return {
            point[0U] * matrix[0U] + point[1U] * matrix[4U] +
                point[2U] * matrix[8U] + matrix[12U],
            point[0U] * matrix[1U] + point[1U] * matrix[5U] +
                point[2U] * matrix[9U] + matrix[13U],
            point[0U] * matrix[2U] + point[1U] * matrix[6U] +
                point[2U] * matrix[10U] + matrix[14U],
        };
    }

    /**
     * character.pyx:2085-2089's second draw_scaled: the classic rifle's front
     * bead, sharing the sight's identity root and 180 degree yaw but carrying
     * Weapon.pin_scale and its own translation off the already-offset sight
     * position. Shared by both aimed paths so they cannot drift apart.
     */
    [[nodiscard]] static Mat4 sight_pin_matrix(const world::RetailSightPose& sight) {
        Mat4 pin = mat_scale(static_cast<float>(sight.pin_scale));
        pin = mat_mul(pin,
                      mat_translate(static_cast<float>(sight.pin_position.x),
                                    static_cast<float>(sight.pin_position.y),
                                    static_cast<float>(sight.pin_position.z)));
        return mat_mul(pin, mat_rotate_y(static_cast<float>(sight.yaw_degrees)));
    }

    /** Uploads only newly-created terrain effect meshes and releases expired slots. */
    [[nodiscard]] bool sync_terrain_effect_meshes() {
        const auto effects = terrain_effects.instances();
        const world::ChunkMesh empty;
        for (auto iterator = terrain_effect_slots.begin();
             iterator != terrain_effect_slots.end();) {
            const bool alive = std::ranges::any_of(
                effects, [id = iterator->first](const auto& effect) { return effect.id == id; });
            if (alive) {
                ++iterator;
                continue;
            }
            if (!world_renderer.set_world_model_mesh(iterator->second, empty)) {
                return false;
            }
            iterator = terrain_effect_slots.erase(iterator);
        }

        for (const auto& effect : effects) {
            if (terrain_effect_slots.contains(effect.id)) {
                continue;
            }
            std::optional<std::uint32_t> free_slot;
            for (std::uint32_t slot = render::WorldRenderer::terrain_effect_slot_base;
                 slot < render::WorldRenderer::terrain_effect_slot_base +
                            render::WorldRenderer::terrain_effect_slot_count;
                 ++slot) {
                const bool used =
                    std::ranges::any_of(terrain_effect_slots,
                                        [slot](const auto& entry) { return entry.second == slot; });
                if (!used) {
                    free_slot = slot;
                    break;
                }
            }
            if (!free_slot.has_value()) {
                break;
            }
            if (!world_renderer.set_world_model_mesh(*free_slot, effect.mesh)) {
                return false;
            }
            terrain_effect_slots.emplace(effect.id, *free_slot);
        }
        return true;
    }

    [[nodiscard]] std::vector<render::WorldModelDraw> terrain_effect_draws() const {
        std::vector<render::WorldModelDraw> draws;
        draws.reserve(terrain_effect_slots.size());
        for (const auto& effect : terrain_effects.instances()) {
            const auto found = terrain_effect_slots.find(effect.id);
            if (found == terrain_effect_slots.end()) {
                continue;
            }
            Mat4 model = mat_rotate_x(effect.rotation_degrees[0U]);
            model = mat_mul(model, mat_rotate_y(effect.rotation_degrees[1U]));
            model = mat_mul(model, mat_rotate_z(effect.rotation_degrees[2U]));
            model = mat_mul(
                model,
                mat_translate(effect.position[0U], effect.position[1U], effect.position[2U]));
            draws.push_back({found->second, model});
        }
        return draws;
    }

    bool sync_deployable_preview_meshes(std::uint8_t tool) {
        const auto type = world::entity_placed_by_tool(tool);
        const auto* definition = world::find_entity_definition(type);
        if (definition == nullptr || definition->parts.empty() ||
            definition->parts.size() > placement_deployable_slot_count) {
            preview_deployable_type_uploaded.reset();
            return true;
        }
        const auto team_color = local_player_team_color();
        const auto* cosmetic = local_equipped_cosmetic("entity:" + std::to_string(type));
        const auto appearance = cosmetic != nullptr ? cosmetic->id : std::string{};
        if (preview_deployable_type_uploaded == type &&
            preview_deployable_team_color == team_color &&
            preview_deployable_appearance == appearance) return true;

        preview_deployable_type_uploaded.reset();
        preview_deployable_minimum_y.clear();
        const auto replacements = inventory_character_parts(cosmetic, config.asset_root);
        for (std::size_t part{}; part < definition->parts.size(); ++part) {
            const auto& piece = definition->parts[part];
            const auto asset = config.asset_root / "kv6" / std::string{piece.kv6};
            std::string error;
            auto model = load_runtime_model(asset, &error);
            if (const auto replacement = replacements.find(std::string{piece.kv6});
                replacement != replacements.end()) model = replacement->second;
            if (!model.has_value()) {
                settings_warning = "deployable preview failed: " +
                                   (error.empty() ? asset.string() : error);
                return true;
            }
            model->offset_pivots(piece.pivot_offset);
            if (cosmetic != nullptr) model->apply_cosmetic_palette(cosmetic->palette);
            world::apply_entity_team_material(*model, type, team_color);
            const auto mesh = model->mesh();
            if (!world_renderer.set_world_model_mesh(
                    placement_deployable_slot + static_cast<std::uint32_t>(part), mesh)) {
                return false;
            }
            preview_deployable_minimum_y.push_back(mesh.minimum[1U]);
        }
        preview_deployable_team_color = team_color;
        preview_deployable_appearance = appearance;
        preview_deployable_type_uploaded = type;
        return true;
    }

    bool sync_placement_preview_meshes() {
        if (tutorial_session == nullptr || !world_renderer.is_initialized()) {
            return true;
        }
        const auto selected_color = local_palette_color.value_or(
            (static_cast<std::uint32_t>(tutorial_session->block_color().red) << 16U) |
            (static_cast<std::uint32_t>(tutorial_session->block_color().green) << 8U) |
            tutorial_session->block_color().blue);
        if (!placement_cube_meshes_uploaded || preview_prefab_color != selected_color) {
            const world::VxlColor color{static_cast<std::uint8_t>(selected_color >> 16U),
                                        static_cast<std::uint8_t>(selected_color >> 8U),
                                        static_cast<std::uint8_t>(selected_color),
                                        255U};
            if (!world_renderer.set_world_model_mesh(placement_block_valid_slot,
                                                     world::placement_preview_cube(color)) ||
                !world_renderer.set_world_model_mesh(
                    placement_block_invalid_slot,
                    world::placement_preview_cube(world::VxlColor{255U, 32U, 32U, 255U}))) {
                return false;
            }
            placement_cube_meshes_uploaded = true;
            preview_prefab_color = selected_color;
            preview_prefab_meshes_uploaded = false;
        }

        const auto selected = tutorial_session->selected_tool_id();
        const auto* weapon =
            selected.has_value() ? world::find_weapon_definition(*selected) : nullptr;
        if (selected.has_value() && world::deployable_placement(*selected) != nullptr &&
            !sync_deployable_preview_meshes(*selected)) {
            return false;
        }
        if (weapon != nullptr && weapon->mechanism == world::WeaponMechanism::ugc_entity) {
            const auto selected_item = tutorial_session->selected_ugc_item();
            if (!selected_item.has_value()) {
                preview_ugc_item_uploaded.reset();
                return true;
            }
            if (preview_ugc_item_uploaded != selected_item) {
                const auto parts = world::ugc_entity_model_parts(*selected_item);
                if (parts.size() != 2U) {
                    settings_warning = "UGC marker has no retail two-part presentation";
                    return true;
                }
                for (std::size_t part{}; part < parts.size(); ++part) {
                    const auto asset = config.asset_root / "kv6" / std::string{parts[part].kv6};
                    std::string error;
                    auto model = load_runtime_model(asset, &error);
                    if (!model.has_value()) {
                        settings_warning = "UGC marker preview failed: " +
                                           (error.empty() ? asset.string() : error);
                        return true;
                    }
                    model->offset_pivots(parts[part].pivot_offset);
                    const auto team = world::ugc_entity_team(*selected_item);
                    if (team == 2U || team == 3U) {
                        world::apply_entity_team_material(*model, 29U, remote_team_color(team));
                    }
                    const auto slot = part == 0U ? placement_prefab_valid_slot
                                                 : placement_prefab_invalid_slot;
                    if (!world_renderer.set_world_model_mesh(slot, model->mesh())) {
                        return false;
                    }
                }
                preview_ugc_item_uploaded = selected_item;
                // Prefab and UGC ghosts deliberately share two bounded slots.
                preview_prefab_meshes_uploaded = false;
            }
            preview_prefab_position.reset();
            preview_prefab_valid = false;
            return true;
        }
        if (preview_ugc_item_uploaded.has_value()) {
            preview_ugc_item_uploaded.reset();
            preview_prefab_meshes_uploaded = false;
        }
        const bool prefab_tool =
            weapon != nullptr && (weapon->mechanism == world::WeaponMechanism::prefab_builder ||
                                  weapon->mechanism == world::WeaponMechanism::ugc_prefab_editor);
        const auto name =
            prefab_tool ? std::string{tutorial_session->selected_prefab()} : std::string{};
        if (name.empty()) {
            preview_prefab_position.reset();
            preview_prefab_valid = false;
            ugc_prefab_control.reset();
            return true;
        }
        if (name != preview_prefab_name) {
            preview_prefab_name = name;
            preview_prefab_model.reset();
            preview_prefab_placement.reset();
            preview_prefab_icon = world::prefab_preview_asset(config.asset_root, name);
            preview_prefab_meshes_uploaded = false;
            prefab_yaw_override = 1U;
            ugc_prefab_control.reset();
            const auto path = resolve_prefab_asset(name);
            std::string error;
            preview_prefab_model = path.has_value() ? world::Kv6Model::load_file(*path, &error)
                                                    : std::optional<world::Kv6Model>{};
            if (!preview_prefab_model.has_value()) {
                settings_warning =
                    "prefab preview failed: " +
                    (error.empty() ? path.value_or(std::filesystem::path{name}).string() : error);
                return true;
            }
            std::vector<world::PrefabPlacementCell> authored;
            authored.reserve(preview_prefab_model->voxels().size());
            for (const auto& voxel : preview_prefab_model->voxels()) {
                authored.push_back({static_cast<std::int32_t>(voxel.x),
                                     static_cast<std::int32_t>(voxel.y),
                                     static_cast<std::int32_t>(voxel.z)});
            }
            preview_prefab_placement.reset(authored);
        }
        if (preview_prefab_model.has_value() && !preview_prefab_meshes_uploaded) {
            const std::array<float, 3U> tint =
                weapon->mechanism == world::WeaponMechanism::ugc_prefab_editor
                    ? std::array<float, 3U>{0.0F, 1.0F, 0.0F}
                    : std::array<float, 3U>{
                          static_cast<float>((selected_color >> 16U) & 0xFFU) / 255.0F,
                          static_cast<float>((selected_color >> 8U) & 0xFFU) / 255.0F,
                          static_cast<float>(selected_color & 0xFFU) / 255.0F};
            if (!world_renderer.set_world_model_mesh(placement_prefab_valid_slot,
                                                     preview_prefab_model->mesh({}, tint)) ||
                !world_renderer.set_world_model_mesh(
                    placement_prefab_invalid_slot,
                    preview_prefab_model->mesh({}, {1.0F, 0.08F, 0.08F}))) {
                return false;
            }
            preview_prefab_meshes_uploaded = true;
        }
        update_prefab_candidate();
        return true;
    }

    [[nodiscard]] std::vector<render::WorldModelDraw> placement_preview_draws() {
        std::vector<render::WorldModelDraw> draws;
        if (tutorial_session == nullptr || !tutorial_session->alive() || death_camera.active() ||
            match_results.visible())
            return draws;
        if (network_match && local_player_id.has_value()) {
            const auto* local = tutorial_roster.player(*local_player_id);
            if (local != nullptr && local->team != 2U && local->team != 3U) return draws;
        }
        const auto selected = tutorial_session->selected_tool_id();
        const auto* weapon =
            selected.has_value() ? world::find_weapon_definition(*selected) : nullptr;
        if (weapon == nullptr)
            return draws;

        if (world::deployable_placement(*selected) != nullptr) {
            // Weapon.can_draw_ghosting accepts either remaining ammo pool.
            const auto* ammo = tutorial_session->selected_ammo();
            if (ammo == nullptr || (ammo->magazine == 0U && ammo->reserve == 0U)) return draws;
            const auto target = tutorial_session->deployable_target(*selected);
            const auto type = world::entity_placed_by_tool(*selected);
            const auto* definition = world::find_entity_definition(type);
            if (!target.has_value() || preview_deployable_type_uploaded != type ||
                definition == nullptr) return draws;
            world::LocalEntity ghost;
            ghost.type = type;
            ghost.position = {static_cast<double>(target->cell[0U]),
                              static_cast<double>(target->cell[1U]),
                              static_cast<double>(target->cell[2U])};
            ghost.face = target->face;
            ghost.attached = true;
            ghost.grounded = true;
            const auto contact = world::entity_rig_vertical_contact_adjustment(
                ghost, *definition, definition->parts, preview_deployable_minimum_y);
            for (std::size_t part{}; part < definition->parts.size(); ++part) {
                // All six retail gadget draw_ghosting methods use alpha 0.3.
                draws.push_back({placement_deployable_slot + static_cast<std::uint32_t>(part),
                    world::entity_presentation_transform(
                        ghost, *definition, definition->parts[part], contact), 0.3F});
            }
            return draws;
        }

        if (weapon->mechanism == world::WeaponMechanism::ugc_entity) {
            const auto item = tutorial_session->selected_ugc_item();
            const auto target = tutorial_session->placement_cell(10.0);
            if (!item.has_value() || !target.has_value() ||
                preview_ugc_item_uploaded != item) {
                return draws;
            }
            // Retail hides the placement ghost while the crosshair is over an
            // existing marker; primary removes it and RMB replaces its group
            // variant instead.
            const bool marker_under_cursor = std::ranges::any_of(
                server_ugc_items, [&](const network::InitialUgcItem& retained) {
                    const auto dx = static_cast<int>(retained.position[0U]) - (*target)[0U];
                    const auto dy = static_cast<int>(retained.position[1U]) - (*target)[1U];
                    const auto dz = static_cast<int>(retained.position[2U]) - (*target)[2U];
                    return dx * dx + dy * dy + dz * dz <= 1;
                });
            if (marker_under_cursor) {
                return draws;
            }
            const auto* definition = world::find_entity_definition(29U);
            const auto parts = world::ugc_entity_model_parts(*item);
            if (definition == nullptr || parts.size() != 2U) {
                return draws;
            }
            world::LocalEntity ghost;
            ghost.type = 29U;
            ghost.team = world::ugc_entity_team(*item);
            ghost.face = 4U;
            ghost.ugc_item_id = *item;
            ghost.position = {static_cast<double>((*target)[0U]),
                              static_cast<double>((*target)[1U]),
                              static_cast<double>((*target)[2U])};
            for (std::size_t part{}; part < parts.size(); ++part) {
                auto model = mat_scale(definition->model_size * parts[part].scale);
                model = mat_mul(model, mat_rotate_x(-90.0F));
                const auto origin = world::entity_presentation_position(ghost, parts[part]);
                model = mat_mul(model,
                                mat_translate(static_cast<float>(origin.x),
                                              static_cast<float>(origin.y),
                                              static_cast<float>(origin.z)));
                draws.push_back({part == 0U ? placement_prefab_valid_slot
                                            : placement_prefab_invalid_slot,
                                 model,
                                 0.3F});
            }
            return draws;
        }

        if (weapon->mechanism == world::WeaponMechanism::block_builder) {
            const auto current =
                tutorial_session->placement_cell(match_initial_info.classic ? 5.0 : 10.0);
            if (!current.has_value())
                return draws;
            network::BlockLinePacket line;
            line.start = block_line_start.value_or(*current);
            line.end = *current;
            const auto cells = network::cube_line_cells(line, 65U);
            const auto placement = world::evaluate_block_line_placement(
                tutorial_session->map(), cells);
            const bool valid = placement.can_place(tutorial_session->blocks_remaining(),
                                                   tutorial_session->infinite_blocks());
            for (const auto& cell : cells) {
                if (cell.x >= world::VxlMap::width || cell.y >= world::VxlMap::depth ||
                    cell.z >= world::VxlMap::height ||
                    tutorial_session->map().solid(cell.x, cell.y, cell.z)) {
                    continue;
                }
                draws.push_back(render::WorldModelDraw{valid ? placement_block_valid_slot
                                                             : placement_block_invalid_slot,
                                                       mat_translate(static_cast<float>(cell.x),
                                                                     static_cast<float>(cell.y),
                                                                     static_cast<float>(cell.z)),
                                                       valid ? 80.0F / 255.0F : 0.4F});
            }
            return draws;
        }

        if ((weapon->mechanism == world::WeaponMechanism::prefab_builder ||
             weapon->mechanism == world::WeaponMechanism::ugc_prefab_editor) &&
            preview_prefab_model.has_value()) {
            update_prefab_candidate();
            if (!preview_prefab_position.has_value())
                return draws;
            const auto model = world::prefab_preview_transform(
                preview_prefab_model->pivot(),
                {(*preview_prefab_position)[0U], (*preview_prefab_position)[1U],
                 (*preview_prefab_position)[2U]},
                preview_prefab_yaw, preview_prefab_pitch, preview_prefab_roll);
            draws.push_back(render::WorldModelDraw{
                preview_prefab_valid ? placement_prefab_valid_slot : placement_prefab_invalid_slot,
                model,
                preview_prefab_valid ? 0.5F : 0.4F,
                preview_prefab_valid &&
                        weapon->mechanism == world::WeaponMechanism::ugc_prefab_editor
                    ? static_cast<float>(ugc_prefab_control.color_animation())
                    : 1.0F});
        }
        return draws;
    }

    /** Uploads projectile KV6s into the dedicated bounded world-model range. */
    [[nodiscard]] bool sync_projectile_meshes() {
        if (tutorial_session == nullptr) {
            return true;
        }
        const auto projectiles = tutorial_session->projectiles();
        const world::ChunkMesh empty;
        for (auto iterator = projectile_slots.begin(); iterator != projectile_slots.end();) {
            const bool alive =
                std::ranges::any_of(projectiles, [id = iterator->first](const auto& projectile) {
                    return projectile.id == id;
                });
            if (alive) {
                ++iterator;
                continue;
            }
            if (!world_renderer.set_world_model_mesh(iterator->second, empty)) {
                return false;
            }
            iterator = projectile_slots.erase(iterator);
        }
        for (const auto& projectile : projectiles) {
            if (projectile_slots.contains(projectile.id)) {
                continue;
            }
            std::optional<std::uint32_t> free_slot;
            for (std::uint32_t slot = render::WorldRenderer::projectile_slot_base;
                 slot < render::WorldRenderer::projectile_slot_base +
                            render::WorldRenderer::projectile_slot_count;
                 ++slot) {
                if (!std::ranges::any_of(projectile_slots, [slot](const auto& entry) {
                        return entry.second == slot;
                    })) {
                    free_slot = slot;
                    break;
                }
            }
            if (!free_slot.has_value()) {
                break;
            }
            std::string error;
            const auto asset =
                config.asset_root / "kv6" / projectile_model_asset(projectile.tool_id);
            auto model = load_runtime_model(asset, &error);
            if (!model.has_value() ||
                !world_renderer.set_world_model_mesh(*free_slot, model->mesh())) {
                settings_warning = "projectile model failed: " +
                                   (error.empty() ? std::string{asset.string()} : error);
                return false;
            }
            projectile_slots.emplace(projectile.id, *free_slot);
        }
        return true;
    }

    [[nodiscard]] std::vector<render::WorldModelDraw> projectile_draws() const {
        std::vector<render::WorldModelDraw> draws;
        if (tutorial_session == nullptr) {
            return draws;
        }
        for (const auto& projectile : tutorial_session->projectiles()) {
            const auto found = projectile_slots.find(projectile.id);
            if (found == projectile_slots.end()) {
                continue;
            }
            auto position = std::array<double, 3U>{
                projectile.position.x, projectile.position.y, projectile.position.z};
            const bool owning_first_person =
                !projectile.autonomous_source &&
                (!network_match ||
                 (local_player_id.has_value() && projectile.source_player == local_player_id));
            if (owning_first_person) {
                position = world::local_rocket_presentation_anchor(
                    projectile.tool_id,
                    {projectile.spawn_position.x, projectile.spawn_position.y,
                     projectile.spawn_position.z},
                    position,
                    {projectile.velocity.x, projectile.velocity.y, projectile.velocity.z},
                    projectile.presentation_age);
            }
            const auto model = world::projectile_presentation_transform(
                position,
                {projectile.velocity.x, projectile.velocity.y, projectile.velocity.z},
                projectile.roll,
                projectile_model_scale(projectile.tool_id));
            draws.push_back({found->second, model});
        }
        return draws;
    }

    /** Packs an entity id and part index into one stable slot key. */
    [[nodiscard]] static constexpr std::uint64_t entity_part_key(std::uint64_t entity_id,
                                                                 std::size_t part) noexcept {
        return (entity_id << 8U) | static_cast<std::uint64_t>(part & 0xFFU);
    }

    /** Uploads entity KV6s into the dedicated bounded world-model range. */
    [[nodiscard]] bool sync_entity_meshes() {
        if (tutorial_session == nullptr) {
            return true;
        }
        if (network_match && remote_rig_uploaded_this_tick) {
            // Do not stack two cold model-upload lanes in one live frame.
            // Entity state is retained and this presentation pass retries on
            // the next tick after the roster has streamed in.
            return true;
        }
        const PerformanceScope performance{"entity_meshes", std::chrono::microseconds{2'000}};
        const auto entities = tutorial_session->entities();
        const world::ChunkMesh empty;
        const auto live = [&entities](std::uint64_t key) {
            const auto id = key >> 8U;
            return std::ranges::any_of(entities, [id](const auto& entity) {
                // A consumed pickup keeps its slot: it is coming back, and
                // releasing the mesh would make it re-upload on every respawn.
                return entity.id == id;
            });
        };
        for (auto iterator = entity_part_slots.begin(); iterator != entity_part_slots.end();) {
            if (live(iterator->first)) {
                ++iterator;
                continue;
            }
            if (!world_renderer.set_world_model_mesh(iterator->second, empty)) {
                return false;
            }
            entity_part_minimum_y.erase(iterator->first);
            entity_part_appearances.erase(iterator->first);
            iterator = entity_part_slots.erase(iterator);
        }
        std::size_t uploaded_this_tick{};
        for (const auto& entity : entities) {
            const auto* definition = world::find_entity_definition(entity.type);
            if (definition == nullptr) {
                continue;
            }
            const auto model_parts = entity.type == 29U
                                         ? world::ugc_entity_model_parts(entity.ugc_item_id)
                                         : definition->parts;
            const auto* cosmetic=(entity.type==11U||entity.type==12U) ? equipped_cosmetic(entity.owner,"tombstone") : equipped_cosmetic(entity.owner,"entity:"+std::to_string(entity.type));
            if(!cosmetic&&entity.owner>=128U&&(!network_match||applied_settings.main.show_other_skins))
                cosmetic=local_equipped_cosmetic("entity:"+std::to_string(entity.type));
            const auto appearance=cosmetic ? cosmetic->id : std::string{};
            for (std::size_t part = 0U; part < model_parts.size(); ++part) {
                const auto key = entity_part_key(entity.id, part);
                const auto existing_slot=entity_part_slots.find(key);
                if (existing_slot!=entity_part_slots.end() && entity_part_appearances[key]==appearance) {
                    continue;
                }
                if (uploaded_this_tick >= entity_mesh_upload_budget) {
                    return true;
                }
                std::optional<std::uint32_t> free_slot;
                if (existing_slot!=entity_part_slots.end()) free_slot=existing_slot->second;
                for (std::uint32_t slot = render::WorldRenderer::entity_slot_base;
                     !free_slot.has_value() && slot < render::WorldRenderer::entity_slot_base +
                                render::WorldRenderer::entity_slot_count;
                     ++slot) {
                    if (!std::ranges::any_of(entity_part_slots, [slot](const auto& entry) {
                            return entry.second == slot;
                        })) {
                        free_slot = slot;
                        break;
                    }
                }
                if (!free_slot.has_value()) {
                    // The session refuses spawns past the budget, so reaching
                    // here means the two limits have drifted apart. Say so
                    // rather than silently drawing nothing.
                    settings_warning = "entity slots exhausted";
                    return true;
                }
                const auto asset =
                    config.asset_root / "kv6" / std::string{model_parts[part].kv6};
                std::optional<world::VxlColor> tint;
                bool team_material{};
                // Entity.draw uses state/team colour whenever state is a real
                // team, including GraveEntity. This is wider than the
                // catalog's team_tinted marker.
                if (entity.team == 2U || entity.team == 3U) {
                    tint = entity.has_color ? world::VxlColor{entity.color[0U],
                                                              entity.color[1U],
                                                              entity.color[2U],
                                                              255U}
                                            : remote_team_color(entity.team);
                    team_material = true;
                } else if (entity.has_color) {
                    tint =
                        world::VxlColor{entity.color[0U], entity.color[1U], entity.color[2U], 255U};
                } else if (definition->team_tinted) {
                    tint = remote_team_color(entity.team);
                }

                const auto tint_key =
                    tint.has_value()
                        ? (1ULL << 40U) | (static_cast<std::uint64_t>(tint->red) << 24U) |
                              (static_cast<std::uint64_t>(tint->green) << 16U) |
                              (static_cast<std::uint64_t>(tint->blue) << 8U) | tint->alpha
                        : 0ULL;
                const auto variant_key = entity.type == 29U
                                             ? static_cast<std::uint64_t>(entity.ugc_item_id & 0x1FU)
                                             : 0ULL;
                const auto model_key = std::pair{(static_cast<std::uint64_t>(entity.type) << 56U) |
                                       (static_cast<std::uint64_t>(part & 0xFFU) << 48U) |
                                       (variant_key << 42U) |
                                       (team_material ? (1ULL << 41U) : 0ULL) | tint_key, cosmetic ? cosmetic->id : std::string{}};
                auto cached = entity_model_cache.find(model_key);
                if (cached == entity_model_cache.end()) {
                    std::string error;
                    auto model = load_runtime_model(asset, &error);
                    if(cosmetic){
                        if(cosmetic->kind=="tombstone"){const auto replacement=inventory_verified_model(*cosmetic,config.asset_root);if(replacement)model=*replacement;}
                        else {const auto parts=inventory_character_parts(cosmetic,config.asset_root);const auto replacement=parts.find(std::string{model_parts[part].kv6});if(replacement!=parts.end())model=replacement->second;}
                    }
                    if (!model.has_value()) {
                        settings_warning = "entity model failed: " +
                                           (error.empty() ? std::string{asset.string()} : error);
                        return false;
                    }
                    const auto& piece = model_parts[part];
                    if(!cosmetic||cosmetic->kind!="tombstone")model->offset_pivots(piece.pivot_offset);
                    if (cosmetic) model->apply_cosmetic_palette(cosmetic->palette);
                    if (tint.has_value() && team_material) {
                        world::apply_entity_team_material(*model, entity.type, *tint);
                    } else if (tint.has_value()) {
                        model->apply_default_color(*tint);
                    }
                    cached = entity_model_cache.emplace(model_key, model->mesh()).first;
                }
                if (!world_renderer.set_world_model_mesh(*free_slot, cached->second)) {
                    settings_warning =
                        "entity model upload failed: " + std::string{world_renderer.last_error()};
                    return false;
                }
                entity_part_slots.emplace(key, *free_slot);
                entity_part_appearances.insert_or_assign(key,appearance);
                entity_part_minimum_y.insert_or_assign(key, cached->second.minimum[1U]);
                ++uploaded_this_tick;
            }
        }
        return true;
    }

    [[nodiscard]] std::vector<render::WorldModelDraw> entity_draws() const {
        std::vector<render::WorldModelDraw> draws;
        if (tutorial_session == nullptr) {
            return draws;
        }
        for (const auto& entity : tutorial_session->entities()) {
            if (!entity.alive) {
                // Consumed pickups keep their slot but must not be drawn.
                continue;
            }
            const auto* definition = world::find_entity_definition(entity.type);
            if (definition == nullptr) {
                continue;
            }
            const auto model_parts = entity.type == 29U
                                         ? world::ugc_entity_model_parts(entity.ugc_item_id)
                                         : definition->parts;
            std::vector<float> contact_bounds(model_parts.size(),std::numeric_limits<float>::quiet_NaN());
            for(std::size_t part=0U;part<model_parts.size();++part){
                const auto key=entity_part_key(entity.id,part);
                const auto contact=entity_part_minimum_y.find(key);
                if(entity_part_slots.contains(key)&&contact!=entity_part_minimum_y.end())contact_bounds[part]=contact->second;
            }
            const double contact_adjustment=world::entity_rig_vertical_contact_adjustment(
                entity,*definition,model_parts,contact_bounds);
            for (std::size_t part = 0U; part < model_parts.size(); ++part) {
                const auto found = entity_part_slots.find(entity_part_key(entity.id, part));
                if (found == entity_part_slots.end()) {
                    continue;
                }
                const auto& piece = model_parts[part];
                const bool flying_projectile =
                    definition->category == world::EntityCategory::projectile ||
                    (entity.type == 37U && (entity.velocity.x != 0.0 || entity.velocity.y != 0.0 ||
                                            entity.velocity.z != 0.0));
                if (flying_projectile) {
                    // CreateEntity rockets used the generic placed-entity
                    // transform, which added a face standoff, ignored velocity,
                    // and left the bazooka round lying sideways. Their retail
                    // classes use the exact same pitch/yaw/-0.5 presentation as
                    // packet-10 projectiles, so keep one transform for both.
                    auto position = std::array<double, 3U>{
                        entity.position.x, entity.position.y, entity.position.z};
                    if (entity.local_launcher_muzzle) {
                        position = world::local_rocket_presentation_anchor(
                            entity.type == 21U ? 12U : 13U,
                            {entity.home.x, entity.home.y, entity.home.z},
                            position,
                            {entity.velocity.x, entity.velocity.y, entity.velocity.z},
                            entity.presentation_age);
                    }
                    const auto model = world::projectile_presentation_transform(
                        position,
                        {entity.velocity.x, entity.velocity.y, entity.velocity.z},
                        entity.accumulators[0U],
                        definition->model_size * piece.scale);
                    draws.push_back({found->second, model});
                    continue;
                }
                const auto model = world::entity_presentation_transform(
                    entity, *definition, piece, contact_adjustment);
                draws.push_back({found->second, model});
            }
        }
        return draws;
    }

    /** Retail HealthCrate's unique soft terrain-projected contact shadow. */
    [[nodiscard]] std::vector<render::SpotShadowDraw> entity_spot_shadow_draws() const {
        std::vector<render::SpotShadowDraw> draws;
        if (tutorial_session == nullptr) {
            return draws;
        }
        for (const auto& entity : tutorial_session->entities()) {
            const auto position = world::health_crate_spot_shadow_position(
                entity, tutorial_session->map());
            if (!position.has_value()) {
                continue;
            }
            draws.push_back({{static_cast<float>(position->x),
                              static_cast<float>(position->y),
                              static_cast<float>(position->z)},
                             1.0F,
                             1.0F});
        }
        return draws;
    }

    /** Retail's additive 3D packet-43 objective/base boundaries. */
    [[nodiscard]] std::vector<render::ZoneVolumeDraw> objective_zone_draws() const {
        std::vector<render::ZoneVolumeDraw> draws;
        std::uint8_t local_team{};
        if (network_match && local_player_id.has_value()) {
            if (const auto* local = tutorial_roster.player(*local_player_id);
                local != nullptr) {
                local_team = local->team;
            }
        }
        const float opacity = static_cast<float>(
            (std::sin(game_hud.minimap().zone_phase_radians) * 0.4 + 0.6) * 0.5);
        draws.reserve(server_minimap_zones.size());
        for (const auto& [bounds, zone] : server_minimap_zones) {
            static_cast<void>(bounds);
            if (!objective_visible_to_team(zone.key, local_team)) {
                continue;
            }
            draws.push_back(render::ZoneVolumeDraw{
                {static_cast<float>(zone.minimum[0U]),
                 static_cast<float>(zone.minimum[1U]),
                 static_cast<float>(zone.minimum[2U])},
                {static_cast<float>(zone.maximum[0U]),
                 static_cast<float>(zone.maximum[1U]),
                 static_cast<float>(zone.maximum[2U])},
                {zone.color[0U] / 255.0F,
                 zone.color[1U] / 255.0F,
                 zone.color[2U] / 255.0F},
                opacity,
                zone.locked_in_zone});
        }
        return draws;
    }

    /** Advance the recovered timed-dynamite audio without fabricating C4 fuses. */
    void advance_timed_explosive_audio() {
        if (tutorial_session == nullptr) {
            timed_explosive_seconds.clear();
            return;
        }
        std::set<std::uint64_t> alive;
        for (const auto& entity : tutorial_session->entities()) {
            const auto timer = world::timed_explosive_presentation(entity);
            if (!timer.visible) {
                continue;
            }
            alive.insert(entity.id);
            const auto previous = timed_explosive_seconds.find(entity.id);
            const bool changed = previous == timed_explosive_seconds.end() ||
                                 previous->second != timer.seconds;
            timed_explosive_seconds.insert_or_assign(entity.id, timer.seconds);
            if (audio_started && changed) {
                static_cast<void>(audio->play_named_one_shot(
                    timer.ticking_sound,
                    {static_cast<float>(timer.label_position.x),
                     static_cast<float>(timer.label_position.y),
                     static_cast<float>(timer.label_position.z)},
                    1.0F));
            }
        }
        std::erase_if(timed_explosive_seconds,
                      [&alive](const auto& entry) { return !alive.contains(entry.first); });
    }

    /**
     * Feed Training's stationary peers through the same strict packet-28
     * decoder and roster replacement path used by the live session.
     */
    [[nodiscard]] world::VxlColor remote_team_color(std::uint8_t team) const noexcept {
        if (!network_match) {
            return team == 3U   ? world::VxlColor{92U, 174U, 74U, 255U}
                   : team == 2U ? world::VxlColor{44U, 117U, 179U, 255U}
                                : world::VxlColor{160U, 160U, 160U, 255U};
        }
        if (team != 2U && team != 3U) {
            return {160U, 160U, 160U, 255U};
        }
        const auto& source =
            team == 3U ? match_state_info.team2_color : match_state_info.team1_color;
        return {source[0U], source[1U], source[2U], 255U};
    }

    /** Resolve the local material color through the same StateData path. */
    [[nodiscard]] world::VxlColor local_player_team_color() const noexcept {
        if (network_match && local_player_id.has_value()) {
            if (const auto* local = tutorial_roster.player(*local_player_id); local != nullptr) {
                return remote_team_color(local->team);
            }
        }
        return {44U, 117U, 179U, 255U};
    }

    /**
     * Index into the retail per-team asset pairs: 0 = TEAM1 (blue),
     * 1 = TEAM2 (green). Offline sessions have no roster, so they present as
     * TEAM1 exactly like the tutorial's own blue loadout.
     */
    [[nodiscard]] std::size_t local_player_team_index() const noexcept {
        if (network_match && local_player_id.has_value()) {
            if (const auto* local = tutorial_roster.player(*local_player_id); local != nullptr) {
                // Protocol 168 uses TEAM1=2 and TEAM2=3. Checking 1 here
                // selected TEAM1 art for every playable client.
                return local->team == 3U ? 1U : 0U;
            }
        }
        return 0U;
    }

    /**
     * Rebuild the C++ equivalent of VXL.minimap_texture after canonical map
     * mutations. The server stays authoritative: this only visualizes the
     * already-applied local VXL and never sends or invents terrain state.
     */
    [[nodiscard]] bool sync_minimap_texture() {
        if (tutorial_session == nullptr || !renderer.is_initialized()) {
            return true;
        }
        const auto revision = tutorial_session->map().revision();
        const auto key = texture_key(minimap_texture_asset, render::TextureFilter::linear);
        const auto existing = image_textures.find(key);
        const bool pixels_current = !minimap_pixels.empty() && revision == minimap_map_revision;
        if (pixels_current && existing != image_textures.end() && !minimap_texture_upload_pending) {
            return true;
        }
        if (!pixels_current) {
            // Dirty chunks are refreshed incrementally by the bounded remesh
            // lane. Rebuilding all 262,144 columns here made a single block
            // edit hitch the gameplay thread. The HUD may trail terrain by
            // one frame while that bounded work completes.
            if (!live_chunk_remesh_queue.empty()) {
                return true;
            }
            minimap_pixels = world::build_minimap_overview_rgba(tutorial_session->map());
            minimap_texture_upload_pending = true;
        }
        if (existing == image_textures.end()) {
            const auto texture = renderer.create_texture_rgba8(
                minimap_pixels,
                render::UiExtent{world::VxlMap::width, world::VxlMap::depth},
                render::TextureFilter::linear);
            if (!texture.has_value()) {
                settings_warning = "minimap upload failed: " + std::string{renderer.last_error()};
                return false;
            }
            image_textures.emplace(key, *texture);
        } else if (!renderer.update_texture_rgba8(existing->second.texture, minimap_pixels)) {
            settings_warning = "minimap refresh failed: " + std::string{renderer.last_error()};
            return false;
        }
        minimap_map_revision = revision;
        minimap_texture_upload_pending = false;
        return true;
    }

    /** Publish the map crop and only the player markers retail may expose. */
    void sync_minimap_hud_state() {
        GameHudMinimapState state;
        state.texture_asset = minimap_texture_asset;
        state.full_map_visible = game_hud.minimap().full_map_visible;
        state.zone_phase_radians = game_hud.minimap().zone_phase_radians;
        if (tutorial_session == nullptr || minimap_pixels.empty()) {
            game_hud.set_inside_zone_tint(std::nullopt);
            game_hud.set_minimap(std::move(state));
            return;
        }
        state.visible = !network_match || match_initial_info.enable_minimap;
        const auto& local_motion = tutorial_session->player();
        state.focus_x = local_motion.position.x;
        state.focus_y = local_motion.position.y;

        const auto team = local_player_team_color();
        const auto team_ui = ui::ColorRgba8{team.red, team.green, team.blue, team.alpha};
        const auto brighten = [](world::VxlColor color) {
            const auto channel = [](std::uint8_t value) {
                return static_cast<std::uint8_t>(
                    std::min(255U, static_cast<unsigned int>(value) * 3U / 2U));
            };
            return ui::ColorRgba8{
                channel(color.red), channel(color.green), channel(color.blue), color.alpha};
        };
        const bool local_alive = game_hud.health() > 0 && tutorial_session->alive();
        std::uint8_t local_team{};
        const network::RemotePlayerReplica* local_replica{};
        if (network_match && local_player_id.has_value()) {
            local_replica = tutorial_roster.player(*local_player_id);
            if (local_replica != nullptr) {
                local_team = local_replica->team;
            }
        }
        game_hud.set_inside_zone_tint(std::nullopt);
        for (const auto& [bounds, zone] : server_minimap_zones) {
            static_cast<void>(bounds);
            // visible_team: neutral zones are shared, team-owned zones are
            // private, and spectators receive the complete mode overview.
            if (!objective_visible_to_team(zone.key, local_team)) {
                continue;
            }
            if (!game_hud.inside_zone_tint().has_value()) {
                game_hud.set_inside_zone_tint(objective_zone_player_tint(
                    ObjectiveZoneVolume{
                        {static_cast<double>(zone.minimum[0U]),
                         static_cast<double>(zone.minimum[1U]),
                         static_cast<double>(zone.minimum[2U])},
                        {static_cast<double>(zone.maximum[0U]),
                         static_cast<double>(zone.maximum[1U]),
                         static_cast<double>(zone.maximum[2U])},
                        zone.color,
                        zone.key,
                        zone.locked_in_zone},
                    local_motion.position, local_motion.crouch, local_team));
            }
            const auto style = minimap_zone_icon_style(zone.icon_id);
            state.zones.push_back(GameHudMinimapZone{
                static_cast<double>(zone.minimum[0U]),
                static_cast<double>(zone.minimum[1U]),
                static_cast<double>(zone.maximum[0U]),
                static_cast<double>(zone.maximum[1U]),
                ui::ColorRgba8{zone.color[0U], zone.color[1U], zone.color[2U], 255U},
                style.has_value() ? std::string{style->icon_asset} : std::string{},
                style.has_value() ? style->authored_size_pixels : 0.0,
                static_cast<double>(zone.icon_scale)});
        }
        if (local_alive) {
            const auto map_rotation = minimap_marker_rotation_degrees(local_motion.orientation.x,
                                                                      local_motion.orientation.y);
            // player.pyx defines player_cone_view_icon_scale = 0.2 and applies
            // it to the centred 256x256 image during Player construction.
            // Feeding the raw canvas size here creates a map-filling wedge.
            constexpr double cone_view_icon_scale{0.2};
            state.view_cone = GameHudMinimapMarker{std::string{game_hud_assets::minimap_view_cone},
                                                   local_motion.position.x,
                                                   local_motion.position.y,
                                                   256.0 * cone_view_icon_scale,
                                                   map_rotation,
                                                   team_ui,
                                                   false};
            // Keep the local pin aligned with the cone. The recovered retail
            // orient_map_icon gate left the self pin upright, but that makes
            // the directional authored pin contradict the live view cone and
            // provides no heading when the translucent cone is hard to see.
            state.markers.push_back(GameHudMinimapMarker{
                std::string{local_replica != nullptr && local_replica->high_minimap_visibility
                                ? game_hud_assets::minimap_vip_player
                                : game_hud_assets::minimap_player},
                local_motion.position.x,
                local_motion.position.y,
                16.0,
                map_rotation,
                brighten(team),
                local_replica != nullptr && local_replica->high_minimap_visibility});
        }

        // gameScene.pyd assigns these icon assets on the entity classes. They
        // are driven by the already-installed packet-21 world state; the HUD
        // does not infer or synthesize server entities.
        for (const auto& entity : tutorial_session->entities()) {
            if (!entity.alive) {
                continue;
            }
            const auto style = minimap_entity_style(entity.type);
            if (!style.has_value() ||
                (style->friendly_only && local_team != 0U && entity.team != local_team)) {
                continue;
            }
            ui::ColorRgba8 color{255U, 255U, 255U, 255U};
            if (entity.team == 2U || entity.team == 3U) {
                const auto team_color = remote_team_color(entity.team);
                color = {team_color.red, team_color.green, team_color.blue, team_color.alpha};
            } else if (entity.has_color) {
                color = {entity.color[0U], entity.color[1U], entity.color[2U], 255U};
            }
            state.markers.push_back(GameHudMinimapMarker{std::string{style->icon_asset},
                                                         entity.position.x,
                                                         entity.position.y,
                                                         16.0,
                                                         0.0,
                                                         color,
                                                         false});
            if (style->supports_height_indicator &&
                match_initial_info.enable_minimap_height_icons &&
                std::abs(entity.position.z - local_motion.position.z) > 4.0) {
                // The shipped 8px art points down at rotation zero. Map Z
                // grows downward, so an entity above the player flips it.
                const auto rotation = entity.position.z < local_motion.position.z ? 180.0 : 0.0;
                state.markers.push_back(
                    GameHudMinimapMarker{std::string{game_hud_assets::minimap_height},
                                         entity.position.x,
                                         entity.position.y,
                                         8.0,
                                         rotation,
                                         color,
                                         false});
            }
        }

        if (network_match && local_player_id.has_value()) {
            const auto is_zombie_class = [](std::uint8_t class_id) noexcept {
                return class_id == 4U || class_id == 14U || class_id == 15U;
            };
            const bool local_is_zombie =
                local_replica != nullptr && is_zombie_class(local_replica->class_id);
            const double heartbeat_size = zombie_heartbeat_marker_size(
                character_animation_timer_ms / 1000.0);
            for (const auto& player : tutorial_roster.players()) {
                const bool state_data_reveals_enemy =
                    (local_team == 2U && player.team == 3U &&
                     match_state_info.team1_can_see_team2) ||
                    (local_team == 3U && player.team == 2U &&
                     match_state_info.team2_can_see_team1);
                if (player.player_id == *local_player_id || player.dead ||
                    (player.team != local_team &&
                     !match_initial_info.exposed_teams_always_on_minimap &&
                     !state_data_reveals_enemy &&
                     !server_team_map_visibility[player.team] && !player.high_minimap_visibility)) {
                    continue;
                }
                const auto color = remote_team_color(player.team);
                const auto map_rotation =
                    minimap_marker_rotation_degrees(player.orientation.x, player.orientation.y);
                // Player.get_map_icon uses a pulsing 256px heart when a Zombie
                // views a living enemy survivor. A high-visibility (last-man)
                // marker wins first, exactly as in the compiled client.
                const bool survivor_heart =
                    !player.high_minimap_visibility && local_is_zombie &&
                    player.team != local_team && !is_zombie_class(player.class_id) &&
                    heartbeat_size > 0.0;
                state.markers.push_back(GameHudMinimapMarker{
                    std::string{player.high_minimap_visibility
                                    ? game_hud_assets::minimap_vip_player
                                : survivor_heart
                                    ? game_hud_assets::minimap_zombie_heart
                                    : game_hud_assets::minimap_player},
                    player.position.x,
                    player.position.y,
                    survivor_heart ? heartbeat_size : 16.0,
                    survivor_heart ? 0.0 : map_rotation,
                    ui::ColorRgba8{color.red, color.green, color.blue, color.alpha},
                    player.high_minimap_visibility});
                // get_map_icon returns immediately for a high-visibility
                // player before consulting the carried tool. Do not layer a
                // second bomb/diamond/intel icon on that VIP/spotted marker.
                const auto objective_asset = player.high_minimap_visibility ? std::string_view{}
                                             : player.pickup_id == 14U || player.tool_id == 25U
                                                 ? game_hud_assets::minimap_bomb
                                             : player.pickup_id == 15U || player.tool_id == 26U
                                                 ? game_hud_assets::minimap_diamond
                                             : player.pickup_id == 16U || player.tool_id == 30U
                                                 ? game_hud_assets::minimap_intel
                                                 : std::string_view{};
                if (!objective_asset.empty()) {
                    state.markers.push_back(GameHudMinimapMarker{
                        std::string{objective_asset},
                        player.position.x,
                        player.position.y,
                        16.0,
                        0.0,
                        ui::ColorRgba8{color.red, color.green, color.blue, color.alpha},
                        true});
                }
            }
        }
        game_hud.set_minimap(std::move(state));
    }

    /** Upload one generation-safe body, crouch body, tool and arm rig. */
    [[nodiscard]] bool sync_remote_player_rig(const network::RemotePlayerReplica& replica) {
        // A first-person client never renders its own third-person body.
        if (network_match && local_player_id == replica.player_id)
            return true;
        const auto color = remote_team_color(replica.team);
        const bool disguised = (replica.state_flags & 0x02U) != 0U;
        world::VxlColor disguise_color{96U, 96U, 96U, 255U};
        bool has_disguise_color{};
        if (disguised) {
            if (live_terrain_replica != nullptr) {
                if (const auto packed = live_terrain_replica->player_color(replica.player_id);
                    packed.has_value()) {
                    disguise_color = {static_cast<std::uint8_t>(*packed >> 16U),
                                      static_cast<std::uint8_t>(*packed >> 8U),
                                      static_cast<std::uint8_t>(*packed),
                                      255U};
                    has_disguise_color = true;
                }
            }
            // SetColor normally arrives before the active state. A reconnect
            // can expose the state first, so sample the nearby floor rather
            // than flashing team colour or a white placeholder.
            if (!has_disguise_color && tutorial_ready_map != nullptr && replica.position.x >= 0.0 &&
                replica.position.y >= 0.0) {
                const auto x = static_cast<std::uint32_t>(
                    std::clamp(std::floor(replica.position.x),
                               0.0,
                               static_cast<double>(world::VxlMap::width - 1U)));
                const auto y = static_cast<std::uint32_t>(
                    std::clamp(std::floor(replica.position.y),
                               0.0,
                               static_cast<double>(world::VxlMap::depth - 1U)));
                const auto start_z = static_cast<std::int32_t>(
                    std::clamp(std::floor(replica.position.z),
                               0.0,
                               static_cast<double>(world::VxlMap::height - 1U)));
                for (std::int32_t offset{}; offset <= 5; ++offset) {
                    const auto z = start_z + offset;
                    if (z >= static_cast<std::int32_t>(world::VxlMap::height))
                        break;
                    if (const auto sampled =
                            tutorial_ready_map->color(x, y, static_cast<std::uint32_t>(z));
                        sampled.has_value()) {
                        disguise_color = *sampled;
                        has_disguise_color = true;
                        break;
                    }
                }
            }
        }
        auto found = remote_player_rigs.find(replica.player_id);
        const auto* body_cosmetic = equipped_cosmetic(replica.player_id,"class:"+std::to_string(replica.class_id)+":body");
        const auto* hat_cosmetic = equipped_cosmetic(replica.player_id,"class:"+std::to_string(replica.class_id)+":hat");
        const auto* held_cosmetic = equipped_cosmetic(replica.player_id,"weapon:"+std::to_string(replica.tool_id)+":world");
        const auto body_appearance = (body_cosmetic ? body_cosmetic->id : "") + std::string{"/"} + (hat_cosmetic ? hat_cosmetic->id : "");
        const auto weapon_appearance = held_cosmetic ? held_cosmetic->id : std::string{};
        const auto corpse_jetpack_id =
            replica.dead
                ? world::retail_jetpack_id(replica.loadout, replica.ugc_tools)
                : std::optional<std::uint8_t>{};
        const bool body_matches =
            found != remote_player_rigs.end() && found->second.generation == replica.generation &&
            found->second.class_id == replica.class_id && found->second.team == replica.team &&
            found->second.body_appearance == body_appearance &&
            found->second.resolved_team_color == color && found->second.disguised == disguised &&
            (!disguised || found->second.disguise_color == disguise_color);
        if (body_matches && corpse_jetpack_id.has_value() &&
            found->second.attached_jetpack_id == corpse_jetpack_id) {
            return true;
        }
        if (body_matches && !corpse_jetpack_id.has_value() &&
            found->second.tool_id == replica.tool_id && found->second.weapon_appearance == weapon_appearance) {
            found->second.pending_tool_id.reset();
            found->second.pending_tool_snapshots = 0U;
            return true;
        }
        if (body_matches && !corpse_jetpack_id.has_value() && disguised) {
            // No held tool or arms are visible through DisguiseBlocks. Retain
            // the authoritative byte for the reveal without touching GPU data.
            found->second.tool_id = replica.tool_id;
            found->second.pending_tool_id.reset();
            found->second.pending_tool_snapshots = 0U;
            return true;
        }
        if (body_matches && !corpse_jetpack_id.has_value()) {
            // Tool bytes can briefly bounce while a grouped WorldUpdate and
            // SetClassLoadout cross. Rebuilding GPU buffers on every transient
            // byte caused multi-hundred-millisecond stalls with bot-heavy
            // servers. Two consecutive authority rows add at most one 30 Hz
            // snapshot of visual latency and reject the unstable edge.
            if (found->second.pending_tool_id != replica.tool_id) {
                found->second.pending_tool_id = replica.tool_id;
                found->second.pending_tool_snapshots = 1U;
                return true;
            }
            found->second.pending_tool_snapshots = static_cast<std::uint8_t>(std::min<unsigned int>(
                2U, static_cast<unsigned int>(found->second.pending_tool_snapshots) + 1U));
            if (found->second.pending_tool_snapshots < 2U) {
                return true;
            }
        }
        if (network_match && remote_rig_uploads_remaining == 0U) {
            // The authority state is already retained in tutorial_roster. A
            // later WorldUpdate retries this presentation-only upload.
            return true;
        }
        if (network_match) {
            --remote_rig_uploads_remaining;
            remote_rig_uploaded_this_tick = true;
        }
        const PerformanceScope performance{"remote_player_rig", std::chrono::microseconds{2'000}};

        RemotePlayerRenderRig rig = body_matches ? found->second : RemotePlayerRenderRig{};
        const auto base =
            RemotePlayerRenderRig::slot_base +
            static_cast<std::uint32_t>(replica.player_id) * RemotePlayerRenderRig::slot_stride;
        rig.standing_body_slot = base;
        rig.crouching_slot = base + 1U;
        rig.head_slot = base + 2U;
        rig.left_leg_slot = base + 3U;
        rig.right_leg_slot = base + 4U;
        rig.crouching_left_leg_slot = base + 5U;
        rig.crouching_right_leg_slot = base + 6U;
        rig.tool_slots = {base + 7U, base + 8U, base + 9U};
        rig.arm_upper_slot = base + 10U;
        rig.arm_lower_slot = base + 11U;
        rig.generation = replica.generation;
        rig.body_appearance = body_appearance;
        rig.weapon_appearance = weapon_appearance;
        rig.class_id = replica.class_id;
        rig.team = replica.team;
        rig.tool_id = replica.tool_id;
        rig.resolved_team_color = color;
        rig.disguised = disguised;
        rig.disguise_color = disguise_color;
        rig.pending_tool_id.reset();
        rig.pending_tool_snapshots = 0U;
        for (std::uint32_t slot = rig.standing_body_slot; slot <= rig.arm_lower_slot; ++slot) {
            // A player id may be reused before an old deferred release reaches
            // this slot. New authority wins; never clear its freshly uploaded
            // mesh on a later maintenance tick.
            pending_remote_mesh_clears.erase(slot);
        }
        if (!body_matches) {
            rig.motion.reset({replica.position, replica.orientation, replica.velocity});
        }
        if (!body_matches && found != remote_player_rigs.end() &&
            found->second.generation == replica.generation) {
            rig.primary_was_held = found->second.primary_was_held;
            rig.last_primary_world_loop = found->second.last_primary_world_loop;
            rig.last_snapshot_world_loop = found->second.last_snapshot_world_loop;
            rig.action_serial = found->second.action_serial;
            rig.block_sucker_state = found->second.block_sucker_state;
            rig.block_sucker_state_world_loop = found->second.block_sucker_state_world_loop;
            rig.motion = found->second.motion;
        }

        const auto color_key = (static_cast<std::uint32_t>(color.red) << 24U) |
                               (static_cast<std::uint32_t>(color.green) << 16U) |
                               (static_cast<std::uint32_t>(color.blue) << 8U) | color.alpha;
        const world::ChunkMesh empty;
        if (!body_matches) {
            for (std::uint32_t slot = rig.standing_body_slot; slot <= rig.arm_lower_slot; ++slot) {
                if (!world_renderer.set_world_model_mesh(slot, empty)) {
                    settings_warning = std::string{world_renderer.last_error()};
                    return false;
                }
            }
            if (disguised) {
                const auto disguise_key = (static_cast<std::uint32_t>(disguise_color.red) << 16U) |
                                          (static_cast<std::uint32_t>(disguise_color.green) << 8U) |
                                          static_cast<std::uint32_t>(disguise_color.blue);
                auto cached = remote_disguise_model_cache.find(disguise_key);
                if (cached == remote_disguise_model_cache.end()) {
                    auto loaded = world::load_disguise_models(
                        config.asset_root, disguise_color, model_inverse_scale);
                    if (!loaded) {
                        settings_warning = "remote disguise model failed: " + loaded.error;
                        return false;
                    }
                    cached =
                        remote_disguise_model_cache.emplace(disguise_key, std::move(*loaded.models))
                            .first;
                }
                if (!world_renderer.set_world_model_mesh(rig.standing_body_slot,
                                                         cached->second.standing) ||
                    !world_renderer.set_world_model_mesh(rig.crouching_slot,
                                                         cached->second.crouching)) {
                    settings_warning = "remote disguise upload failed: " +
                                       std::string{world_renderer.last_error()};
                    return false;
                }
                rig.draws_arms = false;
                rig.arm_meshes_available = false;
                rig.combined_arms = false;
                rig.tool_part_count = 0U;
            } else {
                const auto* cosmetic=body_cosmetic;
                const auto palette=cosmetic?std::optional{cosmetic->palette}:std::nullopt;
                const auto class_key = std::pair{
                    (static_cast<std::uint64_t>(replica.class_id) << 32U) | color_key, body_appearance};
                auto cached = remote_class_model_cache.find(class_key);
                if (cached == remote_class_model_cache.end()) {
                    const auto head = hat_cosmetic ? inventory_verified_model(*hat_cosmetic,config.asset_root) : nullptr;
                    const auto parts=inventory_character_parts(body_cosmetic,config.asset_root);
                    auto loaded =
                        world::load_class_models(config.asset_root, replica.class_id, color,
                                                 model_inverse_scale, palette, head.get(), &parts);
                    if (!loaded) {
                        settings_warning = "remote class model failed: " + loaded.error;
                        return false;
                    }
                    cached = remote_class_model_cache.emplace(class_key, std::move(*loaded.models))
                                 .first;
                }
                const auto& character = cached->second;
                if (!world_renderer.set_world_model_mesh(rig.standing_body_slot,
                                                         character.standing_torso_preview) ||
                    !world_renderer.set_world_model_mesh(rig.crouching_slot,
                                                         character.crouching_torso_preview) ||
                    !world_renderer.set_world_model_mesh(rig.head_slot,
                                                         character.head_preview) ||
                    !world_renderer.set_world_model_mesh(rig.left_leg_slot,
                                                         character.left_leg_preview) ||
                    !world_renderer.set_world_model_mesh(rig.right_leg_slot,
                                                         character.right_leg_preview) ||
                    !world_renderer.set_world_model_mesh(
                        rig.crouching_left_leg_slot,
                        character.crouching_left_leg_preview) ||
                    !world_renderer.set_world_model_mesh(
                        rig.crouching_right_leg_slot,
                        character.crouching_right_leg_preview)) {
                    settings_warning = std::string{world_renderer.last_error()};
                    return false;
                }
                const auto& arms = character.first_person_arms;
                rig.combined_arms=character.combined_arms.has_value();
                if(rig.combined_arms&&!world_renderer.set_world_model_mesh(rig.arm_upper_slot,*character.combined_arms))return false;
                rig.arm_meshes_available = arms.size() >= 2U;
                rig.draws_arms = rig.arm_meshes_available;
                if (rig.arm_meshes_available &&
                    (!world_renderer.set_world_model_mesh(rig.arm_upper_slot, arms[0U]) ||
                     !world_renderer.set_world_model_mesh(rig.arm_lower_slot, arms[1U]))) {
                    settings_warning =
                        "remote arm upload failed: " + std::string{world_renderer.last_error()};
                    return false;
                }
            }
        }

        if (disguised) {
            remote_player_rigs[replica.player_id] = rig;
            return true;
        }

        // Commit the body before resolving the held tool. WorldUpdate's tool
        // byte can legitimately contain equipment sentinels (jetpacks and the
        // parachute) for which no handheld KV6 exists. The old all-or-nothing
        // path returned here and consequently made the entire Specialist or
        // Medic disappear. A presentation-only weapon failure must never erase
        // an otherwise valid CreatePlayer body.
        for (const auto slot : rig.tool_slots) {
            if (!world_renderer.set_world_model_mesh(slot, empty)) {
                settings_warning =
                    "remote weapon clear failed: " + std::string{world_renderer.last_error()};
                remote_player_rigs[replica.player_id] = rig;
                return false;
            }
        }
        rig.tool_part_count = 0U;
        rig.draws_arms = rig.arm_meshes_available;
        rig.attached_jetpack_id.reset();
        remote_player_rigs[replica.player_id] = rig;

        if (corpse_jetpack_id.has_value()) {
            const auto model_stem = world::retail_jetpack_model(*corpse_jetpack_id);
            const auto pack_key =
                (static_cast<std::uint64_t>(*corpse_jetpack_id) << 32U) | color_key;
            auto cached_pack = remote_jetpack_model_cache.find(pack_key);
            if (cached_pack == remote_jetpack_model_cache.end()) {
                std::string load_error;
                auto model = load_runtime_model(
                    config.asset_root / "kv6" / (std::string{model_stem} + ".kv6"),
                    &load_error);
                if (!model.has_value()) {
                    settings_warning = "remote jetpack art unavailable; body retained: " +
                                       load_error;
                    return true;
                }
                const auto attachment = world::retail_jetpack_attachment();
                model->offset_pivots(
                    {0.0F, 0.0F, static_cast<float>(attachment.z_offset)});
                model->apply_default_color(color);
                cached_pack = remote_jetpack_model_cache
                                  .emplace(pack_key, model->mesh())
                                  .first;
            }
            if (!world_renderer.set_world_model_mesh(rig.tool_slots[0U],
                                                     cached_pack->second)) {
                settings_warning = "remote jetpack upload failed: " +
                                   std::string{world_renderer.last_error()};
                return false;
            }
            rig.attached_jetpack_id = corpse_jetpack_id;
            remote_player_rigs[replica.player_id] = rig;
            return true;
        }

        const auto weapon_key = std::pair{(static_cast<std::uint64_t>(replica.tool_id) << 32U) | color_key, weapon_appearance};
        auto cached_weapon = remote_weapon_model_cache.find(weapon_key);
        if (cached_weapon == remote_weapon_model_cache.end()) {
            const auto finish=inventory_weapon_finish(held_cosmetic,config.asset_root,replica.tool_id);
            auto loaded = world::load_weapon_models(
                config.asset_root, replica.tool_id, {1.0F, 1.0F, 1.0F}, color,
                model_inverse_scale, finish?&*finish:nullptr);
            if (!loaded) {
                settings_warning =
                    "remote held-tool art unavailable; body retained: " + loaded.error;
                return true;
            }
            cached_weapon =
                remote_weapon_model_cache.emplace(weapon_key, std::move(*loaded.models)).first;
        }
        const auto& weapon = cached_weapon->second;
        rig.tool_part_count =
            std::min<std::size_t>(weapon.third_person_parts.size(), rig.tool_slots.size());
        for (std::size_t part{}; part < rig.tool_part_count; ++part) {
            if (!world_renderer.set_world_model_mesh(rig.tool_slots[part],
                                                     weapon.third_person_parts[part])) {
                settings_warning =
                    "remote weapon upload failed: " + std::string{world_renderer.last_error()};
                rig.tool_part_count = 0U;
                rig.draws_arms = rig.arm_meshes_available;
                remote_player_rigs[replica.player_id] = rig;
                return false;
            }
        }
        rig.draws_arms = rig.arm_meshes_available;
        remote_player_rigs[replica.player_id] = rig;
        return true;
    }

    /**
     * Reconcile retained remote rigs without invalidating unchanged GPU data.
     *
     * CreatePlayer, SetClassLoadout and StateData can arrive together during
     * join. The former implementation cleared and reloaded every character,
     * arm and weapon KV6 for each of those packets. Besides redundant file
     * parsing, that repeatedly destroyed/recreated dozens of GPU buffers on
     * the exact frame gameplay became visible.
     */
    [[nodiscard]] bool sync_roster_players() {
        for (auto iterator = remote_player_rigs.begin(); iterator != remote_player_rigs.end();) {
            const auto player_id = iterator->first;
            const auto& rig = iterator->second;
            const auto* replica = tutorial_roster.player(player_id);
            const bool retained =
                replica != nullptr && (!network_match || local_player_id != player_id);
            if (retained) {
                ++iterator;
                continue;
            }
            for (std::uint32_t slot = rig.standing_body_slot; slot <= rig.arm_lower_slot; ++slot) {
                pending_remote_mesh_clears.insert(slot);
            }
            iterator = remote_player_rigs.erase(iterator);
        }
        for (const auto& replica : tutorial_roster.players()) {
            if (!sync_remote_player_rig(replica))
                return false;
        }
        return true;
    }

    [[nodiscard]] bool load_tutorial_packet_players() {
        tutorial_roster.clear();
        for (const auto& fixture : network::tutorial_create_player_fixtures()) {
            const auto bytes = network::encode_packet(fixture);
            std::string error;
            if (bytes.empty() || !tutorial_roster.apply(bytes, &error)) {
                settings_warning = error.empty() ? "packet 28 fixture encode failed" : error;
                return false;
            }
        }
        return sync_roster_players();
    }

    [[nodiscard]] bool ensure_parachute_mesh(bool first_person) {
        const std::size_t index = first_person ? 1U : 0U;
        if (parachute_mesh_attempted[index]) return parachute_mesh_uploaded[index];
        parachute_mesh_attempted[index] = true;
        const auto stem = first_person ? world::retail_first_person_parachute_model
                                       : world::retail_parachute_model;
        std::string error;
        auto model = load_runtime_model(config.asset_root / "kv6" /
                                           (std::string{stem} + ".kv6"), &error);
        if (!model.has_value()) {
            settings_warning = "parachute art unavailable; character retained: " + error;
            return false;
        }
        model->offset_pivots({0.0F, 0.0F, world::retail_parachute_pivot_offset});
        const auto slot = first_person ? parachute_first_person_slot : parachute_world_slot;
        parachute_mesh_uploaded[index] = world_renderer.set_world_model_mesh(slot, model->mesh());
        if (!parachute_mesh_uploaded[index]) {
            settings_warning = "parachute upload failed: " + std::string{world_renderer.last_error()};
        }
        // The separate model-inspection scene uses slots 0..17 for its class
        // gallery. Its next entry must restore that gallery after gameplay.
        lab_models_color.reset();
        return parachute_mesh_uploaded[index];
    }

    [[nodiscard]] std::optional<render::WorldModelDraw> local_parachute_draw() {
        if (tutorial_session == nullptr || !tutorial_session->alive() ||
            !tutorial_session->player().parachute ||
            !tutorial_session->player().parachute_active || !ensure_parachute_mesh(true)) {
            return std::nullopt;
        }
        const auto& orientation = tutorial_session->player().orientation;
        const auto yaw = world::retail_character_root_yaw_degrees(
            {orientation.x, orientation.y, orientation.z});
        return render::WorldModelDraw{
            parachute_first_person_slot,
            world::retail_parachute_world_transform(tutorial_session->eye_position(), yaw, true)};
    }

    [[nodiscard]] std::vector<render::WorldModelDraw> tutorial_player_draws() {
        std::vector<render::WorldModelDraw> draws;
        const auto tune_character_draws = [&draws](std::size_t first) {
            for (std::size_t index{first}; index < draws.size(); ++index) {
                // Retail characters used their own model shader. A slight
                // darkening plus local contrast keeps team colours distinct
                // from equally coloured terrain without turning them neon.
                draws[index].albedo_gain = 0.90F;
                draws[index].albedo_contrast = 1.08F;
            }
        };
        const auto players = tutorial_roster.players();
        draws.reserve(players.size() * 8U);
        for (const auto& player : players) {
            const auto rig = remote_player_rigs.find(player.player_id);
            const auto* jetpack_corpse = jetpack_deaths.state(player.player_id);
            const bool draws_jetpack_corpse =
                player.dead && jetpack_corpse != nullptr &&
                jetpack_corpse->generation == player.generation;
            if (rig == remote_player_rigs.end() || (player.dead && !draws_jetpack_corpse))
                continue;
            const auto& motion = rig->second.motion.sample();
            const float yaw = static_cast<float>(world::retail_character_root_yaw_degrees(
                {motion.orientation.x, motion.orientation.y, motion.orientation.z}));
            const bool crouching = !draws_jetpack_corpse && (player.input_flags & 0x20U) != 0U;
            if (rig->second.disguised) {
                // DisguiseBlocks.draw deliberately omits character yaw: the
                // two blocks stay aligned to the voxel grid and therefore do
                // not reveal aim direction. Retail offsets standing/crouched
                // models by -0.8/-0.4 on its upward character axis. Our map
                // Z grows downward, so disguise_ground_offset converts them.
                auto disguise = mat_translate(0.0F, 0.0F, world::disguise_ground_offset(crouching));
                disguise = mat_mul(disguise,
                                   mat_translate(static_cast<float>(motion.position.x),
                                                 static_cast<float>(motion.position.y),
                                                 static_cast<float>(motion.position.z)));
                draws.push_back(
                    {crouching ? rig->second.crouching_slot : rig->second.standing_body_slot,
                     disguise});
                continue;
            }
            auto root = mat_rotate_z(
                yaw + (draws_jetpack_corpse
                           ? static_cast<float>(jetpack_corpse->rotation_degrees.x)
                           : 0.0F));
            if (draws_jetpack_corpse) {
                // Character.update_dead adds its random vector to yaw, pitch
                // and roll before Character.draw applies the complete root.
                root = mat_mul(
                    root,
                    mat_rotate_x(static_cast<float>(jetpack_corpse->rotation_degrees.y)));
                root = mat_mul(
                    root,
                    mat_rotate_y(static_cast<float>(jetpack_corpse->rotation_degrees.z)));
            }
            root = mat_mul(root,
                           mat_translate(static_cast<float>(motion.position.x),
                                         static_cast<float>(motion.position.y),
                                         static_cast<float>(motion.position.z)));
            const double aim_pitch = draws_jetpack_corpse
                                         ? 0.0
                                         : std::asin(std::clamp(motion.orientation.z, -1.0, 1.0)) *
                                               180.0 / std::numbers::pi;
            const auto first_character_draw = draws.size();

            // Retail draws the torso, head and both legs as separate
            // DisplayLists. Pitching the old combined body either left the
            // head rigid or rotated the entire player around their feet.
            draws.push_back(
                {crouching ? rig->second.crouching_slot : rig->second.standing_body_slot, root});
            const float head_pivot_z = crouching ? 0.3F : 0.2F;
            auto head = mat_translate(0.0F, 0.0F, crouching ? 0.1F : 0.0F);
            head = mat_mul(head, mat_translate(0.0F, 0.0F, -head_pivot_z));
            head = mat_mul(head, mat_rotate_x(static_cast<float>(aim_pitch)));
            head = mat_mul(head, mat_translate(0.0F, 0.0F, head_pivot_z));
            head = mat_mul(head, root);
            draws.push_back({rig->second.head_slot, head});
            if(rig->second.combined_arms){
                auto arms=mat_translate(0.F,0.F,-.25F);
                arms=mat_mul(arms,mat_rotate_x(static_cast<float>(aim_pitch)));
                arms=mat_mul(arms,mat_translate(0.F,crouching?-.3F:0.F,crouching?.35F:.25F));
                draws.push_back({rig->second.arm_upper_slot,mat_mul(arms,root)});
            }

            const auto walk_pose = world::evaluate_retail_walk_pose(
                static_cast<std::uint64_t>(character_animation_timer_ms),
                draws_jetpack_corpse
                    ? world::ViewModelVector{}
                    : world::ViewModelVector{
                          motion.velocity.x, motion.velocity.y, motion.velocity.z},
                {motion.orientation.x, motion.orientation.y, motion.orientation.z},
                crouching);
            const float leg_pivot_y = crouching ? -0.3F : 0.0F;
            const float leg_pivot_z = crouching ? 0.7F : 1.1F;
            const auto animated_leg = [&](float pivot_x,
                                          const world::RetailLegPose& leg_pose) {
                auto model = mat_translate(-pivot_x, -leg_pivot_y, -leg_pivot_z);
                model = mat_mul(
                    model, mat_rotate_x(static_cast<float>(leg_pose.rotation_x_degrees)));
                model = mat_mul(
                    model, mat_rotate_y(static_cast<float>(leg_pose.rotation_y_degrees)));
                model = mat_mul(model, mat_translate(pivot_x, leg_pivot_y, leg_pivot_z));
                return mat_mul(model, root);
            };
            draws.push_back(
                {crouching ? rig->second.crouching_left_leg_slot : rig->second.left_leg_slot,
                 animated_leg(0.25F, walk_pose.left)});
            draws.push_back(
                {crouching ? rig->second.crouching_right_leg_slot : rig->second.right_leg_slot,
                 animated_leg(-0.25F, walk_pose.right)});

            // Character.set_jetpack_model keeps this exact child attached
            // while Character.update_dead rotates the complete owner. The
            // z-offset belongs to KV6 pivot construction above; applying it
            // again here would double-shift the pack.
            if (draws_jetpack_corpse) {
                if (rig->second.attached_jetpack_id ==
                    std::optional<std::uint8_t>{jetpack_corpse->jetpack_id}) {
                    constexpr auto attachment = world::retail_jetpack_attachment();
                    const auto display_position = world::retail_display_vector(
                        {0.0, attachment.y, attachment.z});
                    auto pack = mat_scale(static_cast<float>(attachment.size));
                    pack = mat_mul(
                        pack,
                        mat_translate(static_cast<float>(display_position.x),
                                      static_cast<float>(display_position.y),
                                      static_cast<float>(display_position.z)));
                    pack = mat_mul(pack, mat_rotate_x(-90.0F));
                    pack = mat_mul(pack, root);
                    draws.push_back({rig->second.tool_slots[0U], pack});
                }
                tune_character_draws(first_character_draw);
                continue;
            }

            // Character.draw draws the canopy independently of its held tool
            // and arms, under the same yaw/body anchor, before the weapon.
            if ((player.state_flags & 0x01U) != 0U &&
                std::ranges::find(player.loadout, world::retail_parachute_equipment) !=
                    player.loadout.end() && ensure_parachute_mesh(false)) {
                draws.push_back({parachute_world_slot,
                    world::retail_parachute_world_transform(
                        {motion.position.x, motion.position.y, motion.position.z}, yaw, false)});
            }

            const double elapsed =
                rig->second.last_primary_world_loop < 0
                    ? 1.0e9
                    : std::max(0.0,
                               static_cast<double>(latest_world_loop -
                                                   rig->second.last_primary_world_loop) /
                                   60.0);
            const auto pose = world::evaluate_retail_third_person_pose(player.tool_id,
                                                                       rig->second.tool_part_count,
                                                                       elapsed,
                                                                       rig->second.action_serial,
                                                                       aim_pitch,
                                                                       (player.action_flags & 0x10U) != 0U);
            world::ViewModelVector sucker_shake{};
            if (player.tool_id == 63U && rig->second.block_sucker_state != 0U) {
                const double sucker_elapsed =
                    std::max(0.0,
                             static_cast<double>(latest_world_loop -
                                                 rig->second.block_sucker_state_world_loop) /
                                 60.0);
                double amplitude{0.02};
                if (rig->second.block_sucker_state == 1U) {
                    amplitude =
                        sucker_elapsed < 0.5
                            ? 0.06 * (sucker_elapsed / 0.5)
                            : 0.06 - 0.04 * std::clamp((sucker_elapsed - 0.5) / 0.5, 0.0, 1.0);
                }
                sucker_shake = world::retail_display_vector(
                    {std::sin(sucker_elapsed * 20.0 + player.player_id) * amplitude,
                     std::sin(sucker_elapsed * 27.5 + player.player_id * 0.7) * amplitude,
                     0.0});
            }
            for (std::size_t part{}; part < pose.tool_part_count; ++part) {
                const auto& part_pose = pose.tool_parts[part];
                // Tool.apply_transform is outside DisplayList: scale the KV6,
                // rotate it, then apply the tool's DIRECT GL-space child
                // translation. Treating this as DisplayList `(x,-z,y)` data,
                // or placing T before S, leaves Minigun's barrel in the body.
                auto held = mat_scale(static_cast<float>(pose.tool_model_scale));
                held = mat_mul(held,
                               mat_rotate_z(static_cast<float>(part_pose.orientation_degrees.z)));
                held = mat_mul(held,
                               mat_rotate_y(static_cast<float>(part_pose.orientation_degrees.y)));
                held = mat_mul(held,
                               mat_rotate_x(static_cast<float>(part_pose.orientation_degrees.x)));
                held = mat_mul(held,
                               mat_translate(static_cast<float>(part_pose.position.x),
                                             static_cast<float>(part_pose.position.y),
                                             static_cast<float>(part_pose.position.z)));
                // Character.weapon.set_pitch rotates every child around the
                // hand joint before DisplayList applies its fixed position.
                // Applying this after the anchor made the complete weapon
                // orbit upward when the player looked up.
                held = mat_mul(
                    held, mat_rotate_x(static_cast<float>(pose.weapon_pitch_degrees)));
                // Character.weapon owns an unscaled (0,0,0.5) parent anchor;
                // each Tool model has a direct, unscaled local position.
                // Keeping both translations distinct is what seats the
                // minigun barrel in its body instead of inside the player.
                const auto display_anchor = world::retail_display_vector(pose.tool_anchor);
                held = mat_mul(held,
                               mat_translate(static_cast<float>(display_anchor.x),
                                             static_cast<float>(display_anchor.y),
                                             static_cast<float>(display_anchor.z)));
                held = mat_mul(held, mat_rotate_x(-90.0F));
                held = mat_mul(held,
                               mat_translate(static_cast<float>(sucker_shake.x),
                                             static_cast<float>(sucker_shake.y),
                                             static_cast<float>(sucker_shake.z)));
                held = mat_mul(held, root);
                draws.push_back({rig->second.tool_slots[part], held});
            }
            const auto arm_draw = [&](std::uint32_t slot,
                                      const world::RetailThirdPersonArmPose& part) {
                const auto display_offset = world::retail_display_vector(part.model_offset);
                const auto display_position = world::retail_display_vector(part.position);
                auto arm = mat_rotate_z(static_cast<float>(part.extra_roll_degrees));
                arm = mat_mul(arm, mat_rotate_y(static_cast<float>(part.extra_yaw_degrees)));
                arm = mat_mul(arm,
                              mat_translate(static_cast<float>(display_offset.x),
                                            static_cast<float>(display_offset.y),
                                            static_cast<float>(display_offset.z)));
                arm = mat_mul(arm, mat_rotate_y(static_cast<float>(part.yaw_degrees)));
                arm = mat_mul(arm, mat_rotate_x(static_cast<float>(part.pitch_degrees)));
                arm = mat_mul(arm, mat_rotate_z(static_cast<float>(part.roll_degrees)));
                arm = mat_mul(arm, mat_scale(static_cast<float>(pose.arm_model_scale)));
                arm = mat_mul(arm,
                              mat_translate(static_cast<float>(display_position.x),
                                            static_cast<float>(display_position.y),
                                            static_cast<float>(display_position.z)));
                arm = mat_mul(arm, mat_rotate_x(-90.0F));
                arm = mat_mul(arm,
                              mat_translate(static_cast<float>(sucker_shake.x),
                                            static_cast<float>(sucker_shake.y),
                                            static_cast<float>(sucker_shake.z)));
                arm = mat_mul(arm, root);
                draws.push_back({slot, arm});
            };
            if (rig->second.draws_arms && pose.draws_player_arms) {
                const auto& arms = pose.arms;
                arm_draw(
                    rig->second.arm_upper_slot,
                    arms[static_cast<std::size_t>(world::RetailThirdPersonArmPart::right_upper)]);
                arm_draw(
                    rig->second.arm_lower_slot,
                    arms[static_cast<std::size_t>(world::RetailThirdPersonArmPart::right_lower)]);
                arm_draw(
                    rig->second.arm_upper_slot,
                    arms[static_cast<std::size_t>(world::RetailThirdPersonArmPart::left_upper)]);
                arm_draw(
                    rig->second.arm_lower_slot,
                    arms[static_cast<std::size_t>(world::RetailThirdPersonArmPart::left_lower)]);
            }
            tune_character_draws(first_character_draw);
        }
        return draws;
    }

    /** Build observer-side retail LaserAttachment draws from packet-2 state. */
    [[nodiscard]] std::vector<render::LaserBeamDraw> sniper_laser_draws() const {
        std::vector<render::LaserBeamDraw> draws;
        if (!network_match || tutorial_session == nullptr || !local_player_id.has_value() ||
            !match_initial_info.enable_sniper_beam) {
            return draws;
        }

        const auto players = tutorial_roster.players();
        std::vector<world::SniperLaserTarget> targets;
        targets.reserve(players.size());
        for (const auto& player : players) {
            world::Vec3 position = player.position;
            if (player.player_id == *local_player_id) {
                position = tutorial_session->player().position;
            } else if (const auto rig = remote_player_rigs.find(player.player_id);
                       rig != remote_player_rigs.end()) {
                position = rig->second.motion.sample().position;
            }
            targets.push_back(
                {player.player_id,
                 {static_cast<float>(position.x),
                  static_cast<float>(position.y),
                  static_cast<float>(position.z)},
                 (player.input_flags & 0x20U) != 0U,
                 player.dead});
        }

        const auto observer = tutorial_session->player().position;
        draws.reserve(players.size());
        for (const auto& player : players) {
            if (player.player_id == *local_player_id || player.dead ||
                !network::world_player_zoomed(player.action_flags) ||
                (player.tool_id != 18U && player.tool_id != 19U)) {
                continue;
            }
            world::Vec3 position = player.position;
            world::Vec3 orientation = player.orientation;
            if (const auto rig = remote_player_rigs.find(player.player_id);
                rig != remote_player_rigs.end()) {
                const auto& motion = rig->second.motion.sample();
                position = motion.position;
                orientation = motion.orientation;
            }
            const auto* weapon = world::find_weapon_definition(player.tool_id);
            if (weapon == nullptr) {
                continue;
            }
            world::SniperLaserInput input;
            input.server_enabled = true;
            input.owner_id = player.player_id;
            input.tool_id = player.tool_id;
            input.team = player.team;
            input.zoomed = true;
            input.position = {static_cast<float>(position.x),
                              static_cast<float>(position.y),
                              static_cast<float>(position.z)};
            input.orientation = {static_cast<float>(orientation.x),
                                 static_cast<float>(orientation.y),
                                 static_cast<float>(orientation.z)};
            input.observer_position = {static_cast<float>(observer.x),
                                       static_cast<float>(observer.y),
                                       static_cast<float>(observer.z)};
            input.maximum_range = static_cast<float>(weapon->maximum_range);
            auto pose = world::evaluate_sniper_laser(tutorial_session->map(), input, targets);
            if (pose.visible) {
                draws.push_back({pose});
            }
        }
        return draws;
    }

    [[nodiscard]] bool gameplay_lab_in_stack() const noexcept {
        return developer_tools_allowed() &&
               std::ranges::find(navigation.stack(), screen_id(FrontendScreen::gameplay_debug)) !=
                   navigation.stack().end();
    }

    /** Loads both team-colored character skins and their FPS arms on demand. */
    bool load_gameplay_lab_class_models() {
        const auto color = gameplay_debug_lab.team_color();
        if (lab_models_color == color) {
            return true;
        }
        world_renderer.clear_world_models();
        preview_deployable_type_uploaded.reset();
        parachute_mesh_attempted.fill(false);
        parachute_mesh_uploaded.fill(false);
        for (const auto& definition : world::class_catalog()) {
            auto loaded = world::load_class_models(config.asset_root, definition.class_id, color,
                                                   model_inverse_scale);
            if (!loaded) {
                settings_warning = "class model failed to load: " + loaded.error;
                return false;
            }
            lab_class_meshes[definition.class_id] = std::move(loaded.models->standing_preview);
            lab_class_arms[definition.class_id] = std::move(loaded.models->first_person_arms);
            if (!world_renderer.set_world_model_mesh(definition.class_id,
                                                     lab_class_meshes[definition.class_id])) {
                settings_warning =
                    "class model upload failed: " + std::string{world_renderer.last_error()};
                return false;
            }
        }
        lab_models_color = color;
        uploaded_lab_class.reset();
        uploaded_lab_tool.reset();
        return true;
    }

    /** Dynamic viewmodel slots let the lab inspect every 0..64 tool. */
    bool sync_gameplay_lab_view_model() {
        const auto tool = gameplay_debug_lab.selected_tool_id();
        const auto klass = gameplay_debug_lab.selected_class_id();
        if (uploaded_lab_tool == tool && uploaded_lab_class == klass) {
            return true;
        }
        world_renderer.clear_view_model();
        lab_tool_part_count = 0U;
        lab_world_tool_part_count = 0U;
        lab_arm_upper_slot.reset();
        lab_arm_lower_slot.reset();
        lab_world_arm_upper_slot.reset();
        lab_world_arm_lower_slot.reset();
        const auto weapon = world::load_weapon_models(
            config.asset_root, tool, {1.0F, 1.0F, 1.0F},
            gameplay_debug_lab.team_color(), model_inverse_scale);
        if (!weapon) {
            settings_warning = "weapon model failed to load: " + weapon.error;
            return false;
        }
        for (const auto& mesh : weapon.models->first_person_parts) {
            if (lab_tool_part_count >= render::WorldRenderer::view_model_slot_count ||
                !world_renderer.set_view_model_mesh(lab_tool_part_count, mesh)) {
                settings_warning = "weapon viewmodel exceeds or failed its GPU slots";
                return false;
            }
            ++lab_tool_part_count;
        }
        constexpr std::uint32_t world_tool_slot_base{
            static_cast<std::uint32_t>(world::retail_class_count)};
        for (const auto& mesh : weapon.models->third_person_parts) {
            const auto slot = world_tool_slot_base + lab_world_tool_part_count;
            if (slot >= render::WorldRenderer::world_model_slot_count ||
                !world_renderer.set_world_model_mesh(slot, mesh)) {
                settings_warning = "third-person weapon exceeds or failed its GPU slots";
                return false;
            }
            ++lab_world_tool_part_count;
        }
        const auto& arms = lab_class_arms[klass];
        if (arms.size() >= 2U &&
            lab_tool_part_count + 2U <= render::WorldRenderer::view_model_slot_count) {
            lab_arm_upper_slot = lab_tool_part_count++;
            lab_arm_lower_slot = lab_tool_part_count++;
            if (!world_renderer.set_view_model_mesh(*lab_arm_upper_slot, arms[0U]) ||
                !world_renderer.set_view_model_mesh(*lab_arm_lower_slot, arms[1U])) {
                settings_warning = "class arm viewmodel upload failed";
                return false;
            }
            const auto world_upper = world_tool_slot_base + 3U;
            const auto world_lower = world_tool_slot_base + 4U;
            if (world_lower < render::WorldRenderer::world_model_slot_count &&
                world_renderer.set_world_model_mesh(world_upper, arms[0U]) &&
                world_renderer.set_world_model_mesh(world_lower, arms[1U])) {
                lab_world_arm_upper_slot = world_upper;
                lab_world_arm_lower_slot = world_lower;
            }
        }
        uploaded_lab_tool = tool;
        uploaded_lab_class = klass;
        return true;
    }

    [[nodiscard]] std::vector<render::ViewModelDraw> gameplay_lab_view_model_draws() {
        std::vector<render::ViewModelDraw> draws;
        if (gameplay_debug_lab.inspection_mode() != world::DebugInspectionMode::first_person) {
            return draws;
        }
        const auto pose = world::evaluate_weapon_view_model(
            world::WeaponViewModelInput{gameplay_debug_lab.selected_tool_id(),
                                        gameplay_debug_lab.seconds_since_action(),
                                        gameplay_debug_lab.emitted_action_count(),
                                        0.0,
                                        0.0,
                                        0.0});
        const auto tool_matrix = [&](const world::RetailModelPose& part_pose) {
            Mat4 tool = mat_scale(static_cast<float>(pose.model_scale));
            tool = mat_mul(tool, mat_rotate_z(static_cast<float>(part_pose.orientation_degrees.z)));
            tool = mat_mul(tool, mat_rotate_y(static_cast<float>(part_pose.orientation_degrees.y)));
            tool = mat_mul(tool, mat_rotate_x(static_cast<float>(part_pose.orientation_degrees.x)));
            tool = mat_mul(tool,
                           mat_translate(static_cast<float>(part_pose.position.x),
                                         static_cast<float>(part_pose.position.y),
                                         static_cast<float>(part_pose.position.z)));
            tool = mat_mul(tool, mat_rotate_x(static_cast<float>(pose.digging_pitch_degrees)));
            // Tool and hands must consume the same Character.draw_fps sway.
            // Omitting this here made the all-weapons gun appear immediately
            // while its hands arrived later through the pullout animation.
            tool = mat_mul(
                tool,
                mat_translate(static_cast<float>(pose.tool_sway.x + pose.character_offset.x),
                              static_cast<float>(pose.tool_sway.y + pose.character_offset.y),
                              static_cast<float>(pose.tool_sway.z + pose.character_offset.z)));
            return mat_mul(tool, mat_rotate_y(static_cast<float>(pose.character_yaw_degrees)));
        };
        for (std::uint32_t slot{}; slot < lab_tool_part_count; ++slot) {
            const bool is_upper = lab_arm_upper_slot.has_value() && slot == *lab_arm_upper_slot;
            const bool is_lower = lab_arm_lower_slot.has_value() && slot == *lab_arm_lower_slot;
            if (!is_upper && !is_lower) {
                const auto part = static_cast<std::size_t>(slot);
                const auto& part_pose =
                    part < pose.tool_part_count ? pose.tool_parts[part] : pose.tool;
                draws.push_back({slot, tool_matrix(part_pose)});
            }
        }
        const auto append_arm = [&](std::uint32_t slot, const world::RetailArmPartPose& part) {
            Mat4 model = mat_scale(static_cast<float>(pose.model_scale));
            model = mat_mul(model, mat_rotate_y(static_cast<float>(part.yaw_degrees)));
            model = mat_mul(model,
                            mat_translate(static_cast<float>(part.position.x),
                                          static_cast<float>(part.position.y),
                                          static_cast<float>(part.position.z)));
            model = mat_mul(model,
                            mat_translate(static_cast<float>(pose.arms_anchor.x),
                                          static_cast<float>(pose.arms_anchor.y),
                                          static_cast<float>(pose.arms_anchor.z)));
            model = mat_mul(model,
                            mat_rotate_x(static_cast<float>(pose.arms_orientation_degrees.x *
                                                            pose.arm_rotation_ratio)));
            model = mat_mul(
                model,
                mat_translate(static_cast<float>(pose.arms_position.x + pose.character_offset.x),
                              static_cast<float>(pose.arms_position.y + pose.character_offset.y),
                              static_cast<float>(pose.arms_position.z + pose.character_offset.z)));
            model = mat_mul(model, mat_rotate_y(static_cast<float>(pose.character_yaw_degrees)));
            draws.push_back({slot, model});
        };
        if (pose.draws_player_arms && lab_arm_upper_slot.has_value() &&
            lab_arm_lower_slot.has_value()) {
            const auto& parts = pose.arm_parts;
            append_arm(*lab_arm_lower_slot,
                       parts[static_cast<std::size_t>(world::RetailArmPart::left_lower)]);
            append_arm(*lab_arm_lower_slot,
                       parts[static_cast<std::size_t>(world::RetailArmPart::right_lower)]);
            append_arm(*lab_arm_upper_slot,
                       parts[static_cast<std::size_t>(world::RetailArmPart::left_upper)]);
        }
        return draws;
    }

    [[nodiscard]] std::vector<render::WorldModelDraw> gameplay_lab_world_draws() const {
        std::vector<render::WorldModelDraw> draws;
        if (gameplay_debug_lab.inspection_mode() == world::DebugInspectionMode::first_person ||
            gameplay_debug_lab.inspection_mode() == world::DebugInspectionMode::effects) {
            return draws;
        }
        const auto spawned = gameplay_debug_lab.spawned_classes();
        draws.reserve(spawned.size() + lab_world_tool_part_count + 3U);
        for (std::size_t index{}; index < spawned.size(); ++index) {
            const bool gallery =
                gameplay_debug_lab.inspection_mode() == world::DebugInspectionMode::gallery;
            const auto column = static_cast<float>(index % 6U);
            const auto row = static_cast<float>(index / 6U);
            const float x = 0.0F;
            // Keep the close-up clear of the diagnostics panel while the
            // gallery remains centered around the camera axis.
            const float y = gallery ? (column - 2.5F) * 1.75F - 2.5F : -1.45F;
            const float z = gallery ? row * 2.0F : 0.0F;
            auto model = mat_scale(gallery ? 1.0F : gameplay_debug_lab.preview_zoom());
            model = mat_mul(model, mat_rotate_z(gameplay_debug_lab.preview_yaw()));
            model = mat_mul(model, mat_translate(x, y, z));
            draws.push_back({spawned[index], model});
        }
        if (gameplay_debug_lab.inspection_mode() == world::DebugInspectionMode::character &&
            !spawned.empty()) {
            const auto pose =
                world::evaluate_retail_third_person_pose(gameplay_debug_lab.selected_tool_id(),
                                                         lab_world_tool_part_count,
                                                         gameplay_debug_lab.seconds_since_action(),
                                                         gameplay_debug_lab.emitted_action_count());
            constexpr std::uint32_t world_tool_slot_base{
                static_cast<std::uint32_t>(world::retail_class_count)};
            for (std::uint32_t part{}; part < lab_world_tool_part_count; ++part) {
                const auto& part_pose = pose.tool_parts[part];
                // Tool.apply_transform translates in direct GL coordinates
                // outside DisplayList's scale. Row-vector composition is the
                // transposed retail chain: S, rotations, then T(child).
                auto held = mat_scale(static_cast<float>(pose.tool_model_scale));
                held = mat_mul(held,
                               mat_rotate_z(static_cast<float>(part_pose.orientation_degrees.z)));
                held = mat_mul(held,
                               mat_rotate_y(static_cast<float>(part_pose.orientation_degrees.y)));
                held = mat_mul(held,
                               mat_rotate_x(static_cast<float>(part_pose.orientation_degrees.x)));
                held = mat_mul(held,
                               mat_translate(static_cast<float>(part_pose.position.x),
                                             static_cast<float>(part_pose.position.y),
                                             static_cast<float>(part_pose.position.z)));
                held = mat_mul(
                    held, mat_rotate_x(static_cast<float>(pose.weapon_pitch_degrees)));
                const auto display_anchor = world::retail_display_vector(pose.tool_anchor);
                held = mat_mul(held,
                               mat_translate(static_cast<float>(display_anchor.x),
                                             static_cast<float>(display_anchor.y),
                                             static_cast<float>(display_anchor.z)));
                // The debug mannequin is pre-combined in authored XYZ while
                // KV6 tool meshes retain retail's VBO basis (X,-Z,Y). Convert
                // the completed retail DisplayList hierarchy back to the
                // mannequin/world basis; without this the Zombie palms and
                // every held weapon point toward the ground.
                held = mat_mul(held, mat_rotate_x(-90.0F));
                held = mat_mul(held, mat_scale(gameplay_debug_lab.preview_zoom()));
                held = mat_mul(held, mat_rotate_z(gameplay_debug_lab.preview_yaw()));
                held = mat_mul(held, mat_translate(0.0F, -1.45F, 0.0F));
                draws.push_back({world_tool_slot_base + part, held});
            }
            const auto arm_draw = [&](std::uint32_t slot,
                                      const world::RetailThirdPersonArmPose& part) {
                // DisplayList.draw uses two distinct rotation layers. The
                // authored extra yaw/roll acts on the model first, followed
                // by the local offset, then Matrix4.rotate(pitch, yaw, roll).
                // In this row-vector renderer the recovered logical chain is:
                // Rz(extra_roll), Ry(extra_yaw), T(offset.x,-offset.z,offset.y),
                // Ry(yaw), Rx(pitch), Rz(roll), S, T(position).
                // Applying the Matrix4 rotation before T(offset) rotates the
                // joint pivot itself and visibly tears hands from forearms.
                const auto display_offset = world::retail_display_vector(part.model_offset);
                const auto display_position = world::retail_display_vector(part.position);
                auto arm = mat_rotate_z(static_cast<float>(part.extra_roll_degrees));
                arm = mat_mul(arm, mat_rotate_y(static_cast<float>(part.extra_yaw_degrees)));
                arm = mat_mul(arm,
                              mat_translate(static_cast<float>(display_offset.x),
                                            static_cast<float>(display_offset.y),
                                            static_cast<float>(display_offset.z)));
                arm = mat_mul(arm, mat_rotate_y(static_cast<float>(part.yaw_degrees)));
                arm = mat_mul(arm, mat_rotate_x(static_cast<float>(part.pitch_degrees)));
                arm = mat_mul(arm, mat_rotate_z(static_cast<float>(part.roll_degrees)));
                arm = mat_mul(arm, mat_scale(static_cast<float>(pose.arm_model_scale)));
                arm = mat_mul(arm,
                              mat_translate(static_cast<float>(display_position.x),
                                            static_cast<float>(display_position.y),
                                            static_cast<float>(display_position.z)));
                arm = mat_mul(arm, mat_rotate_x(-90.0F));
                arm = mat_mul(arm, mat_scale(gameplay_debug_lab.preview_zoom()));
                arm = mat_mul(arm, mat_rotate_z(gameplay_debug_lab.preview_yaw()));
                arm = mat_mul(arm, mat_translate(0.0F, -1.45F, 0.0F));
                draws.push_back({slot, arm});
            };
            if (pose.draws_player_arms && lab_world_arm_upper_slot.has_value() &&
                lab_world_arm_lower_slot.has_value()) {
                const auto& arms = pose.arms;
                arm_draw(
                    *lab_world_arm_upper_slot,
                    arms[static_cast<std::size_t>(world::RetailThirdPersonArmPart::right_upper)]);
                arm_draw(
                    *lab_world_arm_lower_slot,
                    arms[static_cast<std::size_t>(world::RetailThirdPersonArmPart::right_lower)]);
                arm_draw(
                    *lab_world_arm_upper_slot,
                    arms[static_cast<std::size_t>(world::RetailThirdPersonArmPart::left_upper)]);
                arm_draw(
                    *lab_world_arm_lower_slot,
                    arms[static_cast<std::size_t>(world::RetailThirdPersonArmPart::left_lower)]);
            }
        }
        return draws;
    }

    [[nodiscard]] std::uint8_t first_person_class_id() const {
        if (network_match && local_player_id) {
            if (const auto* local=tutorial_roster.player(*local_player_id)) return local->class_id;
        }
        return tutorial_session ? tutorial_session->debug_class_id() : 0U;
    }

    /** Keep retail poses, using the equipped character's authored arm pair. */
    [[nodiscard]] bool load_tutorial_class_arms(std::uint8_t class_id) {
        const auto team_color = local_player_team_color();
        if (loaded_tutorial_arm_class == class_id && loaded_tutorial_arm_color == team_color) {
            return true;
        }

        const auto* definition = world::find_class_definition(class_id);
        if (definition == nullptr) {
            settings_warning = "debug class is outside the retail catalog";
            return false;
        }
        // Zombie classes deliberately have no separate arm pair: their
        // equipped zombie-hands tool owns the complete FPS presentation.
        if (definition->first_person_arm_assets[0U].empty() &&
            definition->first_person_arm_assets[1U].empty()) {
            arms_upper_mesh = {};
            arms_lower_mesh = {};
            arms_debug_upper_mesh = {};
            arms_debug_lower_a_mesh = {};
            arms_debug_lower_b_mesh = {};
            tutorial_class_draws_arms = false;
            uploaded_sandbox_tool.reset();
            view_model_meshes_uploaded = false;
            loaded_tutorial_arm_class = class_id;
            loaded_tutorial_arm_color = team_color;
            return true;
        }
        if (definition->first_person_arm_assets[0U].empty() ||
            definition->first_person_arm_assets[1U].empty()) {
            settings_warning = "debug class has an incomplete FPS arm pair";
            return false;
        }

        std::string error;
        auto upper = load_runtime_model(
            config.asset_root / definition->first_person_arm_assets[0U], &error);
        if (!upper.has_value()) {
            settings_warning = "upper FPS arm failed to load: " + error;
            return false;
        }
        auto lower = load_runtime_model(
            config.asset_root / definition->first_person_arm_assets[1U], &error);
        if (!lower.has_value()) {
            settings_warning = "lower FPS arm failed to load: " + error;
            return false;
        }
        if (const auto* cosmetic=local_equipped_cosmetic("class:"+std::to_string(class_id)+":body")) {
            upper->apply_cosmetic_palette(cosmetic->palette);
            lower->apply_cosmetic_palette(cosmetic->palette);
        }
        upper->apply_default_color(team_color);
        lower->apply_default_color(team_color);
        auto upper_mesh = upper->mesh();
        auto lower_mesh = lower->mesh();
        const auto* character=local_equipped_cosmetic("class:"+std::to_string(class_id)+":body");
        const auto parts=inventory_character_parts(character,config.asset_root);
        if(parts.contains("arm_upper")&&parts.contains("arm_lower")) {
            const auto loaded=world::load_class_models(config.asset_root,class_id,team_color,
                                                       model_inverse_scale,std::nullopt,nullptr,&parts);
            if(!loaded||loaded.models->first_person_arms.size()!=2U) {
                settings_warning="equipped character arms failed: "+loaded.error;
                return false;
            }
            upper_mesh=loaded.models->first_person_arms[0];
            lower_mesh=loaded.models->first_person_arms[1];
        }
        // Commit both hands together after every required model succeeded.
        // A missing cosmetic/model keeps the last usable pair instead of
        // emptying it while the previous cache identity remains valid.
        arms_upper_mesh = std::move(upper_mesh);
        arms_lower_mesh = std::move(lower_mesh);
        arms_debug_upper_mesh = upper->mesh({}, {2.0F, 0.4F, 0.4F});
        arms_debug_lower_a_mesh = lower->mesh({}, {0.4F, 2.0F, 0.4F});
        arms_debug_lower_b_mesh = lower->mesh({}, {0.4F, 0.4F, 2.0F});
        tutorial_class_draws_arms = true;
        // Class/team can change while holding the same tool. Invalidate the
        // GPU cache only after the complete replacement pair has loaded.
        uploaded_sandbox_tool.reset();
        view_model_meshes_uploaded = false;
        loaded_tutorial_arm_class = class_id;
        loaded_tutorial_arm_color = team_color;
        return true;
    }

    void load_tool_meshes() {
        if (!tool_meshes.empty()) {
            return;
        }
        const auto kv6_root = config.asset_root / "kv6";
        const auto load_model = [&](const char* file) {
            std::string error;
            auto model = load_runtime_model(kv6_root / file, &error);
            if (!model.has_value()) {
                settings_warning = "tool model failed to load: " + error;
            }
            return model;
        };
        if (auto model = load_model("block.kv6"); model.has_value()) {
            // Retail draws the all-white block model blended with the build
            // color; bake the same color the session places.
            tool_meshes.emplace(
                world::TutorialTool::block,
                model->mesh({}, {110.0F / 255.0F, 110.0F / 255.0F, 110.0F / 255.0F}));
        }
        if (auto model = load_model("spade.kv6"); model.has_value()) {
            tool_meshes.emplace(world::TutorialTool::spade, model->mesh());
        }
        if (auto model = load_model("pistol.kv6"); model.has_value()) {
            tool_meshes.emplace(world::TutorialTool::pistol, model->mesh());
        }
        // The pistol is the only tutorial tool that aims, and Character.
        // draw_sight draws its own models rather than the held weapon. Both
        // come from the catalog so the pin follows automatically if the
        // tutorial ever hands out a tool that has one.
        if (const auto aimed =
                world::load_weapon_models(config.asset_root, tutorial_pistol_tool_id,
                                          {1.0F, 1.0F, 1.0F}, std::nullopt,
                                          model_inverse_scale);
            aimed) {
            if (aimed.models->sight.has_value()) {
                tutorial_sight_mesh = *aimed.models->sight;
            }
            if (aimed.models->pin.has_value()) {
                tutorial_pin_mesh = *aimed.models->pin;
            }
        }
    }

    void clear_scripted_weapon() {
        if(tutorial_session)tutorial_session->set_skin_zoom(0U,std::nullopt);
        scripted_weapon.reset();scripted_cosmetic_id.clear();scripted_model_slots.clear();scripted_sounds.clear();
        scripted_images.clear(renderer);scripted_shots=0;scripted_reload_started=scripted_reload_finished=false;scripted_aim=scripted_raise=0;
        scripted_motion={};
    }

    bool load_scripted_weapon(const InventoryCosmetic* item,std::uint8_t tool) {
        if(!item||item->scripted_skin.empty()||std::ranges::none_of(item->parents,[tool](const auto& p){return p.tool==tool;}))return false;
        if(std::ranges::find(failed_scripted_skins,item->id)!=failed_scripted_skins.end())return false;
        auto skin=std::make_unique<world::ScriptedWeapon>();std::string error;
        const auto variant=skin_variant_preferences?skin_variant_preferences->selection(item->id):world::SkinVariantSelection{};
        if(!skin->load(config.asset_root.parent_path()/item->scripted_skin,error,variant)){
            failed_scripted_skins.push_back(item->id);settings_warning="Skin animation failed: "+error;return false;
        }
        const auto* character=local_equipped_cosmetic("class:"+std::to_string(first_person_class_id())+":body");
        const auto arms=inventory_character_parts(character,config.asset_root);
        world_renderer.clear_view_model();std::uint32_t slot=0;
        for(std::size_t id=0;id<skin->resources().size();++id){const auto& r=skin->resources()[id];
            if(r.path.empty())continue;
            if(r.kind==0){auto mesh=skin->model_mesh(id,local_player_team_color(),arms);
                if(mesh.empty()||slot>=render::WorldRenderer::view_model_slot_count||!world_renderer.set_view_model_mesh(slot,mesh)){
                    settings_warning="Skin model failed: "+r.name;clear_scripted_weapon();return false;
                }scripted_model_slots[id]=slot++;
            }else if(r.kind==2&&audio_started)scripted_sounds[id]=audio->preload_skin_sound(r.path);
        }
        if(slot==0)return false;
        if(!scripted_images.load(renderer,*skin,error))settings_warning="Skin sight image failed: "+error;
        if(tutorial_session&&skin->variant().magnification>0.F)
            tutorial_session->set_skin_zoom(tool,world::skin_variant_zoom_target(skin->variant().magnification));
        scripted_cosmetic_id=item->id;scripted_weapon=std::move(skin);scripted_time=std::chrono::steady_clock::now();
        if(audio_started)static_cast<void>(audio->play_cosmetic_cue(item->id,"raise",0,{},.7F,true));
        uploaded_sandbox_tool=tool;uploaded_tool.reset();view_model_meshes_uploaded=false;return true;
    }

    std::vector<render::ViewModelDraw> scripted_weapon_draws() {
        std::vector<render::ViewModelDraw> draws;if(!scripted_weapon||!tutorial_session||!uploaded_sandbox_tool)return draws;
        world::SkinInput input;const auto now=std::chrono::steady_clock::now();
        input.dt=std::clamp(std::chrono::duration<float>(now-scripted_time).count(),0.F,.1F);scripted_time=now;
        const float target=tutorial_session->zoomed()?1.F:0.F;
        scripted_aim+=std::clamp(target-scripted_aim,-input.dt*3.F,input.dt*8.F);input.aim=scripted_aim;
        const auto movement=tutorial_session->diagnostics();
        const bool running=tutorial_session->action_held(world::TutorialAction::sprint)&&
            !movement.airborne&&std::hypot(movement.velocity.x,movement.velocity.y)>.01;
        input.sprint=running?1.F:0.F;
        scripted_raise=std::min(1.F,scripted_raise+input.dt*4.F);input.raise=scripted_raise;
        const auto* definition=world::find_weapon_definition(*uploaded_sandbox_tool);
        if(definition){input.clip_size=definition->clip_size;
            if(definition->melee)input.aim=scripted_dig?1.F:0.F;
            input.ready=std::clamp(static_cast<float>(tutorial_session->seconds_since_primary()/std::max(definition->fire_interval,.01)),0.F,1.F);
            input.reload_progress=1.F-std::clamp(static_cast<float>(tutorial_session->weapon_reload_remaining()/std::max(definition->reload_time,.01)),0.F,1.F);
        }
        if(const auto* ammo=tutorial_session->selected_ammo()){input.ammo=ammo->magazine;input.reloading=ammo->reloading;}
        // Authored scopes hide the weapon while aimed. Cancel that pose on
        // the first reload frame so the entire reload animation stays visible.
        if(input.reloading){scripted_aim=0.F;input.aim=0.F;}
        const auto sway=first_person_sway();input.swing={-static_cast<float>(sway.x),static_cast<float>(sway.z),-static_cast<float>(sway.y)};
        scripted_motion.apply(input,applied_settings.main.weapon_motion);
        const auto team=local_player_team_color();input.team_color={team.red/255.F,team.green/255.F,team.blue/255.F};
        input.screen_width=static_cast<float>(drawable_extent.width);input.screen_height=static_cast<float>(drawable_extent.height);
        input.muted=!audio_started;input.reload_started=std::exchange(scripted_reload_started,false);input.reload_finished=std::exchange(scripted_reload_finished,false);
        const bool fired=scripted_shots>0;unsigned events=std::max(1U,scripted_shots);scripted_shots=0;
        for(unsigned n=0;n<events;++n){input.fired=fired;
            std::string error;if(!scripted_weapon->update(input,error)){failed_scripted_skins.push_back(scripted_cosmetic_id);settings_warning="Skin animation stopped: "+error;clear_scripted_weapon();uploaded_sandbox_tool.reset();return draws;}
            if(audio_started)for(const auto& s:scripted_weapon->frame().sounds){auto found=scripted_sounds.find(s.resource);if(found!=scripted_sounds.end()&&found->second)audio->play_skin_sound(found->second,s.gain*.125F,s.pitch);}
            input.dt=0;input.reload_started=input.reload_finished=false;
        }
        for(const auto& d:scripted_weapon->frame().models){const auto slot=scripted_model_slots.find(d.resource);if(slot!=scripted_model_slots.end())draws.push_back({slot->second,d.transform});}
        return draws;
    }

    void draw_scripted_images() {
        if(!scripted_weapon||!tutorial_session||!tutorial_world_in_stack())return;
        if(death_camera.active()||!tutorial_session->weapon_view_model_visible())return;
        const auto* ammo=tutorial_session->selected_ammo();
        const bool iron_dot=tutorial_session->zoomed()&&scripted_aim>.8F&&
            !(ammo&&ammo->reloading)&&!tutorial_session->action_held(world::TutorialAction::sprint);
        if(!scripted_images.draw(renderer,scripted_weapon->frame(),{drawable_extent.width,drawable_extent.height},
            static_cast<float>(world::zoom_fov_y_degrees(tutorial_session->zoom_level())),iron_dot))
            settings_warning="Skin sight drawing failed: "+std::string{renderer.last_error()};
    }

    /** Streams the selected all-weapons sandbox tool into viewmodel slots. */
    [[nodiscard]] bool sync_sandbox_view_model() {
        if (tutorial_session == nullptr) {
            return true;
        }
        // Inventory refresh invalidates the arm cache even while the same
        // weapon is held. Refresh before uploading its viewmodel again.
        if(!load_tutorial_class_arms(first_person_class_id())) return false;
        const auto selected = tutorial_session->selected_tool_id();
        if (!selected.has_value() || uploaded_sandbox_tool == selected) {
            return true;
        }
        const PerformanceScope performance{"local_viewmodel", std::chrono::microseconds{2'000}};
        std::array<float, 3U> tint{1.0F, 1.0F, 1.0F};
        if (*selected == 5U || *selected == 22U || *selected == 23U || *selected == 27U ||
            *selected == 28U) {
            const auto color = tutorial_session->block_color();
            tint = {static_cast<float>(color.red) / 255.0F,
                    static_cast<float>(color.green) / 255.0F,
                    static_cast<float>(color.blue) / 255.0F};
        }
        const auto* cosmetic=local_equipped_cosmetic("weapon:"+std::to_string(*selected)+":view");
        // Local visual oracle cannot advertise or award an unowned item online.
        if (applied_settings.main.show_skins && !network_match && developer_tools_allowed() && config.tutorial_debug_cosmetic)
            cosmetic=find_inventory_cosmetic(*config.tutorial_debug_cosmetic);
        clear_scripted_weapon();
        if(load_scripted_weapon(cosmetic,*selected))return true;
        const auto finish=inventory_weapon_finish(cosmetic,config.asset_root,*selected);
        const auto loaded = world::load_weapon_models(
            config.asset_root, *selected, tint, local_player_team_color(),
            model_inverse_scale, finish?&*finish:nullptr);
        if (!loaded) {
            settings_warning = "sandbox weapon model failed: " + loaded.error;
            return false;
        }
        world_renderer.clear_view_model();
        sandbox_tool_part_count = 0U;
        sandbox_sight_slot.reset();
        sandbox_pin_slot.reset();
        sandbox_arm_upper_slot.reset();
        sandbox_arm_lower_slot.reset();
        for (const auto& mesh : loaded.models->first_person_parts) {
            if (sandbox_tool_part_count >= render::WorldRenderer::view_model_slot_count ||
                !world_renderer.set_view_model_mesh(sandbox_tool_part_count, mesh)) {
                settings_warning = "sandbox weapon exceeds viewmodel slots";
                return false;
            }
            ++sandbox_tool_part_count;
        }
        if (loaded.models->sight.has_value()) {
            if (sandbox_tool_part_count >= render::WorldRenderer::view_model_slot_count ||
                !world_renderer.set_view_model_mesh(sandbox_tool_part_count,
                                                    *loaded.models->sight)) {
                settings_warning = "sandbox sight exceeds viewmodel slots";
                return false;
            }
            sandbox_sight_slot = sandbox_tool_part_count++;
        }
        // character.pyx:2083-2085 draws the pin right after the sight. Only
        // the classic rifle carries one, so this normally costs nothing.
        if (loaded.models->pin.has_value()) {
            if (sandbox_tool_part_count >= render::WorldRenderer::view_model_slot_count ||
                !world_renderer.set_view_model_mesh(sandbox_tool_part_count, *loaded.models->pin)) {
                settings_warning = "sandbox sight pin exceeds viewmodel slots";
                return false;
            }
            sandbox_pin_slot = sandbox_tool_part_count++;
        }
        if (tutorial_class_draws_arms &&
            sandbox_tool_part_count + 2U <= render::WorldRenderer::view_model_slot_count) {
            sandbox_arm_upper_slot = sandbox_tool_part_count++;
            sandbox_arm_lower_slot = sandbox_tool_part_count++;
            if (!world_renderer.set_view_model_mesh(*sandbox_arm_upper_slot, arms_upper_mesh) ||
                !world_renderer.set_view_model_mesh(*sandbox_arm_lower_slot, arms_lower_mesh)) {
                settings_warning = "sandbox arm upload failed";
                return false;
            }
        }
        if (audio_started && uploaded_sandbox_tool.has_value()) {
            audio->play_head_relative_one_shot(audio::OpenAlFrontendAudio::tool_switch_sound, 1.0F);
        }
        uploaded_sandbox_tool = selected;
        uploaded_tool.reset();
        view_model_meshes_uploaded = false;
        return true;
    }

    /**
     * The complete first-person sway aggregate: walk bob, mouse sway and the
     * airborne lift.
     *
     * Shared by BOTH viewmodel paths on purpose. The all-weapons sandbox used to
     * build its own vector as {mouse_x, mouse_y, 0.0}, and since the walk bob
     * lives entirely in Z, hardcoding that zero silently deleted the bob for
     * every weapon reached through the debug loadout -- the hands simply stopped
     * moving as you walked, while the ordinary tools still bobbed. One helper
     * means the two paths cannot disagree again.
     *
     * Pullout is deliberately NOT included: it is applied per-path further in,
     * against each path's own pose composer.
     */
    [[nodiscard]] world::ViewModelVector first_person_sway() {
        {
            // Mouse sway, integrated here so it happens exactly once per frame:
            // the two viewmodel paths are mutually exclusive, so whichever runs
            // calls this once. It used to live in the ordinary path only, which
            // meant the sandbox -- reached by the all-weapons loadout -- never
            // consumed the mouse delta at all and its hands did not drift with
            // the look either.
            const double height = std::max(1.0, static_cast<double>(drawable_extent.height));
            const double aspect = static_cast<double>(drawable_extent.width) / height;
            const double target_x = 0.00005 * viewmodel_mouse_dx * aspect;
            const double target_y = -0.00005 * viewmodel_mouse_dy * aspect;
            viewmodel_mouse_dx = 0.0;
            viewmodel_mouse_dy = 0.0;
            // interpolate(old, new, 20) at the 60 Hz baseline multiplier.
            weapon_sway_x += (target_x - weapon_sway_x) / 20.0;
            weapon_sway_y += (target_y - weapon_sway_y) / 20.0;
        }
        world::ViewModelVector sway{weapon_sway_x, weapon_sway_y, 0.0};
        if (!applied_settings.main.weapon_motion) return {};
        if (tutorial_session == nullptr) {
            return sway;
        }
        const auto info = tutorial_session->diagnostics();
        // bob = ((timer_ms & 511) - 255) * max(|vy|, |vx|), the sign alternating
        // every 512 ms and scaled by 1/1000. Amplitude is horizontal speed, so
        // standing still bobs not at all and sprinting bobs hardest.
        const auto timer_ms =
            static_cast<std::int64_t>(tutorial_session->ticks_simulated() * 1000ULL / 60ULL);
        const double amplitude = std::max(std::fabs(info.velocity.y), std::fabs(info.velocity.x));
        double bob = (static_cast<double>(timer_ms & 511) - 255.0) * amplitude;
        bob /= ((timer_ms & 1023) > 511) ? 1000.0 : -1000.0;
        sway.z += bob;
        if (info.airborne) {
            sway.y += info.velocity.z * 0.2;
        }
        return sway;
    }

    [[nodiscard]] std::vector<render::ViewModelDraw> sandbox_view_model_draws() {
        std::vector<render::ViewModelDraw> draws;
        if (tutorial_session == nullptr || !uploaded_sandbox_tool.has_value()) {
            return draws;
        }
        if(scripted_weapon)return scripted_weapon_draws();
        if (!tutorial_session->weapon_view_model_visible()) {
            return draws;
        }
        // Character.draw_fps applies the selection pullout to X/Y. The old
        // positional aggregate accidentally passed this timer as sway_z,
        // making every F4/wheel change shove and twist the hands toward the
        // camera. Assign fields explicitly so equal-typed values cannot drift.
        auto sway = first_person_sway();
        const auto sucker_shake = tutorial_session->weapon_view_model_shake();
        sway.x += sucker_shake[0U];
        sway.y += sucker_shake[1U];
        sway.z += sucker_shake[2U];
        const auto input =
            world::compose_weapon_view_model_input(*uploaded_sandbox_tool,
                                                   tutorial_session->seconds_since_primary(),
                                                   tutorial_session->weapon_action_sequence(),
                                                   sway,
                                                   tutorial_session->pullout_remaining(),
                                                   tutorial_session->weapon_mechanism_phase());
        const auto pose = world::evaluate_weapon_view_model(input);
        const auto tool_matrix = [&](const world::RetailModelPose& part_pose) {
            Mat4 tool = mat_scale(static_cast<float>(pose.model_scale));
            tool = mat_mul(tool, mat_rotate_z(static_cast<float>(part_pose.orientation_degrees.z)));
            tool = mat_mul(tool, mat_rotate_y(static_cast<float>(part_pose.orientation_degrees.y)));
            tool = mat_mul(tool, mat_rotate_x(static_cast<float>(part_pose.orientation_degrees.x)));
            tool = mat_mul(tool,
                           mat_translate(static_cast<float>(part_pose.position.x),
                                         static_cast<float>(part_pose.position.y),
                                         static_cast<float>(part_pose.position.z)));
            tool = mat_mul(tool, mat_rotate_x(static_cast<float>(pose.digging_pitch_degrees)));
            // Character.draw_fps owns one root translation for both the
            // selected tool and its arm hierarchy.  F4 exposes enough tools
            // to make any split obvious: the weapon used to render at its
            // settled root while the hands alone followed pullout_remaining.
            tool = mat_mul(
                tool,
                mat_translate(static_cast<float>(pose.tool_sway.x + pose.character_offset.x),
                              static_cast<float>(pose.tool_sway.y + pose.character_offset.y),
                              static_cast<float>(pose.tool_sway.z + pose.character_offset.z)));
            return mat_mul(tool, mat_rotate_y(static_cast<float>(pose.character_yaw_degrees)));
        };
        if (tutorial_session->zoomed()) {
            if (!sandbox_sight_slot.has_value()) {
                // character.pyx:2070 early-returns when the weapon has no
                // sight, drawing nothing at all. Unreachable today -- zoomed_
                // is only set for aims_down_sights() behaviours and
                // weapon_secondary.cpp:37 already demands a sight mesh -- so
                // this is a guard, not a fix: without it a sightless aimed
                // weapon would fall through to the full hip pose (including
                // character_offset.x = -0.4) under an ADS field of view.
                return draws;
            }
            // Retail Character.draw_sight substitutes the sight display for
            // the ordinary multipart weapon and resets the matrix first.
            const auto sight = world::evaluate_weapon_sight(*uploaded_sandbox_tool);
            Mat4 model = mat_scale(static_cast<float>(sight.model_scale));
            model = mat_mul(model,
                            mat_translate(static_cast<float>(sight.position.x),
                                          static_cast<float>(sight.position.y),
                                          static_cast<float>(sight.position.z)));
            model = mat_mul(model, mat_rotate_y(static_cast<float>(sight.yaw_degrees)));
            draws.push_back({*sandbox_sight_slot, model});
            if (sight.has_pin && sandbox_pin_slot.has_value()) {
                draws.push_back({*sandbox_pin_slot, sight_pin_matrix(sight)});
            }
            return draws;
        }
        for (std::uint32_t slot{}; slot < sandbox_tool_part_count; ++slot) {
            if (sandbox_sight_slot == slot || sandbox_pin_slot == slot ||
                sandbox_arm_upper_slot == slot || sandbox_arm_lower_slot == slot) {
                continue;
            }
            const auto part = static_cast<std::size_t>(slot);
            const auto& part_pose = part < pose.tool_part_count ? pose.tool_parts[part] : pose.tool;
            draws.push_back({slot, tool_matrix(part_pose)});
        }
        const auto append_arm = [&](std::uint32_t slot, const world::RetailArmPartPose& part) {
            Mat4 model = mat_scale(static_cast<float>(pose.model_scale));
            model = mat_mul(model, mat_rotate_y(static_cast<float>(part.yaw_degrees)));
            model = mat_mul(model,
                            mat_translate(static_cast<float>(part.position.x),
                                          static_cast<float>(part.position.y),
                                          static_cast<float>(part.position.z)));
            model = mat_mul(model,
                            mat_translate(static_cast<float>(pose.arms_anchor.x),
                                          static_cast<float>(pose.arms_anchor.y),
                                          static_cast<float>(pose.arms_anchor.z)));
            model = mat_mul(model,
                            mat_rotate_x(static_cast<float>(pose.arms_orientation_degrees.x *
                                                            pose.arm_rotation_ratio)));
            model = mat_mul(
                model,
                mat_translate(static_cast<float>(pose.arms_position.x + pose.character_offset.x),
                              static_cast<float>(pose.arms_position.y + pose.character_offset.y),
                              static_cast<float>(pose.arms_position.z + pose.character_offset.z)));
            model = mat_mul(model, mat_rotate_y(static_cast<float>(pose.character_yaw_degrees)));
            draws.push_back({slot, model});
        };
        if (pose.draws_player_arms && sandbox_arm_upper_slot.has_value() &&
            sandbox_arm_lower_slot.has_value()) {
            const auto& parts = pose.arm_parts;
            append_arm(*sandbox_arm_lower_slot,
                       parts[static_cast<std::size_t>(world::RetailArmPart::left_lower)]);
            append_arm(*sandbox_arm_lower_slot,
                       parts[static_cast<std::size_t>(world::RetailArmPart::right_lower)]);
            append_arm(*sandbox_arm_upper_slot,
                       parts[static_cast<std::size_t>(world::RetailArmPart::left_upper)]);
        }
        return draws;
    }

    /** Uploads every viewmodel mesh slot once per world entry. */
    void sync_view_model() {
        if (!sync_placement_preview_meshes()) {
            last_error = "placement preview mesh synchronization failed: " +
                         std::string{world_renderer.last_error()};
        }
        const auto sync_status_widgets = [this]() {
            if (tutorial_session == nullptr) {
                game_hud.set_ammo_state({}, 0, std::nullopt, false);
                game_hud.set_player_score(0, false);
                game_hud.set_numeric_health_visible(false);
                game_hud.set_jetpack_fuel(0.0, false);
                game_hud.set_ability_hint({});
                game_hud.set_disguise_active(false);
                game_hud.set_parachute_active(false);
                game_hud.set_team_scores({}, {}, false);
                game_hud.set_match_clock(0.0, false);
                game_hud.set_minimap({});
                game_hud.set_palette_state({}, 8U, std::nullopt, false);
                return;
            }
            sync_minimap_hud_state();
            sync_palette_hud();

            // InitialInfo owns both presentation switches. The score flag also
            // gates the class portrait, while CLASS_UGCBUILDER suppresses the
            // SCORE box even when a host enables it. Tutorial has no remote
            // InitialInfo and retains its local numeric readout/target score.
            const auto local_class_id = tutorial_session->debug_class_id();
            const bool player_score_visible =
                local_class_id !=
                    static_cast<std::uint8_t>(retail::CLASS_UGCBUILDER) &&
                (!network_match || match_initial_info.enable_player_score);
            game_hud.set_numeric_health_visible(
                !network_match || match_initial_info.enable_numeric_hp);
            game_hud.set_player_score(
                network_match ? game_hud.player_score()
                              : tutorial_session->targets_destroyed() * 100,
                player_score_visible);

            // draw_healthbar draws class_icons[class.id][team.id] beside the
            // bar, and our class catalog already carries both team variants.
            const auto team = local_player_team_index();
            game_hud.set_team(team == 1U ? frontend::hud_layout::Team::team2
                                         : frontend::hud_layout::Team::team1);
            if (network_match) {
                const auto color = local_player_team_color();
                game_hud.set_team_color(
                    ui::ColorRgba8{color.red, color.green, color.blue, color.alpha});
            }
            if (const auto* klass =
                    world::find_class_definition(tutorial_session->debug_class_id());
                klass != nullptr) {
                // The class id is server-selected. Retail divides raw HP by
                // this profile only for the numeric readout (Zombie 100/0.6
                // becomes 167) while leaving the bar on its raw 0..100 pool.
                game_hud.set_health_damage_multiplier(klass->damage_multiplier);
                const bool high_minimap_visibility =
                    network_match && local_player_id.has_value() &&
                    tutorial_roster.player(*local_player_id) != nullptr &&
                    tutorial_roster.player(*local_player_id)->high_minimap_visibility;
                game_hud.set_class_portrait(cosmetic_class_icon(klass->class_id,team==0U,false,klass->team_icon_assets[team]),
                                            high_minimap_visibility);
            } else {
                game_hud.set_health_damage_multiplier(1.0);
                game_hud.set_class_portrait({}, false);
            }

            const network::RemotePlayerReplica* local_replica = nullptr;
            if (network_match && local_player_id.has_value()) {
                local_replica = tutorial_roster.player(*local_player_id);
            }
            game_hud.set_intel_carrier(local_replica != nullptr ? local_replica->team : 0U,
                                       local_replica != nullptr &&
                                           local_replica->pickup_id == 16U &&
                                           match_initial_info.allow_shooting_holding_intel);
            const auto& movement = tutorial_session->player();
            if (local_replica != nullptr) {
                tutorial_session->set_infinite_blocks(
                    local_replica->team == 2U
                        ? match_state_info.team1_infinite_blocks
                        : local_replica->team == 3U
                              ? match_state_info.team2_infinite_blocks
                              : false);
            }
            const bool has_jetpack =
                movement.jetpack != 0U ||
                (local_replica != nullptr &&
                 std::any_of(local_replica->loadout.begin(),
                             local_replica->loadout.end(),
                             [](std::uint8_t item) { return item >= 66U && item <= 69U; }));
            game_hud.set_jetpack_fuel(
                retail_jetpack_fuel_fraction(tutorial_session->jetpack_fuel()), has_jetpack);
            const auto key_name = [&](settings::ControlAction action, std::string_view fallback) {
                const auto binding = applied_settings.controls.binding(action);
                if (binding.kind == settings::BindingKind::keyboard_scancode) {
                    const auto value = scancode_display_name(binding.code);
                    if (value != "?") return value;
                }
                return std::string{fallback};
            };
            std::string ability_hint;
            if (tutorial_session->alive() && movement.parachute) {
                ability_hint = movement.parachute_active ? "Parachute deployed"
                    : movement.parachute_pending ? "Parachute opens on descent"
                    : key_name(settings::ControlAction::hover, "Z") + ": deploy parachute in air";
            } else if (tutorial_session->alive() && has_jetpack) {
                ability_hint = key_name(movement.jetpack == 4U ? settings::ControlAction::hover
                                                              : settings::ControlAction::jump,
                                        movement.jetpack == 4U ? "Z" : "SPACE") + ": thrust";
                if (movement.jetpack != 4U &&
                    (!network_match || match_initial_info.flight_profile.grounded_refill_only)) {
                    ability_hint += "; release + land to recharge";
                }
            }
            game_hud.set_ability_hint(std::move(ability_hint));
            game_hud.set_disguise_active(local_replica != nullptr &&
                                         (local_replica->state_flags & 0x02U) != 0U);
            game_hud.set_parachute_active(local_replica != nullptr
                                              ? (local_replica->state_flags & 0x01U) != 0U
                                              : movement.parachute_active);

            if (network_match) {
                std::int32_t team1_players{};
                std::int32_t team2_players{};
                for (const auto& player : tutorial_roster.players()) {
                    team1_players += player.team == 2U ? 1 : 0;
                    team2_players += player.team == 3U ? 1 : 0;
                }
                const auto team1_value = resolve_game_hud_head_count(
                    match_state_info.team_headcount_type,
                    match_state_info.team1_score, team1_players);
                const auto team2_value = resolve_game_hud_head_count(
                    match_state_info.team_headcount_type,
                    match_state_info.team2_score, team2_players);
                game_hud.set_team_scores(
                    GameHudTeamScore{hud_layout::Team::team1,
                                     team1_value.value,
                                     match_state_info.score_limit,
                                     match_state_info.team1_show_max_score,
                                     ui::ColorRgba8{match_state_info.team1_color[0U],
                                                    match_state_info.team1_color[1U],
                                                    match_state_info.team1_color[2U],
                                                    255U}},
                    GameHudTeamScore{hud_layout::Team::team2,
                                     team2_value.value,
                                     match_state_info.score_limit,
                                     match_state_info.team2_show_max_score,
                                     ui::ColorRgba8{match_state_info.team2_color[0U],
                                                    match_state_info.team2_color[1U],
                                                    match_state_info.team2_color[2U],
                                                    255U}},
                    team1_value.visible && team2_value.visible);
            } else {
                game_hud.set_team_scores({}, {}, false);
                game_hud.set_match_clock(0.0, false);
            }

            // draw_tools_hud emits the blocks row unconditionally, so the
            // counter stays on screen whatever tool is equipped -- only the
            // weapon row above it swaps with the selection.
            const auto* block_class =
                world::find_class_definition(tutorial_session->debug_class_id());
            game_hud.set_block_state(
                std::string{game_hud_assets::block_icon},
                static_cast<std::int32_t>(tutorial_session->blocks_remaining()),
                block_class != nullptr ? static_cast<std::int32_t>(block_class->maximum_blocks) : 0,
                true);

            const auto selected = tutorial_session->selected_tool_id();
            const auto* weapon =
                selected.has_value() ? world::find_weapon_definition(*selected) : nullptr;
            if (weapon == nullptr || weapon->first_person_image_asset.empty()) {
                game_hud.set_ammo_state({}, 0, std::nullopt, false);
                return;
            }

            const bool prefab_tool = weapon->mechanism == world::WeaponMechanism::prefab_builder ||
                                     weapon->mechanism == world::WeaponMechanism::ugc_prefab_editor;
            if (prefab_tool) {
                const auto prefab_name = tutorial_session->selected_prefab();
                // sync_placement_preview_meshes runs before this HUD pass and
                // owns the selected KV6 cache. Reusing it avoids parsing a
                // prefab every frame merely to recover prefab_cost.
                const bool matching_model = !prefab_name.empty() &&
                                            prefab_name == preview_prefab_name &&
                                            preview_prefab_model.has_value();
                const auto cost = matching_model ? preview_prefab_cost : 0;
                game_hud.set_prefab_cost_state(preview_prefab_icon,
                                               cost,
                                               matching_model &&
                                                   (tutorial_session->infinite_blocks() ||
                                                    tutorial_session->blocks_remaining() >= cost),
                                               game_hud.team_color(),
                                               matching_model);
                return;
            }

            if (weapon->mechanism == world::WeaponMechanism::block_builder) {
                // Retail BlockTool's upper row is placement cost, even though
                // blocks have no magazine. Keep this before sandbox/live ammo
                // handling so it cannot disappear as a non-ammunition tool.
                const auto current = tutorial_session->placement_cell(
                    match_initial_info.classic ? 5.0 : 10.0);
                std::int32_t cost{1};
                bool can_place = false;
                if (current.has_value()) {
                    network::BlockLinePacket line;
                    line.start = block_line_start.value_or(*current);
                    line.end = *current;
                    const auto cells = network::cube_line_cells(line, 65U);
                    const auto placement = world::evaluate_block_line_placement(
                        tutorial_session->map(), cells);
                    cost = static_cast<std::int32_t>(placement.required_blocks);
                    can_place = placement.can_place(tutorial_session->blocks_remaining(),
                                                     tutorial_session->infinite_blocks());
                }
                game_hud.set_block_cost_state(
                    cost, can_place, game_hud.team_color(), true);
                return;
            }

            if (tutorial_session->weapon_sandbox_enabled()) {
                const auto* ammo = tutorial_session->selected_ammo();
                const bool count_bearing =
                    ammo != nullptr && (weapon->clip_size > 0U || weapon->reserve_ammo > 0U ||
                                        ammo->magazine > 0U || ammo->reserve > 0U);
                game_hud.set_ammo_state(
                    cosmetic_weapon_icon(*selected,weapon->first_person_image_asset,local_player_team_index()==0U),
                    count_bearing ? static_cast<std::int32_t>(ammo->magazine) : 0,
                    count_bearing && weapon->reserve_ammo > 0U
                        ? std::optional<std::int32_t>{static_cast<std::int32_t>(ammo->reserve)}
                        : std::nullopt,
                    count_bearing);
                return;
            }

            // Recovered tutorial protocol ids: block=5, spade=2, pistol=17.
            // DiggingTool intentionally displays the shared block stock.
            if (*selected == 17U) {
                game_hud.set_ammo_state(cosmetic_weapon_icon(*selected,weapon->first_person_image_asset,local_player_team_index()==0U),
                                        tutorial_session->pistol_clip(),
                                        tutorial_session->pistol_stock(),
                                        true);
            } else if (*selected == 5U || *selected == 2U) {
                const auto* block = world::find_weapon_definition(5U);
                game_hud.set_ammo_state(block != nullptr
                                            ? std::string{block->first_person_image_asset}
                                            : std::string{weapon->first_person_image_asset},
                                        tutorial_session->blocks_remaining(),
                                        std::nullopt,
                                        true);
            } else {
                game_hud.set_ammo_state({}, 0, std::nullopt, false);
            }
        };

        if (tutorial_session != nullptr && tutorial_session->weapon_sandbox_enabled()) {
            const auto& toolbar = tutorial_session->inventory();
            std::vector<GameHudInventorySlot> hud_slots;
            // Retail class strips are short. The developer inventory contains
            // all 65 tools, so drawing it as one 5,200-pixel strip both hides
            // the selected item and needlessly floods UI resources. Present a
            // moving ten-entry window while retaining the real global index
            // in RetailInventory and WeaponReplicationState.
            constexpr std::size_t sandbox_visible_slots{10U};
            const auto selected_global = toolbar.selected_index().value_or(0U);
            const auto count = toolbar.slots().size();
            const auto visible_count = std::min(count, sandbox_visible_slots);
            const auto maximum_start = count > visible_count ? count - visible_count : 0U;
            const auto preferred_start =
                selected_global > visible_count / 2U ? selected_global - visible_count / 2U : 0U;
            const auto first = std::min(preferred_start, maximum_start);
            const auto last = first + visible_count;
            hud_slots.reserve(visible_count);
            for (std::size_t index = first; index < last; ++index) {
                const auto& slot = toolbar.slots()[index];
                const auto* definition = world::find_weapon_definition(slot.tool_id);
                std::string icon;
                if (slot.kind == world::InventorySlotKind::prefab &&
                    slot.variant_id < tutorial_session->inventory_prefabs().size()) {
                    icon = world::prefab_preview_asset(
                        config.asset_root, tutorial_session->inventory_prefabs()[slot.variant_id]);
                } else if (slot.kind == world::InventorySlotKind::ugc_tool) {
                    icon = std::string{world::ugc_tool_icon_asset(
                        static_cast<std::uint8_t>(slot.variant_id))};
                }
                if (icon.empty() && definition != nullptr) {
                    icon = cosmetic_weapon_icon(slot.tool_id,definition->toolbar_icon_asset,local_player_team_index()==0U);
                }
                hud_slots.push_back({std::move(icon),
                                     index < 9U    ? std::to_string(index + 1U)
                                     : index == 9U ? "0"
                                                   : std::string{}});
            }
            game_hud.set_inventory_state(std::move(hud_slots),
                                         selected_global >= first && selected_global < last
                                             ? std::optional<std::size_t>{selected_global - first}
                                             : std::nullopt,
                                         toolbar.toolbar_visible());
            if (!sync_sandbox_view_model()) {
                last_error = settings_warning;
            }
            const auto selected = tutorial_session->selected_tool_id();
            const auto* weapon =
                selected.has_value() ? world::find_weapon_definition(*selected) : nullptr;
            // Retail drives the reticle from the weapon's own show_crosshair
            // ordinal (constants.py:846), never from whether the player is
            // aiming. Exactly one class asks to lose it in the sights: the
            // classic rifle's UNZOOMED_CROSSHAIR. Both snipers inherit
            // HAS_AMMO_CROSSHAIR and keep their reticle over the scope, so
            // hiding on every zoom got the two most visible weapons in the
            // game backwards. The remaining ordinals stay visible here: which
            // of them carries an ammo predicate was never recovered from the
            // shipped client, and a name alone is not enough to start hiding
            // reticles on thirty tools.
            constexpr std::int16_t unzoomed_crosshair{2};
            const bool hidden_while_aimed =
                weapon != nullptr && weapon->retail.use.crosshair_mode == unzoomed_crosshair &&
                tutorial_session->zoomed();
            const bool skin_crosshair=scripted_weapon&&scripted_images.has_screen_image(scripted_weapon->frame());
            game_hud.set_crosshair_visible(weapon!=nullptr&&!hidden_while_aimed&&
                (!scripted_weapon||(!tutorial_session->zoomed()&&!skin_crosshair)));
            game_hud.set_crosshair_geometry(tutorial_session->weapon_crosshair_radius_pixels(
                                                static_cast<double>(drawable_extent.height)),
                                            weapon != nullptr &&
                                                weapon->retail.use.show_crosshair_center);
            sync_status_widgets();
            return;
        }
        const auto equipped =
            tutorial_session != nullptr ? tutorial_session->equipped_tool() : std::nullopt;
        if (tutorial_session != nullptr) {
            std::vector<GameHudInventorySlot> hud_slots;
            const auto& inventory = tutorial_session->inventory();
            hud_slots.reserve(inventory.slots().size());
            for (std::size_t index{}; index < inventory.slots().size(); ++index) {
                const auto& slot = inventory.slots()[index];
                const auto* definition = world::find_weapon_definition(slot.tool_id);
                std::string icon;
                if (slot.kind == world::InventorySlotKind::prefab &&
                    slot.variant_id < tutorial_session->inventory_prefabs().size()) {
                    icon = world::prefab_preview_asset(
                        config.asset_root, tutorial_session->inventory_prefabs()[slot.variant_id]);
                } else if (slot.kind == world::InventorySlotKind::ugc_tool) {
                    icon = std::string{world::ugc_tool_icon_asset(
                        static_cast<std::uint8_t>(slot.variant_id))};
                }
                if (icon.empty() && definition != nullptr) {
                    icon = cosmetic_weapon_icon(slot.tool_id,definition->toolbar_icon_asset,local_player_team_index()==0U);
                }
                hud_slots.push_back(
                    GameHudInventorySlot{icon, index == 9U ? "0" : std::to_string(index + 1U)});
            }
            game_hud.set_inventory_state(
                std::move(hud_slots), inventory.selected_index(), inventory.toolbar_visible());
        } else {
            game_hud.set_inventory_state({}, std::nullopt, false);
        }
        sync_status_widgets();
        if (tutorial_session != nullptr && !view_model_meshes_uploaded &&
            world_renderer.is_initialized()) {
            const auto upload = [&](std::uint32_t slot, const world::ChunkMesh& mesh) {
                if (!mesh.vertices.empty()) {
                    static_cast<void>(world_renderer.set_view_model_mesh(slot, mesh));
                }
            };
            for (const auto& [tool, mesh] : tool_meshes) {
                switch (tool) {
                case world::TutorialTool::block:
                    upload(view_model_slot_block, mesh);
                    break;
                case world::TutorialTool::spade:
                    upload(view_model_slot_spade, mesh);
                    break;
                case world::TutorialTool::pistol:
                    upload(view_model_slot_pistol, mesh);
                    break;
                }
            }
            upload(view_model_slot_arms_upper, arms_upper_mesh);
            upload(view_model_slot_arms_lower, arms_lower_mesh);
            upload(view_model_slot_debug_upper, arms_debug_upper_mesh);
            upload(view_model_slot_debug_lower_a, arms_debug_lower_a_mesh);
            upload(view_model_slot_debug_lower_b, arms_debug_lower_b_mesh);
            if (!tutorial_sight_mesh.vertices.empty()) {
                upload(view_model_slot_sight, tutorial_sight_mesh);
                tutorial_sight_slot = view_model_slot_sight;
            }
            if (!tutorial_pin_mesh.vertices.empty()) {
                upload(view_model_slot_pin, tutorial_pin_mesh);
                tutorial_pin_slot = view_model_slot_pin;
            }
            view_model_meshes_uploaded = true;
        }
        if (equipped == uploaded_tool) {
            return;
        }
        // Retail plays switch.ogg alongside the pullout animation.
        if (audio_started && uploaded_tool.has_value() && equipped.has_value()) {
            audio->play_head_relative_one_shot(audio::OpenAlFrontendAudio::tool_switch_sound, 1.0F);
        }
        uploaded_tool = equipped;
        // Recovered per-tool crosshair enum: pistol ALWAYS, block ALWAYS,
        // spade ALWAYS — every tutorial tool shows the crosshair.
        game_hud.set_crosshair_visible(equipped.has_value());
        game_hud.set_crosshair_geometry(6.0, true);
    }

    /**
     * Recovered Character.draw_fps composite for the current frame: the
     * held tool under R_y(180)*T(-0.4,-0.55,+0.9)*apply_transform and the
     * three soldier arm parts under their own chain through
     * T(0.401,-0.01,-0.801), all at view_model_size 0.05. Composition is
     * row-vector, so each recovered GL chain is built back-to-front.
     */
    [[nodiscard]] std::vector<render::ViewModelDraw> view_model_draws() {
        if (death_camera.active() || local_jetpack_death_state() != nullptr) {
            return {};
        }
        if (tutorial_session != nullptr && tutorial_session->weapon_sandbox_enabled()) {
            return sandbox_view_model_draws();
        }
        std::vector<render::ViewModelDraw> draws;
        if (tutorial_session == nullptr || !uploaded_tool.has_value()) {
            return draws;
        }
        if (!tutorial_session->weapon_view_model_visible()) {
            return draws;
        }
        // Slot selection is presentation-only. All actual pose values come
        // from the renderer-neutral retail oracle below.
        std::uint32_t tool_slot{view_model_slot_pistol};
        switch (*uploaded_tool) {
        case world::TutorialTool::pistol:
            tool_slot = view_model_slot_pistol;
            break;
        case world::TutorialTool::spade:
            tool_slot = view_model_slot_spade;
            break;
        case world::TutorialTool::block:
            tool_slot = view_model_slot_block;
            break;
        }
        // Recovered draw_fps head: pullout drop, walk bob, mouse sway and
        // airborne lift, all in the pre-flip tool frame. The literals are
        // frame-rate-baselined at 60 Hz, which matches our fixed tick.
        float sway_x{};
        float sway_y{};
        float sway_z{};
        const auto pullout = static_cast<float>(tutorial_session->pullout_remaining());
        if (pullout > 0.0F) {
            sway_x -= pullout * 5.0F;
            sway_y -= pullout * 5.0F;
        }
        const auto walk = first_person_sway();
        sway_x += static_cast<float>(walk.x);
        sway_y += static_cast<float>(walk.y);
        sway_z += static_cast<float>(walk.z);

        world::RetailViewModelInput pose_input;
        pose_input.tool = *uploaded_tool;
        pose_input.seconds_since_primary = tutorial_session->seconds_since_primary();
        pose_input.sway_x = sway_x;
        pose_input.sway_y = sway_y;
        pose_input.sway_z = sway_z;
        const auto pose = world::evaluate_retail_view_model(pose_input);

        // gameScene.pyx:1443-1447 -- draw_sight and draw_fps are an if/else,
        // so the aimed frame draws neither the tool nor the arms. Gated on the
        // tool as well as on zoom: of the three tutorial tools only the pistol
        // aims, and an unconditional early return would blank the block and
        // the spade instead.
        if (tutorial_session->zoomed() && *uploaded_tool == world::TutorialTool::pistol &&
            tutorial_sight_slot.has_value()) {
            const auto sight = world::evaluate_weapon_sight(tutorial_pistol_tool_id);
            Mat4 m = mat_scale(static_cast<float>(sight.model_scale));
            m = mat_mul(m,
                        mat_translate(static_cast<float>(sight.position.x),
                                      static_cast<float>(sight.position.y),
                                      static_cast<float>(sight.position.z)));
            m = mat_mul(m, mat_rotate_y(static_cast<float>(sight.yaw_degrees)));
            draws.push_back(render::ViewModelDraw{*tutorial_sight_slot, m});
            if (sight.has_pin && tutorial_pin_slot.has_value()) {
                draws.push_back(render::ViewModelDraw{*tutorial_pin_slot, sight_pin_matrix(sight)});
            }
            return draws;
        }

        // Tool chain: glRotatef(180,0,1,0); glTranslatef(x-0.4, y-0.55,
        // z+0.9); apply_transform = T(position) R_x(ori.x) R_y(ori.y);
        // draw_scaled(0.05).
        {
            Mat4 m = mat_scale(static_cast<float>(pose.model_scale));
            m = mat_mul(m, mat_rotate_z(static_cast<float>(pose.tool.orientation_degrees.z)));
            m = mat_mul(m, mat_rotate_y(static_cast<float>(pose.tool.orientation_degrees.y)));
            m = mat_mul(m, mat_rotate_x(static_cast<float>(pose.tool.orientation_degrees.x)));
            m = mat_mul(m,
                        mat_translate(static_cast<float>(pose.tool.position.x),
                                      static_cast<float>(pose.tool.position.y),
                                      static_cast<float>(pose.tool.position.z)));
            // DiggingTool.pitch is separate from Tool.apply_transform.
            m = mat_mul(m, mat_rotate_x(static_cast<float>(pose.digging_pitch_degrees)));
            m = mat_mul(
                m,
                mat_translate(static_cast<float>(pose.tool_sway.x + pose.character_offset.x),
                              static_cast<float>(pose.tool_sway.y + pose.character_offset.y),
                              static_cast<float>(pose.tool_sway.z + pose.character_offset.z)));
            m = mat_mul(m, mat_rotate_y(static_cast<float>(pose.character_yaw_degrees)));
            draws.push_back(render::ViewModelDraw{tool_slot, m});
        }

        // Exact character.pyd draw_fps arm hierarchy: shared weapon/sway
        // translation, animated x rotation, fixed anchor, then the three
        // recovered local part transforms. No screen-fitted pivots remain.
        const auto arm_part = [&](std::uint32_t slot, const world::RetailArmPartPose& part) {
            Mat4 m = mat_scale(static_cast<float>(pose.model_scale));
            m = mat_mul(m, mat_rotate_y(static_cast<float>(part.yaw_degrees)));
            m = mat_mul(m,
                        mat_translate(static_cast<float>(part.position.x),
                                      static_cast<float>(part.position.y),
                                      static_cast<float>(part.position.z)));
            m = mat_mul(m,
                        mat_translate(static_cast<float>(pose.arms_anchor.x),
                                      static_cast<float>(pose.arms_anchor.y),
                                      static_cast<float>(pose.arms_anchor.z)));
            m = mat_mul(m,
                        mat_rotate_x(static_cast<float>(pose.arms_orientation_degrees.x *
                                                        pose.arm_rotation_ratio)));
            m = mat_mul(
                m,
                mat_translate(static_cast<float>(pose.arms_position.x + pose.character_offset.x),
                              static_cast<float>(pose.arms_position.y + pose.character_offset.y),
                              static_cast<float>(pose.arms_position.z + pose.character_offset.z)));
            m = mat_mul(m, mat_rotate_y(static_cast<float>(pose.character_yaw_degrees)));
            draws.push_back(render::ViewModelDraw{slot, m});
        };
        const bool color_parts = (debug_arm_variant % 2) == 1;
        const auto part = [&](world::RetailArmPart value) -> const auto& {
            return pose.arm_parts[static_cast<std::size_t>(value)];
        };
        arm_part(color_parts ? view_model_slot_debug_lower_a : view_model_slot_arms_lower,
                 part(world::RetailArmPart::left_lower));
        arm_part(color_parts ? view_model_slot_debug_lower_b : view_model_slot_arms_lower,
                 part(world::RetailArmPart::right_lower));
        arm_part(color_parts ? view_model_slot_debug_upper : view_model_slot_arms_upper,
                 part(world::RetailArmPart::left_upper));
        return draws;
    }

    /** Reconciles desired and actual capture once per tick. */
    void update_mouse_capture() {
        const bool want_capture =
            tutorial_session != nullptr && screen() == FrontendScreen::tutorial_world &&
            window_focused && !window_suspended && !game_chat.active() &&
            !ugc_ingame_settings.visible() && !match_results.visible();
        if (want_capture == mouse_captured) {
            return;
        }
        if (window.set_relative_mouse_mode(want_capture)) {
            mouse_captured = want_capture;
        } else if (!want_capture) {
            // Releasing must fail-safe even if the platform call does not.
            mouse_captured = false;
        }
        if (!mouse_captured && tutorial_session != nullptr) {
            tutorial_session->clear_input();
            ugc_prefab_control.clear_inputs();
        }
    }

    /** Shaped width of one help-panel line for retail backing sizing. */
    [[nodiscard]] double measure_help_line(std::string_view line, double font_pixels) {
        auto* const rasterizer = font_for_text(main_menu_assets::button_font, line);
        if (rasterizer == nullptr) {
            return 0.0;
        }
        const auto raster = rasterizer->rasterize(text::TextRasterRequest{
            std::string{line},
            text::TextCase::preserve,
            static_cast<std::uint32_t>(std::max(1.0, std::floor(font_pixels + 0.5))),
        });
        if (!raster || raster.output == nullptr) {
            return 0.0;
        }
        return static_cast<double>(raster.output->metrics.content_width_pixels);
    }

